// ─────────── Agnostic Customizer branding ───────────
// Team Stores is brand-agnostic: whichever Customizer the rep signed in from
// brands the platform. The landing page hands the choice off via ?brand=<id>.
// PROLOOK is the default when no brand is specified. Non-PROLOOK brands render
// as text wordmark placeholders — swap in real logo assets when available.
const CUSTOMIZER_BRANDS = {
  prolook: { name: "Marucci", logoInk: "assets/prolook-mark-ink.png", logoBlack: "assets/prolook-mark-black.png", logoWhite: "assets/prolook-mark.png" },
  alli: { name: "Alli Sports", wordmark: "ALLI SPORTS" },
  riddell: { name: "Riddell", wordmark: "Riddell" },
  "game-one": { name: "Game One", wordmark: "GAME ONE" },
  varsity: { name: "Varsity", wordmark: "VARSITY" },
  squadlocker: { name: "SquadLocker", wordmark: "SquadLocker" },
  "bsn-sports": { name: "BSN Sports", wordmark: "BSN SPORTS" },
  augusta: { name: "Augusta", wordmark: "AUGUSTA" },
};
// How the rep authenticated (Landing Page hand-off): "customizer" (federated),
// "native" (Team Stores credentials), "native-new" (just signed up), "linked" (both).
function getAuthMode() {
  try {
    const a = new URLSearchParams(window.location.search).get("auth");
    if (a === "native" || a === "native-new" || a === "linked" || a === "customizer") return a;
  } catch (e) {}
  try { return sessionStorage.getItem("ts_auth_mode") || "native"; } catch (e) { return "native"; }
}
function getActiveBrand() {
  try {
    const id = new URLSearchParams(window.location.search).get("brand");
    return CUSTOMIZER_BRANDS[id] || CUSTOMIZER_BRANDS.prolook;
  } catch (e) { return CUSTOMIZER_BRANDS.prolook; }
}
// Team Stores is a brand-agnostic platform: the header always shows the neutral
// QX platform mark rather than the signed-in Customizer's brand.
// variant: "ink" (dark on light) | "black" | "white" (on dark)
function BrandMark({ variant = "ink", height = 38 }) {
  return <img src="assets/marucci-mark.png" alt="Marucci Team Stores" style={{ height, width: "auto", display: "block" }} />;
}

