// ─────────── PORTAL (composed) ───────────
function TeamStoresPortal({ onEnter, headlineKey = "fulfillment", heroVariant = "cinematic", ctaLabel = "Enter Store Manager", ctaColor = "black" }) {
  const gwRef = React.useRef(null);
  const scrollToGateway = () => {
    const el = gwRef.current;
    if (!el) return;
    const top = el.getBoundingClientRect().top + window.scrollY - 90;
    window.scrollTo({ top, behavior: "smooth" });
  };
  return (
    <div style={{ flex: 1, minWidth: 0, background: "#fff" }}>
      <TspHero variant={heroVariant} headlineKey={headlineKey} onExplore={scrollToGateway} />
      <TspGateway ctaLabel={ctaLabel} ctaColor={ctaColor} onEnter={onEnter} gwRef={gwRef} />
      <TspFeatures />
    </div>
  );
}

