// Thumbnail list for curated templates — real vault product photos.
function TplVaultProductList({ products, maxHeight }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight, overflowY: maxHeight ? "auto" : "visible", paddingRight: maxHeight ? 4 : 0 }}>
      {products.map((p, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ width: 38, height: 42, borderRadius: 6, flexShrink: 0, background: "#f4f4f6", display: "inline-flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
            <img src={"assets/products/" + p.photo + ".png"} alt={p.title} style={{ maxWidth: "88%", maxHeight: "88%", objectFit: "contain", display: "block" }} />
          </span>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: "#0e0e10", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.title}</div>
            <div style={{ fontSize: 10.5, color: "#9a9aa1", marginTop: 1 }}>{p.cat}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

// One template option in the repository grid.
function TemplateSummaryCard({ tpl, kind, accent, onSelect }) {
  const [hover, setHover] = React.useState(false);
  const total = tpl.products ? tpl.products.length : (tpl.blocks || []).reduce((n, b) => n + b.count, 0);
  return (
    <div
      onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
      onClick={onSelect}
      style={{
        display: "flex", flexDirection: "column", cursor: "pointer",
        border: `1px solid ${hover ? accent : "#ececf0"}`, borderRadius: 14, background: "#fff", overflow: "hidden",
        boxShadow: hover ? "0 14px 34px rgba(20,20,30,.11)" : "0 1px 2px rgba(20,20,30,.03)",
        transform: hover ? "translateY(-2px)" : "none",
        transition: "border-color .16s, box-shadow .16s, transform .16s",
      }}>
      {/* Header strip */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 20px", borderBottom: "1px solid #f1f1f3" }}>
        <span style={{ width: 44, height: 44, borderRadius: 11, flexShrink: 0, background: kind === "user" ? "#0e0e10" : accent, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
          {kind === "user" ? <IconLayers size={21} /> : <IconTemplateGrid size={20} />}
        </span>
        <div style={{ minWidth: 0, flex: 1 }}>
          <div style={{ fontSize: 16, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{tpl.name}</div>
          <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 1 }}>
            {kind === "user" ? `From ${tpl.sourceName}` : tpl.sport} · {total} products
          </div>
        </div>
      </div>

      {/* Stacked agnostic-product summary */}
      <div style={{ padding: "16px 20px", flex: 1 }}>
        <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".08em", color: "#9a9aa1", textTransform: "uppercase", marginBottom: 12 }}>{tpl.products ? "Pre-loaded products" : "Pre-loaded blocks"}</div>
        {tpl.products ? <TplVaultProductList products={tpl.products} maxHeight={168} /> : <AgnosticBlockList blocks={tpl.blocks} dense maxHeight={168} />}
      </div>

      {/* Structural flags */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, padding: "0 20px 16px" }}>
        <TplFlagPill icon={tpl.storeType === "single" ? <IconUsers size={14} /> : <IconLayers size={14} />} label="Structure" value={tplTypeLabel(tpl.storeType)} />
        <TplFlagPill icon={tpl.distributionModel === "home" ? <IconBag size={14} /> : <IconUsers size={14} />} label="Distribution" value={tplDistLabel(tpl.distributionModel)} />
      </div>

      {/* CTA */}
      <div style={{ padding: "0 20px 20px" }}>
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          background: hover ? "#0e0e10" : "#f4f4f5", color: hover ? "#fff" : "#0e0e10",
          borderRadius: 8, padding: "12px 0", fontSize: 13, fontWeight: 800, letterSpacing: ".02em",
          transition: "background .16s, color .16s",
        }}>
          Use this template <IconChevronRight size={15} />
        </div>
      </div>
    </div>
  );
}

// ── The tabbed "Start with Template" repository ──
function TemplateRepository({ userTemplates = [], accent = "#e1251b", onCancel, onPickCurated, onPickUser }) {
  const [tab, setTab] = React.useState("curated");
  const tabs = [
    { key: "curated", label: "Curated Templates", count: CURATED_TEMPLATES.length },
    { key: "user", label: "User-Generated", count: userTemplates.length },
  ];
  const list = tab === "curated" ? CURATED_TEMPLATES : userTemplates;

  return (
    <div style={{ flex: 1, background: "#fbfbfc", overflowY: "auto", minWidth: 0 }}>
      {/* Header band */}
      <div style={{ background: "#fff", borderBottom: "1px solid #ececf0", padding: "28px 48px 0" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 20, marginBottom: 20 }}>
          <div>
            <div style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".12em", color: "#9a9aa1", textTransform: "uppercase", marginBottom: 8 }}>Team Store Setup</div>
            <h1 style={{ fontSize: 30, fontWeight: 800, margin: 0, letterSpacing: ".005em", color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>Choose a Template</h1>
            <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0", maxWidth: 560, lineHeight: 1.55 }}>
              Start from a curated system package or one of your organization's saved store blueprints. Branding is applied after you pick.
            </p>
          </div>
          <Button variant="ghost" onClick={onCancel} style={{ flexShrink: 0, marginTop: 8 }}>CANCEL</Button>
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: 4 }}>
          {tabs.map((t) => {
            const on = tab === t.key;
            return (
              <button key={t.key} onClick={() => setTab(t.key)} style={{
                background: "transparent", border: 0, padding: "16px 4px", marginRight: 24,
                fontSize: 14, fontWeight: on ? 800 : 600, color: on ? "#0e0e10" : "#9a9aa1",
                cursor: "pointer", borderBottom: `2.5px solid ${on ? "#0e0e10" : "transparent"}`,
                display: "inline-flex", alignItems: "center", gap: 8, marginBottom: -1.5, transition: "color .15s",
              }}>
                {t.label}
                <span style={{ fontSize: 11, fontWeight: 800, color: on ? "#fff" : "#9a9aa1", background: on ? "#0e0e10" : "#ececf0", borderRadius: 999, padding: "2px 8px", minWidth: 20, textAlign: "center" }}>{t.count}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Grid */}
      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "32px 40px 120px" }}>
        {list.length === 0 ? (
          <div style={{ textAlign: "center", padding: "80px 20px", color: "#9a9aa1" }}>
            <span style={{ width: 56, height: 56, borderRadius: 14, background: "#f1f1f3", color: "#9a9aa1", display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}><IconLayers size={26} /></span>
            <div style={{ fontSize: 16, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif", marginBottom: 8 }}>No saved templates yet</div>
            <div style={{ fontSize: 13.5, lineHeight: 1.55, maxWidth: 400, margin: "0 auto" }}>
              Open a live store and choose <strong style={{ color: "#52525b" }}>Create Template</strong> from its menu to save a reusable blueprint here.
            </div>
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 24 }}>
            {list.map((tpl) => (
              <TemplateSummaryCard key={tpl.id} tpl={tpl} kind={tab === "user" ? "user" : "curated"} accent={accent}
                onSelect={() => tab === "user" ? onPickUser && onPickUser(tpl) : onPickCurated && onPickCurated(tpl)} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

