/* ===== ASSET 19 : 872b91cb-ba31-4a9e-9fba-2ac759b1a5ee ===== */
// New store dashboard — General Information tab (matches screenshot 6).

// ─────────── Tab badge persistence ───────────
// Red "needs attention" badges on the dashboard tabs. Dismissal is per-store and
// persisted to localStorage so cleared badges don't reappear after a refresh.
const BADGE_KEY = "prolook_tab_badges_v1";
function loadBadgeState(storeId) {
  try {
    const all = JSON.parse(localStorage.getItem(BADGE_KEY) || "{}");
    return all[storeId] || {};
  } catch (e) {return {};}
}
function saveBadgeState(storeId, state) {
  try {
    const all = JSON.parse(localStorage.getItem(BADGE_KEY) || "{}");
    all[storeId] = state;
    localStorage.setItem(BADGE_KEY, JSON.stringify(all));
  } catch (e) {}
}

// A red dot that fades + scales out when it clears (and in if it ever returns).
function TabDot({ show }) {
  const [mounted, setMounted] = React.useState(show);
  const [on, setOn] = React.useState(show);
  React.useEffect(() => {
    if (show) {
      setMounted(true);
      const id = requestAnimationFrame(() => setOn(true));
      return () => cancelAnimationFrame(id);
    }
    setOn(false);
    const t = setTimeout(() => setMounted(false), 380);
    return () => clearTimeout(t);
  }, [show]);
  if (!mounted) return null;
  return (
    <span style={{
      width: 8, height: 8, borderRadius: "50%", background: "#e1251b",
      display: "inline-block", marginLeft: 2, marginBottom: 8,
      opacity: on ? 1 : 0, transform: on ? "scale(1)" : "scale(0.3)",
      transition: "opacity .35s ease, transform .35s ease"
    }} />);

}

/* ===== Store Home tab (spec-adherent 11a/11b) ===== */
function homeLifecycle(store) {
  const archived = !!(store && (store.archived || store.status === "archived"));
  const closed = !archived && !!store && store.status === "closed";
  const open = !archived && !closed && !!(store && store.live);
  return { archived, closed, open, draft: !archived && !closed && !open };
}
function homeOrdersInfo(store) {
  const data = store && store.seeded ? makeOrdersDataset(store) : { myOrders: [], fanOrders: [], pending: [] };
  const pendingGroups = data.pending || [];
  const pending = pendingGroups.reduce(function (n, g) { return n + ((g.rows || []).length); }, 0);
  const submitted = (data.myOrders || []).length + (data.fanOrders || []).length;
  return { pending, submitted, total: pending + submitted, pendingGroups };
}
function homeBankInfo(org) {
  const bank = (org && org.bank) || {};
  let total = 0; const byTeam = {};
  Object.keys(bank).forEach(function (tid) {
    const n = (bank[tid] || []).filter(function (c) { return !c.committed; }).length;
    byTeam[tid] = n; total += n;
  });
  return { total, byTeam };
}
function homeStructureInfo(org) {
  const groups = (org && org.groups) || [];
  const loose = (org && org.loose) || [];
  const teams = groups.reduce(function (n, g) { return n + (g.rosters || []).length; }, 0) + loose.length;
  const players = groups.reduce(function (n, g) { return n + (g.rosters || []).reduce(function (m, r) { return m + (r.players || 0); }, 0); }, 0)
    + loose.reduce(function (n, r) { return n + (r.players || 0); }, 0);
  return { groups, loose, teams, players, divisions: groups.length };
}
function homeCloseInfo(store) {
  const raw = store && store.storeOpenEnd;
  if (!raw) return null;
  const end = new Date(raw + "T12:00:00");
  if (isNaN(end)) return null;
  const daysLeft = Math.max(0, Math.ceil((end - new Date()) / 86400000));
  return { label: end.toLocaleDateString("en-US", { month: "short", day: "numeric" }), daysLeft };
}
function homeFailedProducts(store) {
  return ((store && store.products) || []).filter(function (p) {
    return p && (p.renderFailed || p.imageFailed || p.renderStatus === "failed" || p.imageStatus === "failed");
  });
}
// The one attention model both the Home tab and the nav-dot rule read.
// Rail tones: red = blocking, blue = action, grey = informational. Never amber,
// never a severity label — rail color and ordering carry it.
function buildHomeAttention(store, org) {
  const lc = homeLifecycle(store);
  const oi = homeOrdersInfo(store);
  const bank = homeBankInfo(org);
  const close = homeCloseInfo(store);
  const cards = [];
  if (!lc.archived) {
    if (lc.draft) {
      if (((store.products || []).length) === 0) {
        cards.push({ tone: "red", navTab: "products", kind: "products", title: "Add a product before you launch", detail: "Customers need at least one thing to buy", action: "Go to Products" });
      } else {
        cards.push({ tone: "blue", kind: "launch", title: "Your store is ready to launch", detail: "Customers can start ordering as soon as you do", action: "Launch store" });
      }
      if (!String(store.shipStreet || "").trim()) {
        cards.push({ tone: "red", navTab: "general", kind: "settings-store", title: "Add a delivery address before orders can ship", detail: "Orders ship to the team manager, and there's no address on file yet", action: "Add address" });
      }
    } else {
      if (lc.open && (store.storeType || "league") === "league" && org) {
        const gatedNames = []; const gatedIds = {}; let target = null;
        (org.groups || []).forEach(function (g) {
          if (((org.modes || {})[g.id] || "league") !== "teams") return;
          const missing = (g.rosters || []).filter(function (r) { return !managerComplete((org.managers || {})[r.id]); });
          if (missing.length) { gatedNames.push(g.name); gatedIds[String(g.id).toLowerCase()] = true; if (!target) target = { groupId: g.id, rosterId: missing[0].id }; }
        });
        if (gatedNames.length) {
          const waiting = oi.pendingGroups.reduce(function (n, g) { return n + (gatedIds[String(g.shippingGroup || "").toLowerCase()] ? (g.rows || []).length : 0); }, 0);
          const names = gatedNames.length > 1 ? gatedNames.slice(0, -1).join(", ") + " and " + gatedNames[gatedNames.length - 1] : gatedNames[0];
          cards.push({ tone: "red", navTab: "general", kind: "assign", target: target,
            title: names + (gatedNames.length > 1 ? " need" : " needs") + " a manager before their orders can ship",
            detail: waiting ? waiting + " order" + (waiting === 1 ? " is" : "s are") + " waiting on this" : "Orders from these teams can't ship until a manager is assigned",
            action: "Assign managers" });
        }
      }
      const failed = homeFailedProducts(store);
      if (lc.open && failed.length) {
        cards.push({ tone: "red", navTab: "products", kind: "products",
          title: failed.length === 1 ? "Images failed for " + (failed[0].title || failed[0].name || "a product") : "Images failed for " + failed.length + " products",
          detail: (failed.length === 1 ? "It can't" : "They can't") + " go on the storefront until this is retried",
          action: "Retry" });
      }
      if (oi.pending > 0) {
        cards.push({ tone: "blue", kind: "pending", title: oi.pending + " pending order" + (oi.pending === 1 ? "" : "s") + " to submit", detail: "Oldest placed 3 days ago — orders reach the factory after you submit", action: "Go to Pending Orders" });
      }
      if (lc.open && bank.total > 0) {
        cards.push({ tone: "blue", kind: "bank", title: bank.total + " Roster Bank capture" + (bank.total === 1 ? "" : "s") + " awaiting review",
          detail: (store.storeType === "single") ? "Banked from storefront orders, not yet on this store's roster" : "Oldest captured 2 days ago — banked from storefront orders, not yet on a roster",
          action: "Open Roster Bank" });
      }
      if (lc.closed) {
        cards.push({ tone: "grey", kind: "report", link: true, title: "Your close report is ready", detail: "Totals, fundraising, and what shipped", action: "View report" });
        if (oi.submitted > 0) cards.push({ tone: "grey", kind: "orders", link: true, title: oi.submitted + " order" + (oi.submitted === 1 ? " is" : "s are") + " still being made", detail: "They'll ship as they're finished — nothing needed from you", action: "View orders" });
      }
      if (lc.open && close) {
        cards.push({ tone: "grey", kind: "schedule", link: true, title: "Ordering window closes " + close.label + " — " + close.daysLeft + " days left", detail: "Change the close date from the store schedule", action: "Edit Store Schedule" });
      }
    }
  }
  const rank = { red: 0, blue: 1, grey: 2 };
  cards.sort(function (a, b) { return rank[a.tone] - rank[b.tone]; });
  return { cards: cards, lc: lc, oi: oi, bank: bank, close: close };
}
// Red dot on a nav tab only when a red-rail card resolves to it.
function homeRedNavTabs(store, org) {
  const s = new Set();
  buildHomeAttention(store, org).cards.forEach(function (c) { if (c.tone === "red" && c.navTab) s.add(c.navTab); });
  return s;
}
function HomeLinkBtn({ label, onClick, muted }) {
  return (
    <button onClick={onClick} style={{ background: "transparent", border: 0, padding: 0, fontSize: 12, fontWeight: 700, color: muted ? "#6b6b72" : "#0e0e10", cursor: "pointer", fontFamily: "inherit", flexShrink: 0 }}>{label}</button>
  );
}
function HomeAttentionCard({ card, readOnly, onAction }) {
  const rail = card.tone === "red" ? "#e1251b" : card.tone === "blue" ? "#2563eb" : "#d4d4d8";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 14, background: "#fff", border: "1px solid #ececf0", borderLeft: "3px solid " + rail, borderRadius: 10, padding: "14px 18px" }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{card.title}</div>
        <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 2 }}>{card.detail}</div>
      </div>
      {!readOnly && (card.link ? (
        <button onClick={onAction} style={{ flexShrink: 0, background: "transparent", border: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit", padding: "8px 0" }}>{card.action} ›</button>
      ) : (
        <button onClick={onAction} style={{
          flexShrink: 0, background: card.tone === "red" ? "#0e0e10" : "#fff", color: card.tone === "red" ? "#fff" : "#0e0e10",
          border: "1px solid " + (card.tone === "red" ? "#0e0e10" : "#d4d4d8"), fontSize: 12, fontWeight: 700, borderRadius: 7,
          padding: "8px 14px", cursor: "pointer", fontFamily: "inherit"
        }}>{card.action}</button>
      ))}
    </div>
  );
}
function HomeTab({ store, org, readOnly, onGoTab, onPendingOrders, onAllOrders, onRosterBank, onManagers, onLaunch, onGoSettings, onUpdateStore }) {
  const model = buildHomeAttention(store, org);
  const lc = model.lc, oi = model.oi, bank = model.bank, close = model.close, cards = model.cards;
  const st = homeStructureInfo(org);
  const isLeague = (store.storeType || "league") === "league";
  const [showAll, setShowAll] = React.useState(false);
  const [copied, setCopied] = React.useState(false);
  const [copiedUrl, setCopiedUrl] = React.useState(false);
  const products = store.products || [];
  const failedProducts = homeFailedProducts(store);
  const slug = store.storeSlug || tcStoreSlug(store);
  const url = "prolook.com/store/" + slug;
  const raised = lc.draft ? 0 : (store.revenue || (store.seeded ? 3810 : 0));
  const fmtMoney = function (n) { return "$" + Math.round(n).toLocaleString("en-US"); };
  const run = function (card) {
    if (readOnly) return;
    if (card.kind === "products") onGoTab("products");
    else if (card.kind === "launch") onLaunch();
    else if (card.kind === "settings-store") onGoSettings("store");
    else if (card.kind === "assign") onManagers(card.target);
    else if (card.kind === "pending") onPendingOrders();
    else if (card.kind === "bank") onRosterBank();
    else if (card.kind === "schedule") onGoSettings("schedule");
    else if (card.kind === "report") window.dispatchEvent(new CustomEvent("closereport:open", { detail: { layer: "summary" } }));
    else if (card.kind === "orders") onAllOrders();
  };
  const copyUrl = function () {
    try { navigator.clipboard && navigator.clipboard.writeText("https://" + url); } catch (e) {}
    setCopiedUrl(true); setTimeout(function () { setCopiedUrl(false); }, 1500);
  };
  const visible = showAll ? cards : cards.slice(0, 5);
  const hiddenCount = cards.length - visible.length;

  const pill = lc.archived ? { label: "Archived", bg: "#f1f1f3", color: "#6b6b72", dot: "#9a9aa1" }
    : lc.closed ? { label: "Closed", bg: "#fdf3d3", color: "#8a6408", dot: "#d9a514" }
    : lc.open ? { label: "Open", bg: "#d8f5e3", color: "#1f7a44", dot: "#1f9d55" }
    : { label: "Draft", bg: "#dbeafe", color: "#1d4ed8", dot: "#3b82f6" };

  // Manager panel rows — the record buyers see is tagged Point of Contact
  // (the exact name of the setting it feeds).
  const prefText = function (p) {
    const s = String(p || "").toLowerCase();
    if (s.indexOf("email") >= 0 && s.indexOf("phone") >= 0) return "Prefers email or phone";
    if (s.indexOf("phone") >= 0) return "Prefers phone";
    if (s.indexOf("email") >= 0) return "Prefers email";
    return null;
  };
  const primaryMgr = { name: store.managerName || store.shipName || "Team Manager", email: store.email || "", phone: store.phone || "", pref: prefText(store.contactPref), poc: true };
  const extras = [];
  const seen = {}; seen[(primaryMgr.email || "").toLowerCase()] = true;
  Object.keys((org && org.managers) || {}).forEach(function (k) {
    const m = org.managers[k]; if (!m) return;
    const nm = m.name || [m.firstName, m.lastName].filter(Boolean).join(" ");
    const em = String(m.email || "").toLowerCase();
    if (!nm || !em || seen[em]) return;
    seen[em] = true;
    extras.push({ name: nm, email: m.email, phone: m.phone, pref: null, poc: false });
  });
  const managerRows = [primaryMgr].concat(extras.slice(0, 3));

  // Recently worked on — activity trail. Absent when there is nothing to show
  // (the normal case on a Draft store). Rows read Open ›, never Resume.
  const trail = (!store.seeded || lc.draft) ? [] : isLeague ? [
    { name: "Division 7 → U12 Blue — roster", when: "2 hours ago", tabLabel: "My Teams", tab: "roster", icon: "users" },
    { name: "Fan Gear — pricing", when: "Yesterday", tabLabel: "Products", tab: "products", icon: "shirt" },
    { name: "Announcement message", when: "Monday", tabLabel: "Settings", tab: "general", icon: "settings" }
  ] : [
    { name: "Home Jersey — pricing", when: "2 hours ago", tabLabel: "My Team", tab: "roster", icon: "shirt" },
    { name: "Imported 4 players", when: "Yesterday", tabLabel: "My Team", tab: "roster", icon: "users" },
    { name: "Store banner image", when: "Monday", tabLabel: "Settings", tab: "general", icon: "settings" }
  ];
  const trailIcon = function (kind) {
    if (kind === "shirt") return <IconShirt size={15} />;
    if (kind === "settings") return <IconSettings size={15} />;
    return <IconUsers size={15} />;
  };

  const groupCaptures = function (g) { return (g.rosters || []).reduce(function (n, r) { return n + (bank.byTeam[r.id] || 0); }, 0); };

  const defaultTheme = (store.teamColors && store.teamColors[1]) || null;
  const themeColor = store.primaryColor || defaultTheme || "#e1251b";
  const themeCustom = !!(defaultTheme && store.primaryColor && String(store.primaryColor).toLowerCase() !== String(defaultTheme).toLowerCase());

  const storeRows = [
    { id: "roster", label: isLeague ? "My Teams" : "My Team", sub: st.players + " players", extra: bank.total ? { text: bank.total + " Roster Bank capture" + (bank.total === 1 ? "" : "s"), color: "#2563eb" } : null },
    { id: "products", label: "Products", sub: products.length + " products", extra: failedProducts.length ? { text: failedProducts.length + " render failed", color: "#b81d14" } : null },
    { id: "orders", label: "Orders", sub: (oi.total) + " orders", extra: oi.pending ? { text: oi.pending + " to submit", color: "#2563eb" } : null },
    { id: "payouts", label: "Reports", sub: "Store analytics" }
  ];

  const panelStyle = { background: "#fff", border: "1px solid #ececf0", borderRadius: 10, overflow: "hidden" };
  const sectionTitle = { fontSize: 15, fontWeight: 800, color: "#0e0e10" };

  return (
    <div data-screen-label="Home" style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Status strip — the one place amber is allowed (canonical Closed pill). */}
      <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap", background: "#fff", border: "1px solid #ececf0", borderRadius: 10, padding: "12px 18px" }}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 7, background: pill.bg, color: pill.color, borderRadius: 999, padding: "5px 12px", fontSize: 12, fontWeight: 700 }}>
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: pill.dot }} />{pill.label}
        </span>
        {lc.open && close && <span style={{ fontSize: 12.5, color: "#52525a" }}>Closes <strong style={{ color: "#0e0e10" }}>{close.label}</strong> · {close.daysLeft} days left</span>}
        {lc.closed && close && <span style={{ fontSize: 12.5, color: "#52525a" }}>Closed <strong style={{ color: "#0e0e10" }}>{close.label}</strong></span>}
        {!lc.draft && <span style={{ width: 1, height: 16, background: "#e6e6ea" }} />}
        {!lc.draft && <span style={{ fontSize: 12.5, color: "#52525a" }}><strong style={{ color: "#0e0e10" }}>{oi.total}</strong> orders · <strong style={{ color: "#0e0e10" }}>{fmtMoney(raised)}</strong> raised{lc.open ? " this window" : ""}</span>}
        <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12, color: "#6b6b72", background: "#f6f6f8", borderRadius: 7, padding: "6px 10px" }}>
          <span style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "#9a9aa1" }}>Code</span>
          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontWeight: 700, letterSpacing: ".08em", color: "#0e0e10" }}>{storeCodeOf(store)}</span>
          {!readOnly && <button onClick={function () { try { navigator.clipboard && navigator.clipboard.writeText(storeCodeOf(store)); } catch (e) {} setCopied(true); setTimeout(function () { setCopied(false); }, 1500); }} style={{ background: "transparent", border: 0, padding: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>{copied ? "Copied" : "Copy"}</button>}
        </span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12, color: "#6b6b72", background: "#f6f6f8", borderRadius: 7, padding: "6px 10px" }}>
          {url}
          {!readOnly && <button onClick={copyUrl} style={{ background: "transparent", border: 0, padding: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>{copiedUrl ? "Copied" : "Copy link"}</button>}
        </span>
        </span>
      </div>

      <div style={{ display: "flex", gap: 20, alignItems: "flex-start" }}>
        {/* Main column */}
        <div style={{ flex: 1.65, display: "flex", flexDirection: "column", gap: 20, minWidth: 0 }}>
          {/* Needs your attention — always renders, even empty. */}
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={sectionTitle}>Needs your attention</span>
              {cards.length > 0 && <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", minWidth: 20, height: 20, borderRadius: 999, background: "#e1251b", color: "#fff", fontSize: 11.5, fontWeight: 800, padding: "0 6px" }}>{cards.length}</span>}
            </div>
            {visible.map(function (card, i) { return <HomeAttentionCard key={i} card={card} readOnly={readOnly} onAction={function () { run(card); }} />; })}
            {hiddenCount > 0 && (
              <button onClick={function () { setShowAll(true); }} style={{ alignSelf: "flex-start", background: "transparent", border: 0, padding: "2px 4px", fontSize: 12, fontWeight: 700, color: "#6b6b72", cursor: "pointer", fontFamily: "inherit" }}>{hiddenCount} more</button>
            )}
            {cards.length === 0 && (
              <div style={{ background: "#fff", border: "1px solid #ececf0", borderRadius: 10, padding: "16px 18px", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>
                {lc.archived ? "This store is archived and read-only — nothing is awaiting action." : lc.open ? "Nothing needs your attention right now. The store is open and taking orders." : "Nothing needs your attention right now."}
              </div>
            )}
          </div>

          {/* Recently worked on — absent entirely when there is nothing to show. */}
          {trail.length > 0 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <span style={sectionTitle}>Recently worked on</span>
              <div style={panelStyle}>
                {trail.map(function (r, i) { return (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 18px", borderBottom: i < trail.length - 1 ? "1px solid #f2f2f5" : "none" }}>
                    <span style={{ width: 30, height: 30, borderRadius: 7, background: "#f4f4f5", display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#52525a", flexShrink: 0 }}>{trailIcon(r.icon)}</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>{r.name}</div>
                      <div style={{ fontSize: 11.5, color: "#9a9aa1" }}>{r.when} · {r.tabLabel}</div>
                    </div>
                    <HomeLinkBtn label="Open ›" onClick={function () { onGoTab(r.tab); }} />
                  </div>
                ); })}
              </div>
            </div>
          )}

          {/* Manager panel */}
          <div style={panelStyle}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "14px 18px", borderBottom: "1px solid #f2f2f5" }}>
              <span style={{ fontSize: 13.5, fontWeight: 800, color: "#0e0e10" }}>{isLeague ? "League Manager Information" : "Team Manager Information"}</span>
              {!readOnly && (
                <button onClick={function () { onManagers(null); }} style={{ background: "#fff", border: "1px solid #d4d4d8", fontSize: 11.5, fontWeight: 700, borderRadius: 7, padding: "6px 12px", cursor: "pointer", fontFamily: "inherit", color: "#0e0e10" }}>Add manager</button>
              )}
            </div>
            {managerRows.map(function (m, i) { return (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 18px", borderBottom: "1px solid #f2f2f5" }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{m.name}</span>
                    {m.poc && <span style={{ fontSize: 10, fontWeight: 700, color: "#6b6b72", background: "#f4f4f5", borderRadius: 4, padding: "2px 6px" }}>Point of Contact</span>}
                  </div>
                  <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 2 }}>{[m.email, m.phone, m.pref].filter(Boolean).join(" · ") || "No contact details yet"}</div>
                </div>
                {!readOnly && (
                  <span style={{ display: "inline-flex", gap: 14, flexShrink: 0 }}>
                    {!m.poc && <HomeLinkBtn label="Invite" onClick={function () { onGoSettings("store"); }} />}
                    <HomeLinkBtn label="Edit ›" onClick={function () { m.poc ? onGoSettings("store") : onManagers(null); }} />
                  </span>
                )}
              </div>
            ); })}
            <div style={{ padding: "12px 18px", background: "#fafafb", fontSize: 11.5, color: "#6b6b72", lineHeight: 1.55 }}>
              Adding a manager creates a contact record only — it does not grant portal access. Send invites from <strong style={{ color: "#0e0e10", cursor: readOnly ? "default" : "pointer" }} onClick={function () { if (!readOnly) onGoSettings("store"); }}>Settings → People &amp; Access</strong>.
            </div>
          </div>
        </div>

        {/* Right rail */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 14, minWidth: 0 }}>
          {/* In your store — one row per tab; first row matches the nav label exactly. */}
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <span style={sectionTitle}>In your store</span>
            <div style={panelStyle}>
              {storeRows.map(function (row, i) { return (
                <React.Fragment key={row.id}>
                  <div onClick={function () { if (!readOnly) onGoTab(row.id); }} style={{ display: "flex", alignItems: "center", gap: 12, padding: (row.id === "products" && products.length > 0) ? "14px 18px 10px" : "14px 18px", borderBottom: (i < storeRows.length - 1 && !(row.id === "products" && products.length > 0)) ? "1px solid #f2f2f5" : "none", cursor: readOnly ? "default" : "pointer" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{row.label}</div>
                      <div style={{ fontSize: 11.5, color: "#9a9aa1" }}>{row.sub}{row.extra && <span> · <span style={{ color: row.extra.color, fontWeight: 700 }}>{row.extra.text}</span></span>}</div>
                    </div>
                    <span style={{ color: "#b9b9c2", fontWeight: 700 }}>›</span>
                  </div>
                  {row.id === "products" && products.length > 0 && (
                    <div style={{ padding: "0 18px 14px", display: "flex", gap: 8, borderBottom: i < storeRows.length - 1 ? "1px solid #f2f2f5" : "none" }}>
                      {products.slice(0, 4).map(function (p, j) { return <span key={j} style={{ width: 44, height: 50, borderRadius: 6, background: "#f0f0f3" }} />; })}
                      {products.length > 4 && <span style={{ width: 44, height: 50, borderRadius: 6, background: "#f6f6f8", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, color: "#6b6b72" }}>+{products.length - 4}</span>}
                    </div>
                  )}
                </React.Fragment>
              ); })}
            </div>
          </div>

          {/* League structure — League stores only; bounded so it can't push the attention list off screen. */}
          {isLeague && (
            <div style={panelStyle}>
              <div style={{ padding: "14px 18px", borderBottom: "1px solid #f2f2f5" }}>
                <div style={{ fontSize: 13.5, fontWeight: 800, color: "#0e0e10" }}>League structure</div>
                <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 2 }}>{st.divisions} division{st.divisions === 1 ? "" : "s"} · {st.teams} team{st.teams === 1 ? "" : "s"} · {st.players} player{st.players === 1 ? "" : "s"}</div>
              </div>
              <div style={{ maxHeight: 300, overflowY: "auto" }}>
                {st.groups.length === 0 && st.loose.length === 0 && (
                  <div style={{ padding: "16px 18px", fontSize: 12, color: "#9a9aa1", lineHeight: 1.5 }}>No divisions yet — build the structure from {"My Teams"}.</div>
                )}
                {st.groups.map(function (g, i) { const caps = groupCaptures(g); return (
                  <div key={g.id} onClick={function () { if (!readOnly) onRosterBank(); }} style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 18px", borderBottom: "1px solid #f2f2f5", cursor: readOnly ? "default" : "pointer" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{g.name}</div>
                      <div style={{ fontSize: 11.5, color: "#9a9aa1" }}>{(g.rosters || []).length} teams · {(g.rosters || []).reduce(function (n, r) { return n + (r.players || 0); }, 0)} players{caps > 0 && <span> · <span style={{ color: "#2563eb", fontWeight: 700 }}>{caps} capture{caps === 1 ? "" : "s"}</span></span>}</div>
                    </div>
                    <span style={{ color: "#b9b9c2", fontWeight: 700 }}>›</span>
                  </div>
                ); })}
                {st.loose.map(function (r, i) { const caps = bank.byTeam[r.id] || 0; return (
                  <div key={r.id} onClick={function () { if (!readOnly) onRosterBank(); }} style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 18px", borderBottom: i < st.loose.length - 1 ? "1px solid #f2f2f5" : "none", cursor: readOnly ? "default" : "pointer" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{r.name} <span style={{ fontSize: 10, fontWeight: 700, color: "#6b6b72", background: "#f4f4f5", borderRadius: 4, padding: "2px 6px", marginLeft: 4 }}>STANDALONE</span></div>
                      <div style={{ fontSize: 11.5, color: "#9a9aa1" }}>{r.players || 0} players{caps > 0 && <span> · <span style={{ color: "#2563eb", fontWeight: 700 }}>{caps} capture{caps === 1 ? "" : "s"}</span></span>}</div>
                    </div>
                    <span style={{ color: "#b9b9c2", fontWeight: 700 }}>›</span>
                  </div>
                ); })}
              </div>
            </div>
          )}

          {/* Brand assets — editable after launch; only Archived locks it. */}
          <div style={panelStyle}>
            <div style={{ padding: "14px 18px", borderBottom: "1px solid #f2f2f5", fontSize: 13.5, fontWeight: 800, color: "#0e0e10" }}>Brand assets</div>
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 18px", borderBottom: "1px solid #f2f2f5" }}>
              <TeamEmblem store={store} size={34} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 700, color: "#0e0e10" }}>Team Logo</div>
                <div style={{ fontSize: 11, color: "#9a9aa1" }}>From the workspace logo library</div>
              </div>
              {!readOnly && <HomeLinkBtn label="Edit ›" onClick={function () { onGoSettings("store"); }} />}
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 18px", borderBottom: "1px solid #f2f2f5" }}>
              <span style={{ display: "inline-flex", gap: 6 }}>
                <span style={{ width: 22, height: 22, borderRadius: 5, background: (store.teamColors && store.teamColors[0]) || "#e1e2dd", border: "1px solid #ececf0" }} />
                <span style={{ width: 22, height: 22, borderRadius: 5, background: (store.teamColors && store.teamColors[1]) || "#f4f4f5", border: "1px solid #ececf0" }} />
              </span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 700, color: "#0e0e10" }}>Team Colors</div>
              </div>
              {!readOnly && <HomeLinkBtn label="Edit ›" onClick={function () { onGoSettings("store"); }} />}
            </div>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "12px 18px", borderBottom: "1px solid #f2f2f5" }}>
              <span style={{ width: 22, height: 22, borderRadius: 5, background: themeColor, flexShrink: 0, marginTop: 2, border: "1px solid #ececf0" }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 12.5, fontWeight: 700, color: "#0e0e10" }}>Store Theme Color</span>
                  <span style={{ fontSize: 10, fontWeight: 700, color: "#6b6b72", background: "#f4f4f5", borderRadius: 4, padding: "2px 6px" }}>{themeCustom ? "Custom" : "Team default"}</span>
                </div>
                <div style={{ fontSize: 11, color: "#9a9aa1", marginTop: 2 }}>Applies to storefront buttons and accents only.</div>
                {themeCustom && !readOnly && (
                  <div onClick={function () { onUpdateStore && onUpdateStore({ primaryColor: defaultTheme }); }} style={{ fontSize: 11.5, fontWeight: 700, marginTop: 4, cursor: "pointer", color: "#0e0e10" }}>Reset to team color</div>
                )}
              </div>
              {!readOnly && <HomeLinkBtn label="Edit ›" onClick={function () { onGoSettings("customization"); }} />}
            </div>
            <div onClick={function () { if (!readOnly) onGoSettings("store"); }} style={{ padding: "12px 18px", fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: readOnly ? "default" : "pointer" }}>
              Store logos <span style={{ fontWeight: 500, color: "#9a9aa1" }}>— picked from the workspace logo library</span> ›
            </div>
          </div>

          <div style={{ background: "#f6f6f8", borderRadius: 10, padding: "14px 18px", fontSize: 12, color: "#6b6b72", lineHeight: 1.55 }}>
            Need orientation? <strong style={{ color: "#0e0e10", cursor: "pointer" }} onClick={function () { window.dispatchEvent(new CustomEvent("setupguide:open")); }}>Reopen the setup guide</strong>.
          </div>
        </div>
      </div>
    </div>
  );
}


/* ===== Marucci Phase 1 — Workspace Settings sections + Store Code ===== */

// ── shared bits ──
const WS_MONO = "'JetBrains Mono', ui-monospace, monospace";
function WsToast({ text }) {
  if (!text) return null;
  return <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", background: "#0e0e10", color: "#fff", padding: "12px 20px", borderRadius: 8, fontSize: 12.5, boxShadow: "0 12px 32px rgba(9,9,11,.25)", zIndex: 700 }}>{text}</div>;
}
function useWsToast() {
  const [toast, setToast] = React.useState(null);
  React.useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 2600); return () => clearTimeout(t); }, [toast]);
  return [toast, setToast];
}
function WsSectionHead({ title, desc, right }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 24, marginBottom: 18 }}>
      <div style={{ minWidth: 0 }}>
        <h3 style={{ margin: "0 0 4px", fontSize: 17, fontWeight: 800, fontFamily: "Archivo, sans-serif", color: "#09090b" }}>{title}</h3>
        {desc && <p style={{ fontSize: 13, color: "#71717a", margin: 0, maxWidth: 640, lineHeight: 1.55 }}>{desc}</p>}
      </div>
      {right && <div style={{ flexShrink: 0, display: "flex", gap: 10, alignItems: "center" }}>{right}</div>}
    </div>
  );
}
function WsSearch({ value, onChange, placeholder, width = 260 }) {
  return (
    <div style={{ position: "relative", width }}>
      <span style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", color: "#9a9aa1", display: "inline-flex" }}><IconSearch size={14} /></span>
      <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} style={{ width: "100%", height: 38, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 12px 0 32px", fontSize: 13, fontFamily: "inherit", outline: "none", background: "#fff" }} />
    </div>
  );
}
function WsSelect({ value, onChange, options, width = 160, style }) {
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} style={{ height: 38, width, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 10px", fontSize: 13, fontFamily: "inherit", outline: "none", background: "#fff", color: "#0e0e10", ...style }}>
      {options.map((o) => <option key={o.value === undefined ? o : o.value} value={o.value === undefined ? o : o.value}>{o.label === undefined ? o : o.label}</option>)}
    </select>
  );
}
function WsPill({ text, tone = "grey" }) {
  const m = { grey: ["#f1f1f3", "#3f3f46"], green: ["#e7f5ed", "#1f7a44"], red: ["#fdecea", "#b81d14"], blue: ["#eef3fb", "#1e40af"], amber: ["#fdf3d3", "#8a6408"], dark: ["#0e0e10", "#fff"] };
  const [bg, fg] = m[tone] || m.grey;
  return <span style={{ display: "inline-flex", alignItems: "center", fontSize: 11, fontWeight: 700, color: fg, background: bg, borderRadius: 999, padding: "3px 9px", whiteSpace: "nowrap" }}>{text}</span>;
}
function WsSync({ when = "Today, 6:02 AM", source = "ERP" }) {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, color: "#6b6b72" }}>
      <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#1f9d55" }} />Synced from {source} · {when}
    </span>
  );
}
function WsTh({ children, style }) { return <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".07em", color: "#9a9aa1", textTransform: "uppercase", ...style }}>{children}</span>; }
function WsBtn({ children, onClick, primary, danger, small, disabled, style }) {
  return (
    <button type="button" disabled={disabled} onClick={onClick} style={{ background: primary ? "#0e0e10" : "#fff", color: primary ? "#fff" : danger ? "#b81d14" : "#0e0e10", border: "1px solid " + (primary ? "#0e0e10" : "#d4d4d8"), borderRadius: 6, padding: small ? "7px 12px" : "10px 16px", fontSize: small ? 12 : 13, fontWeight: 700, cursor: disabled ? "not-allowed" : "pointer", fontFamily: "inherit", opacity: disabled ? .5 : 1, display: "inline-flex", alignItems: "center", gap: 8, whiteSpace: "nowrap", ...style }}>{children}</button>
  );
}
function WsField({ label, children, hint }) {
  return (
    <label style={{ display: "block" }}>
      <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 6 }}>{label}</span>
      {children}
      {hint && <span style={{ display: "block", fontSize: 11.5, color: "#9a9aa1", marginTop: 6, lineHeight: 1.5 }}>{hint}</span>}
    </label>
  );
}
const WS_INPUT = { width: "100%", height: 40, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 12px", fontSize: 13.5, fontFamily: "inherit", outline: "none", background: "#fff" };
function WsMenu({ items }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef(null);
  React.useEffect(() => { if (!open) return; const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); }; document.addEventListener("mousedown", h); return () => document.removeEventListener("mousedown", h); }, [open]);
  return (
    <div ref={ref} style={{ position: "relative", display: "inline-flex" }}>
      <button type="button" onClick={() => setOpen((o) => !o)} style={{ width: 30, height: 30, borderRadius: 6, border: "1px solid #ececf0", background: open ? "#f4f4f5" : "#fff", color: "#52525b", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 16, lineHeight: 1, letterSpacing: 1 }}>···</button>
      {open && (
        <div style={{ position: "absolute", right: 0, top: "calc(100% + 4px)", zIndex: 60, background: "#fff", border: "1px solid #e4e4e7", borderRadius: 8, boxShadow: "0 8px 24px rgba(20,20,30,.12)", padding: 4, minWidth: 200 }}>
          {items.filter(Boolean).map((it, i) => (
            <div key={i} onClick={() => { setOpen(false); it.onClick && it.onClick(); }} style={{ padding: "9px 12px", fontSize: 13, cursor: "pointer", borderRadius: 5, color: it.danger ? "#b81d14" : "#0e0e10", fontWeight: 600 }}
              onMouseEnter={(e) => e.currentTarget.style.background = "#f4f4f5"} onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>{it.label}</div>
          ))}
        </div>
      )}
    </div>
  );
}

// ══════════════════ G1/G2 · User Management ══════════════════
const WS_ROLES = [
  { id: "admin", label: "Admin", desc: "Full workspace control — settings, pricing, users, every store." },
  { id: "rep", label: "Rep", desc: "Builds and runs stores. Sees own stores, orders and commission." },
  { id: "manager", label: "Team Manager", desc: "Reports and rosters for assigned stores only." },
];
window.__wsUsers = window.__wsUsers || [
  { id: "u1", name: "Dana Whitfield", email: "dana@marucci.com", role: "admin", status: "active", last: "Today, 8:14 AM" },
  { id: "u2", name: "Jake Morrison", email: "jake.m@marucci.com", role: "rep", status: "active", last: "Today, 7:52 AM" },
  { id: "u3", name: "Priya Natarajan", email: "priya@marucci.com", role: "admin", status: "active", last: "Yesterday" },
  { id: "u4", name: "Sam Okafor", email: "sam.o@marucci.com", role: "rep", status: "active", last: "Sep 26" },
  { id: "u5", name: "Coach Rivera", email: "rivera@tigersbaseball.org", role: "manager", status: "active", last: "Sep 25", stores: ["Tigers Baseball Org", "Tigers 14U", "Lady Tigers 12U"] },
  { id: "u6", name: "Tom Delgado", email: "tom@tigers14u.org", role: "manager", status: "active", last: "Sep 22", stores: ["Tigers 14U"] },
  { id: "u7", name: "Alex Chen", email: "alex.chen@marucci.com", role: "rep", status: "invited", last: "—" },
  { id: "u8", name: "Marcus Hale", email: "m.hale@marucci.com", role: "rep", status: "deactivated", last: "Jul 30" },
];
function WsAvatar({ name, size = 32 }) {
  const ini = String(name || "?").split(/\s+/).map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  return <span style={{ width: size, height: size, borderRadius: "50%", background: "#f1f1f3", color: "#0e0e10", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: size * .36, fontWeight: 800, flexShrink: 0 }}>{ini}</span>;
}
function UserManagementSection({ stores }) {
  const [users, setUsers] = React.useState(() => window.__wsUsers.slice());
  const sync = (next) => { window.__wsUsers = next; setUsers(next); };
  const [q, setQ] = React.useState("");
  const [role, setRole] = React.useState("all");
  const [status, setStatus] = React.useState("all");
  const [invite, setInvite] = React.useState(false);
  const [editUser, setEditUser] = React.useState(null);
  const [confirm, setConfirm] = React.useState(null);
  const [toast, setToast] = useWsToast();
  const [shopperQ, setShopperQ] = React.useState("");
  const shoppers = [
    { name: "Maria Alvarez", email: "maria.alvarez@gmail.com", stores: "Tigers 14U · Lady Tigers 12U", via: "Email" },
    { name: "Denise Park", email: "dpark88@yahoo.com", stores: "Tigers 14U", via: "Interpro" },
    { name: "Luis Ortega", email: "l.ortega@outlook.com", stores: "Bayshore Bulldogs", via: "Email" },
  ];
  const storeNames = React.useMemo(() => Array.from(new Set(["Tigers Baseball Org", "Tigers 14U", "Lady Tigers 12U", ...((stores || []).map((s) => s.storeTitle || s.teamName).filter(Boolean))])), [stores]);
  const rows = users.filter((u) => (role === "all" || u.role === role) && (status === "all" || u.status === status) && (!q || (u.name + " " + u.email).toLowerCase().includes(q.toLowerCase())));
  const roleLabel = (r) => (WS_ROLES.find((x) => x.id === r) || {}).label || r;
  const statusPill = (s) => s === "active" ? <WsPill text="Active" tone="green" /> : s === "invited" ? <WsPill text="Invited" tone="blue" /> : <WsPill text="Deactivated" tone="grey" />;
  const shopperRows = shoppers.filter((s) => !shopperQ || (s.name + s.email).toLowerCase().includes(shopperQ.toLowerCase()));
  const doInvite = (u) => { sync([{ id: "u" + Date.now(), ...u, status: "invited", last: "—" }, ...users]); setInvite(false); setToast("Invitation sent to " + u.email); };
  const saveRole = (u) => { sync(users.map((x) => x.id === u.id ? u : x)); setEditUser(null); setToast(u.name + " is now " + roleLabel(u.role)); };
  const act = () => {
    if (!confirm) return;
    if (confirm.kind === "reset") setToast("Password reset sent to " + confirm.user.email);
    if (confirm.kind === "deactivate") { sync(users.map((x) => x.id === confirm.user.id ? { ...x, status: "deactivated" } : x)); setToast(confirm.user.name + " deactivated"); }
    if (confirm.kind === "reactivate") { sync(users.map((x) => x.id === confirm.user.id ? { ...x, status: "active" } : x)); setToast(confirm.user.name + " reactivated"); }
    if (confirm.kind === "resend") setToast("Invitation re-sent to " + confirm.user.email);
    setConfirm(null);
  };
  const grid = "minmax(200px,1.4fr) minmax(200px,1.4fr) 130px 120px 120px 40px";
  return (
    <div>
      <WsSectionHead title="User Management" desc="Workspace accounts live in Team Stores. Invite reps and admins, give team managers a scoped view of their stores, and unblock anyone with a password reset." right={<WsBtn primary onClick={() => setInvite(true)}><IconPlus size={14} style={{ strokeWidth: 2.4 }} /> Invite user</WsBtn>} />
      <div style={{ display: "flex", gap: 10, marginBottom: 14, alignItems: "center", flexWrap: "wrap" }}>
        <WsSearch value={q} onChange={setQ} placeholder="Search name or email" />
        <WsSelect value={role} onChange={setRole} options={[{ value: "all", label: "All roles" }, ...WS_ROLES.map((r) => ({ value: r.id, label: r.label }))]} />
        <WsSelect value={status} onChange={setStatus} options={[{ value: "all", label: "Any status" }, { value: "active", label: "Active" }, { value: "invited", label: "Invited" }, { value: "deactivated", label: "Deactivated" }]} />
        <span style={{ marginLeft: "auto", fontSize: 12.5, color: "#9a9aa1" }}>{rows.length} of {users.length} users</span>
      </div>
      <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, overflow: "hidden" }}>
        <div style={{ display: "grid", gridTemplateColumns: grid, gap: 12, alignItems: "center", padding: "10px 18px", borderBottom: "1px solid #ececf0", background: "#fafafb" }}>
          <WsTh>User</WsTh><WsTh>Email</WsTh><WsTh>Role</WsTh><WsTh>Status</WsTh><WsTh>Last sign-in</WsTh><span />
        </div>
        {rows.length === 0 && <div style={{ padding: "32px 18px", textAlign: "center", fontSize: 13, color: "#9a9aa1" }}>No users match.</div>}
        {rows.map((u, i) => (
          <div key={u.id} style={{ display: "grid", gridTemplateColumns: grid, gap: 12, alignItems: "center", padding: "12px 18px", borderBottom: i < rows.length - 1 ? "1px solid #f4f4f5" : "none", opacity: u.status === "deactivated" ? .6 : 1 }}>
            <span style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
              <WsAvatar name={u.name} />
              <span style={{ minWidth: 0 }}>
                <span style={{ display: "block", fontSize: 13.5, fontWeight: 700, color: "#0e0e10", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{u.name}</span>
                {u.role === "manager" && <span style={{ display: "block", fontSize: 11.5, color: "#9a9aa1", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{(u.stores || []).length} store{(u.stores || []).length === 1 ? "" : "s"} · {(u.stores || []).join(", ")}</span>}
              </span>
            </span>
            <span style={{ fontSize: 13, color: "#52525b", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{u.email}</span>
            <span><WsPill text={roleLabel(u.role)} tone={u.role === "admin" ? "dark" : "grey"} /></span>
            <span>{statusPill(u.status)}</span>
            <span style={{ fontSize: 12.5, color: "#6b6b72" }}>{u.last}</span>
            <WsMenu items={[
              { label: "Edit role & access", onClick: () => setEditUser({ ...u, stores: (u.stores || []).slice() }) },
              u.status === "invited" ? { label: "Resend invitation", onClick: () => setConfirm({ kind: "resend", user: u }) } : { label: "Send password reset", onClick: () => setConfirm({ kind: "reset", user: u }) },
              u.status === "deactivated" ? { label: "Reactivate", onClick: () => setConfirm({ kind: "reactivate", user: u }) } : { label: "Deactivate", danger: true, onClick: () => setConfirm({ kind: "deactivate", user: u }) },
            ]} />
          </div>
        ))}
      </div>

      <div style={{ marginTop: 32 }}>
        <WsSectionHead title="Storefront shoppers" desc="Consumer accounts are created on the storefront. You can't edit them here, but you can send a password reset when a parent is locked out." />
        <div style={{ display: "flex", gap: 10, marginBottom: 12 }}><WsSearch value={shopperQ} onChange={setShopperQ} placeholder="Search shopper by email" width={320} /></div>
        <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, overflow: "hidden" }}>
          {shopperRows.map((s, i) => (
            <div key={s.email} style={{ display: "grid", gridTemplateColumns: "minmax(180px,1.2fr) minmax(200px,1.4fr) minmax(160px,1.4fr) 90px 150px", gap: 12, alignItems: "center", padding: "12px 18px", borderBottom: i < shopperRows.length - 1 ? "1px solid #f4f4f5" : "none" }}>
              <span style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{s.name}</span>
              <span style={{ fontSize: 13, color: "#52525b" }}>{s.email}</span>
              <span style={{ fontSize: 12.5, color: "#6b6b72" }}>{s.stores}</span>
              <span><WsPill text={s.via} tone={s.via === "Interpro" ? "blue" : "grey"} /></span>
              <span style={{ textAlign: "right" }}>{s.via === "Interpro" ? <span style={{ fontSize: 11.5, color: "#9a9aa1" }}>Managed by Interpro</span> : <WsBtn small onClick={() => setToast("Password reset sent to " + s.email)}>Send password reset</WsBtn>}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Invite / edit modal */}
      <UserInviteModal open={invite} onClose={() => setInvite(false)} onSubmit={doInvite} storeNames={storeNames} />
      <UserInviteModal open={!!editUser} user={editUser} onClose={() => setEditUser(null)} onSubmit={saveRole} storeNames={storeNames} />

      <Modal open={!!confirm} onClose={() => setConfirm(null)} width={460}>
        {confirm && (
          <React.Fragment>
            <div style={{ padding: "28px 28px 8px" }}>
              <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>
                {confirm.kind === "reset" ? "Send password reset?" : confirm.kind === "deactivate" ? "Deactivate " + confirm.user.name + "?" : confirm.kind === "reactivate" ? "Reactivate " + confirm.user.name + "?" : "Resend invitation?"}
              </h2>
              <p style={{ margin: "12px 0 0", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>
                {confirm.kind === "reset" ? "A reset link goes to " + confirm.user.email + " and expires in 24 hours. Their current password keeps working until they use it."
                  : confirm.kind === "deactivate" ? "They lose access immediately. Stores, orders and commission history they created stay in place. You can reactivate them later."
                  : confirm.kind === "reactivate" ? "Access is restored with the same role and store assignments."
                  : "A fresh invitation link goes to " + confirm.user.email + ". The earlier link stops working."}
              </p>
            </div>
            <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
              <Button variant="secondary" onClick={() => setConfirm(null)}>Cancel</Button>
              <Button variant="primary" onClick={act}>{confirm.kind === "reset" ? "Send reset" : confirm.kind === "deactivate" ? "Deactivate" : confirm.kind === "reactivate" ? "Reactivate" : "Resend"}</Button>
            </div>
          </React.Fragment>
        )}
      </Modal>
      <WsToast text={toast} />
    </div>
  );
}
function UserInviteModal({ open, user, onClose, onSubmit, storeNames }) {
  const [name, setName] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [role, setRole] = React.useState("rep");
  const [sel, setSel] = React.useState([]);
  const [sq, setSq] = React.useState("");
  React.useEffect(() => { if (open) { setName(user ? user.name : ""); setEmail(user ? user.email : ""); setRole(user ? user.role : "rep"); setSel(user ? (user.stores || []) : []); setSq(""); } }, [open]);
  const ok = /\S+@\S+\.\S+/.test(email) && (role !== "manager" || sel.length > 0);
  const toggle = (n) => setSel((s) => s.includes(n) ? s.filter((x) => x !== n) : [...s, n]);
  return (
    <Modal open={open} onClose={onClose} width={520}>
      <div style={{ padding: "28px 28px 4px" }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{user ? "Edit role & access" : "Invite user"}</h2>
        <p style={{ margin: "8px 0 20px", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>{user ? "Changes apply the next time they sign in." : "They get an email with a link to set a password. No Customizer account is needed."}</p>
        <div style={{ display: "grid", gap: 14 }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <WsField label="Name"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="Optional" style={WS_INPUT} /></WsField>
            <WsField label="Email"><input value={email} disabled={!!user} onChange={(e) => setEmail(e.target.value)} placeholder="name@marucci.com" style={{ ...WS_INPUT, background: user ? "#fafafb" : "#fff" }} /></WsField>
          </div>
          <div>
            <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 6 }}>Role</span>
            <div style={{ display: "grid", gap: 8 }}>
              {WS_ROLES.map((r) => (
                <label key={r.id} onClick={() => setRole(r.id)} style={{ display: "flex", alignItems: "flex-start", gap: 12, border: "1px solid " + (role === r.id ? "#0e0e10" : "#e4e4e7"), borderRadius: 8, padding: "11px 14px", cursor: "pointer", background: role === r.id ? "#fafafb" : "#fff" }}>
                  <span style={{ width: 16, height: 16, borderRadius: "50%", border: "2px solid " + (role === r.id ? "#0e0e10" : "#c4c4c8"), background: role === r.id ? "#0e0e10" : "#fff", boxShadow: role === r.id ? "inset 0 0 0 3px #fff" : "none", flexShrink: 0, marginTop: 1 }} />
                  <span><span style={{ display: "block", fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{r.label}</span><span style={{ display: "block", fontSize: 12, color: "#6b6b72", marginTop: 2 }}>{r.desc}</span></span>
                </label>
              ))}
            </div>
          </div>
          {role === "manager" && (
            <div>
              <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 6 }}>Stores they can see</span>
              <div style={{ border: "1px solid #e4e4e7", borderRadius: 8, overflow: "hidden" }}>
                <div style={{ padding: 8, borderBottom: "1px solid #f4f4f5" }}><WsSearch value={sq} onChange={setSq} placeholder="Search stores" width="100%" /></div>
                <div style={{ maxHeight: 180, overflowY: "auto" }}>
                  {storeNames.filter((n) => !sq || n.toLowerCase().includes(sq.toLowerCase())).map((n) => (
                    <div key={n} style={{ padding: "8px 12px", borderBottom: "1px solid #f8f8f9" }}><Checkbox checked={sel.includes(n)} onChange={() => toggle(n)} size={15} label={<span style={{ fontSize: 13, color: "#0e0e10" }}>{n}</span>} /></div>
                  ))}
                </div>
              </div>
              <span style={{ display: "block", fontSize: 11.5, color: "#9a9aa1", marginTop: 6, lineHeight: 1.5 }}>Team managers see Reports and My Team for these stores only. Picking an organization's store includes its affiliates.</span>
            </div>
          )}
        </div>
      </div>
      <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
        <Button variant="secondary" onClick={onClose}>Cancel</Button>
        <Button variant="primary" disabled={!ok} onClick={() => ok && onSubmit(user ? { ...user, name: name || user.name, role, stores: role === "manager" ? sel : undefined } : { name: name || email.split("@")[0], email, role, stores: role === "manager" ? sel : undefined })}>{user ? "Save" : "Send invitation"}</Button>
      </div>
    </Modal>
  );
}

// ══════════════════ Pricing Tiers · code-based ══════════════════
// Tiers are ordered high → low price. Shoppers pay Retail unless they enter a
// store / team code on the storefront; each code carries one tier. Commission on
// a sale is the spread between the tier paid and the tier directly below it.
window.__wsTiers = window.__wsTiers || [
  { id: "retail", name: "Retail", desc: "No code. Fans, walk-up parents and anyone browsing the public storefront.", off: 0, source: "erp" },
  { id: "booster", name: "Booster / Sponsor", desc: "Supporters and sponsors the team hands a code to.", off: 10, source: "erp" },
  { id: "team", name: "Team / Player", desc: "Rostered players and parents. Default for store and team codes.", off: 18, source: "erp" },
  { id: "coach", name: "Coach & Staff", desc: "Coaches, managers and staff.", off: 28, source: "erp" },
  { id: "base", name: "Base", desc: "Marucci cost floor. Nothing sells below this.", off: 40, source: "erp" },
];
// code → tier id. Codes not listed here fall back to the "team" tier.
window.__wsCodeTiers = window.__wsCodeTiers || { KNCOACH: "coach", KNBOOST: "booster" };
// Extra codes a rep mints for a tier (beyond store / team codes), per store.
window.__wsExtraCodes = window.__wsExtraCodes || [
  { code: "KNCOACH", storeId: null, storeName: "Knights Knation Baseball", label: "Coaching staff" },
  { code: "KNBOOST", storeId: null, storeName: "Knights Knation Baseball", label: "Booster club" },
];
function wsCodeTierId(code) { const c = String(code || "").toUpperCase(); if (!c) return "retail"; const t = window.__wsCodeTiers[c]; const tiers = window.__wsTiers || []; return t && tiers.some((x) => x.id === t) ? t : (tiers.some((x) => x.id === "team") ? "team" : (tiers[1] || tiers[0] || {}).id); }
function wsSetCodeTier(code, tierId) { window.__wsCodeTiers = { ...(window.__wsCodeTiers || {}), [String(code).toUpperCase()]: tierId }; }
// Every code in the workspace: store codes, team codes (registered by store dashboards) and extra codes.
window.__wsTeamCodeRegistry = window.__wsTeamCodeRegistry || {};
function wsAllCodes(stores) {
  const out = [];
  (stores || window.__tsAllStores || []).forEach((s) => {
    out.push({ code: storeCodeOf(s), kind: "store", storeId: s.id, storeName: s.storeTitle || s.teamName || "Store", label: "Store code" });
    (window.__wsTeamCodeRegistry[s.id] || []).forEach((t) => out.push({ code: t.code, kind: "team", storeId: s.id, storeName: s.storeTitle || s.teamName || "Store", label: t.name + (t.division ? " · " + t.division : "") }));
  });
  (window.__wsExtraCodes || []).forEach((x) => out.push({ code: x.code, kind: "extra", storeId: x.storeId, storeName: x.storeName, label: x.label }));
  const seen = new Set();
  return out.filter((c) => { if (seen.has(c.code)) return false; seen.add(c.code); return true; });
}
const WS_SAMPLE_SKUS = [{ name: "CATX Connect BBCOR", msrp: 399 }, { name: "Team Jersey (sublimated)", msrp: 90 }, { name: "Batting Gloves", msrp: 35 }];
function tierPrice(tier, msrp) { return Math.round(msrp * (1 - (tier.off || 0) / 100)); }
function tierBelow(tiers, id) { const i = tiers.findIndex((t) => t.id === id); return i >= 0 && i < tiers.length - 1 ? tiers[i + 1] : null; }

function PricingTiersSection({ stores }) {
  const [view, setView] = React.useState("tiers");
  const [tiers, setTiersState] = React.useState(() => window.__wsTiers.map((t) => ({ ...t })));
  const setTiers = (n) => { window.__wsTiers = n; setTiersState(n); };
  const [codeTiers, setCodeTiersState] = React.useState(() => ({ ...window.__wsCodeTiers }));
  const setCodeTier = (code, tid) => { wsSetCodeTier(code, tid); setCodeTiersState({ ...window.__wsCodeTiers }); };
  const [extras, setExtrasState] = React.useState(() => window.__wsExtraCodes.slice());
  const setExtras = (n) => { window.__wsExtraCodes = n; setExtrasState(n); };
  const [toast, setToast] = useWsToast();
  const [editTier, setEditTier] = React.useState(null);
  const [newCode, setNewCode] = React.useState(null); // { code, storeId, label, tier }
  const [q, setQ] = React.useState("");
  const [kindF, setKindF] = React.useState("all");
  const [tierF, setTierF] = React.useState("all");
  const [sel, setSel] = React.useState({});
  const tierName = (id) => (tiers.find((t) => t.id === id) || {}).name || "—";
  const codes = React.useMemo(() => wsAllCodes(stores).map((c) => ({ ...c, tier: wsCodeTierId(c.code) })), [stores, codeTiers, extras]);
  const counts = React.useMemo(() => { const c = {}; codes.forEach((x) => { c[x.tier] = (c[x.tier] || 0) + 1; }); return c; }, [codes]);
  const rows = codes.filter((c) => (kindF === "all" || c.kind === kindF) && (tierF === "all" || c.tier === tierF) && (!q || (c.code + " " + c.storeName + " " + c.label).toLowerCase().includes(q.toLowerCase())));
  const selIds = Object.keys(sel).filter((k) => sel[k]);
  const move = (i, d) => { const n = tiers.slice(); const j = i + d; if (j < 0 || j >= n.length) return; [n[i], n[j]] = [n[j], n[i]]; setTiers(n); };
  const saveTier = (t) => { setTiers(t.id && tiers.some((x) => x.id === t.id) ? tiers.map((x) => x.id === t.id ? t : x) : [...tiers, { ...t, id: "t" + Date.now(), source: "local" }]); setEditTier(null); setToast(t.name + " saved — prices update in every store"); };
  const subTabs = [{ id: "tiers", label: "Tiers" }, { id: "codes", label: "Codes" }];
  const exSku = WS_SAMPLE_SKUS[1];
  const kindPill = (k) => k === "store" ? <WsPill text="Store code" tone="dark" /> : k === "team" ? <WsPill text="Team code" /> : <WsPill text="Pricing code" tone="blue" />;
  const storeOptions = (stores || []).map((s) => ({ value: s.id, label: s.storeTitle || s.teamName || "Store" }));
  const codeClean = (v) => String(v || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 16);
  const codeExists = (c) => codes.some((x) => x.code === c);
  return (
    <div>
      <WsSectionHead title="Pricing Tiers" desc="Shoppers pay Retail unless they enter a code on the storefront. Every store and team code carries a tier — anyone who enters it sees that tier's prices. Commission is the spread between the tier paid and the one below it." />
      <div style={{ display: "inline-flex", background: "#f1f1f3", borderRadius: 8, padding: 3, marginBottom: 20 }}>
        {subTabs.map((t) => <button key={t.id} type="button" onClick={() => setView(t.id)} style={{ border: 0, background: view === t.id ? "#fff" : "transparent", color: view === t.id ? "#0e0e10" : "#6b6b72", borderRadius: 6, padding: "8px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit", boxShadow: view === t.id ? "0 1px 2px rgba(20,20,30,.08)" : "none" }}>{t.label}</button>)}
      </div>

      {view === "tiers" && (
        <React.Fragment>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
            <span style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".08em", color: "#0e0e10", textTransform: "uppercase" }}>Tiers · highest price first</span>
            <WsBtn small onClick={() => setEditTier({ name: "", desc: "", off: 15 })}><IconPlus size={13} style={{ strokeWidth: 2.4 }} /> Add tier</WsBtn>
          </div>
          <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, overflow: "hidden", marginBottom: 20 }}>
            <div style={{ display: "grid", gridTemplateColumns: "40px minmax(200px,1.6fr) 110px 120px 130px 40px", gap: 12, alignItems: "center", padding: "10px 18px", borderBottom: "1px solid #ececf0", background: "#fafafb" }}>
              <span /><WsTh>Tier</WsTh><WsTh>Off retail</WsTh><WsTh>{exSku.name.split(" ")[0]} jersey</WsTh><WsTh>Codes</WsTh><span />
            </div>
            {tiers.map((t, i) => {
              const below = tierBelow(tiers, t.id);
              const comm = below ? tierPrice(below, exSku.msrp) - tierPrice(t, exSku.msrp) : 0;
              const isRetail = t.id === "retail";
              return (
                <div key={t.id} style={{ display: "grid", gridTemplateColumns: "40px minmax(200px,1.6fr) 110px 120px 130px 40px", gap: 12, alignItems: "center", padding: "12px 18px", borderBottom: i < tiers.length - 1 ? "1px solid #f4f4f5" : "none" }}>
                  <span style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                    <button type="button" onClick={() => move(i, -1)} disabled={i === 0} style={{ border: 0, background: "transparent", cursor: i === 0 ? "default" : "pointer", color: i === 0 ? "#d4d4d8" : "#6b6b72", padding: 0, fontSize: 11, lineHeight: 1 }}>▲</button>
                    <button type="button" onClick={() => move(i, 1)} disabled={i === tiers.length - 1} style={{ border: 0, background: "transparent", cursor: i === tiers.length - 1 ? "default" : "pointer", color: i === tiers.length - 1 ? "#d4d4d8" : "#6b6b72", padding: 0, fontSize: 11, lineHeight: 1 }}>▼</button>
                  </span>
                  <span style={{ minWidth: 0 }}>
                    <span style={{ display: "flex", alignItems: "center", gap: 8 }}><span style={{ fontSize: 14, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>{t.name}</span>{t.source === "erp" ? <WsPill text="ERP" /> : <WsPill text="Team Stores" tone="blue" />}{t.id === "team" && <WsPill text="Default for codes" tone="green" />}</span>
                    <span style={{ display: "block", fontSize: 12, color: "#6b6b72", marginTop: 2 }}>{t.desc}</span>
                  </span>
                  <span style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{t.off}%</span>
                  <span style={{ fontSize: 13 }}><span style={{ fontWeight: 700, color: "#0e0e10" }}>${tierPrice(t, exSku.msrp)}</span>{below && <span style={{ display: "block", fontSize: 11, color: "#1f7a44", fontWeight: 700 }}>{comm >= 0 ? "$" + Math.abs(comm) + " commission" : "below " + below.name}</span>}</span>
                  <span style={{ fontSize: 12.5, color: "#52525b" }}>{isRetail ? <span style={{ color: "#9a9aa1" }}>No code needed</span> : counts[t.id] ? counts[t.id] + " code" + (counts[t.id] === 1 ? "" : "s") : <span style={{ color: "#9a9aa1" }}>None</span>}</span>
                  <WsMenu items={[{ label: "Edit tier", onClick: () => setEditTier({ ...t }) }, !isRetail && { label: "View codes", onClick: () => { setView("codes"); setTierF(t.id); } }, !isRetail && { label: "Mint a code for this tier", onClick: () => setNewCode({ code: "", storeId: storeOptions[0] ? storeOptions[0].value : null, label: "", tier: t.id }) }, t.source !== "erp" && !counts[t.id] && { label: "Delete tier", danger: true, onClick: () => { setTiers(tiers.filter((x) => x.id !== t.id)); setToast(t.name + " deleted"); } }]} />
                </div>
              );
            })}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
            <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: 18 }}>
              <div style={{ fontSize: 13.5, fontWeight: 800, color: "#0e0e10", marginBottom: 4 }}>Price by tier · sample SKUs</div>
              <div style={{ fontSize: 12, color: "#9a9aa1", marginBottom: 12 }}>What each tier pays today. Product pages show the same numbers.</div>
              <div style={{ display: "grid", gridTemplateColumns: "1.4fr " + tiers.map(() => "1fr").join(" "), gap: 8, alignItems: "center" }}>
                <span /><React.Fragment>{tiers.map((t) => <WsTh key={t.id} style={{ textAlign: "right" }}>{t.name.split(" ")[0]}</WsTh>)}</React.Fragment>
                {WS_SAMPLE_SKUS.map((s) => (
                  <React.Fragment key={s.name}>
                    <span style={{ fontSize: 12.5, fontWeight: 600, color: "#0e0e10" }}>{s.name}</span>
                    {tiers.map((t) => <span key={t.id} style={{ fontSize: 13, textAlign: "right", fontFamily: WS_MONO, color: "#0e0e10" }}>${tierPrice(t, s.msrp)}</span>)}
                  </React.Fragment>
                ))}
              </div>
            </div>
            <div style={{ background: "#0e0e10", color: "#fff", borderRadius: 10, padding: 18 }}>
              <div style={{ fontSize: 13.5, fontWeight: 800, marginBottom: 4 }}>How codes and commission work</div>
              <div style={{ fontSize: 12.5, color: "rgba(255,255,255,.7)", lineHeight: 1.6, marginBottom: 14 }}>A parent opens the storefront and sees the ${exSku.msrp} jersey at Retail. They enter the team code from their coach and the price drops to the Team / Player tier. Your commission is the spread between what they paid and the tier below.</div>
              {(() => { const team = tiers.find((t) => t.id === "team") || tiers[1] || tiers[0]; const below = tierBelow(tiers, team.id) || team; const ret = tierPrice(tiers.find((t) => t.id === "retail") || tiers[0], exSku.msrp); const tp = tierPrice(team, exSku.msrp); const comm = Math.max(tierPrice(below, exSku.msrp) - tp, 0); return (
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
                  {[["No code", "$" + ret], ["With team code", "$" + tp], ["Commission", "$" + Math.abs(comm)]].map(([l, v]) => <div key={l} style={{ background: "rgba(255,255,255,.08)", borderRadius: 8, padding: "10px 12px" }}><div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "rgba(255,255,255,.6)" }}>{l}</div><div style={{ fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif", marginTop: 2 }}>{v}</div></div>)}
                </div>); })()}
              <div style={{ fontSize: 11.5, color: "rgba(255,255,255,.55)", marginTop: 12 }}>Fundraising adds on top of the tier price and reports separately.</div>
            </div>
          </div>
        </React.Fragment>
      )}

      {view === "codes" && (
        <React.Fragment>
          <div style={{ display: "flex", gap: 10, marginBottom: 14, alignItems: "center", flexWrap: "wrap" }}>
            <WsSearch value={q} onChange={setQ} placeholder="Search codes or stores" />
            <WsSelect value={kindF} onChange={setKindF} options={[{ value: "all", label: "All codes" }, { value: "store", label: "Store codes" }, { value: "team", label: "Team codes" }, { value: "extra", label: "Pricing codes" }]} width={160} />
            <WsSelect value={tierF} onChange={setTierF} options={[{ value: "all", label: "Any tier" }, ...tiers.filter((t) => t.id !== "retail").map((t) => ({ value: t.id, label: t.name }))]} />
            <span style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
              <WsBtn small primary onClick={() => setNewCode({ code: "", storeId: storeOptions[0] ? storeOptions[0].value : null, label: "", tier: "coach" })}><IconPlus size={13} style={{ strokeWidth: 2.4 }} /> Mint pricing code</WsBtn>
            </span>
          </div>
          {selIds.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 14, background: "#0e0e10", color: "#fff", borderRadius: 8, padding: "10px 16px", marginBottom: 10 }}>
              <span style={{ fontSize: 13, fontWeight: 700 }}>{selIds.length} code{selIds.length === 1 ? "" : "s"} selected</span>
              <span style={{ display: "flex", gap: 8, marginLeft: "auto", alignItems: "center" }}>
                <WsSelect value="" onChange={(v) => { if (!v) return; selIds.forEach((c) => wsSetCodeTier(c, v)); setCodeTiersState({ ...window.__wsCodeTiers }); setSel({}); setToast(selIds.length + " code" + (selIds.length === 1 ? "" : "s") + " moved to " + tierName(v)); }} options={[{ value: "", label: "Move to tier…" }, ...tiers.filter((t) => t.id !== "retail").map((t) => ({ value: t.id, label: t.name }))]} width={180} style={{ height: 32, fontSize: 12 }} />
                <button type="button" onClick={() => setSel({})} style={{ background: "transparent", border: 0, color: "rgba(255,255,255,.7)", fontSize: 12, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Clear</button>
              </span>
            </div>
          )}
          <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, overflow: "hidden" }}>
            <div style={{ display: "grid", gridTemplateColumns: "32px 150px minmax(200px,1.4fr) minmax(160px,1fr) 190px 40px", gap: 12, alignItems: "center", padding: "10px 18px", borderBottom: "1px solid #ececf0", background: "#fafafb" }}>
              <Checkbox checked={rows.length > 0 && rows.every((r) => sel[r.code])} onChange={(v) => setSel(v ? Object.fromEntries(rows.map((r) => [r.code, true])) : {})} size={15} />
              <WsTh>Code</WsTh><WsTh>Used for</WsTh><WsTh>Store</WsTh><WsTh>Pricing tier</WsTh><span />
            </div>
            {rows.length === 0 && <div style={{ padding: "32px 18px", textAlign: "center", fontSize: 13, color: "#9a9aa1" }}>No codes yet. Store codes appear once a store is created; team codes come from My Teams.</div>}
            {rows.map((c, i) => (
              <div key={c.code} style={{ display: "grid", gridTemplateColumns: "32px 150px minmax(200px,1.4fr) minmax(160px,1fr) 190px 40px", gap: 12, alignItems: "center", padding: "10px 18px", borderBottom: i < rows.length - 1 ? "1px solid #f4f4f5" : "none", background: sel[c.code] ? "#fafafb" : "#fff" }}>
                <Checkbox checked={!!sel[c.code]} onChange={(v) => setSel((s) => ({ ...s, [c.code]: v }))} size={15} />
                <span style={{ fontFamily: WS_MONO, fontWeight: 700, letterSpacing: ".08em", color: "#0e0e10", fontSize: 13.5 }}>{c.code}</span>
                <span style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>{kindPill(c.kind)}<span style={{ fontSize: 12.5, color: "#52525b", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.label}</span></span>
                <span style={{ fontSize: 12.5, color: "#52525b", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.storeName}</span>
                <WsSelect value={c.tier} onChange={(v) => { setCodeTier(c.code, v); setToast(c.code + " → " + tierName(v)); }} options={tiers.filter((t) => t.id !== "retail").map((t) => ({ value: t.id, label: t.name + " · " + t.off + "% off" }))} width="100%" style={{ height: 34, fontSize: 12.5 }} />
                <WsMenu items={[{ label: "Copy code", onClick: () => { try { navigator.clipboard && navigator.clipboard.writeText(c.code); } catch (e) {} setToast(c.code + " copied"); } }, c.kind === "extra" && { label: "Delete code", danger: true, onClick: () => { setExtras(extras.filter((x) => x.code !== c.code)); setToast(c.code + " deleted — it stops working on the storefront"); } }]} />
              </div>
            ))}
          </div>
          <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 10, lineHeight: 1.5 }}>Store and team codes are managed on each store (Settings → Store Code, My Teams). Changing a code's tier applies to new orders only.</div>
        </React.Fragment>
      )}

      {/* Tier editor */}
      <Modal open={!!editTier} onClose={() => setEditTier(null)} width={520}>
        {editTier && (
          <React.Fragment>
            <div style={{ padding: "28px 28px 4px" }}>
              <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{editTier.id ? "Edit " + editTier.name : "New tier"}</h2>
              {editTier.source === "erp" && <p style={{ margin: "8px 0 0", fontSize: 12.5, color: "#6b6b72", lineHeight: 1.55 }}>This tier's price list comes from the ERP. Edits here override it in Team Stores until the next sync replaces them.</p>}
              <div style={{ display: "grid", gap: 14, marginTop: 18 }}>
                <WsField label="Name"><input value={editTier.name} onChange={(e) => setEditTier({ ...editTier, name: e.target.value })} style={WS_INPUT} /></WsField>
                <WsField label="Description"><input value={editTier.desc} onChange={(e) => setEditTier({ ...editTier, desc: e.target.value })} placeholder="Who this tier is for" style={WS_INPUT} /></WsField>
                <WsField label="Discount off retail" hint={"A $" + exSku.msrp + " jersey is $" + tierPrice(editTier, exSku.msrp) + " at this tier."}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <input type="range" min={0} max={60} value={editTier.off} onChange={(e) => setEditTier({ ...editTier, off: +e.target.value })} style={{ flex: 1, accentColor: "#0e0e10" }} />
                    <span style={{ display: "inline-flex", alignItems: "center", border: "1px solid #d4d4d8", borderRadius: 6, height: 38, padding: "0 10px", width: 80, boxSizing: "border-box" }}><input type="number" min={0} max={60} value={editTier.off} onChange={(e) => setEditTier({ ...editTier, off: Math.max(0, Math.min(60, +e.target.value || 0)) })} style={{ width: "100%", border: 0, outline: 0, fontSize: 13.5, fontFamily: "inherit" }} /><span style={{ fontSize: 13, color: "#6b6b72" }}>%</span></span>
                  </div>
                </WsField>
              </div>
            </div>
            <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
              <Button variant="secondary" onClick={() => setEditTier(null)}>Cancel</Button>
              <Button variant="primary" disabled={!editTier.name.trim()} onClick={() => saveTier(editTier)}>Save tier</Button>
            </div>
          </React.Fragment>
        )}
      </Modal>

      {/* Mint a pricing code */}
      <Modal open={!!newCode} onClose={() => setNewCode(null)} width={500}>
        {newCode && (() => { const c = codeClean(newCode.code); const dup = codeExists(c); const ok = c.length >= 4 && !dup && newCode.tier; const st = (stores || []).find((s) => s.id === newCode.storeId); return (
          <React.Fragment>
            <div style={{ padding: "28px 28px 4px" }}>
              <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>Mint a pricing code</h2>
              <p style={{ margin: "8px 0 18px", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>A code the team hands to a specific group — coaches, boosters, sponsors. Anyone who enters it on the storefront sees that tier's prices.</p>
              <div style={{ display: "grid", gap: 14 }}>
                <WsField label="Code" hint={c.length < 4 ? "At least 4 letters or numbers" : dup ? c + " is already in use" : c + " is available"}>
                  <input autoFocus value={newCode.code} onChange={(e) => setNewCode({ ...newCode, code: e.target.value })} placeholder="KNCOACH" style={{ ...WS_INPUT, fontFamily: WS_MONO, fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", border: "1px solid " + (newCode.code && (dup || c.length < 4) ? "#e1251b" : "#d4d4d8") }} />
                </WsField>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <WsField label="Store"><WsSelect width="100%" value={newCode.storeId || ""} onChange={(v) => setNewCode({ ...newCode, storeId: v })} options={storeOptions} style={{ height: 40 }} /></WsField>
                  <WsField label="Pricing tier"><WsSelect width="100%" value={newCode.tier} onChange={(v) => setNewCode({ ...newCode, tier: v })} options={tiers.filter((t) => t.id !== "retail").map((t) => ({ value: t.id, label: t.name + " · " + t.off + "% off" }))} style={{ height: 40 }} /></WsField>
                </div>
                <WsField label="Who gets this code"><input value={newCode.label} onChange={(e) => setNewCode({ ...newCode, label: e.target.value })} placeholder="Coaching staff" style={WS_INPUT} /></WsField>
              </div>
            </div>
            <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
              <Button variant="secondary" onClick={() => setNewCode(null)}>Cancel</Button>
              <Button variant="primary" disabled={!ok} onClick={() => { if (!ok) return; setExtras([...extras, { code: c, storeId: newCode.storeId, storeName: st ? (st.storeTitle || st.teamName) : "—", label: newCode.label || tierName(newCode.tier) }]); wsSetCodeTier(c, newCode.tier); setCodeTiersState({ ...window.__wsCodeTiers }); setNewCode(null); setView("codes"); setToast(c + " minted → " + tierName(newCode.tier)); }}>Mint code</Button>
            </div>
          </React.Fragment>); })()}
      </Modal>
      <WsToast text={toast} />
    </div>
  );
}

// ══════════════════ E2 · Logo Library (synced from ERP) ══════════════════
const WS_LOGO_SEED = (() => {
  const orgsL = ["Tigers Baseball Org", "Tigers 14U", "Lady Tigers 12U", "Bayshore Bulldogs", "Gulf Coast Storm", "Red Stick Softball", "Storm 12U", "Bulldogs 16U Elite"];
  const kinds = ["Primary", "Wordmark", "Secondary", "Cap mark", "Alternate"];
  const colors = ["#1d3a8a", "#e1251b", "#0e0e10", "#1f9d55", "#7c3aed", "#b45309", "#0f766e", "#be123c"];
  const out = [];
  for (let i = 0; i < 28; i++) {
    const o = orgsL[i % orgsL.length]; const k = kinds[i % kinds.length];
    out.push({ id: "L" + (10420 + i * 7), name: o.split(" ")[0] + " " + k, org: o, color: colors[i % colors.length], ready: i % 5 !== 3, mono: o.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase(), updated: i % 3 === 0 ? "Today" : i % 3 === 1 ? "Sep 24" : "Aug 30" });
  }
  return out;
})();
window.__wsLogos = window.__wsLogos || WS_LOGO_SEED;
function LogoThumb({ logo, size = 56 }) {
  return <span style={{ width: size, height: size, borderRadius: 8, background: logo.color, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: size * .34, fontFamily: "Archivo, sans-serif", letterSpacing: ".02em", flexShrink: 0 }}>{logo.mono}</span>;
}
function LogoLibrarySection() {
  const logos = window.__wsLogos;
  const [q, setQ] = React.useState("");
  const [status, setStatus] = React.useState("all");
  const [orgF, setOrgF] = React.useState("all");
  const [open, setOpen] = React.useState(null);
  const [toast, setToast] = useWsToast();
  const orgsL = Array.from(new Set(logos.map((l) => l.org)));
  const rows = logos.filter((l) => (status === "all" || (status === "ready") === l.ready) && (orgF === "all" || l.org === orgF) && (!q || (l.name + l.org + l.id).toLowerCase().includes(q.toLowerCase())));
  const needs = logos.filter((l) => !l.ready).length;
  return (
    <div>
      <WsSectionHead title="Logo Library" desc="Every logo uploaded to the ERP, with its ID. Stores pick from this library — reps never upload their own files, so production always gets the approved artwork." right={<WsSync source="ERP" when="Today, 5:40 AM" />} />
      <div style={{ display: "flex", gap: 10, marginBottom: 14, alignItems: "center", flexWrap: "wrap" }}>
        <WsSearch value={q} onChange={setQ} placeholder="Search name, organization or ERP ID" width={300} />
        <WsSelect value={orgF} onChange={setOrgF} options={[{ value: "all", label: "All organizations" }, ...orgsL.map((o) => ({ value: o, label: o }))]} width={200} />
        <WsSelect value={status} onChange={setStatus} options={[{ value: "all", label: "Any status" }, { value: "ready", label: "Production-ready" }, { value: "needs", label: "Needs vector" }]} width={170} />
        <span style={{ marginLeft: "auto", fontSize: 12.5, color: "#9a9aa1" }}>{rows.length} of {logos.length} logos{needs ? " · " : ""}{needs ? <span style={{ color: "#b81d14", fontWeight: 700 }}>{needs} need vector</span> : null}</span>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: 12 }}>
        {rows.map((l) => (
          <div key={l.id} onClick={() => setOpen(l)} style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: 14, cursor: "pointer", display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 8 }}>
              <LogoThumb logo={l} />
              {l.ready ? <WsPill text="Production-ready" tone="green" /> : <WsPill text="Needs vector" tone="red" />}
            </div>
            <div>
              <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{l.name}</div>
              <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 2 }}>{l.org}</div>
              <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 4, fontFamily: WS_MONO }}>{l.id}</div>
            </div>
          </div>
        ))}
      </div>
      <div style={{ marginTop: 18, background: "#f6f6f8", borderRadius: 10, padding: "14px 18px", fontSize: 12.5, color: "#6b6b72", lineHeight: 1.55 }}>New logos are added in the ERP and appear here on the next sync. A product decorated with a <strong style={{ color: "#0e0e10" }}>Needs vector</strong> logo stays off the storefront until the art team marks it Production-ready.</div>
      <Modal open={!!open} onClose={() => setOpen(null)} width={520}>
        {open && (
          <React.Fragment>
            <div style={{ padding: "28px 28px 8px", display: "flex", gap: 18 }}>
              <LogoThumb logo={open} size={96} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{open.name}</h2>
                <div style={{ marginTop: 8, display: "grid", gridTemplateColumns: "110px 1fr", rowGap: 6, fontSize: 13 }}>
                  <span style={{ color: "#9a9aa1" }}>ERP ID</span><span style={{ fontFamily: WS_MONO, color: "#0e0e10" }}>{open.id}</span>
                  <span style={{ color: "#9a9aa1" }}>Organization</span><span style={{ color: "#0e0e10" }}>{open.org}</span>
                  <span style={{ color: "#9a9aa1" }}>Status</span><span>{open.ready ? <WsPill text="Production-ready" tone="green" /> : <WsPill text="Needs vector" tone="red" />}</span>
                  <span style={{ color: "#9a9aa1" }}>Updated</span><span style={{ color: "#0e0e10" }}>{open.updated}</span>
                  <span style={{ color: "#9a9aa1" }}>Used in</span><span style={{ color: "#0e0e10" }}>{open.ready ? "3 stores · 11 products" : "1 store · 2 products (held)"}</span>
                </div>
              </div>
            </div>
            <div style={{ padding: "16px 28px 24px", display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center" }}>
              <span style={{ fontSize: 12, color: "#9a9aa1" }}>Files are managed in the ERP.</span>
              <span style={{ display: "flex", gap: 10 }}><WsBtn onClick={() => { try { navigator.clipboard && navigator.clipboard.writeText(open.id); } catch (e) {} setToast("ERP ID " + open.id + " copied"); }}>Copy ERP ID</WsBtn><WsBtn primary onClick={() => setOpen(null)}>Done</WsBtn></span>
            </div>
          </React.Fragment>
        )}
      </Modal>
      <WsToast text={toast} />
    </div>
  );
}

// ══════════════════ I3 · Pick-up locations ══════════════════
window.__wsPickup = window.__wsPickup || [
  { id: "p1", name: "Marucci Baton Rouge", addr1: "5818 McCann Dr", city: "Baton Rouge", state: "LA", zip: "70809", hours: [["Mon – Fri", "9:00 AM – 5:00 PM"], ["Sat", "10:00 AM – 2:00 PM"], ["Sun", "Closed"]], enabled: true, note: "Ask for Team Stores pick-up at the front desk." },
];
function PickupLocationsSection() {
  const [locs, setLocsState] = React.useState(() => window.__wsPickup.map((l) => ({ ...l })));
  const setLocs = (n) => { window.__wsPickup = n; setLocsState(n); };
  const [edit, setEdit] = React.useState(null);
  const [toast, setToast] = useWsToast();
  return (
    <div>
      <WsSectionHead title="Pick-up Locations" desc="Places a shopper can collect an order instead of shipping. Each store turns pick-up on in its own Settings; checkout only offers it to shoppers in range." right={<WsBtn primary onClick={() => setEdit({ name: "", addr1: "", city: "", state: "LA", zip: "", hours: [["Mon – Fri", "9:00 AM – 5:00 PM"]], enabled: true, note: "", isNew: true })}><IconPlus size={14} style={{ strokeWidth: 2.4 }} /> Add location</WsBtn>} />
      <div style={{ display: "grid", gap: 12 }}>
        {locs.map((l) => (
          <div key={l.id} style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: "18px 20px", display: "flex", gap: 20, alignItems: "flex-start", opacity: l.enabled ? 1 : .6 }}>
            <span style={{ width: 44, height: 44, borderRadius: 10, background: "#f1f1f3", display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#0e0e10", flexShrink: 0 }}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M12 21s7-6.2 7-11a7 7 0 1 0-14 0c0 4.8 7 11 7 11z" /><circle cx="12" cy="10" r="2.5" /></svg></span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}><span style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>{l.name}</span>{l.enabled ? <WsPill text="Available to stores" tone="green" /> : <WsPill text="Off" />}</div>
              <div style={{ fontSize: 13, color: "#52525b", marginTop: 4 }}>{l.addr1}, {l.city}, {l.state} {l.zip}</div>
              <div style={{ display: "grid", gridTemplateColumns: "110px 1fr", rowGap: 3, marginTop: 10, fontSize: 12.5 }}>{l.hours.map(([d, h]) => <React.Fragment key={d}><span style={{ color: "#9a9aa1" }}>{d}</span><span style={{ color: "#0e0e10" }}>{h}</span></React.Fragment>)}</div>
              {l.note && <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 10 }}>{l.note}</div>}
              <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 10 }}>Used by <strong style={{ color: "#0e0e10" }}>{l.enabled ? 4 : 0} stores</strong> · Shopper range: <span style={{ color: "#9a9aa1" }}>to be configured</span></div>
            </div>
            <span style={{ display: "flex", gap: 10, alignItems: "center", flexShrink: 0 }}>
              <SettingsToggle value={l.enabled} onChange={(v) => { setLocs(locs.map((x) => x.id === l.id ? { ...x, enabled: v } : x)); setToast(l.name + (v ? " available to stores" : " turned off — stores using it fall back to shipping")); }} />
              <WsBtn small onClick={() => setEdit({ ...l, hours: l.hours.map((h) => h.slice()) })}>Edit</WsBtn>
            </span>
          </div>
        ))}
      </div>
      <Modal open={!!edit} onClose={() => setEdit(null)} width={540}>
        {edit && (
          <React.Fragment>
            <div style={{ padding: "28px 28px 4px" }}>
              <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{edit.isNew ? "Add pick-up location" : "Edit " + edit.name}</h2>
              <div style={{ display: "grid", gap: 14, marginTop: 18 }}>
                <WsField label="Location name"><input value={edit.name} onChange={(e) => setEdit({ ...edit, name: e.target.value })} style={WS_INPUT} /></WsField>
                <WsField label="Street address"><input value={edit.addr1} onChange={(e) => setEdit({ ...edit, addr1: e.target.value })} style={WS_INPUT} /></WsField>
                <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 12 }}>
                  <WsField label="City"><input value={edit.city} onChange={(e) => setEdit({ ...edit, city: e.target.value })} style={WS_INPUT} /></WsField>
                  <WsField label="State"><input value={edit.state} onChange={(e) => setEdit({ ...edit, state: e.target.value })} style={WS_INPUT} /></WsField>
                  <WsField label="ZIP"><input value={edit.zip} onChange={(e) => setEdit({ ...edit, zip: e.target.value })} style={WS_INPUT} /></WsField>
                </div>
                <div>
                  <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#0e0e10", marginBottom: 6 }}>Hours</span>
                  <div style={{ display: "grid", gap: 8 }}>
                    {edit.hours.map((h, i) => <div key={i} style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr 32px", gap: 8 }}><input value={h[0]} onChange={(e) => { const n = edit.hours.map((x) => x.slice()); n[i][0] = e.target.value; setEdit({ ...edit, hours: n }); }} style={{ ...WS_INPUT, height: 36 }} /><input value={h[1]} onChange={(e) => { const n = edit.hours.map((x) => x.slice()); n[i][1] = e.target.value; setEdit({ ...edit, hours: n }); }} style={{ ...WS_INPUT, height: 36 }} /><button type="button" onClick={() => setEdit({ ...edit, hours: edit.hours.filter((_, j) => j !== i) })} style={{ border: "1px solid #ececf0", background: "#fff", borderRadius: 6, cursor: "pointer", color: "#9a9aa1" }}>×</button></div>)}
                    <button type="button" onClick={() => setEdit({ ...edit, hours: [...edit.hours, ["", ""]] })} style={{ justifySelf: "start", background: "transparent", border: 0, padding: 0, fontSize: 12.5, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>+ Add hours</button>
                  </div>
                </div>
                <WsField label="Pick-up instructions" hint="Shown on the order confirmation and the Ready for pick-up email."><input value={edit.note} onChange={(e) => setEdit({ ...edit, note: e.target.value })} style={WS_INPUT} /></WsField>
              </div>
            </div>
            <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
              <Button variant="secondary" onClick={() => setEdit(null)}>Cancel</Button>
              <Button variant="primary" disabled={!edit.name.trim() || !edit.addr1.trim()} onClick={() => { const { isNew, ...rest } = edit; if (isNew) setLocs([...locs, { ...rest, id: "p" + Date.now() }]); else setLocs(locs.map((x) => x.id === edit.id ? rest : x)); setEdit(null); setToast(edit.name + " saved"); }}>{edit.isNew ? "Add location" : "Save"}</Button>
            </div>
          </React.Fragment>
        )}
      </Modal>
      <WsToast text={toast} />
    </div>
  );
}

// ══════════════════ L1/L2/L4, H3 · Emails split by platform ══════════════════
// Consumer transactional + shipping → Narvar. Marketing → Klaviyo. Rep-facing
// notifications stay in Team Stores. Templates for Narvar/Klaviyo edit there.
const WS_EMAIL_PLATFORM = { "Consumers": "Narvar" };
const WS_MARKETING_EMAILS = { group: "Marketing", note: "Sent through Klaviyo. Shoppers who turn off marketing email in their account are skipped automatically.", platform: "Klaviyo", rows: [
  { id: "abandon-24", name: "Abandoned Cart · 24 hours", purpose: "Cart left untouched for 24 hours — links straight back to the cart.", subject: "Still need the {{store}} package?", timing: "24 h after last cart activity" },
  { id: "abandon-48", name: "Abandoned Cart · 48 hours", purpose: "Second and final reminder, 48 hours after the cart was left.", subject: "Last look: your {{store}} cart", timing: "48 h after last cart activity" },
  { id: "store-launch", name: "Store Launch Announcement", purpose: "Sent to the organization's shopper list when a store opens.", subject: "{{store}} is open — shop team gear", timing: "When a store goes live" },
  { id: "campaign", name: "Campaigns & promotions", purpose: "Marketing-run sends (e.g. Back to the Diamond). Managed entirely in Klaviyo.", subject: "—", timing: "Scheduled by marketing" },
] };
function PlatformPill({ name }) {
  const tone = name === "Narvar" ? "blue" : name === "Klaviyo" ? "amber" : "grey";
  return <WsPill text={name} tone={tone} />;
}
function EmailsSectionV2() {
  const groups = React.useMemo(() => [...SYSTEM_EMAILS.map((g) => ({ ...g, platform: WS_EMAIL_PLATFORM[g.group] || "Team Stores" })), WS_MARKETING_EMAILS], []);
  const [state, setState] = React.useState(() => {
    if (!window.__sysEmailState) window.__sysEmailState = {};
    groups.forEach((g) => g.rows.forEach((r) => { if (!window.__sysEmailState[r.id]) window.__sysEmailState[r.id] = { on: true, subject: r.subject, body: r.body || "" }; }));
    return { ...window.__sysEmailState };
  });
  const patch = (id, p) => setState((s) => { const next = { ...s, [id]: { ...s[id], ...p } }; window.__sysEmailState = next; return next; });
  const allIds = React.useMemo(() => groups.flatMap((g) => g.rows.map((r) => r.id)), [groups]);
  const enabledCount = allIds.filter((id) => state[id] && state[id].on).length;
  const allOn = enabledCount === allIds.length;
  const setAll = (v) => { setState((s) => { const next = { ...s }; allIds.forEach((id) => { next[id] = { ...next[id], on: v }; }); window.__sysEmailState = next; return next; }); setToast(v ? "All emails enabled" : "All emails disabled — nothing will send"); };
  const [open, setOpen] = React.useState(null);
  const [toast, setToast] = useWsToast();
  const chev = (isOpen) => <span style={{ flexShrink: 0, color: "#9a9aa1", transform: isOpen ? "rotate(180deg)" : "none", transition: "transform .15s", display: "inline-flex" }}><svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6l5 5 5-5" /></svg></span>;
  return (
    <div>
      <WsSectionHead title="Emails" desc="Every email the platform sends, and which system sends it. Order and shipping emails go through Narvar, marketing through Klaviyo — their templates are edited there. Rep notifications are edited here." />
      <div style={{ display: "flex", gap: 10, marginBottom: 20, flexWrap: "wrap" }}>
        {[["Team Stores", "Rep & internal notifications"], ["Narvar", "Order, shipping & return emails"], ["Klaviyo", "Marketing & abandoned cart"]].map(([p, d]) => <span key={p} style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "#fff", border: "1px solid #e4e4e7", borderRadius: 999, padding: "6px 12px 6px 6px", fontSize: 12, color: "#52525b" }}><PlatformPill name={p} />{d}</span>)}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: "14px 20px", marginBottom: 24 }}>
        <span style={{ flex: 1, minWidth: 0 }}>
          <span style={{ display: "block", fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>All Emails</span>
          <span style={{ display: "block", fontSize: 12, color: "#9a9aa1", marginTop: 2 }}>{allOn ? "Every email is active." : enabledCount === 0 ? "Everything is paused — nothing will send from any platform." : enabledCount + " of " + allIds.length + " emails active."}</span>
        </span>
        {enabledCount === 0 && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: "#b81d14", background: "#fdecea", borderRadius: 999, padding: "3px 9px", flexShrink: 0 }}>ALL PAUSED</span>}
        <span style={{ flexShrink: 0, display: "inline-flex" }}><SettingsToggle value={enabledCount > 0} onChange={(v) => setAll(v)} /></span>
      </div>
      {groups.map((g) => (
        <div key={g.group} style={{ marginBottom: 24 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}><span style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".08em", color: "#0e0e10", textTransform: "uppercase" }}>{g.group}</span><PlatformPill name={g.platform} /></div>
          <div style={{ fontSize: 12, color: "#9a9aa1", marginBottom: 10 }}>{g.note}</div>
          <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, overflow: "hidden" }}>
            {g.rows.map((r, ri) => {
              const st = state[r.id] || { on: true, subject: r.subject, body: r.body || "" };
              const isOpen = open === r.id;
              const external = g.platform !== "Team Stores";
              return (
                <div key={r.id} style={{ borderTop: ri === 0 ? "none" : "1px solid #f4f4f5" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "13px 20px", cursor: "pointer", background: isOpen ? "#fafafa" : "#fff" }} onClick={() => setOpen(isOpen ? null : r.id)}>
                    <span style={{ flex: 1, minWidth: 0 }}>
                      <span style={{ display: "block", fontSize: 13.5, fontWeight: 700, color: st.on ? "#0e0e10" : "#9a9aa1" }}>{r.name}</span>
                      <span style={{ display: "block", fontSize: 12, color: "#9a9aa1", marginTop: 2 }}>{r.purpose}{r.timing ? " · " + r.timing : ""}</span>
                    </span>
                    {!st.on && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: "#6b6b72", background: "#f1f1f3", borderRadius: 999, padding: "3px 9px", flexShrink: 0 }}>DISABLED</span>}
                    <span onClick={(e) => e.stopPropagation()} style={{ flexShrink: 0, display: "inline-flex" }}><SettingsToggle value={st.on} onChange={(v) => { patch(r.id, { on: v }); setToast(r.name + (v ? " enabled" : " disabled")); }} /></span>
                    {chev(isOpen)}
                  </div>
                  {isOpen && (
                    <div style={{ padding: "4px 20px 18px", background: "#fafafa", borderTop: "1px solid #f4f4f5" }}>
                      {external ? (
                        <div style={{ display: "flex", alignItems: "center", gap: 16, paddingTop: 12 }}>
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa", marginBottom: 6 }}>Subject · from {g.platform}</div>
                            <div style={{ fontSize: 13, fontFamily: WS_MONO, color: "#0e0e10" }}>{st.subject}</div>
                            <div style={{ fontSize: 12, color: "#6b6b72", marginTop: 10, lineHeight: 1.55 }}>This template lives in {g.platform}. Team Stores sends the event and {g.platform} renders and delivers the email; the on/off switch here controls whether the event is sent at all.</div>
                          </div>
                          <WsBtn onClick={() => setToast("Opening " + g.platform + " template…")}>Edit in {g.platform} <IconExternal size={13} /></WsBtn>
                        </div>
                      ) : (
                        <React.Fragment>
                          <label style={{ display: "block", fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa", margin: "12px 0 6px" }}>Subject</label>
                          <input value={st.subject} onChange={(e) => patch(r.id, { subject: e.target.value })} style={{ width: "100%", boxSizing: "border-box", height: 38, border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 12px", fontSize: 13, fontFamily: WS_MONO, outline: "none", background: "#fff" }} />
                          <label style={{ display: "block", fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa", margin: "12px 0 6px" }}>Body</label>
                          <textarea value={st.body} onChange={(e) => patch(r.id, { body: e.target.value })} rows={Math.min(10, st.body.split("\n").length + 1)} style={{ width: "100%", boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "10px 12px", fontSize: 12.5, lineHeight: 1.6, fontFamily: WS_MONO, outline: "none", resize: "vertical", background: "#fff" }} />
                          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 10 }}>
                            <span style={{ fontSize: 11.5, color: "#9a9aa1" }}>{"{{placeholders}}"} are filled per event at send time.</span>
                            <span style={{ display: "flex", gap: 8 }}>
                              <button type="button" onClick={() => patch(r.id, { subject: r.subject, body: r.body })} style={{ background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6, padding: "8px 14px", fontSize: 12, fontWeight: 700, color: "#3f3f46", cursor: "pointer", fontFamily: "inherit" }}>Reset to default</button>
                              <button type="button" onClick={() => { setToast(r.name + " template saved"); setOpen(null); }} style={{ background: "#0e0e10", border: 0, borderRadius: 6, padding: "8px 16px", fontSize: 12, fontWeight: 700, color: "#fff", cursor: "pointer", fontFamily: "inherit" }}>Save template</button>
                            </span>
                          </div>
                        </React.Fragment>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      ))}
      <WsToast text={toast} />
    </div>
  );
}

// ══════════════════ A6 · Categories sourced from the ERP ══════════════════
function CategoriesSectionERP({ stores }) {
  const [cats, setCats] = React.useState(() => window.__prodCats.map((c) => ({ ...c, subs: c.subs.slice() })));
  const sync = (next) => { window.__prodCats = next; setCats(next); };
  const [newCat, setNewCat] = React.useState("");
  const [newSub, setNewSub] = React.useState({});
  const [deleteTarget, setDeleteTarget] = React.useState(null);
  const [reassignTo, setReassignTo] = React.useState("");
  const [toast, setToast] = useWsToast();
  const productCount = (catName) => { let n = 0; (stores || []).forEach((s) => (s.products || []).forEach((p) => { if (p.storeCategory === catName) n++; })); return n; };
  const addCat = () => { const name = newCat.trim(); if (!name || cats.some((c) => c.name.toLowerCase() === name.toLowerCase())) return; sync([...cats, { id: name.toLowerCase().replace(/[^a-z0-9]+/g, "-"), name, subs: [], erp: false }]); setNewCat(""); setToast("Category \u201c" + name + "\u201d created"); };
  const addSub = (cid) => { const name = (newSub[cid] || "").trim(); if (!name) return; sync(cats.map((c) => c.id === cid ? (c.subs.some((x) => x.toLowerCase() === name.toLowerCase()) ? c : { ...c, subs: [...c.subs, name] }) : c)); setNewSub((s) => ({ ...s, [cid]: "" })); };
  const removeSub = (cid, sub) => sync(cats.map((c) => c.id === cid ? { ...c, subs: c.subs.filter((x) => x !== sub) } : c));
  const confirmDelete = () => { if (!deleteTarget) return; const n = productCount(deleteTarget.name); sync(cats.filter((c) => c.id !== deleteTarget.id)); setToast(n > 0 ? ("\u201c" + deleteTarget.name + "\u201d deleted — " + n + " product" + (n === 1 ? "" : "s") + " reassigned to \u201c" + (reassignTo || "Uncategorized") + "\u201d") : ("\u201c" + deleteTarget.name + "\u201d deleted")); setDeleteTarget(null); setReassignTo(""); };
  const erp = cats.filter((c) => c.erp); const local = cats.filter((c) => !c.erp);
  const card = (c) => {
    const n = productCount(c.name);
    return (
      <div key={c.id} style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: 18 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
          <span style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
            <span style={{ fontSize: 14.5, fontWeight: 800, color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>{c.name}</span>
            <span style={{ fontSize: 11, fontWeight: 700, color: "#6b6b72", background: "#f1f1f3", borderRadius: 999, padding: "3px 9px", whiteSpace: "nowrap" }}>{n} product{n === 1 ? "" : "s"}</span>
          </span>
          {c.erp ? <span title="Managed in the ERP" style={{ color: "#9a9aa1", display: "inline-flex" }}><IconLock size={14} /></span>
            : <button type="button" title="Delete category" onClick={() => { setDeleteTarget(c); setReassignTo((cats.find((x) => x.id !== c.id) || {}).name || ""); }} style={{ width: 30, height: 30, borderRadius: 6, border: "1px solid #ececf0", background: "#fff", color: "#9a9aa1", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><IconTrash size={14} /></button>}
        </div>
        <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa", marginBottom: 8 }}>Subcategories</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: c.erp ? 0 : 12 }}>
          {c.subs.length === 0 && <span style={{ fontSize: 12, color: "#9a9aa1" }}>None yet</span>}
          {c.subs.map((s) => (
            <span key={s} style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 600, color: "#3f3f46", background: "#f4f4f5", borderRadius: 999, padding: c.erp ? "5px 12px" : "5px 6px 5px 12px" }}>
              {s}
              {!c.erp && <button type="button" onClick={() => removeSub(c.id, s)} title={"Remove " + s} style={{ width: 18, height: 18, borderRadius: 999, border: 0, background: "#e4e4e7", color: "#52525b", cursor: "pointer", fontSize: 11, lineHeight: 1, display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0 }}>×</button>}
            </span>
          ))}
        </div>
        {!c.erp && (
          <div style={{ display: "flex", gap: 8 }}>
            <input value={newSub[c.id] || ""} onChange={(e) => setNewSub((s) => ({ ...s, [c.id]: e.target.value }))} onKeyDown={(e) => { if (e.key === "Enter") addSub(c.id); }} placeholder="Add subcategory" style={{ flex: 1, height: 34, boxSizing: "border-box", border: "1px solid #e4e4e7", borderRadius: 6, padding: "0 10px", fontSize: 12.5, fontFamily: "inherit", outline: "none" }} />
            <button type="button" onClick={() => addSub(c.id)} style={{ background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 14px", fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>Add</button>
          </div>
        )}
      </div>
    );
  };
  return (
    <div>
      <WsSectionHead title="Product Categories" desc="Product Vault items arrive already assigned to ERP categories, so the storefront matches how the rest of the catalog is organized. Reps reorder categories per store but can't rename or delete ERP ones." right={<WsSync source="ERP" />} />
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}><span style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".08em", color: "#0e0e10", textTransform: "uppercase" }}>ERP categories</span><WsPill text={erp.length + " synced"} /></div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 28 }}>{erp.map(card)}</div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}><span style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".08em", color: "#0e0e10", textTransform: "uppercase" }}>Workspace categories</span><WsPill text="Team Stores only" tone="blue" /></div>
      <div style={{ fontSize: 12, color: "#9a9aa1", marginBottom: 10 }}>Added here, not in the ERP. Useful for groupings the ERP doesn't have, like Team Gear.</div>
      <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
        <input value={newCat} onChange={(e) => setNewCat(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addCat(); }} placeholder="New workspace category" style={{ flex: "0 1 280px", height: 40, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 12px", fontSize: 13.5, fontFamily: "inherit", outline: "none" }} />
        <Button variant="secondary" disabled={!newCat.trim()} onClick={addCat}>Add Category</Button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>{local.map(card)}</div>
      <Modal open={!!deleteTarget} onClose={() => setDeleteTarget(null)} width={480}>
        <div style={{ padding: "28px 28px 8px" }}>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>Delete “{deleteTarget && deleteTarget.name}”?</h2>
          {deleteTarget && productCount(deleteTarget.name) > 0 ? (
            <React.Fragment>
              <p style={{ margin: "12px 0 0", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>{productCount(deleteTarget.name)} product{productCount(deleteTarget.name) === 1 ? " uses" : "s use"} this category. Choose where they go:</p>
              <select value={reassignTo} onChange={(e) => setReassignTo(e.target.value)} style={{ marginTop: 14, width: "100%", height: 40, boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 6, padding: "0 10px", fontSize: 13, fontFamily: "inherit", outline: "none", background: "#fff" }}>
                {cats.filter((c) => c.id !== deleteTarget.id).map((c) => <option key={c.id} value={c.name}>Reassign to {c.name}</option>)}
                <option value="">Leave uncategorized</option>
              </select>
            </React.Fragment>
          ) : <p style={{ margin: "12px 0 0", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>No products use this category. This can't be undone.</p>}
        </div>
        <div style={{ padding: "20px 28px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
          <Button variant="secondary" onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button variant="primary" onClick={confirmDelete}>Delete Category</Button>
        </div>
      </Modal>
      <WsToast text={toast} />
    </div>
  );
}

// ══════════════════ G3 · Store code (store Settings + launch) ══════════════════
function storeCodeOf(store) {
  if (!store) return "STORE";
  if (store.storeCode) return store.storeCode;
  // Readable default: first word + any age/number token ("Tigers 14U" → TIGERS14U,
  // "Knights Knation Baseball" → KNIGHTS). Never cut mid-word.
  const words = String(store.teamName || store.storeTitle || "STORE").toUpperCase().split(/[^A-Z0-9]+/).filter(Boolean);
  const first = words[0] || "STORE";
  const num = words.slice(1).find((w) => /\d/.test(w)) || "";
  const code = (first.length > 12 ? first.slice(0, 12) : first) + (first.length + num.length <= 16 ? num : "");
  return code || "STORE";
}
window.__wsTakenCodes = window.__wsTakenCodes || ["TIGERS", "BEARS", "EAGLES", "WILDCATS", "STORM", "BULLDOGS", "TIGERS14U"];
function storeCodeTaken(code, store) {
  const c = String(code || "").toUpperCase();
  if (!c) return false;
  if (c === storeCodeOf(store)) return false;
  const others = (window.__tsAllStores || []).filter((s) => s.id !== (store && store.id)).map(storeCodeOf);
  return window.__wsTakenCodes.includes(c) || others.includes(c);
}
function storeCodeSuggest(code, store) { let n = 2; const base = String(code).toUpperCase().replace(/\d+$/, ""); while (storeCodeTaken(base + n, store)) n++; return base + n; }
function StoreCodeSection({ store, org, onUpdateStore, onToast }) {
  const code = storeCodeOf(store);
  const isLeague = (store.storeType || "league") === "league";
  const mode = store.codeMode || "store";
  const [draft, setDraft] = React.useState(code);
  const [editing, setEditing] = React.useState(false);
  const [copied, setCopied] = React.useState(null);
  React.useEffect(() => { setDraft(code); }, [code]);
  const clean = draft.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 16);
  const taken = storeCodeTaken(clean, store);
  const tooShort = clean.length < 4;
  const url = "prolookstores.com/join/" + code;
  const copy = (txt, key) => { try { navigator.clipboard && navigator.clipboard.writeText(txt); } catch (e) {} setCopied(key); setTimeout(() => setCopied(null), 1500); };
  const teams = typeof owTeams === "function" ? owTeams(org, store) : [];
  React.useEffect(() => { window.__wsTeamCodeRegistry[store.id] = teams.map((t) => ({ code: t.code, name: t.name, division: t.division })); }, [store.id, teams.map((t) => t.code).join(",")]);
  const [, bump] = React.useState(0);
  const tiers = (window.__wsTiers || []).filter((t) => t.id !== "retail");
  const tierOpts = tiers.map((t) => ({ value: t.id, label: t.name + " · " + t.off + "% off" }));
  const setTier = (c, v) => { wsSetCodeTier(c, v); bump((n) => n + 1); onToast && onToast(c + " now unlocks " + ((window.__wsTiers.find((t) => t.id === v) || {}).name || v) + " pricing"); };
  const extras = (window.__wsExtraCodes || []).filter((x) => x.storeId === store.id || (!x.storeId && (store.storeTitle || store.teamName) === x.storeName));
  return (
    <React.Fragment>
      <h3 style={{ margin: "24px 0 4px", fontSize: 17, fontWeight: 800, fontFamily: "Archivo, sans-serif", color: "#09090b" }}>Store Code</h3>
      <p style={{ fontSize: 13, color: "#71717a", margin: "0 0 18px", maxWidth: 640, lineHeight: 1.55 }}>The storefront is public at Retail prices. Shoppers who enter this code unlock the store's team gear and its pricing tier.</p>
      <div style={{ background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: 20 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap" }}>
          <div style={{ flex: "1 1 260px", minWidth: 0 }}>
            <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa", marginBottom: 6 }}>{isLeague && mode === "team" ? "Organization code" : "Store code"}</div>
            {editing ? (
              <div>
                <input autoFocus value={draft} onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => { if (e.key === "Escape") { setEditing(false); setDraft(code); } }} style={{ ...WS_INPUT, fontFamily: WS_MONO, fontSize: 18, fontWeight: 700, letterSpacing: ".08em", height: 46, border: "1px solid " + (taken || tooShort ? "#e1251b" : "#0e0e10"), maxWidth: 320 }} />
                <div style={{ marginTop: 6, fontSize: 12, color: taken || tooShort ? "#b81d14" : "#1f7a44", fontWeight: 600, minHeight: 16 }}>
                  {tooShort ? "At least 4 letters or numbers" : taken ? <span>{clean} is already in use — try <button type="button" onClick={() => setDraft(storeCodeSuggest(clean, store))} style={{ background: "transparent", border: 0, padding: 0, color: "#0e0e10", fontWeight: 800, cursor: "pointer", fontFamily: WS_MONO, textDecoration: "underline" }}>{storeCodeSuggest(clean, store)}</button></span> : clean + " is available"}
                </div>
              </div>
            ) : (
              <div style={{ fontFamily: WS_MONO, fontSize: 24, fontWeight: 700, letterSpacing: ".1em", color: "#0e0e10", userSelect: "all" }}>{code}</div>
            )}
          </div>
          <span style={{ display: "flex", gap: 8, flexShrink: 0 }}>
            {editing ? (
              <React.Fragment>
                <WsBtn small onClick={() => { setEditing(false); setDraft(code); }}>Cancel</WsBtn>
                <WsBtn small primary disabled={taken || tooShort} onClick={() => { onUpdateStore && onUpdateStore({ storeCode: clean }); setEditing(false); onToast && onToast("Store code changed to " + clean + " — the old code stops working"); }}>Save code</WsBtn>
              </React.Fragment>
            ) : (
              <React.Fragment>
                <WsBtn small onClick={() => copy(code, "code")}><IconClipboard size={12} style={{ strokeWidth: 2 }} /> {copied === "code" ? "Copied" : "Copy code"}</WsBtn>
                <WsBtn small onClick={() => copy("https://" + url, "link")}><IconLink size={12} /> {copied === "link" ? "Copied" : "Copy join link"}</WsBtn>
                <WsBtn small onClick={() => setEditing(true)}>Change</WsBtn>
              </React.Fragment>
            )}
          </span>
        </div>
        <div style={{ marginTop: 12, fontSize: 12, color: "#9a9aa1", fontFamily: WS_MONO }}>{url}</div>

        {/* Code → pricing tier */}
        <div style={{ marginTop: 18, paddingTop: 18, borderTop: "1px solid #f1f1f3" }}>
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
            <div>
              <div style={{ fontSize: 13, fontWeight: 800, color: "#0e0e10", marginBottom: 4 }}>Pricing by code</div>
              <div style={{ fontSize: 12, color: "#6b6b72", lineHeight: 1.5 }}>Each code carries a pricing tier. Anyone who enters it sees that tier's prices; everyone else pays Retail.</div>
            </div>
            <button type="button" onClick={() => window.__goWorkspaceSettings && window.__goWorkspaceSettings("pricing")} style={{ background: "transparent", border: 0, padding: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit", whiteSpace: "nowrap", textDecoration: "underline", textUnderlineOffset: 3 }}>Manage tiers ›</button>
          </div>
          <div style={{ border: "1px solid #ececf0", borderRadius: 8, overflow: "hidden" }}>
            {[{ code, label: "Store code", sub: "Whole store" }, ...teams.map((t) => ({ code: t.code, label: t.name, sub: t.division || "Team code" })), ...extras.map((x) => ({ code: x.code, label: x.label, sub: "Pricing code" }))].map((r, i, arr) => (
              <div key={r.code} style={{ display: "grid", gridTemplateColumns: "130px minmax(0,1fr) 200px", gap: 12, alignItems: "center", padding: "9px 14px", borderBottom: i < arr.length - 1 ? "1px solid #f4f4f5" : "none", fontSize: 12.5 }}>
                <span style={{ fontFamily: WS_MONO, fontWeight: 700, letterSpacing: ".06em", color: "#0e0e10" }}>{r.code}</span>
                <span style={{ minWidth: 0, color: "#0e0e10", fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.label}<span style={{ color: "#9a9aa1", fontWeight: 400 }}> · {r.sub}</span></span>
                <WsSelect width="100%" value={wsCodeTierId(r.code)} onChange={(v) => setTier(r.code, v)} options={tierOpts} style={{ height: 32, fontSize: 12 }} />
              </div>
            ))}
          </div>
          <div style={{ marginTop: 8, fontSize: 11.5, color: "#9a9aa1", lineHeight: 1.5 }}>Need a code for coaches or boosters? Mint one in Workspace Settings → Pricing Tiers.</div>
        </div>
        {isLeague && (
          <div style={{ marginTop: 18, paddingTop: 18, borderTop: "1px solid #f1f1f3" }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: "#0e0e10", marginBottom: 4 }}>How shoppers join this league store</div>
            <div style={{ fontSize: 12, color: "#6b6b72", marginBottom: 12, lineHeight: 1.5 }}>One code drops every shopper into the store and asks for their team; per-team codes route each shopper to their team directly.</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[["store", "One code for the whole store", "Shoppers enter " + code + " and pick their team after signing in."], ["team", "A code per team", "Each team's code (from My Teams) opens the store already scoped to that team. " + code + " still works as the organization code."]].map(([v, t, d]) => (
                <label key={v} onClick={() => { onUpdateStore && onUpdateStore({ codeMode: v }); }} style={{ display: "flex", gap: 12, border: "1px solid " + (mode === v ? "#0e0e10" : "#e4e4e7"), borderRadius: 8, padding: "12px 14px", cursor: "pointer", background: mode === v ? "#fafafb" : "#fff" }}>
                  <span style={{ width: 16, height: 16, borderRadius: "50%", border: "2px solid " + (mode === v ? "#0e0e10" : "#c4c4c8"), background: mode === v ? "#0e0e10" : "#fff", boxShadow: mode === v ? "inset 0 0 0 3px #fff" : "none", flexShrink: 0, marginTop: 2 }} />
                  <span><span style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{t}</span><span style={{ display: "block", fontSize: 12, color: "#6b6b72", marginTop: 2, lineHeight: 1.5 }}>{d}</span></span>
                </label>
              ))}
            </div>
            {mode === "team" && teams.length > 0 && (
              <div style={{ marginTop: 12, border: "1px solid #ececf0", borderRadius: 8, overflow: "hidden" }}>
                {teams.slice(0, 6).map((t, i) => (
                  <div key={t.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "9px 14px", borderBottom: i < Math.min(teams.length, 6) - 1 ? "1px solid #f4f4f5" : "none", fontSize: 12.5 }}>
                    <span style={{ flex: 1, color: "#0e0e10", fontWeight: 600 }}>{t.name}{t.division && <span style={{ color: "#9a9aa1", fontWeight: 400 }}> · {t.division}</span>}</span>
                    <span style={{ fontFamily: WS_MONO, fontWeight: 700, letterSpacing: ".06em", color: "#0e0e10" }}>{t.code}</span>
                    <button type="button" onClick={() => copy(t.code, t.id)} style={{ background: "transparent", border: 0, padding: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>{copied === t.id ? "Copied" : "Copy"}</button>
                  </div>
                ))}
                {teams.length > 6 && <div style={{ padding: "9px 14px", fontSize: 12, color: "#9a9aa1" }}>{teams.length - 6} more in My Teams</div>}
              </div>
            )}
          </div>
        )}
      </div>
    </React.Fragment>
  );
}
// Compact code row for the launch-success modal and the Home status strip.
function StoreCodeRow({ store }) {
  const [copied, setCopied] = React.useState(false);
  const code = storeCodeOf(store);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, width: "100%", boxSizing: "border-box", background: "#fafafb", border: "1px solid #ececf0", borderRadius: 8, padding: "10px 10px 10px 16px", marginBottom: 12 }}>
      <span style={{ flex: 1, minWidth: 0, textAlign: "left" }}>
        <span style={{ display: "block", fontSize: 10.5, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "#a1a1aa" }}>Store code</span>
        <span style={{ display: "block", fontFamily: WS_MONO, fontSize: 16, fontWeight: 700, letterSpacing: ".1em", color: "#0e0e10" }}>{code}</span>
      </span>
      <button onClick={() => { try { navigator.clipboard?.writeText(code); } catch (e) {} setCopied(true); setTimeout(() => setCopied(false), 1600); }} style={{ flexShrink: 0, display: "inline-flex", alignItems: "center", gap: 8, background: copied ? "#e7f5ed" : "#fff", border: `1px solid ${copied ? "#1f9d55" : "#d4d4d8"}`, color: copied ? "#1f7a44" : "#0e0e10", borderRadius: 6, padding: "8px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{copied ? "Copied" : "Copy Code"}</button>
    </div>
  );
}


function Dashboard({ store, onBack, onCustomize, initialTab, onProductsChange, simulateOrders, liveStores, onLaunch, onSwitchStore, onSetStatus, onViewStore, onUpdateStore, onCreateTemplate, embedded, readOnly }) {
  const [tab, setTab] = React.useState(initialTab || "home");
  React.useEffect(() => {if (initialTab) setTab(initialTab);}, [initialTab]);
  // Shared roster structure + manager mapping — lifted here so the Settings
  // tab's "Team Manager & Freight Mapping" and the Rosters tab mirror each
  // other live (both read/write the same org object).
  const [org, setOrg] = React.useState(() => makeRosterOrg(store, !!store.__fresh));
  const managerGated = store.storeType === "league" && (store.distributionModel || "coach") === "coach";
  const [managerFocus, setManagerFocus] = React.useState(null); // {groupId, rosterId, n}
  const jumpToManagers = (groupId, rosterId) => { setManagerFocus({ groupId, rosterId, n: Date.now() }); setSettingsSection("distribution"); setTab("general"); };
  // Settings page sub-nav (embedded workspace): Store Settings | Distribution & Fulfillment
  const [settingsSection, setSettingsSection] = React.useState("store");
  // Notify the onboarding tour which dashboard tab is active so it can advance.
  React.useEffect(() => {
    window.dispatchEvent(new CustomEvent("tour:dashboard-tab", { detail: tab }));
  }, [tab]);
  const [showLaunchModal, setShowLaunchModal] = React.useState(false);
  const [showSuccessModal, setShowSuccessModal] = React.useState(false);
  // Bumped whenever something requests a jump to a specific pending order, so
  // OrdersTabV2 can react and open that order's drawer.
  const [pendingJump, setPendingJump] = React.useState(0);
  // Bumped to request a jump to the Orders tab's "All Orders" sub-tab.
  const [allOrdersJump, setAllOrdersJump] = React.useState(0);
  // Bumped to request a jump to the Orders tab's "Pending Orders" sub-tab (no drawer).
  const [pendingTabJump, setPendingTabJump] = React.useState(0);
  React.useEffect(() => {
    window.__goToPendingOrder = () => {setTab("orders");setPendingJump((n) => n + 1);};
    return () => {delete window.__goToPendingOrder;};
  }, []);
  // 4 — the Settings card hands off to the Products tab's category control.
  React.useEffect(() => {
    const h = () => setTab("products");
    window.addEventListener("ts:openProductCats", h);
    return () => window.removeEventListener("ts:openProductCats", h);
  }, []);
  // Hooks for the onboarding checklist to drive navigation / launch.
  React.useEffect(() => {
    window.__goToDashTab = (t) => setTab(t);
    window.__openLaunchModal = () => {if (!store.live) setShowLaunchModal(true);};
    return () => {delete window.__goToDashTab;delete window.__openLaunchModal;};
  }, [store.live]);
  const canLaunch = (store.products || []).length > 0;
  const isLive = !!store.live;

  // ─── Tab badges (Cody's matrix) ───
  const [viewed, setViewed] = React.useState(() => loadBadgeState(store.id));
  React.useEffect(() => {setViewed(loadBadgeState(store.id));}, [store.id]);
  const markViewed = React.useCallback((patch) => {
    setViewed((prev) => {
      const changed = Object.keys(patch).some((k) => prev[k] !== patch[k]);
      if (!changed) return prev;
      const next = { ...prev, ...patch };
      saveBadgeState(store.id, next);
      return next;
    });
  }, [store.id]);

  // Clear-on-view for General / Payouts / Roster; Orders marks its main tab
  // (sub-tabs report separately via onSubView).
  React.useEffect(() => {
    if (tab === "general") markViewed({ general: true });else
    if (tab === "payouts") markViewed({ payouts: true });else
    if (tab === "roster") markViewed({ roster: true });else
    if (tab === "orders") markViewed({ ordersTab: true });
  }, [tab, markViewed]);

  const ordersCleared = viewed.ordersTab && viewed.sub_pending && viewed.sub_all;
  const productsCleared = (store.products?.length || 0) >= 1;

  const tabBtnRefs = React.useRef({});
  const [tabIndicator, setTabIndicator] = React.useState({ left: 0, width: 0 });
  React.useLayoutEffect(() => {
    const btn = tabBtnRefs.current[tab];
    if (btn) setTabIndicator({ left: btn.offsetLeft, width: btn.offsetWidth });
  }, [tab]);

  const tabs = [
  { id: "home", label: "Home", dot: false },
  { id: "general", label: "Settings", dot: !viewed.general },
  { id: "orders", label: "Orders", dot: !ordersCleared },
  { id: "products", label: "Products", dot: !productsCleared },
  { id: "roster", label: (store && store.storeType === "league") ? "My Teams" : "My Team", dot: !viewed.roster },
  { id: "payouts", label: "Reports", dot: !viewed.payouts }];

  const confirmLaunch = () => {
    setShowLaunchModal(false);
    onLaunch && onLaunch(store.id);
    setShowSuccessModal(true);
  };

  // Tab content shared between the legacy layout and the embedded workspace.
  const tabContent =
  <React.Fragment>
      {tab === "home" && <HomeTab store={store} org={org} readOnly={readOnly} onGoTab={setTab} onPendingOrders={() => {setTab("orders");setPendingTabJump((n) => n + 1);}} onAllOrders={() => {setTab("orders");setAllOrdersJump((n) => n + 1);}} onRosterBank={() => setTab("roster")} onManagers={(t) => jumpToManagers(t && t.groupId, t && t.rosterId)} onLaunch={() => {if ((store.products || []).length) setShowLaunchModal(true);}} onGoSettings={(s) => {setSettingsSection(s || "store");setTab("general");}} onUpdateStore={onUpdateStore} />}
      {tab === "general" && <React.Fragment><GeneralInfo store={store} onUpdateStore={onUpdateStore} org={org} setOrg={setOrg} managerFocus={managerFocus} onCreateTemplate={onCreateTemplate} section={embedded ? settingsSection : "all"} />{(!embedded || settingsSection === "catalog") && <CatalogPolicySection store={store} onUpdate={onUpdateStore} />}</React.Fragment>}
      {tab === "orders" && <OrdersTabV2 store={store} org={org} setOrg={setOrg} pendingJump={pendingJump} allOrdersJump={allOrdersJump} pendingTabJump={pendingTabJump} onSubView={(s) => markViewed({ ["sub_" + s]: true })} />}
      {tab === "payouts" && <PayoutsTab store={store} onViewAllOrders={() => {setTab("orders");setAllOrdersJump((n) => n + 1);}} onViewPendingOrders={() => {setTab("orders");setPendingTabJump((n) => n + 1);}} />}
      {tab === "products" && <ProductsTab store={store} onCustomize={onCustomize} onProductsChange={onProductsChange} simulateOrders={simulateOrders} />}
      {tab === "roster" && <RosterTab startEmpty={!!store.__fresh} store={store} org={org} setOrg={setOrg} managerGated={managerGated} onManageManagers={jumpToManagers} />}
    </React.Fragment>;


  const launchModals =
  <React.Fragment>
      <LaunchStoreModal
      open={showLaunchModal}
      onClose={() => setShowLaunchModal(false)}
      onConfirm={confirmLaunch} />
      <LaunchSuccessModal
      open={showSuccessModal}
      store={store}
      onClose={() => setShowSuccessModal(false)}
      onViewStore={() => {setShowSuccessModal(false);onViewStore && onViewStore(store);}}
      onStayInEditor={() => setShowSuccessModal(false)} />
    </React.Fragment>;


  // ── Embedded workspace layout: icon side-rail + content, no header/tab strip ──
  if (embedded) {
    const homeRed = homeRedNavTabs(store, org);
    const badges = {
      general: !viewed.general || homeRed.has("general"),
      orders: !ordersCleared || homeRed.has("orders"),
      products: !productsCleared || homeRed.has("products"),
      roster: !viewed.roster || homeRed.has("roster"),
      payouts: !viewed.payouts
    };
    return (
      <div style={{ flex: 1, display: "flex", minWidth: 0, alignItems: "stretch", minHeight: 0, overflow: "hidden" }}>
        <StoreSideNav tab={tab} onChange={setTab} badges={badges} store={store} />
        <div ref={(el) => { if (el) { if (readOnly) el.setAttribute("inert", ""); else el.removeAttribute("inert"); } }} style={{ flex: 1, minWidth: 0, padding: "28px 36px 92px", background: "#fbfbfc", opacity: readOnly ? 0.72 : 1, transition: "opacity .15s", overflowY: "auto" }}>
          {/* Page header (24/800) + Settings sub-nav pills */}
          {tab !== "home" && <div style={{ display: "flex", flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 16, marginBottom: (tab === "products" || tab === "orders") ? 12 : 24 }}>
            <h1 data-screen-label={tab} style={{ fontFamily: "Archivo, sans-serif", fontSize: 24, fontWeight: 800, lineHeight: "32px", letterSpacing: "-.01em", color: "#09090b", margin: 0 }}>
              {tab === "general" ? "Settings"
                : tab === "payouts" ? "Reports"
                : tab === "roster" ? ((store && store.storeType === "league") ? "My Teams" : "My Team")
                : tab === "products" ? "Products"
                : "Orders"}
            </h1>
          </div>}
          <StoreCloseReportHost store={store} />
          {tab === "general" ? (
            <div style={{ display: "flex", gap: 36, alignItems: "flex-start" }}>
              <StoreSettingsNav store={store} value={settingsSection} onChange={setSettingsSection} />
              <div style={{ flex: 1, minWidth: 0 }}>{tabContent}</div>
            </div>
          ) : tabContent}
        </div>
        {launchModals}
      </div>);

  }

  return (
    <div style={{ flex: 1, padding: "24px 36px 80px", background: "#fff" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          {store.teamLogo?.url ?
          <img src={store.teamLogo.url} alt="" style={{ width: 36, height: 36, borderRadius: 4, objectFit: "cover" }} /> :

          <div style={{ width: 36, height: 36, borderRadius: 4, background: store.teamLogo?.color || "#e1e2dd", display: "inline-flex", alignItems: "center", justifyContent: "center", color: store.teamLogo?.color ? "#fff" : "#6b6b72", fontWeight: 800, fontSize: 13 }}>
              {store.teamLogo?.mono || store.teamName?.[0]?.toUpperCase() || "T"}
            </div>
          }
          <h1 style={{ fontSize: 18, fontWeight: 800, letterSpacing: ".02em", margin: 0 }}>
            {store.teamName || "[TEAM NAME]"}
          </h1>
        </div>
        {isLive ?
        <LiveStoreControls
          store={store}
          liveStores={liveStores || []}
          onViewStore={() => onViewStore && onViewStore(store)}
          onSwitchStore={(id) => onSwitchStore && onSwitchStore(id)}
          onSetStatus={(status) => onSetStatus && onSetStatus(store.id, status)} /> :

        <button data-tour="launch-btn" disabled={!canLaunch} onClick={() => canLaunch && setShowLaunchModal(true)} style={{
          background: canLaunch ? "#0e0e10" : "#ececf0",
          color: canLaunch ? "#fff" : "#9a9aa1",
          border: `1px solid ${canLaunch ? "#0e0e10" : "#ececf0"}`,
          padding: "12px 24px", borderRadius: 4, fontSize: 13, fontWeight: 800,
          letterSpacing: ".06em", cursor: canLaunch ? "pointer" : "not-allowed"
        }} title={canLaunch ? "Launch this team store" : "Add at least one product to launch your store"}>LAUNCH STORE</button>
        }
      </div>

      {/* Tabs */}
      <div style={{ borderBottom: "1px solid #ececf0", marginBottom: 24, display: "flex", gap: 4, position: "relative" }}>
        <span aria-hidden="true" style={{
          position: "absolute", bottom: -1, height: 2, background: "#0e0e10",
          left: tabIndicator.left, width: tabIndicator.width,
          borderRadius: "1px 1px 0 0",
          transition: "left .2s cubic-bezier(.4,0,.2,1), width .2s cubic-bezier(.4,0,.2,1)",
        }} />
        {tabs.map((t) => {
          const active = tab === t.id;
          return (
            <button key={t.id} onClick={() => setTab(t.id)}
            ref={(el) => { tabBtnRefs.current[t.id] = el; }}
            data-tour={t.id === "products" ? "tab-products" : t.id === "roster" ? "tab-roster" : undefined}
            style={{
              background: "transparent", border: 0, padding: "16px 24px",
              fontSize: 13, fontWeight: active ? 700 : 500,
              color: active ? "#0e0e10" : "#6b6b72",
              cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8,
              marginBottom: -1, transition: "color .15s ease",
            }}>
              {t.label}
              <TabDot show={t.dot} />
            </button>);
        })}
      </div>

      {tabContent}

      <StoreCloseReportHost store={store} />
      {launchModals}
    </div>);

}

// ─────────── Orders tab ───────────
function OrdersTab() {
  const [sub, setSub] = React.useState("pending");
  const subs = [
  { id: "my", label: "My Orders" },
  { id: "pending", label: "Pending Orders" },
  { id: "fan", label: "Fan Orders" }];

  return (
    <div>
      <div style={{ display: "flex", gap: 12, marginBottom: 40 }}>
        {subs.map((s) => {
          const active = sub === s.id;
          return (
            <button key={s.id} onClick={() => setSub(s.id)} style={{
              background: active ? "#0e0e10" : "#fff",
              color: active ? "#fff" : "#0e0e10",
              border: `1px solid ${active ? "#0e0e10" : "#d4d4d8"}`,
              padding: "8px 16px", borderRadius: 999,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
              transition: "all .12s"
            }}>
              {s.label}
            </button>);

        })}
      </div>
      <EmptyTabState
        iconKind="chart"
        title={sub === "my" ? "No Orders Yet" : sub === "pending" ? "No Pending Orders" : "No Fan Orders"}
        body={
        sub === "my" ? "Your placed orders will appear here once you've made a purchase." :
        sub === "pending" ? "When customers place orders through your team store, they'll appear here for review." :
        "Fan and supporter orders will show up here as your store generates sales."
        } />
      
    </div>);

}

// ─────────── Reports tab ───────────
// Analytical dashboard mirroring the master Overview dashboard: a four-card KPI
// row, plus a Team Profit bar chart and a Payouts tracker sitting side by side.
const REP_INK = "#0e0e10";
const REP_MUTED = "#6b6b72";
const REP_LINE = "#ececf0";
const REP_RED = "#e1251b";
const REP_GREEN = "#1f9d55";

function repFmt(n) {
  return "$" + Math.round(n).toLocaleString("en-US");
}
function repFmtK(n) {
  if (n >= 1000) return "$" + (n / 1000).toFixed(n >= 10000 ? 0 : 1) + "K";
  return "$" + Math.round(n);
}

// Deterministic monthly profit series that builds to a clean trend.
function buildProfit(total) {
  const weights = [0.6, 0.8, 1.1, 0.7, 0.9, 1.2, 1.35, 1.5, 1.0, 1.15, 1.3, 1.05];
  const wsum = weights.reduce((a, b) => a + b, 0);
  const now = new Date();
  return weights.map((w, i) => {
    const d = new Date(now.getFullYear(), now.getMonth() - (11 - i), 1);
    return { month: d.toLocaleDateString("en-US", { month: "short" }), profit: Math.round((total * w) / wsum), current: i === 11 };
  });
}

// KPI summary card — identical to the Overview dashboard's StatCard.
function RepStatCard({ label, value, icon, delta, deltaDir = "up", sub, onClick }) {
  const Trend = deltaDir === "up" ? IconTrendUp : IconTrendDown;
  const trendColor = deltaDir === "up" ? REP_GREEN : REP_RED;
  return (
    <div
      onClick={onClick}
      role={onClick ? "button" : undefined}
      title={onClick ? "View orders" : undefined}
      style={{
      background: "#fff", border: `1px solid ${REP_LINE}`, borderRadius: 12, padding: "20px 24px",
      display: "flex", flexDirection: "column", gap: 16, cursor: onClick ? "pointer" : "default",
      transition: "box-shadow .12s, border-color .12s"
    }}
      onMouseEnter={onClick ? (e) => {e.currentTarget.style.boxShadow = "0 4px 14px rgba(20,20,30,.08)";e.currentTarget.style.borderColor = "#c9c9cf";} : undefined}
      onMouseLeave={onClick ? (e) => {e.currentTarget.style.boxShadow = "none";e.currentTarget.style.borderColor = REP_LINE;} : undefined}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".07em", color: REP_MUTED, textTransform: "uppercase" }}>{label}</span>
        <span style={{ width: 36, height: 36, borderRadius: 9, background: "#f5f5f7", color: REP_INK, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>{icon}</span>
      </div>
      <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 32, fontWeight: 800, color: REP_INK, lineHeight: 1, letterSpacing: "-.01em" }}>{value}</div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5 }}>
        {delta != null &&
        <span style={{ display: "inline-flex", alignItems: "center", gap: 4, color: trendColor, fontWeight: 700 }}>
            <Trend size={15} /> {delta}
          </span>
        }
        <span style={{ color: REP_MUTED }}>{sub}</span>
      </div>
    </div>);

}

// Card shell — identical to the Overview dashboard's Panel.
function RepPanel({ title, children, style }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${REP_LINE}`, borderRadius: 12, padding: "20px 24px", ...style }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <h3 style={{ fontSize: 16, fontWeight: 800, margin: 0, color: REP_INK, letterSpacing: ".01em" }}>{title}</h3>
      </div>
      {children}
    </div>);

}

// Vertical column bar chart — same construction as the Overview Revenue chart.
function TeamProfitChart({ data }) {
  const max = Math.max(...data.map((d) => d.profit), 1);
  const [hover, setHover] = React.useState(null);
  const ticks = 4;
  return (
    <div style={{ position: "relative", height: 340, paddingLeft: 48, paddingBottom: 28 }}>
      {/* Y axis */}
      <div style={{ position: "absolute", left: 0, top: 0, bottom: 28, width: 44, display: "flex", flexDirection: "column", justifyContent: "space-between", alignItems: "flex-end", fontSize: 11, color: "#a4a4ab", fontFamily: "JetBrains Mono, monospace" }}>
        {Array.from({ length: ticks + 1 }).map((_, i) =>
        <span key={i}>{repFmtK((max * (ticks - i)) / ticks)}</span>
        )}
      </div>
      {/* Plot */}
      <div style={{ position: "relative", height: "100%", borderLeft: `1px solid ${REP_LINE}`, borderBottom: `1px solid ${REP_LINE}` }}>
        {Array.from({ length: ticks }).map((_, i) =>
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: `${i / ticks * 100}%`, borderTop: "1px dashed #f1f1f3" }} />
        )}
        <div style={{ position: "absolute", inset: "8px 8px 0", display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 8 }}>
          {data.map((d, i) => {
            const totalH = d.profit / max * 100;
            return (
              <div key={d.month} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}
                style={{ position: "relative", flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 8, height: "100%", justifyContent: "flex-end", cursor: "default" }}>
                {hover === i && (
                  <div style={{ position: "absolute", bottom: `calc(${totalH}% + 10px)`, left: "50%", transform: "translateX(-50%)", background: REP_INK, color: "#fff", borderRadius: 8, padding: "8px 12px", whiteSpace: "nowrap", zIndex: 5, boxShadow: "0 6px 18px rgba(20,20,30,.22)", pointerEvents: "none" }}>
                    <div style={{ fontSize: 11, color: "#a4a4ab", marginBottom: 2 }}>{d.month}{d.current ? " · current" : ""}</div>
                    <div style={{ fontSize: 13.5, fontWeight: 700, fontFamily: "JetBrains Mono, monospace" }}>{repFmt(d.profit)}</div>
                  </div>
                )}
                <div style={{ width: "100%", maxWidth: 48, height: `${totalH}%`, borderRadius: 5, background: d.current ? REP_RED : REP_INK, opacity: hover === i ? 0.82 : 1, transition: "opacity .12s" }} />
                <span style={{ fontSize: 11, color: d.current ? REP_INK : REP_MUTED, fontWeight: d.current ? 700 : 400, position: "absolute", bottom: -24 }}>{d.month}</span>
              </div>);

          })}
        </div>
      </div>
    </div>);

}

// ─────────── Fundraising Report (Reports tab) ───────────
const FR_GREEN = "#6cbd45";
const FR_GREEN_HOVER = "#5faf3a";

function frMoney(n) {
  return "$" + (Math.round(n * 100) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function frShortDate(d) {
  const dt = d instanceof Date ? d : new Date(d);
  const p = (n) => String(n).padStart(2, "0");
  return `${p(dt.getMonth() + 1)}/${p(dt.getDate())}/${String(dt.getFullYear()).slice(2)}`;
}
function frLongDate(d) {
  const dt = d instanceof Date ? d : new Date(d);
  const p = (n) => String(n).padStart(2, "0");
  return `${p(dt.getMonth() + 1)}/${p(dt.getDate())}/${dt.getFullYear()}`;
}

function FundraisingReport({ store }) {
  const teamName = store?.teamName || store?.storeTitle || "Team Store";
  const platformFeeLabel = store?.platformFeeLabel || "Platform Fees";
  const revenue = store?.revenue || 3810;
  const orders = Math.max(Math.round(revenue / 46), 1);

  // Fundraising is a subset of collected revenue (price additions flagged as
  // "Fundraising" on products). Modeled off store revenue for the prototype.
  const collected = Math.round(revenue * 0.18 * 100) / 100;
  const platformFees = Math.round(collected * 0.05 * 100) / 100;
  const cardFees = Math.round((collected * 0.029 + orders * 0.3) * 100) / 100;
  const net = Math.round((collected - platformFees - cardFees) * 100) / 100;

  const defStart = new Date(store?.storeOpenStart || "2026-02-03");
  const defEnd = new Date(store?.storeOpenEnd || "2026-07-06");
  const [range, setRange] = React.useState({ start: defStart, end: defEnd });
  const [pickerOpen, setPickerOpen] = React.useState(false);
  const [settingsOpen, setSettingsOpen] = React.useState(false);
  const pickerRef = React.useRef();
  React.useEffect(() => {
    const h = (e) => { if (pickerRef.current && !pickerRef.current.contains(e.target)) setPickerOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const presets = [
    { label: "This season", start: defStart, end: defEnd },
    { label: "Last 7 days", start: new Date("2026-07-06"), end: new Date("2026-07-13") },
    { label: "Last 30 days", start: new Date("2026-06-13"), end: new Date("2026-07-13") },
    { label: "Year to date", start: new Date("2026-01-01"), end: new Date("2026-07-13") },
  ];

  const rows = [
    { label: "Fundraising Collected", val: collected },
    { label: platformFeeLabel, val: platformFees },
    { label: "Card Processing Fees", val: cardFees },
    { label: "Net Fundraising", val: net, bold: true },
  ];

  return (
    <div style={{ marginTop: 16 }}>
      {/* Report card */}
      <div style={{ background: "#fff", border: `1px solid ${REP_LINE}`, borderRadius: 12, padding: "24px 28px 28px", marginTop: 16 }}>
        {/* internal header block */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 20, marginBottom: 16, flexWrap: "wrap" }}>
          <div style={{ fontSize: 16, fontWeight: 800, color: REP_INK, letterSpacing: "-.01em" }}>Fundraising Report</div>
          <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
          <div ref={pickerRef} style={{ position: "relative" }}>
            <button onClick={() => setPickerOpen((v) => !v)} style={{
              display: "inline-flex", alignItems: "center", gap: 12, background: "#fff",
              border: `1.5px solid ${pickerOpen ? FR_GREEN : "#d4d4d8"}`, borderRadius: 8,
              padding: "12px 16px", cursor: "pointer", fontSize: 14, fontWeight: 600, color: REP_INK, transition: "border-color .12s",
            }}>
              <IconCalendar size={17} style={{ color: REP_MUTED }} />
              <span>{frShortDate(range.start)} - {frShortDate(range.end)}</span>
              <IconChevron size={16} style={{ color: REP_MUTED }} />
            </button>
            {pickerOpen && (
              <div style={{ position: "absolute", top: "calc(100% + 8px)", right: 0, zIndex: 20, minWidth: 220, background: "#fff", border: `1px solid ${REP_LINE}`, borderRadius: 10, boxShadow: "0 12px 30px rgba(20,20,30,.14)", padding: 8 }}>
                {presets.map((p) => {
                  const active = frShortDate(p.start) === frShortDate(range.start) && frShortDate(p.end) === frShortDate(range.end);
                  return (
                    <button key={p.label} onClick={() => { setRange({ start: p.start, end: p.end }); setPickerOpen(false); }} style={{
                      width: "100%", textAlign: "left", background: active ? "#f2faec" : "transparent", border: 0, borderRadius: 7,
                      padding: "12px 12px", cursor: "pointer", fontSize: 13.5, fontWeight: 600, color: REP_INK,
                      display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12,
                    }}
                      onMouseEnter={(e) => { if (!active) e.currentTarget.style.background = "#fafafb"; }}
                      onMouseLeave={(e) => { if (!active) e.currentTarget.style.background = "transparent"; }}>
                      <span>{p.label}</span>
                      <span style={{ fontSize: 11.5, color: REP_MUTED, fontWeight: 500 }}>{frShortDate(p.start)}–{frShortDate(p.end)}</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
          <button onClick={() => setSettingsOpen(true)} style={{
            display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", border: 0, borderRadius: 8,
            padding: "12px 20px", cursor: "pointer", fontSize: 14, fontWeight: 700, color: "#fff", transition: "background .12s",
          }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "#2a2a2e")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "#0e0e10")}>
            <IconDownload size={17} /> Download PDF
          </button>
          </div>
        </div>

        {/* Detailed breakdown matrix */}
        <div style={{ border: `1px solid ${REP_LINE}`, borderRadius: 10, overflow: "hidden" }}>
          <div style={{ padding: "16px 16px", background: "#f7f7f8", borderBottom: `1px solid ${REP_LINE}`, fontSize: 14, fontWeight: 700, color: REP_INK }}>Detailed breakdown</div>
          {rows.map((r, i) => (
            <div key={r.label} style={{
              display: "flex", alignItems: "center", justifyContent: "space-between",
              padding: "16px 16px", borderBottom: i < rows.length - 1 ? `1px solid ${REP_LINE}` : "none",
            }}>
              <span style={{ fontSize: 14.5, fontWeight: r.bold ? 800 : 500, color: REP_INK }}>{r.label}</span>
              <span style={{ fontSize: 14.5, fontWeight: r.bold ? 800 : 500, color: REP_INK, fontFamily: "JetBrains Mono, monospace" }}>{frMoney(r.val)}</span>
            </div>
          ))}
        </div>

        {/* Analytical subtext */}
        <p style={{ margin: "16px 2px 0", fontSize: 14, color: REP_MUTED, lineHeight: 1.6 }}>
          You&apos;ve currently collected a total fundraising amount of <strong style={{ color: REP_INK }}>{frMoney(collected)}</strong> from all <strong style={{ color: REP_INK }}>{orders}</strong> order(s) to-date. After fees of <strong style={{ color: REP_INK }}>{frMoney(platformFees + cardFees)}</strong>, your net fundraising is <strong style={{ color: REP_INK }}>{frMoney(net)}</strong>.
        </p>

        {/* Sticky note banner */}
        <div style={{ marginTop: 16, background: "#f5f5f7", borderRadius: 10, padding: "16px 16px", fontSize: 13.5, color: "#4a4a52", lineHeight: 1.55 }}>
          <strong style={{ color: REP_INK, fontWeight: 700 }}>NOTE:</strong> This report only includes price additions that are marked as &quot;Fundraising&quot; on the product edit page.
        </div>
      </div>

      <FundraisingReportSettingsModal open={settingsOpen} onClose={() => setSettingsOpen(false)} range={range} />
    </div>
  );
}

function FrRadio({ selected, onSelect, title, sub }) {
  return (
    <button onClick={onSelect} style={{
      display: "flex", alignItems: "flex-start", gap: 16, width: "100%", textAlign: "left",
      background: "transparent", border: 0, cursor: "pointer", padding: "4px 0",
    }}>
      <span style={{
        flexShrink: 0, marginTop: 2, width: 24, height: 24, borderRadius: "50%",
        border: `2px solid ${selected ? "#0e0e10" : "#c4c4c8"}`, display: "inline-flex", alignItems: "center", justifyContent: "center",
        transition: "border-color .12s",
      }}>
        {selected && <span style={{ width: 12, height: 12, borderRadius: "50%", background: "#0e0e10" }} />}
      </span>
      <span>
        <span style={{ display: "block", fontSize: 16, fontWeight: 800, color: REP_INK, marginBottom: 4 }}>{title}</span>
        <span style={{ display: "block", fontSize: 14, color: REP_MUTED, lineHeight: 1.5 }}>{sub}</span>
      </span>
    </button>
  );
}

function FrCheckbox({ checked, onToggle, title, sub }) {
  return (
    <button onClick={onToggle} style={{
      display: "flex", alignItems: "flex-start", gap: 16, width: "100%", textAlign: "left",
      background: "transparent", border: 0, cursor: "pointer", padding: "4px 0",
    }}>
      <span style={{
        flexShrink: 0, marginTop: 2, width: 24, height: 24, borderRadius: 6,
        border: `2px solid ${checked ? "#0e0e10" : "#c4c4c8"}`, background: checked ? "#0e0e10" : "#fff",
        display: "inline-flex", alignItems: "center", justifyContent: "center", transition: "all .12s",
      }}>
        {checked && <IconCheck size={14} style={{ color: "#fff", strokeWidth: 3 }} />}
      </span>
      <span>
        <span style={{ display: "block", fontSize: 16, fontWeight: 800, color: REP_INK, marginBottom: 4 }}>{title}</span>
        <span style={{ display: "block", fontSize: 14, color: REP_MUTED, lineHeight: 1.5 }}>{sub}</span>
      </span>
    </button>
  );
}

function FundraisingReportSettingsModal({ open, onClose, range }) {
  const [summary, setSummary] = React.useState("net");
  const [opts, setOpts] = React.useState({ breakdown: false, dateRange: false, notes: false });
  React.useEffect(() => {
    if (open) { setSummary("net"); setOpts({ breakdown: false, dateRange: false, notes: false }); }
  }, [open]);
  const toggle = (k) => setOpts((p) => ({ ...p, [k]: !p[k] }));
  const rangeStr = range ? `${frLongDate(range.start)} - ${frLongDate(range.end)}` : "";

  return (
    <Modal open={open} onClose={onClose} width={720}>
      <div style={{ display: "flex", flexDirection: "column", maxHeight: "86vh" }}>
        {/* header */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "28px 32px", borderBottom: `1px solid ${REP_LINE}` }}>
          <h2 style={{ fontFamily: "Archivo, sans-serif", fontSize: 26, fontWeight: 800, margin: 0, color: REP_INK, letterSpacing: "-.01em" }}>Fundraising Report Settings</h2>
          <button onClick={onClose} aria-label="Close" style={{ background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#9a9aa1", display: "inline-flex" }}>
            <IconX size={24} />
          </button>
        </div>

        {/* body */}
        <div style={{ padding: "28px 32px", overflowY: "auto" }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
            <FrRadio selected={summary === "net"} onSelect={() => setSummary("net")}
              title="Net Fundraising Summary (Default)"
              sub="Displays the final fundraising amount after deducting all associated fees for the selected date range." />
            <FrRadio selected={summary === "gross"} onSelect={() => setSummary("gross")}
              title="Gross Total Summary"
              sub="Shows only the total fundraising collected before any fees are deducted." />
          </div>

          <div style={{ height: 1, background: REP_LINE, margin: "28px 0" }} />

          <div style={{ fontSize: 16, fontWeight: 800, color: REP_INK, marginBottom: 16 }}>Report Details:</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
            <FrCheckbox checked={opts.breakdown} onToggle={() => toggle("breakdown")}
              title="Detailed Breakdown (Full Report)"
              sub="Includes the full line-item breakdown of collected funds, fees, and the final net amount." />
            <FrCheckbox checked={opts.dateRange} onToggle={() => toggle("dateRange")}
              title="Selected Date Range"
              sub={`Adds the selected date range (${rangeStr}) to the top of the report PDF.`} />
            <FrCheckbox checked={opts.notes} onToggle={() => toggle("notes")}
              title="Include PDF Report Notes"
              sub={'Adds the notes from the "PDF Report Notes" section to the printed report output.'} />
          </div>
        </div>

        {/* footer */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 16, padding: "16px 32px", borderTop: `1px solid ${REP_LINE}` }}>
          <button onClick={onClose} style={{
            background: "#fff", border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 24px",
            fontSize: 14, fontWeight: 700, color: REP_INK, cursor: "pointer", fontFamily: "inherit",
          }}>Cancel</button>
          <button onClick={onClose} style={{
            display: "inline-flex", alignItems: "center", gap: 8, background: "#0e0e10", border: 0, borderRadius: 8,
            padding: "12px 24px", fontSize: 14, fontWeight: 700, color: "#fff", cursor: "pointer", fontFamily: "inherit", transition: "background .12s",
          }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "#2a2a2e")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "#0e0e10")}>
            <IconDownload size={17} /> Download PDF
          </button>
        </div>
      </div>
    </Modal>
  );
}

function PayoutsTab({ store, onViewAllOrders, onViewPendingOrders }) {
  // available so the page reads consistently across stores.
  const revenue = store?.revenue || 3810;
  const orders = Math.max(Math.round(revenue / 46), 1);
  const pending = Math.max(Math.round(orders * 0.17), 1);
  const aov = revenue / orders;

  const totalProfit = Math.round(revenue * 0.34);
  const profitData = buildProfit(totalProfit);
  const pendingClearance = Math.round(totalProfit * 0.24);
  const paidThisSeason = Math.round(totalProfit * 0.76);

  return (
    <div>
      <StoreCloseReportEntry store={store} variant="reports" />
      {/* KPI row — four uniform summary cards */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 16 }}>
        <RepStatCard label="Total Revenue" value={repFmt(revenue)} icon={<IconDollar size={18} />} delta="12.4%" deltaDir="up" sub="vs last month" />
        <RepStatCard label="Orders" value={orders.toLocaleString()} icon={<IconReceipt size={18} />} delta="8.1%" deltaDir="up" sub="vs last month" onClick={onViewAllOrders} />
        <RepStatCard label="Pending Orders" value={pending.toLocaleString()} icon={<IconClock size={18} />} delta="4.6%" deltaDir="up" sub="vs last month" onClick={onViewPendingOrders} />
        <RepStatCard label="Avg. Order Value" value={repFmt(aov)} icon={<IconWallet size={18} />} delta="3.2%" deltaDir="down" sub="vs last month" />
      </div>

      {/* Team Profit chart — full width */}
      <RepPanel title="Team Profit">
        <TeamProfitChart data={profitData} />
      </RepPanel>

      {(store?.fundraisingEnabled !== false) && <FundraisingReport store={store} />}
    </div>);

}
// Internal helper — produces a "$min - $max" string for a given size, used when
// snapshotting bundle pricing.
function rangePart(items, size) {
  const vals = items.
  map((p) => parseFloat(p?.pricing?.[size]?.retail)).
  filter((v) => !isNaN(v));
  if (vals.length === 0) return "—";
  const min = Math.min(...vals);
  const max = Math.max(...vals);
  if (min === max) return min.toFixed(2);
  return `${min.toFixed(2)} - ${max.toFixed(2)}`;
}

// ─────────── Select Application Size prompt ───────────
// Shown when the user clicks "Add to Team Store" before confirming sizes on
// every pending product. "Specify Sizing" returns them to the configure cards;
// "Label As Shown" sets all applications to AS SHOWN and commits.
function SelectApplicationSizeModal({ open, onClose, onSpecify, onAsShown }) {
  return (
    <Modal open={open} onClose={onClose} width={760}>
      <div style={{ padding: "28px 32px 32px" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", paddingBottom: 16, borderBottom: "1px solid #ececf0" }}>
          <h2 style={{ fontSize: 24, fontWeight: 800, margin: 0, letterSpacing: ".01em", color: "#0e0e10" }}>SELECT APPLICATION SIZE</h2>
          <button onClick={onClose} aria-label="Close" style={{
            background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#0e0e10", display: "inline-flex"
          }}>
            <IconX size={22} style={{ strokeWidth: 2 }} />
          </button>
        </div>

        <div style={{ padding: "40px 0 48px", color: "#6b6b72", fontSize: 17, lineHeight: 1.55 }}>
          <p style={{ margin: "0 0 28px" }}>
            Application sizes have not been specified for all products. Would you like to set all applications to <strong style={{ color: "#0e0e10", fontWeight: 700 }}>&ldquo;As Shown&rdquo;</strong>?
          </p>
          <p style={{ margin: "0 0 28px" }}>
            We will match applications as close as possible to what is shown on the design.
          </p>
          <p style={{ margin: 0 }}>
            Choose &ldquo;<strong style={{ color: "#0e0e10", fontWeight: 700 }}>Specify Sizing</strong>&rdquo; if you have specific sizing requirements<br />
            (Example: Need to follow NFHS rules)
          </p>
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 24 }}>
          <button onClick={onSpecify} style={{
            background: "transparent", border: 0, cursor: "pointer",
            fontSize: 16, fontWeight: 700, color: "#0e0e10", fontFamily: "inherit", padding: "8px 4px"
          }}>Specify Sizing</button>
          <button onClick={onAsShown} style={{
            background: "#0e0e10", border: 0, borderRadius: 8, cursor: "pointer",
            fontSize: 16, fontWeight: 700, color: "#fff", fontFamily: "inherit", padding: "16px 28px"
          }}>Label &ldquo;As Shown&rdquo;</button>
        </div>
      </div>
    </Modal>);

}

// ─────────── Add Products — centralized repository page ───────────
// Consolidates every intake channel (Saved Designs, Saved Carts, Custom Products)
// onto one dedicated page with a three-tab sub-navigation. Replaces the legacy
// fork-in-the-road modal. Mirrors Step 2 (Products) of the store-creation wizard.
function AddProductsPage({ store, onCancel, onCommit, customizer, onChangeCustomizer }) {
  const accent = "#e1251b";
  const [subtab, setSubtab] = React.useState("vault");
  const [staged, setStaged] = React.useState([]);            // items added this session
  const [cfgItems, setCfgItems] = React.useState(null);      // items being size-confirmed
  const [cfgState, setCfgState] = React.useState([]);        // parallel per-item config
  const [cfgActive, setCfgActive] = React.useState(0);
  const [toast, setToast] = React.useState(null);
  // Customize New Product — XL 4-step workflow (sport → product → builder → review)
  const [customizerOpen, setCustomizerOpen] = React.useState(false);
  const [custWizStep, setCustWizStep] = React.useState(0);
  const [custSport, setCustSport] = React.useState(null);
  const [custProduct, setCustProduct] = React.useState(null);
  const [builderKind, setBuilderKind] = React.useState(null); // "bat" | "glove" | null (E1)

  const committedIds = new Set(staged.map((s) => s.srcId).filter(Boolean));
  const customStaged = staged.filter((s) => !s.srcId);
  const inStoreCount = (store.products || []).length + staged.length;

  const beginAdd = (items) => {
    setCfgItems(items);
    setCfgState(items.map(() => ({
      applicationSizes: defaultApplicationSizes(),
      teamSetting: "team-required",
      pricing: defaultPricing(),
      sizesConfirmed: false,
    })));
    setCfgActive(0);
  };
  const updateActiveConfig = (next) => setCfgState((cs) => cs.map((c, i) => i === cfgActive ? next : c));
  const updateActiveRows = (rows) => setCfgState((cs) => cs.map((c, i) => i === cfgActive ? { ...c, applicationSizes: rows } : c));

  const stageItems = (arr) => setStaged((prev) => {
    const existing = new Set(prev.map((c) => c.id));
    return [...prev, ...arr.filter((s) => !existing.has(s.id))];
  });

  const confirmConfig = () => {
    if (!cfgItems) return;
    const stamped = cfgItems.map((it, i) => {
      const cfg = cfgState[i];
      return {
        ...it,
        teamSetting: cfg.teamSetting,
        applicationSizes: cfg.applicationSizes,
        pricing: cfg.pricing,
        adult: cfg.pricing.adult.retail,
        youth: cfg.pricing.youth.retail,
        sizesConfirmed: true,
      };
    });
    stageItems(stamped);
    setCfgItems(null);
    setToast(stamped.length > 1 ? `Added ${stamped.length} products` : `Added "${stamped[0].title}"`);
  };

  const addDesign = (d) => beginAdd([{ id: `wd-${d.id}`, srcId: d.id, title: d.title, style: `${d.sport} · ${d.category}`, photo: d.photo, adult: d.adult, youth: d.youth, teamProfit: d.teamProfit }]);
  const addCart = (c) => beginAdd(c.items.map((it) => ({ id: `wc-${it.id}`, srcId: c.id, title: it.title, style: "From " + c.name, photo: it.photo, adult: it.adult, youth: it.youth, teamProfit: it.teamProfit })));

  const openCustomizer = () => { setCustomizerOpen(true); setCustWizStep(0); setCustSport(null); setCustProduct(null); };

  const TABS = [
    { k: "vault", l: "Product Vault" },
    { k: "designs", l: "Saved Designs" },
    { k: "carts", l: "Saved Carts" },
    { k: "custom", l: "Customize" },
  ];
  const addVaultItem = (v) => beginAdd([{ id: "wv-" + v.id, srcId: v.id, title: v.title, style: v.source + " · from Product Vault", srcKind: "vault", photo: v.photo, letter: v.letter, brand: v.brand, source: v.source, category: v.category, stock: "in", deco: "approved", decoratable: true }]);
  const addCatalogItem = (c) => beginAdd([{ id: "wm-" + c.id, srcId: c.id, srcKind: "catalog", title: c.title, sku: c.sku, style: c.sku + " · blank — supplier cost " + c.cost, photo: c.photo, letter: c.letter, brand: c.sku.startsWith("V") ? "Victus" : "Marucci", source: "Marucci stock", category: c.cat, stock: c.oos ? "out" : "in", deco: "none", decoratable: c.dec }]);

  const dashedAddCard = (
    <div
      onClick={openCustomizer}
      style={{
        border: "1px dashed #b4b4bb", borderRadius: 10, background: "#fafafa",
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        minHeight: 360, cursor: "pointer", gap: 16, padding: 28,
        transition: "border-color .14s, background .14s",
      }}
      onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#0e0e10"; e.currentTarget.style.background = "#f1f1f3"; }}
      onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#b4b4bb"; e.currentTarget.style.background = "#fafafa"; }}>
      <svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
        <circle cx="20" cy="20" r="18.5" stroke="#0e0e10" strokeWidth="1.5" />
        <path d="M20 11v18M11 20h18" stroke="#0e0e10" strokeWidth="2" strokeLinecap="round" />
      </svg>
      <span style={{ fontSize: 16, fontWeight: 800, color: "#0e0e10", textAlign: "center" }}>Customize New Product</span>
      <span style={{ fontSize: 12.5, color: "#9a9aa1", textAlign: "center", lineHeight: 1.5, maxWidth: 200 }}>Build a product from scratch in the customizer.</span>
    </div>
  );

  return (
    <div style={{ paddingBottom: 92 }}>
      {/* Header context */}
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ fontSize: 24, fontWeight: 800, letterSpacing: ".01em", margin: "0 0 8px", color: "#0e0e10", fontFamily: "Archivo, sans-serif" }}>Add Products</h2>
        <p style={{ fontSize: 14, color: "#6b6b72", margin: 0, lineHeight: 1.55, maxWidth: 780 }}>
          Pull products from the Product Vault — every enabled vendor's catalog plus the decorated items saved from it — your saved designs and carts, or customize a new one. Each item confirms its application sizes before it's added to the store.
        </p>
      </div>

      <WizardPanel label="Product catalog" hint={`${inStoreCount} product${inStoreCount === 1 ? "" : "s"} in store`}>
        {/* Segmented sub-tab controller */}
        <div style={{ display: "inline-flex", background: "#f1f1f3", borderRadius: 8, padding: 4, marginBottom: 16 }}>
          {TABS.map((t) => {
            const on = subtab === t.k;
            return (
              <button key={t.k} type="button" onClick={() => setSubtab(t.k)} style={{
                padding: "8px 20px", border: 0, borderRadius: 6, cursor: "pointer",
                fontSize: 13, fontWeight: 700, letterSpacing: ".01em",
                background: on ? "#fff" : "transparent", color: on ? "#0e0e10" : "#6b6b72",
                boxShadow: on ? "0 1px 3px rgba(20,20,30,.12)" : "none", transition: "all .14s",
              }}>{t.l}{t.isNew && <span style={{ marginLeft: 7, fontSize: 8.5, fontWeight: 800, letterSpacing: ".08em", background: "#e1251b", color: "#fff", borderRadius: 4, padding: "2px 5px", verticalAlign: "1px" }}>NEW</span>}</button>
            );
          })}
        </div>
        {customizer && subtab !== "vault" && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 24, width: "fit-content", background: "#f4f4f5", border: "1px solid #ececf0", borderRadius: 999, padding: "8px 16px 8px 12px" }}>
            <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".04em", textTransform: "uppercase", color: "#9a9aa1" }}>Source</span>
            {customizer.logoBlack || customizer.logoInk ? (
              <img src={customizer.logoBlack || customizer.logoInk} alt={customizer.name} style={{ height: 16, width: "auto" }} />
            ) : (
              <span style={{ fontSize: 13.5, fontWeight: 800, color: "#0e0e10" }}>{customizer.wordmark || customizer.name}</span>
            )}
            <button onClick={onChangeCustomizer || onCancel} title="Change customizer" style={{ border: 0, background: "transparent", cursor: "pointer", color: "#6b6b72", fontSize: 12.5, fontWeight: 600, padding: 0, textDecoration: "underline", textUnderlineOffset: 2 }}>Change</button>
          </div>
        )}

        {subtab === "vault" && (
          <VaultTabContent store={typeof store !== "undefined" ? store : null} accent={accent}
            committedIds={committedIds} onAddVault={addVaultItem} onAddCatalog={addCatalogItem} />
        )}
        {subtab === "designs" && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 16 }}>
            {WIZARD_SAVED_DESIGNS.map((d) => (
              <SavedAssetCard key={d.id} kind="design" accent={accent}
                title={d.title} subtitle={d.block || `${d.sport} · ${d.category}`} photo={d.photo}
                committed={committedIds.has(d.id)} onAdd={() => addDesign(d)}
                onEdit={() => {}} onRemove={() => {}} />
            ))}
          </div>
        )}
        {subtab === "carts" && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 16 }}>
            {WIZARD_SAVED_CARTS.map((c) => (
              <SavedAssetCard key={c.id} kind="cart" accent={accent}
                title={c.name} subtitle={`${c.items.length} items · $${c.total.toFixed(2)}`} items={c.items}
                committed={committedIds.has(c.id)} onAdd={() => addCart(c)}
                onEdit={() => {}} onRemove={() => {}} />
            ))}
          </div>
        )}
        {subtab === "custom" && (
          customStaged.length === 0 ? (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 16 }}>
              {dashedAddCard}
            <BuilderLaunchCards onOpen={setBuilderKind} />
            </div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 16 }}>
              {customStaged.map((p) => (
                <SavedAssetCard key={p.id} kind="design" accent={accent}
                  title={p.title} subtitle={p.style || "Custom product"} photo={p.photo}
                  committed={true} onAdd={() => {}} onEdit={() => {}} onRemove={() => {}} />
              ))}
              {dashedAddCard}
            </div>
          )
        )}
      </WizardPanel>

      {/* Per-item application-size confirmation */}
      {cfgItems && (
        <ConfirmSizesModal
          open={!!cfgItems}
          product={cfgItems[cfgActive]}
          store={store}
          rows={cfgState[cfgActive].applicationSizes}
          onChange={updateActiveRows}
          productConfig={cfgState[cfgActive]}
          onConfigChange={updateActiveConfig}
          items={cfgItems}
          activeIndex={cfgActive}
          onActiveIndexChange={setCfgActive}
          confirmLabel={cfgItems.length > 1 ? `Add ${cfgItems.length} Products to Store` : "Add to Store"}
          allowRosterAssign={true}
          onClose={() => setCfgItems(null)}
          onConfirm={confirmConfig} />
      )}

      <MarucciBuilderModal open={!!builderKind} kind={builderKind} store={store} onClose={() => setBuilderKind(null)} onAdd={(p) => { stageItems([p]); setBuilderKind(null); setToast("Added \"" + p.title + "\""); }} />
      {/* Customize New Product — XL 4-step workflow modal */}
      <Modal open={customizerOpen} onClose={() => setCustomizerOpen(false)} width="min(1280px, 92vw)">
        <div style={{ display: "flex", flexDirection: "column", height: "88vh", borderRadius: 8, overflow: "hidden" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 28px", borderBottom: "1px solid #ececf0", flexShrink: 0, background: "#fff" }}>
            <h3 style={{ fontSize: 18, fontWeight: 800, margin: 0, letterSpacing: ".01em", color: "#0e0e10" }}>Customize New Product</h3>
            <button onClick={() => setCustomizerOpen(false)} style={{ background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#6b6b72" }}>
              <IconX size={20} />
            </button>
          </div>
          <div style={{ flex: 1, overflow: "hidden", minHeight: 0, background: "#fff" }}>
            {custWizStep === 0 && (
              <CustSportPickerStep
                storeSport={(store.sports && store.sports[0]) || "Basketball"}
                onPick={(item) => { setCustSport(item); setCustWizStep(1); }} />
            )}
            {custWizStep === 1 && (
              <CustProductPickerStep sport={custSport} onBack={() => setCustWizStep(0)}
                onPick={(product) => { setCustProduct(product); setCustWizStep(2); }} />
            )}
            {custWizStep === 2 && (
              <CustBuilderStep sport={custSport} product={custProduct}
                onBack={() => setCustWizStep(1)} onAddToStore={() => setCustWizStep(3)} />
            )}
            {custWizStep === 3 && (
              <CustReviewStep sport={custSport} product={custProduct}
                onBack={() => setCustWizStep(2)} onCancel={() => setCustomizerOpen(false)}
                onAddToStore={(finalProduct) => {
                  stageItems([finalProduct]);
                  setCustomizerOpen(false);
                  setToast("Added 1 custom product");
                }} />
            )}
          </div>
        </div>
      </Modal>

      {/* Sticky footer control ribbon */}
      <FloatingActionBar
        leftChildren={
          <button type="button" onClick={onCancel} style={{
            background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6,
            padding: "12px 28px", fontSize: 13, fontWeight: 700, color: "#0e0e10", cursor: "pointer",
            transition: "border-color .14s, background .14s",
          }}
            onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#0e0e10"; e.currentTarget.style.background = "#f7f7f8"; }}
            onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#d4d4d8"; e.currentTarget.style.background = "#fff"; }}>
            Cancel
          </button>
        }>
        <button type="button" disabled={staged.length === 0} onClick={() => onCommit(staged)} style={{
          background: staged.length === 0 ? "#e4e4e7" : "#0e0e10",
          color: staged.length === 0 ? "#a1a1aa" : "#fff",
          border: 0, borderRadius: 6, padding: "12px 32px",
          fontSize: 13, fontWeight: 700,
          cursor: staged.length === 0 ? "not-allowed" : "pointer",
          transition: "background .14s, color .14s",
        }}>
          Confirm Selection{staged.length > 0 ? ` (${staged.length})` : ""}
        </button>
      </FloatingActionBar>

      <Toast message={toast} onDone={() => setToast(null)} />
    </div>
  );
}

// Customizers the signed-in user is entitled to pull product from. Mirrors the
// "Choose a Customizer" step of the sign-in flow. Only entitled brands appear.
// MVP showcase: ProLook is the only connected Customizer. Add ids back here
// ("alli", "riddell", "game-one", "varsity", "squadlocker", "bsn-sports", "augusta")
// to demo the multi-brand experience — all multi-brand UI stays functional.
const ACCESSIBLE_CUSTOMIZERS = ["prolook"];

// Reused "Choose a Customizer" picker — shown before the Add Products flow so the
// rep selects which Customizer to pull product from.
function ChooseCustomizerModal({ open, onClose, onSelect, ids = ACCESSIBLE_CUSTOMIZERS }) {
  const items = ids.map((id) => ({ id, ...CUSTOMIZER_BRANDS[id] })).filter((b) => b.name);
  return (
    <Modal open={open} onClose={onClose} width={560}>
      <div style={{ padding: "40px 40px 44px", position: "relative" }}>
        <button onClick={onClose} title="Close" style={{
          position: "absolute", top: 20, right: 20, border: 0, background: "transparent", cursor: "pointer",
          color: "#9a9aa1", width: 32, height: 32, borderRadius: 8, display: "inline-flex", alignItems: "center", justifyContent: "center",
        }}>
          <IconX size={20} />
        </button>
        <h3 style={{ margin: "0 0 8px", fontSize: 25, fontWeight: 800, letterSpacing: "-.3px", color: "#09090b", textAlign: "center" }}>Choose a Customizer</h3>
        <p style={{ margin: "0 0 32px", fontSize: 15, color: "#71717a", textAlign: "center" }}>We use your Customizer sign-in.</p>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
          {items.map((c) => (
            <button key={c.id} onClick={() => onSelect(c)} title={c.name} style={{
              aspectRatio: "1 / 1", display: "flex", alignItems: "center", justifyContent: "center",
              padding: 12, background: "#f4f4f5", border: "1.5px solid #f4f4f5", borderRadius: 14, cursor: "pointer",
              transition: "border-color .12s, background .12s",
            }}
              onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#dc2626"; e.currentTarget.style.background = "#fff"; }}
              onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#f4f4f5"; e.currentTarget.style.background = "#f4f4f5"; }}>
              {c.logoBlack || c.logoInk ? (
                <img src={c.logoBlack || c.logoInk} alt={c.name} style={{ maxHeight: 36, maxWidth: "78%", width: "auto", objectFit: "contain" }} />
              ) : (
                <span style={{ fontSize: 17, fontWeight: 800, letterSpacing: "-.2px", color: "#18181b", lineHeight: 1.1, textAlign: "center" }}>{c.wordmark || c.name}</span>
              )}
            </button>
          ))}
        </div>
      </div>
    </Modal>
  );
}

function ProductsTab({ store, onCustomize, onProductsChange, simulateOrders }) {
  const [showAdd, setShowAdd] = React.useState(false);
  const [addMode, setAddMode] = React.useState(false);
  const [chooseCustomizer, setChooseCustomizer] = React.useState(false);
  const [sourceCustomizer, setSourceCustomizer] = React.useState(null);
  const [toast, setToast] = React.useState(null);
  const [bundleMode, setBundleMode] = React.useState(false);
  const [showSizesPrompt, setShowSizesPrompt] = React.useState(false);
  const pending = store.pendingProducts || [];
  const products = store.products || [];
  // Tell the onboarding tour when products are being configured (drives the
  // m1-choose → m1-sizes step deterministically, no DOM polling).
  React.useEffect(() => {
    if (pending.length > 0) window.dispatchEvent(new CustomEvent("tour:configuring"));
  }, [pending.length]);
  // Catalog items available to bundle (un-bundled, non-bundle items only).
  const bundledIds = new Set(products.flatMap((p) => p.isBundle ? p.bundleItemIds || [] : []));
  const draftPool = products.filter((p) => !p.isBundle && !bundledIds.has(p.id));

  // ── Products Tab Evolution (spec 4231856129): view routing + canonical-record intake ──
  const multiSource = isMultiSourceStore(store);
  const [pteView, setPteView] = React.useState(() => { if (typeof window !== "undefined" && window.__openProductCats) { delete window.__openProductCats; return "cats"; } return "list"; });
  const [batchItems, setBatchItems] = React.useState(null);
  const [imagesId, setImagesId] = React.useState(null);
  const [editorId, setEditorId] = React.useState(null);
  // Register this store as the Product Vault's deploy target while its
  // Products tab is open (re-assigned each render so closures stay fresh).
  React.useEffect(() => {
    window.__vaultDeployTarget = {
      label: store.storeTitle || store.teamName,
      entitled: store.entitledBrands || ["Marucci", "Victus"],
      deploy: (item) => {
        onProductsChange({ pendingProducts: pending, products: [...products, {
          id: "dep-" + item.id + "-" + Date.now(), title: item.title, brand: item.brand, source: item.source,
          category: item.category || "Fleece", stock: "in", deco: "approved", decoratable: true, photo: item.photo,
          status: "live", srcKind: "vault", teamSetting: "fan-gear", subtitle: "From Vault · confirm pricing, setting & sizes",
        }] });
        setPteView("list");
        setToast("Deployed from Vault — pricing, team setting & sizes need confirmation");
      },
    };
    return () => { delete window.__vaultDeployTarget; };
  });
  // Every intake channel passes items through the existing per-item confirm
  // (application sizes, team setting, pricing) before they land as drafts.
  const pteStagePending = (items) => {
    onProductsChange({ products, pendingProducts: [...pending, ...items.map((c) => ({
      __pendingId: "pte-" + c.id + "-" + Date.now() + Math.random().toString(36).slice(2, 5),
      title: c.title, photo: c.photo, thumbnail: c.photo ? <CatalogPhoto photo={c.photo} alt={c.title} /> : undefined,
      brand: c.brand, source: c.source, category: c.category, stock: c.stock, deco: c.deco, decoratable: c.decoratable,
      subtitle: c.subtitle, sku: c.sku,
    }))] });
    setPteView("list");
  };

  // Per-pending-item config state (sizesConfirmed, modal open, pricing, settings, sizes).
  const [configs, setConfigs] = React.useState({});

  // Initialize a config slot for any new pending items
  React.useEffect(() => {
    setConfigs((prev) => {
      const next = { ...prev };
      let changed = false;
      pending.forEach((p) => {
        const key = p.__pendingId;
        if (key && !next[key]) {
          next[key] = {
            teamSetting: p.teamSetting || "team-required",
            optRequired: p.teamSetting !== "team-supplied",
            optSupplied: p.teamSetting === "team-supplied",
            pricing: p.pricing || defaultPricing(),
            applicationSizes: defaultApplicationSizes(),
            // Category pre-fills from source metadata when it matches a workspace category.
            storeCategory: (window.__prodCats || []).some((cc) => cc.name === p.category) ? p.category : "",
            storeSubcategory: "",
            rosters: p.rosters || [],
            sizesConfirmed: pteNoAppSizes(p),
            showSizesModal: false
          };
          changed = true;
        }
      });
      // Garbage-collect configs for items no longer pending
      const pendingIds = new Set(pending.map((p) => p.__pendingId));
      Object.keys(next).forEach((k) => {
        if (!pendingIds.has(k)) {delete next[k];changed = true;}
      });
      return changed ? next : prev;
    });
  }, [pending]);

  const allConfirmed = pending.length > 0 && pending.every((p) => configs[p.__pendingId]?.sizesConfirmed);

  const handleChoice = (choice) => {
    setShowAdd(false);
    if (choice === "Customize New Product") {
      onCustomize && onCustomize();
      return;
    }
    if (choice === "Add From Cart") {
      window.__openMyCarts && window.__openMyCarts();
      return;
    }
    if (choice === "Add Saved Design") {
      window.__openSavedDesigns && window.__openSavedDesigns();
      return;
    }
    setToast(`Opening ${choice}…`);
  };

  const commitAllPending = (forceAsShown = false) => {
    // 2.4 / 3.1 — a category (or a team setting) is required per item before commit.
    const missing = pending.filter((p) => { const c = configs[p.__pendingId] || {}; return !(c.optRequired || c.optSupplied) && !c.storeCategory; });
    if (missing.length) {
      const ids = new Set(missing.map((p) => p.__pendingId));
      setConfigs((cs) => { const n = { ...cs }; ids.forEach((k) => { if (n[k]) n[k] = { ...n[k], catError: true }; }); return n; });
      setToast("Select a category for every item — items no longer default to Fan Gear");
      return;
    }
    const asShownRows = (rows) => (rows || []).map((r) => ({ ...r, adultSize: "AS SHOWN", youthSize: "AS SHOWN" }));
    const newDrafts = pending.map((p) => {
      const c = configs[p.__pendingId] || {};
      // Derive the legacy single-value teamSetting from the two toggles for the
      // product card badge. Required wins if both are on.
      const ts = c.optRequired ? "team-required" : c.optSupplied ? "team-supplied" : "fan-gear";
      return {
        ...p,
        teamSetting: ts,
        optRequired: !!c.optRequired,
        optSupplied: !!c.optSupplied,
        pricing: c.pricing,
        applicationSizes: forceAsShown ? asShownRows(c.applicationSizes) : c.applicationSizes,
        storeCategory: (c.optRequired || c.optSupplied) ? "Team Gear" : (c.storeCategory || ""),
        storeSubcategory: c.storeSubcategory || "",
        rosters: c.rosters || [],
        id: "prod-" + p.__pendingId,
        status: "live",
        ready: true
      };
    });
    onProductsChange({
      pendingProducts: [],
      products: [...products, ...newDrafts]
    });
    setConfigs({});
    // Sizes are confirmed at this point, so the product is Ready — let the tour advance.
    window.dispatchEvent(new CustomEvent("tour:product-ready"));
    setToast(newDrafts.length > 1 ? `Added ${newDrafts.length} items to the store` : `Added "${newDrafts[0].title}" to the store`);
  };

  // Open the Add Products flow, seeded with the chosen source customizer.
  const beginAddFromCustomizer = (c) => {
    setSourceCustomizer(c);
    setChooseCustomizer(false);
    setAddMode(true);
    setToast(`Pulling products from ${c.name}`);
  };

  // Commit items staged on the Add Products page into the store as ready drafts.
  const commitStaged = (staged) => {
    if (!staged || staged.length === 0) { setAddMode(false); return; }
    const newDrafts = staged.map((s) => {
      const ts = s.teamSetting || "team-required";
      return {
        ...s,
        id: s.id && String(s.id).startsWith("prod-") ? s.id : "prod-" + (s.id || Date.now()) + "-" + Math.random().toString(36).slice(2, 6),
        title: s.title,
        thumbnail: s.photo ? <CatalogPhoto photo={s.photo} alt={s.title} /> : undefined,
        status: "live",
        ready: true,
        teamSetting: ts,
        optRequired: ts === "team-required",
        optSupplied: ts === "team-supplied",
        pricing: s.pricing || defaultPricing(),
        applicationSizes: s.applicationSizes,
        isBundle: false,
      };
    });
    onProductsChange({ pendingProducts: pending, products: [...products, ...newDrafts] });
    setAddMode(false);
    window.dispatchEvent(new CustomEvent("tour:product-ready"));
    setToast(newDrafts.length > 1 ? `Added ${newDrafts.length} items to the store` : `Added "${newDrafts[0].title}" to the store`);
  };

  // ── Products Tab Evolution views ──
  if (pteView === "batch" && batchItems) {
    return (
      <React.Fragment>
        <BatchDecorateView
          store={store}
          items={batchItems}
          onCancel={() => { setBatchItems(null); setPteView("list"); }}
          onSave={(included) => {
            const fromStoreIds = new Set(included.filter((b) => b.fromStore).map((b) => b.id));
            const updated = products.map((p) => fromStoreIds.has(p.id)
              ? { ...p, deco: "render", source: "Decorated stock", subtitle: ((p.subtitle || p.sku || "").replace(/ · blank.*$/, "") + " · decorated — render queued") }
              : p);
            const added = included.filter((b) => !b.fromStore).map((c) => ({
              id: "bd-" + c.id + "-" + Date.now(), title: c.title + " — " + ((store.teamName || "Team").split(" ")[0]),
              brand: c.brand || "Marucci", source: "Decorated stock", category: c.category, stock: "in", deco: "render",
              decoratable: true, photo: c.photo, status: "live", teamSetting: "fan-gear",
              subtitle: "Batch decorated · render queued · art: Draft",
            }));
            const holdIds = new Set(included.filter((b) => b.artHold).map((b) => b.id));
            const withHold = (arr) => arr.map((p) => holdIds.has(p.id) || holdIds.has((p.id || "").replace(/-deco.*$/, "")) ? { ...p, artHold: true, hidden: true } : p);
            onProductsChange({ pendingProducts: pending, products: [...withHold(updated), ...withHold(added)] });
            setBatchItems(null);
            setPteView("list");
            setToast(included.some((b) => b.artHold) ? included.length + " decorated items created — held from the storefront until the logo is production-ready" : included.length + " decorated items created — renders queued, art enters approval as Draft");
          }} />
        <Toast message={toast} onDone={() => setToast(null)} />
      </React.Fragment>
    );
  }
  // Image Editor overlay — opened from the products table's decorate action or
  // from the Images view. Saving placement pulls art back to Draft for approval.
  const editorProduct = editorId ? products.find((x) => x.id === editorId) : null;
  const editorOverlay = editorProduct ? (
    <ProductImageEditor
      product={editorProduct}
      store={store}
      onBack={() => setEditorId(null)}
      onSave={({ dirty, zone }) => {
        if (!dirty) return;
        onProductsChange({ pendingProducts: pending, products: products.map((x) => x.id === editorProduct.id
          ? { ...x, deco: "draft", subtitle: (x.sku ? x.sku + " · " : "") + "Placement saved · " + zone + " · art: Draft" }
          : x) });
      }} />
  ) : null;

  // Products sub-navigation — same side-nav treatment as Orders and Settings.
  const prodNav = [
    { id: "list", label: "Catalog", desc: "Products, pricing & visibility" },
    { id: "cats", label: "Categories & Sorting", desc: "Storefront order & featured items" },
  ];

  if (pteView === "cats") {
    return (
      <div style={{ paddingBottom: 60 }}>
        <div style={{ display: "flex", gap: 36, alignItems: "flex-start" }}>
          <SectionSideNav items={prodNav} value="cats" onChange={setPteView} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <StoreCategoryManager store={store} products={products} onToast={setToast} />
          </div>
        </div>
        <Toast message={toast} onDone={() => setToast(null)} />
      </div>);
  }

  if (pteView === "images") {
    const ip = products.find((p) => p.id === imagesId);
    if (ip) return (
      <React.Fragment>
        <ProductImagesView
          product={ip}
          store={store}
          onBack={() => setPteView("list")}
          onOpenEditor={() => setEditorId(ip.id)}
          onUpdateProduct={(u) => onProductsChange({ pendingProducts: pending, products: products.map((p) => p.id === u.id ? u : p) })}
          onToast={setToast} />
        {editorOverlay}
        <Toast message={toast} onDone={() => setToast(null)} />
      </React.Fragment>
    );
  }

  // 0) Add Products page — centralized repository (replaces the fork modal).
  if (addMode) {
    return (
      <React.Fragment>
        <AddProductsPage store={store} customizer={sourceCustomizer} onCancel={() => setAddMode(false)} onChangeCustomizer={() => { setAddMode(false); setChooseCustomizer(true); }} onCommit={commitStaged} />
        <Toast message={toast} onDone={() => setToast(null)} />
      </React.Fragment>
    );
  }

  // 1) If there are pending products to configure, show the configure cards
  if (pending.length > 0) {
    return (
      <div style={{ paddingBottom: 100 }}>
        <h2 style={{ fontSize: 22, fontWeight: 700, margin: "4px 0 16px", color: "#0e0e10" }}>
          {pending.length > 1 ? "Add Products" : "Add Product"}
        </h2>
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {pending.map((p, i) => {
            const cfg = configs[p.__pendingId];
            if (!cfg) return null;
            return (
              <ConfigureProduct
                key={p.__pendingId}
                product={p}
                store={store}
                index={i}
                total={pending.length}
                config={cfg}
                onConfigChange={(next) => setConfigs((cs) => ({ ...cs, [p.__pendingId]: next }))}
                onProductChange={(updated) => {
                  onProductsChange({
                    pendingProducts: pending.map((pp) => pp.__pendingId === p.__pendingId ? updated : pp),
                    products
                  });
                }}
                onDelete={() => {
                  setConfigs((cs) => {const n = { ...cs };delete n[p.__pendingId];return n;});
                  onProductsChange({
                    pendingProducts: pending.filter((pp) => pp.__pendingId !== p.__pendingId),
                    products
                  });
                }} />);


          })}
        </div>

        {/* Single shared footer */}
        <FloatingActionBar>
          <button
            data-tour={allConfirmed ? "add-to-store" : undefined}
            onClick={() => allConfirmed ? commitAllPending() : setShowSizesPrompt(true)}
            style={{
              background: "#0e0e10",
              color: "#fff",
              border: 0, borderRadius: 6, padding: "12px 28px",
              fontSize: 14, fontWeight: 600,
              cursor: "pointer",
              transition: "background .15s, color .15s"
            }}>Add to Team Store</button>
        </FloatingActionBar>
        <SelectApplicationSizeModal
          open={showSizesPrompt}
          onClose={() => setShowSizesPrompt(false)}
          onSpecify={() => setShowSizesPrompt(false)}
          onAsShown={() => {setShowSizesPrompt(false);commitAllPending(true);}} />
        <Toast message={toast} onDone={() => setToast(null)} />
      </div>);

  }

  // 2a) Bundle creation mode — inline panel that replaces the products list.
  if (bundleMode && products.length > 0) {
    return (
      <div>
        <CreateBundleSection
          store={store}
          draftProducts={draftPool}
          onCancel={() => setBundleMode(false)}
          onCreate={({ name, teamSetting, productIds, bundleType, category, bundleProfit, hidden, hideRetail, freeShipping, groups, vaultAdds }) => {
            const pool = [...products, ...(vaultAdds || [])];
            const items = productIds.
            map((id) => pool.find((p) => p.id === id)).
            filter(Boolean);
            const newBundle = {
              id: "bundle-" + Date.now(),
              title: name,
              isBundle: true,
              bundleType: bundleType || "all",
              storeCategory: teamSetting ? "Team Gear" : (category || ""),
              status: "live",
              teamSetting: teamSetting || "fan-gear",
              bundleItemIds: productIds,
              groups: groups || [],
              bundleProfit, hidden: !!hidden, hideRetail: !!hideRetail, freeShipping: !!freeShipping,
              // Snapshot the bundle-derived customer price — the card’s "from $X".
              pricing: bundleCardPricing(
                items, null, bundleProfit, bundleType || "all",
                teamSetting === "team-supplied", store?.fundraisingEnabled !== false
              )
            };
            onProductsChange({
              pendingProducts: pending,
              products: [newBundle, ...products]
            });
            setBundleMode(false);
            setToast(`Created bundle "${name}"`);
          }} />
        <Toast message={toast} onDone={() => setToast(null)} />
      </div>);

  }

  // 2) Drafts / Published / Vault list — rendered even with an empty catalog
  // (the Vault tab must be reachable before any products exist; empty Drafts /
  // Published tabs carry the Add Products call-to-action instead).
  {
    return (
      <div style={{ paddingBottom: 60 }}>
        {editorOverlay}
        <div style={{ display: "flex", gap: 36, alignItems: "flex-start" }}>
        <SectionSideNav items={prodNav} value="list" onChange={setPteView} />
        <div style={{ flex: 1, minWidth: 0 }}>
        <ProductsListV2
          products={products}
          store={store}
          multiSource={multiSource}
          onOpenImages={(id) => { setImagesId(id); setPteView("images"); }}
          onOpenEditor={(id) => setEditorId(id)}
          onManageCategories={() => setPteView("cats")}
          onDecorateBatch={(items) => { setBatchItems(items); setPteView("batch"); }}
          onPatchStore={(patch) => onProductsChange({ pendingProducts: pending, products, ...patch })}
          onToast={setToast}
          onSendForApproval={(id) => {
            setToast("Sent for approval");
          }}
          onRemove={(id) => {
            onProductsChange({
              pendingProducts: pending,
              products: products.filter((p) => p.id !== id)
            });
          }}
          onAddProducts={() => { setSourceCustomizer({ id: "prolook", ...CUSTOMIZER_BRANDS.prolook }); setAddMode(true); }}
          onCreateBundle={() => setBundleMode(true)}
          onUpdateProduct={(updated) => {
            onProductsChange({
              pendingProducts: pending,
              products: products.map((p) => p.id === updated.id ? updated : p)
            });
            setToast("Product updated");
          }}
          onBulkPrice={(ids, profit) => {
            const idSet = new Set(ids);
            const applyTier = (tier) => {
              const t = tier || {};
              const base = parseFloat(t.base) || 0;
              const dealer = profit.dealer !== "" ? profit.dealer : t.dealer ?? "0";
              const team = profit.team !== "" ? profit.team : t.team ?? "0";
              const retail = (base + (parseFloat(dealer) || 0) + (parseFloat(team) || 0)).toFixed(2);
              return { ...t, dealerUnit: "$", dealer: String(dealer), teamUnit: "$", team: String(team), retail };
            };
            onProductsChange({
              pendingProducts: pending,
              products: products.map((p) => {
                if (!idSet.has(p.id)) return p;
                const pricing = p.pricing || defaultPricing();
                return { ...p, pricing: { ...pricing, youth: applyTier(pricing.youth), adult: applyTier(pricing.adult) } };
              })
            });
            setToast(ids.length > 1 ? `Pricing updated for ${ids.length} products` : "Pricing updated");
          }} />
        
        </div>
        </div>
        <Toast message={toast} onDone={() => setToast(null)} />
        <ChooseCustomizerModal open={chooseCustomizer} onClose={() => setChooseCustomizer(false)} onSelect={beginAddFromCustomizer} />
      </div>);

  }

  // 3) Empty state — single CTA into the centralized Add Products page (no fork).
  return (
    <div style={{ paddingBottom: 60 }}>
      <div style={{
        display: "flex", flexDirection: "column", alignItems: "center",
        padding: "152px 20px 24px", textAlign: "center"
      }}>
        <div style={{
          width: 56, height: 56, borderRadius: "50%", background: "#f1f1f3", color: "#0e0e10",
          display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 16
        }}>
          <IconShirt size={26} />
        </div>
        <h2 style={{ fontSize: 22, fontWeight: 800, margin: 0, marginBottom: 8, color: "#0e0e10" }}>No products yet</h2>
        <div style={{ color: "#6b6b72", fontSize: 14, maxWidth: 420, lineHeight: 1.55, marginBottom: 24 }}>
          Pull products from your saved designs and carts, or customize a new one, to start building this store.
        </div>
        <button type="button" onClick={() => { setSourceCustomizer({ id: "prolook", ...CUSTOMIZER_BRANDS.prolook }); setAddMode(true); }} style={{
          background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6,
          padding: "12px 28px", fontSize: 14, fontWeight: 700, cursor: "pointer",
          display: "inline-flex", alignItems: "center", gap: 8,
        }}>
          <IconPlus size={16} style={{ strokeWidth: 2.6 }} /> Add Products
        </button>
      </div>

      <Toast message={toast} onDone={() => setToast(null)} />
      <ChooseCustomizerModal open={chooseCustomizer} onClose={() => setChooseCustomizer(false)} onSelect={beginAddFromCustomizer} />
    </div>);

}

