// Deterministic bulk capture generator — hundreds of checkout captures for
// stores that run roster-less. Same schema the storefront consent gate writes.
function bulkRng(seed) { let a = seed >>> 0; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const BB_FIRST = ["Mason", "Liam", "Noah", "Ethan", "Owen", "Carter", "Wyatt", "Luke", "Jack", "Levi", "Miles", "Eli", "Ava", "Mia", "Zoe", "Ruby", "Nora", "Isla", "Cole", "Reid", "Beckett", "Finn", "Hudson", "Tate", "Brooks", "Nash", "Ivy", "June", "Sage", "Wren"];
const BB_LAST = ["Rivera", "Pruitt", "Chen", "Okafor", "Sorensen", "Whitaker", "Delgado", "Marsh", "Kowalski", "Bennett", "Vaughn", "Ferris", "Nakamura", "Ortiz", "Hale", "Barlow", "Quintana", "Mercer", "Solberg", "Ashton", "Ibarra", "Foss", "Redding", "Calloway", "Voss", "Tran", "Muir", "Ellison", "Padgett", "Rooks"];
function makeBulkBank(prefix, teamIds, clusterCount, items, conflictBudget = 5) {
  const rnd = bulkRng(prefix.length * 7349 + clusterCount);
  const pick = (a) => a[Math.floor(rnd() * a.length)];
  const bank = {};
  let conflicts = 0;
  teamIds.forEach((t) => { bank[t] = []; });
  for (let i = 0; i < clusterCount; i++) {
    const tid = teamIds[i % teamIds.length];
    const first = pick(BB_FIRST), last = pick(BB_LAST);
    const player = first + " " + last;
    const email = (first + "." + last).toLowerCase() + (rnd() < 0.3 ? ".family" : "") + "@" + pick(["gmail.com", "yahoo.com", "outlook.com", "icloud.com"]);
    const phone = "(" + pick(["385", "801", "435", "619", "760"]) + ") 555-0" + String(100 + Math.floor(rnd() * 900)).slice(0, 3);
    const address = String(40 + Math.floor(rnd() * 9600)) + " " + pick(["Fox Hollow Ln", "Cedar St", "Aspen Way", "Harbor Dr", "Canyon Rd", "Willow Ct", "Seacrest Ave", "Alpine Loop"]) + ", " + pick(["Draper, UT 84020", "Lehi, UT 84043", "Sandy, UT 84094", "Provo, UT 84601", "Huntington Beach, CA 92646", "Carlsbad, CA 92009"]);
    // Jerseys are unique within a team except a small deliberate conflict budget —
    // number clashes are rare in practice.
    if (!bank[tid].__used) Object.defineProperty(bank[tid], "__used", { value: [], enumerable: false });
    const used = bank[tid].__used;
    let jersey;
    if (conflicts < conflictBudget && used.length > 3 && rnd() < 0.04) { jersey = pick(used); conflicts++; }
    else { let tries = 0; do { jersey = String(Math.floor(rnd() * 100)); tries++; } while (used.includes(jersey) && tries < 200); }
    used.push(jersey);
    const date = "Jul " + (8 + Math.floor(rnd() * 18)) + ", 2026";
    const order = "435" + Array.from({ length: 10 }, () => pick(["A", "B", "C", "D", "E", "F", "G", "H", "J", "K", "M", "N", "P", "R", "S", "T", "U", "V", "W", "X", "Y", "Z", "2", "3", "4", "5", "6", "7", "8", "9"])).join("");
    const caps = [];
    const n = rnd() < 0.72 ? 1 : 2;
    for (let j = 0; j < n; j++) {
      const it = pick(items);
      caps.push({ id: prefix + "-c" + i + "-" + j, player, nameOnJersey: last, jersey, size: pick(["YS", "YM", "YL", "AS", "AM", "AL"]), item: it.item, tier: it.tier, email, phone, address, order, date });
    }
    bank[tid].push({ id: prefix + "-bz" + i, committed: false, captures: caps });
  }
  return bank;
}
