// ─────────── Shared roster-org state (Rosters tab ⟷ Settings manager mapping) ───────────
function makeRosterOrg(store, startEmpty) {
  const singleMode = (store && store.storeType) === "single";
  const singleName = (store && (store.teamName || store.storeTitle)) || "Team Roster";
  const profile = store && store.rosterProfile;
  if (!singleMode && !startEmpty && profile === "teams-only") {
    // Team mapping complete, zero rosters — the bank back-fills every team.
    const groups = TEAMS_ONLY_GROUP_SEED.map((g) => ({ ...g, rosters: g.rosters.map((r) => ({ ...r })) }));
    const modes = {}; groups.forEach((g) => { modes[g.id] = "league"; });
    return { groups, loose: [], managers: {}, modes, bank: JSON.parse(JSON.stringify(WASATCH_BANK_SEED)) };
  }
  if (!singleMode && !startEmpty && profile === "unstructured-pelicans") {
    // Pelicans Baseball — flat team list mapped from the club's team sheet, no rosters.
    return { groups: [], loose: PELICANS_TEAM_SEED.map((r) => ({ ...r })), managers: {}, modes: {}, bank: JSON.parse(JSON.stringify(PELICANS_BANK_SEED)) };
  }
  if (!singleMode && !startEmpty && profile === "unstructured") {
    // Flat team list, no divisions, no rosters — captures wait store-wide under "__store".
    return { groups: [], loose: KNIGHTS_TEAM_SEED.map((r) => ({ ...r })), managers: {}, modes: {}, bank: JSON.parse(JSON.stringify(BAYSHORE_BANK_SEED)) };
  }
  const groups = singleMode || startEmpty ? [] : ROSTER_GROUP_SEED.map((g) => ({ ...g, rosters: g.rosters.map((r) => ({ ...r })) }));
  const loose = singleMode ? [{ id: "single-roster", name: singleName, players: startEmpty ? 0 : 18 }]
    : startEmpty ? [] : STANDALONE_ROSTER_SEED.map((r) => ({ ...r }));
  const managers = {}, modes = {};
  if (!singleMode && !startEmpty) {
    groups.forEach((g) => {
      managers[g.id] = { ...(MANAGER_SEED[g.id] || { name: "", email: "", phone: "" }) };
      g.rosters.forEach((r) => { if (TEAM_MANAGER_SEED[r.id]) managers[r.id] = { ...TEAM_MANAGER_SEED[r.id] }; });
      // Per-group fulfillment mode: individual teams when any roster is seeded,
      // group manager when one is assigned, otherwise league manager.
      // Two modes only (flattened structure): league-level or individual teams.
      modes[g.id] = g.rosters.some((r) => TEAM_MANAGER_SEED[r.id]) ? "teams" : "league";
    });
  }
  return { groups, loose, managers, modes, bank: makeBankSeed(singleMode, startEmpty) };
}
function leagueManagerName(store) { return (store && (store.shipName || store.teamName)) || "League Manager"; }
// A manager entry is submit-ready only when it has a full name, valid email,
// 10-digit phone, and a street address (required for order fulfillment).
function managerComplete(m) {
  if (!m) return false;
  const hasName = (m.firstName && m.lastName) || m.name;
  return !!(hasName && isValidEmail(m.email) && isValidPhone(m.phone) && String(m.address || "").trim());
}
// Effective manager for a roster: team manager (in teams mode) → group manager
// (in group mode) → league manager (league mode / standalone fallback).
// In teams mode a roster with no manager is UNASSIGNED — it no longer falls
// back to the league manager; pending-order submission is gated on it.
function effectiveManagerFor(org, store, groupId, rosterId) {
  const managers = (org && org.managers) || {}, modes = (org && org.modes) || {};
  const league = { name: leagueManagerName(store), email: (store && store.email) || "", phone: (store && store.phone) || "", src: "league" };
  if (groupId) {
    const mode = modes[groupId] || "league";
    if (mode === "teams") {
      const t = managers[rosterId];
      if (t && t.name) return { ...t, src: "team" };
      return { name: "", email: "", phone: "", src: "unassigned" };
    }
    return league;
  } else if (rosterId) {
    const t = managers[rosterId];
    if (t && t.name) return { ...t, src: "team" };
  }
  return league;
}
// Freight gate: given a roster-org and a pending shipping container key
// (uppercased group id / standalone roster id), report what blocks submission.
// Returns null when fulfillment routing is fully resolved.
function freightGateFor(org, store, shippingGroup) {
  if (!org || (store && store.storeType) === "single") return null;
  const key = String(shippingGroup || "").toLowerCase();
  const g = (org.groups || []).find((x) => x.id.toLowerCase() === key);
  if (!g) return null; // standalone rosters route to the league manager
  const mode = (org.modes || {})[g.id] || "league";
  const managers = org.managers || {};
  if (mode === "teams") {
    const missing = g.rosters.filter((r) => !managerComplete(managers[r.id]));
    if (missing.length) return { kind: "teams", group: g, missing };
  }
  return null;
}
const MGR_SRC_META = {
  team: { label: "Team manager", color: "#0e0e10", bg: "#eef1f6" },
  teams: { label: "Individual teams", color: "#0e0e10", bg: "#eef1f6" },
  group: { label: "Group manager", color: "#1f7a44", bg: "#e7f5ed" },
  league: { label: "League manager", color: "#6b6b72", bg: "#f1f1f3" },
  unassigned: { label: "Unassigned", color: "#b81d14", bg: "#fdecea" },
};
function MgrSrcBadge({ src }) {
  const s = MGR_SRC_META[src] || MGR_SRC_META.league;
  return <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".04em", textTransform: "uppercase", color: s.color, background: s.bg, borderRadius: 4, padding: "4px 8px", whiteSpace: "nowrap" }}>{s.label}</span>;
}
// ─────────── Shared manager entry fields (First/Last/Email/Phone/Address) ───────────
function managerFieldErrors(m) {
  const v = m || {}; const e = {};
  if (!String(v.firstName || "").trim()) e.firstName = "Required";
  if (!String(v.lastName || "").trim()) e.lastName = "Required";
  if (!isValidEmail(v.email)) e.email = "Enter a valid email";
  if (!isValidPhone(v.phone)) e.phone = "Enter a 10-digit phone number";
  if (!String(v.address || "").trim()) e.address = "Address is required for order fulfillment";
  return e;
}
function ManagerFieldsGrid({ value, onChange, errors = {} }) {
  const v = value || {};
  const set = (k, val) => {
    const next = { ...v, [k]: k === "phone" ? formatPhone(val) : val };
    if (k === "firstName" || k === "lastName") next.name = [next.firstName, next.lastName].filter(Boolean).join(" ").trim();
    onChange(next);
  };
  const input = (k, label, placeholder, opts = {}) => (
    <div style={{ gridColumn: opts.span ? "1 / -1" : "auto" }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: errors[k] ? "#b81d14" : "#6b6b72", marginBottom: 6, letterSpacing: ".02em" }}>{label}</div>
      <input value={v[k] || ""} placeholder={placeholder}
        inputMode={opts.tel ? "tel" : undefined} maxLength={opts.tel ? 14 : undefined}
        onChange={(e) => set(k, e.target.value)}
        style={{ width: "100%", border: `1px solid ${errors[k] ? "#e1251b" : "#d4d4d8"}`, borderRadius: 6, padding: "12px 12px", fontSize: 13.5, color: "#0e0e10", outline: "none", boxSizing: "border-box", fontFamily: opts.tel ? "JetBrains Mono, monospace" : "inherit", background: "#fff" }} />
      {errors[k] && <div style={{ fontSize: 11.5, color: "#b81d14", marginTop: 4 }}>{errors[k]}</div>}
    </div>
  );
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
      {input("firstName", "First Name", "First name")}
      {input("lastName", "Last Name", "Last name")}
      {input("email", "Email", "coach@example.com")}
      {input("phone", "Phone", "(000) 000-0000", { tel: true })}
      {input("address", "Address", "Street, City, State ZIP", { span: true })}
    </div>
  );
}
// Blocking modal shown when pending orders are submitted for a group whose
// freight routing is unresolved. Collects the group manager, or a team manager
// for every unassigned roster; addresses are verified with the map service.
function AssignManagersModal({ gate, org, store, onClose, onComplete }) {
  const [drafts, setDrafts] = React.useState({});
  const [errors, setErrors] = React.useState({});
  const [validating, setValidating] = React.useState(false);
  React.useEffect(() => {
    if (!gate) return;
    const managers = (org && org.managers) || {}; const d = {};
    if (gate.kind === "group") d[gate.group.id] = { ...(managers[gate.group.id] || {}) };
    else gate.missing.forEach((r) => { d[r.id] = { ...(managers[r.id] || {}) }; });
    setDrafts(d); setErrors({});
  }, [gate]);
  if (!gate) return null;
  const targets = gate.kind === "group"
    ? [{ id: gate.group.id, label: "Group Manager", sub: `Receives every ${gate.group.name} order` }]
    : gate.missing.map((r) => ({ id: r.id, label: r.name, sub: "Team manager" }));
  const submit = async () => {
    const errs = {};
    targets.forEach((t) => { const e = managerFieldErrors(drafts[t.id]); if (Object.keys(e).length) errs[t.id] = e; });
    setErrors(errs);
    if (Object.keys(errs).length) return;
    setValidating(true);
    const next = { ...drafts };
    for (const t of targets) {
      const res = await validateAddressService(next[t.id].address);
      if (!res.ok) {
        setValidating(false);
        setErrors({ [t.id]: { address: "We couldn’t verify this address — check it and try again." } });
        return;
      }
      next[t.id] = { ...next[t.id], address: res.normalized };
    }
    setValidating(false);
    onComplete(next);
  };
  return (
    <Modal open onClose={validating ? undefined : onClose} width={640}>
      <div style={{ padding: "28px 28px 16px" }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>
          {gate.kind === "group" ? "Assign a group manager" : "Assign team managers"}
        </h2>
        <p style={{ margin: "8px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>
          {gate.kind === "group"
            ? <React.Fragment><strong style={{ color: "#0e0e10" }}>{gate.group.name}</strong> ships to a group manager, but none is assigned. Add one so we know where to send these orders.</React.Fragment>
            : <React.Fragment><strong style={{ color: "#0e0e10" }}>{gate.group.name}</strong> ships to individual team managers. {gate.missing.length === 1 ? "1 roster is" : `${gate.missing.length} rosters are`} missing a manager — add them so we know where to send these orders.</React.Fragment>}
        </p>
      </div>
      <div style={{ padding: "0 28px", maxHeight: "56vh", overflowY: "auto", display: "flex", flexDirection: "column", gap: 20 }}>
        {targets.map((t) => (
          <div key={t.id} style={{ border: "1px solid #ececf0", borderRadius: 10, padding: 16, background: "#fafafb" }}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 12 }}>
              <span style={{ fontSize: 13, fontWeight: 800, color: "#0e0e10" }}>{t.label}</span>
              <span style={{ fontSize: 11.5, color: "#9a9aa1" }}>{t.sub}</span>
            </div>
            <ManagerFieldsGrid value={drafts[t.id]} errors={errors[t.id] || {}} onChange={(v) => setDrafts((d) => ({ ...d, [t.id]: v }))} />
          </div>
        ))}
      </div>
      <div style={{ padding: "20px 28px 24px", display: "flex", justifyContent: "flex-end", gap: 12 }}>
        <Button variant="secondary" onClick={onClose} disabled={validating}>Cancel</Button>
        <Button variant="primary" onClick={submit} disabled={validating}>
          {validating ? "Verifying addresses…" : "Save & Continue"}
        </Button>
      </div>
    </Modal>
  );
}
// Read-only manager strip for Rosters-tab detail views. Editing lives in the
// Settings tab ("Team Manager & Freight Mapping") — the link jumps there.
// Moving delivery van — order-fulfillment glyph (motion lines on the left).
function IconVan({ size = 20, style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" style={style}>
      <path d="M6 7h9v9.5H9.5" />
      <path d="M15 10h3.2l2.3 3v3.5h-1.6" />
      <circle cx="11.2" cy="16.9" r="1.7" />
      <circle cx="17.2" cy="16.9" r="1.7" />
      <path d="M1.5 9.5h3.2M2.7 12.5h2.6M1.5 15.5h3.2" />
    </svg>);
}
function RosterManagerStrip({ main, accent, accentColor, note, onManage, manageLabel }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 16, background: "#fff", border: "1px solid #ececf0", borderRadius: 10, padding: "16px 16px", marginBottom: 16, boxShadow: "0 1px 2px rgba(20,20,30,.03)" }}>
      <span style={{ width: 40, height: 40, borderRadius: 9, flexShrink: 0, background: "#f1f1f3", color: "#0e0e10", display: "inline-flex", alignItems: "center", justifyContent: "center" }}><IconVan size={20} /></span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".06em", color: "#71717a", textTransform: "uppercase" }}>Order Fulfillment</div>
        <div style={{ marginTop: 3, fontSize: 14, fontWeight: 700, color: "#09090b", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
          {main || "Orders shipping to team managers"}
          {accent && <span style={{ marginLeft: 8, color: accentColor || "#c2410c" }}>{accent}</span>}
        </div>
        {note && <div style={{ marginTop: 3, fontSize: 12, color: "#9a9aa1" }}>{note}</div>}
      </div>
      {onManage &&
        <button type="button" onClick={onManage} style={{ flexShrink: 0, display: "inline-flex", alignItems: "center", gap: 8, background: "#fff", border: "1px solid #d4d4d8", color: "#0e0e10", borderRadius: 6, padding: "8px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
          <IconEdit size={13} style={{ strokeWidth: 2 }} /> {manageLabel || "Manage in Settings"}
        </button>}
    </div>);
}

// Inline team-manager editing on the roster view — expands an editor under the
// strip instead of jumping to Settings; saves with a confirmation toast.
function RosterManagerStripEditable({ org, setOrg, rosterId, eff, onToast }) {
  const [open, setOpen] = React.useState(false);
  const [draft, setDraft] = React.useState({});
  const [errors, setErrors] = React.useState({});
  const start = () => { setDraft({ ...(((org && org.managers) || {})[rosterId] || {}) }); setErrors({}); setOpen(true); };
  const save = () => {
    const e = managerFieldErrors(draft);
    setErrors(e);
    if (Object.keys(e).length) return;
    setOrg((o) => ({ ...o, managers: { ...(o.managers || {}), [rosterId]: { ...draft } } }));
    setOpen(false);
    onToast && onToast(`Team manager ${draft.name ? draft.name + " " : ""}saved — freight for this roster routes to them`);
  };
  return (
    <div>
      <RosterManagerStrip main="Orders shipping to team manager"
        accent={eff.src !== "team" ? "Not assigned" : eff.name}
        accentColor={eff.src !== "team" ? "#c2410c" : "#1f7a44"}
        note={eff.src !== "team" ? "A team manager is required before pending orders for this roster can be submitted." : null}
        onManage={open ? null : start}
        manageLabel={eff.src !== "team" ? "Assign Manager" : "Edit Manager"} />
      {open &&
        <div style={{ background: "#fff", border: "1px solid #ececf0", borderRadius: 10, padding: 16, margin: "-8px 0 16px", boxShadow: "0 1px 2px rgba(20,20,30,.03)" }}>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".06em", color: "#9a9aa1", textTransform: "uppercase", marginBottom: 12 }}>Team Manager <span style={{ fontWeight: 600, textTransform: "none", letterSpacing: 0, color: "#b0b0b6" }}>· receives this roster's bulk freight</span></div>
          <ManagerFieldsGrid value={draft} errors={errors} onChange={setDraft} />
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 16 }}>
            <Button variant="secondary" onClick={() => setOpen(false)}>Cancel</Button>
            <Button variant="primary" onClick={save}>Save Manager</Button>
          </div>
        </div>}
    </div>);
}

// ─────────── Roster tab controller ───────────
function RosterTab({ startEmpty, store, org, setOrg, managerGated, onManageManagers }) {
  // Single-Team Locker enforces one roster: no groups, no grouping UI.
  const singleMode = (store && store.storeType) === "single";
  // 5 — team-code links need the store slug from row menus deep in the tree.
  if (typeof window !== "undefined") window.__tcStore = store;
  // Roster structure lives in the shared org (lifted to Dashboard) so the
  // Settings tab's manager mapping mirrors it live.
  const groups = org.groups, loose = org.loose;
  const setGroups = (fn) => setOrg((o) => ({ ...o, groups: typeof fn === "function" ? fn(o.groups) : fn }));
  const setLoose = (fn) => setOrg((o) => ({ ...o, loose: typeof fn === "function" ? fn(o.loose) : fn }));
  const [nav, setNav] = React.useState({ view: "home" });
  const [toast, setToast] = React.useState("");
  // Bank-zone plumbing: committed captures flow into the player table (per
  // team), and the table reports claimed numbers back for conflict flagging.
  const [injected, setInjected] = React.useState({});
  const [rosterNums, setRosterNums] = React.useState([]);
  const handleNumbers = React.useCallback((nums) => setRosterNums(nums), []);
  function commitFromBank(teamId, player) {
    setInjected((cur) => ({ ...cur, [teamId]: [...(cur[teamId] || []), player] }));
    setOrg((o) => ({ ...o,
      groups: o.groups.map((g) => ({ ...g, rosters: g.rosters.map((r) => r.id === teamId ? { ...r, players: (r.players || 0) + 1 } : r) })),
      loose: o.loose.map((r) => r.id === teamId ? { ...r, players: (r.players || 0) + 1 } : r) }));
    setToast(`${player.first} ${player.last} committed to the roster`);
  }

  // 8 — a move lands the intact player record on the destination roster and
  // adjusts both player counts. Numbers were already re-validated in the modal.
  function movePlayersTo(fromId, dest, assignments) {
    const arrivals = assignments.map((a, i) => ({ ...a.player, id: "mv-" + Date.now() + "-" + i, number: a.number }));
    setInjected((cur) => ({ ...cur, [dest.id]: [...(cur[dest.id] || []), ...arrivals] }));
    const n = arrivals.length;
    setOrg((o) => ({ ...o,
      groups: o.groups.map((g) => ({ ...g, rosters: g.rosters.map((r) => r.id === dest.id ? { ...r, players: (r.players || 0) + n } : r.id === fromId ? { ...r, players: Math.max(0, (r.players || 0) - n) } : r) })),
      loose: o.loose.map((r) => r.id === dest.id ? { ...r, players: (r.players || 0) + n } : r.id === fromId ? { ...r, players: Math.max(0, (r.players || 0) - n) } : r) }));
  }
  // Destination candidates stay inside the player's own roster group.
  function moveTargetsFor(rosterId) {
    const all = orgRosterList(org);
    const me = all.find((r) => r.id === rosterId);
    return all.filter((r) => (me ? r.groupId === me.groupId : r.groupId === null));
  }

  // Modal state
  const [groupModal, setGroupModal] = React.useState(null); // {mode:'create'|'edit', group?}
  const [confirm, setConfirm] = React.useState(null); // {kind, id, groupId, name, rosterCount}
  const [looseModal, setLooseModal] = React.useState(null); // {mode:'create'|'edit', roster?}
  const [addRosterFor, setAddRosterFor] = React.useState(null); // group object

  const totalGroups = groups.length;
  const totalRosters = groups.reduce((n, g) => n + g.rosters.length, 0) + loose.length;
  const totalPlayers = groups.reduce((n, g) => n + groupPlayerCount(g), 0) + loose.reduce((n, r) => n + (r.players || 0), 0);

  function saveGroup({ mode, id, name, color, manager }) {
    if (mode === "edit") {
      setOrg((o) => {
        const gs = o.groups.map((g) => g.id === id ? { ...g, name, color: color || g.color } : g);
        let managers = o.managers, modes = o.modes;
        if (manager) {
          modes = { ...o.modes, [id]: manager.mode };
          managers = { ...o.managers };
          if (manager.mode === "group" && manager.entry) managers[id] = { ...(managers[id] || {}), ...manager.entry };
          else if (manager.mode === "league") managers[id] = { name: "", email: "", phone: "" };
        }
        return { ...o, groups: gs, managers, modes };
      });
      setToast("Roster group updated");
    } else {
      const g = { id: "grp-" + Date.now(), name, sport: "Boys Basketball", color, rosters: [] };
      setGroups((cur) => [...cur, g]);
      setToast(`Roster group "${name}" created`);
    }
    setGroupModal(null);
  }
  function saveLoose({ mode, id, name, groupId }) {
    if (mode === "edit") {
      setLoose((cur) => cur.map((r) => r.id === id ? { ...r, name } : r));
      setToast("Roster renamed");
    } else if (groupId) {
      const roster = { id: "ros-" + Date.now(), name, players: 0 };
      const grp = groups.find((g) => g.id === groupId);
      setGroups((cur) => cur.map((g) => g.id === groupId ? { ...g, rosters: [...g.rosters, roster] } : g));
      setToast(`Roster "${name}" added to ${grp ? grp.name : "group"}`);
    } else {
      setLoose((cur) => [...cur, { id: "ros-" + Date.now(), name, players: 0 }]);
      setToast(`Roster "${name}" created`);
    }
    setLooseModal(null);
  }
  function addRoster(groupId, { name, division }) {
    const roster = { id: "ros-" + Date.now(), name, division, players: 0 };
    setGroups((cur) => cur.map((g) => g.id === groupId ? { ...g, rosters: [...g.rosters, roster] } : g));
    setAddRosterFor(null);
    setToast(`Roster "${name}" added`);
  }
  function deleteLoose(id) {
    setLoose((cur) => cur.filter((r) => r.id !== id));
    setToast("Roster removed");
  }
  // Deleting a group keeps its rosters — they become standalone rosters,
  // dropping the group's branding/division tag.
  function deleteGroup(groupId) {
    const g = groups.find((x) => x.id === groupId);
    if (!g) return;
    const freed = g.rosters.map((r) => ({ id: r.id, name: r.name, players: r.players || 0 }));
    setLoose((cur) => [...cur, ...freed]);
    setGroups((cur) => cur.filter((x) => x.id !== groupId));
    if (nav.view === "group" && nav.groupId === groupId) setNav({ view: "home" });
    setToast(freed.length
      ? `Group deleted — ${freed.length} ${freed.length === 1 ? "roster" : "rosters"} kept as standalone`
      : "Roster group deleted");
  }
  function deleteGroupRoster(groupId, rosterId) {
    setGroups((cur) => cur.map((g) => g.id === groupId ? { ...g, rosters: g.rosters.filter((r) => r.id !== rosterId) } : g));
    setToast("Roster removed");
  }

  function openGroup(g) { setNav({ view: "group", groupId: g.id }); }
  function openRoster(group, roster) {
    setNav({
      view: "roster", groupId: group ? group.id : null, rosterId: roster.id,
      title: roster.name,
      subtitle: group ? `${group.sport} · Uses ${group.name} branding` : `Team Code ${rTeamCode(roster.id)}`,
      color: group ? group.color : "#3f3f46",
      avatar: roster.division || rInitials(roster.name),
      fresh: (roster.players || 0) === 0,
      groupName: group ? group.name : null });
  }

  let body;
  if (singleMode) {
    // Single-Team Locker: no groups, no naming, no breadcrumbs/banner —
    // clicking the Roster tab drops straight into the one roster's player table.
    const single = loose[0];
    const sid = single ? single.id : "single-roster";
    body = (
      <React.Fragment>
        <RosterPlayerTable store={store} startEmpty={(single?.players || 0) === 0}
          rosterName={single ? single.name : "your team"} rosterId={sid}
          moveTargets={moveTargetsFor(sid)}
          onMovePlayers={(dest, assignments) => movePlayersTo(sid, dest, assignments)}
          injected={injected[sid]} onNumbers={handleNumbers} />
        <div style={{ marginTop: 20 }}>
          <BankZone teamId={sid} teamName={single ? single.name : "your team"} org={org} setOrg={setOrg} rosterNumbers={rosterNums} onCommit={(p) => commitFromBank(sid, p)} />
        </div>
      </React.Fragment>);
  } else if (nav.view === "roster") {
    const crumbs = nav.groupId ?
      [{ label: "My Teams", onClick: () => setNav({ view: "home" }) },
       { label: nav.groupName, onClick: () => setNav({ view: "home" }) },
       { label: nav.title }] :
      [{ label: "My Teams", onClick: () => setNav({ view: "home" }) }, { label: nav.title }];
    // Per-roster fulfillment only applies when the group is set to individual
    // team managers in Settings; in group/league-manager modes freight is handled
    // at the group level, so no strip or manager label shows here.
    const teamsMode = managerGated && nav.groupId && (((org && org.modes) || {})[nav.groupId] || "league") === "teams";
    const eff = teamsMode ? effectiveManagerFor(org, store, nav.groupId, nav.rosterId) : null;
    const subtitle = eff && nav.groupId
      ? (eff.src !== "team"
        ? <a href="#" onClick={(e) => { e.preventDefault(); onManageManagers && onManageManagers(nav.groupId, nav.rosterId); }}
            style={{ color: "#2563eb", fontWeight: 700, textDecoration: "none" }}>Add team manager</a>
        : <React.Fragment>Team Manager <span style={{ color: "#0e0e10", fontWeight: 600 }}>{eff.name}</span></React.Fragment>)
      : nav.subtitle;
    const header = (
      <div>
        <RosterCrumbs items={crumbs} />
        {eff &&
          <RosterManagerStripEditable org={org} setOrg={setOrg} rosterId={nav.rosterId} eff={eff} onToast={setToast} />}
        <RosterBanner color={nav.color} avatar={nav.avatar} title={nav.title} subtitle={subtitle} />
      </div>);
    body = <RosterPlayerTable store={store} startEmpty={nav.fresh} header={header} injected={injected[nav.rosterId]} onNumbers={handleNumbers}
      rosterName={nav.title} rosterId={nav.rosterId}
      moveTargets={moveTargetsFor(nav.rosterId)}
      onMovePlayers={(dest, assignments) => movePlayersTo(nav.rosterId, dest, assignments)}
      onDeleteRoster={() => {
        if (nav.groupId) deleteGroupRoster(nav.groupId, nav.rosterId); else deleteLoose(nav.rosterId);
        setNav({ view: "home" });
        setToast("Roster \"" + nav.title + "\" deleted");
      }} />;
    body = (
      <React.Fragment>
        {body}
        <div style={{ marginTop: 20 }}>
          <BankZone teamId={nav.rosterId} teamName={nav.title} org={org} setOrg={setOrg} rosterNumbers={rosterNums} onCommit={(p) => commitFromBank(nav.rosterId, p)} />
        </div>
      </React.Fragment>);
  } else {
    // Flattened structure: the division → team canvas replaces the old
    // roster-group card grid entirely (My Teams).
    body = (
      <TeamCanvasView
        groups={groups} loose={loose} org={org} setOrg={setOrg} store={store}
        managerGated={managerGated} onManageManagers={onManageManagers}
        stats={{ totalGroups, totalRosters, totalPlayers }}
        onOpenRoster={openRoster}
        onCommitToTeam={commitFromBank}
        setToast={setToast} />);
  }

  return (
    <React.Fragment>
      {body}
      <RosterGroupModal
        open={!!groupModal}
        mode={groupModal?.mode}
        initial={groupModal?.group}
        org={org} store={store} managerGated={managerGated}
        onClose={() => setGroupModal(null)}
        onSave={saveGroup}
        onDelete={() => {
          const g = groupModal?.group; setGroupModal(null);
          if (g) setConfirm({ kind: "group", id: g.id, name: g.name, rosterCount: g.rosters.length });
        }} />
      <NewRosterModal
        open={!!looseModal}
        mode={looseModal?.mode}
        initial={looseModal?.roster}
        groups={groups}
        store={store}
        org={org}
        onClose={() => setLooseModal(null)}
        onSave={saveLoose} />
      <AddRosterModal
        open={!!addRosterFor}
        group={addRosterFor}
        store={store}
        org={org}
        onClose={() => setAddRosterFor(null)}
        onAdd={(payload) => addRoster(addRosterFor.id, payload)} />
      <RosterConfirmDeleteModal
        confirm={confirm}
        onClose={() => setConfirm(null)}
        onConfirm={() => {
          if (!confirm) return;
          if (confirm.kind === "group") deleteGroup(confirm.id);
          else if (confirm.kind === "groupRoster") deleteGroupRoster(confirm.groupId, confirm.id);
          setConfirm(null);
        }} />
      <Toast message={toast} onDone={() => setToast("")} />
    </React.Fragment>);
}

// ─────────── Bank zone placeholder (Phase 2 builds the real queue) ───────────
