function RosterRulesDefaultCard({ store, org, onUpdateStore, onToast }) {
  const [tick, setTick] = React.useState(0);
  const [prompt, setPrompt] = React.useState(null);
  const [showList, setShowList] = React.useState(false);
  const def = !!store.allowDuplicateNumbers;
  const div = rosterDupeDivergence(store, org);
  const apply = (v, mode) => {
    try { window.localStorage.setItem("ts_allow_dupes", v ? "1" : "0"); } catch (e) {}
    if (mode === "all") div.list.forEach((r) => setRosterDupe(r.id, null));
    onUpdateStore && onUpdateStore({ allowDuplicateNumbers: v });
    setTick((n) => n + 1);
    setPrompt(null);
    onToast && onToast(mode === "all"
      ? (v ? "Duplicates allowed on all " : "Duplicates blocked on all ") + div.total + " teams \u2014 overrides cleared"
      : "Default updated \u2014 " + div.overridden + (div.overridden === 1 ? " team keeps its override" : " teams keep their overrides"));
  };
  const change = (v) => { if (div.overridden > 0) setPrompt({ value: v }); else apply(v, "all"); };
  return (
    <div style={{ marginTop: 0, background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, padding: "18px 20px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
        <span style={{ fontSize: 13, fontWeight: 800, letterSpacing: ".04em", color: "#0e0e10" }}>Roster Rules</span>
        <span style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: ".05em", color: "#6b6b72", background: "#f4f4f5", borderRadius: 999, padding: "3px 8px" }}>STORE DEFAULT · SET PER TEAM</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
        <span style={{
          width: 40, height: 40, borderRadius: 9, flexShrink: 0,
          background: def ? "#fdecea" : "#f1f1f3", color: def ? "#e1251b" : "#6b6b72",
          display: "inline-flex", alignItems: "center", justifyContent: "center",
        }}><IconUsers size={20} /></span>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 14, fontWeight: 500, color: "#0e0e10", marginBottom: 2 }}>Allow Duplicate Numbers</div>
          <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.45 }}>
            The value in force lives on each team. Setting this pushes the default out; a team can still diverge in My Team{store.storeType === "league" ? "s" : ""}.
          </div>
        </div>
        <span style={{ display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: def ? "#1f9d55" : "#6b6b72" }}>{def ? "Allowed" : "Blocked"}</span>
          <SettingsToggle value={def} onChange={change} />
        </span>
      </div>
      {/* What's actually in force — a control that hides divergence is lying. */}
      <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid #f1f1f3", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        {div.overridden === 0
          ? <span style={{ fontSize: 12.5, color: "#6b6b72" }}>All {div.total} teams follow this default.</span>
          : <React.Fragment>
              <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".04em", color: "#8a5f10", background: "#fdf6e7", border: "1px solid #efdcae", borderRadius: 999, padding: "4px 10px" }}>{div.overridden} OF {div.total} TEAMS OVERRIDDEN</span>
              <button type="button" onClick={() => setShowList(!showList)} style={{ background: "none", border: 0, fontSize: 12, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit", textDecoration: "underline", textUnderlineOffset: 2 }}>{showList ? "Hide" : "Which teams?"}</button>
              <button type="button" onClick={() => apply(def, "all")} style={{ background: "none", border: 0, fontSize: 12, fontWeight: 700, color: "#6b6b72", cursor: "pointer", fontFamily: "inherit" }}>Reset all to default</button>
            </React.Fragment>}
      </div>
      {showList && div.overridden > 0 &&
        <div style={{ marginTop: 10, display: "flex", flexWrap: "wrap", gap: 6 }}>
          {div.names.map((n) => <span key={n} style={{ fontSize: 11.5, fontWeight: 600, color: "#3f3f46", background: "#f7f7f8", border: "1px solid #ececf0", borderRadius: 999, padding: "4px 10px" }}>{n} · {def ? "unique numbers" : "duplicates allowed"}</span>)}
        </div>}
      <Modal open={!!prompt} onClose={() => setPrompt(null)} width={480}>
        <div style={{ padding: "28px 28px 8px" }}>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{div.overridden} {div.overridden === 1 ? "team has" : "teams have"} their own setting</h2>
          <p style={{ margin: "12px 0 0", fontSize: 13.5, color: "#6b6b72", lineHeight: 1.6 }}>
            Push <strong style={{ color: "#0e0e10" }}>{prompt && prompt.value ? "duplicates allowed" : "unique numbers"}</strong> to every team, or only to the {div.total - div.overridden} still following the default?
          </p>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 10, padding: "20px 28px 24px" }}>
          <Button variant="secondary" onClick={() => apply(prompt.value, "keep")}>Only the {div.total - div.overridden} following the default</Button>
          <Button variant="primary" onClick={() => apply(prompt.value, "all")}>Apply to all {div.total} teams — clear overrides</Button>
        </div>
      </Modal>
    </div>
  );
}

// ── 7a — allow-duplicates is a TEAM (roster) setting. Settings holds the bulk
// default; each roster can diverge, and the map below is the authority. ──
function rosterDupeMap() { window.__rosterDupes = window.__rosterDupes || {}; return window.__rosterDupes; }
function rosterDupeAllowed(store, rosterId) {
  const m = rosterDupeMap();
  if (rosterId != null && Object.prototype.hasOwnProperty.call(m, rosterId)) return !!m[rosterId];
  return !!(store && store.allowDuplicateNumbers);
}
function rosterDupeOverridden(rosterId) { return rosterId != null && Object.prototype.hasOwnProperty.call(rosterDupeMap(), rosterId); }
function setRosterDupe(rosterId, v) {
  const m = rosterDupeMap();
  if (v === null) delete m[rosterId]; else m[rosterId] = !!v;
  // The buyer-facing number entry reads the same rule (see the storefront file).
  try { if (v !== null) window.localStorage.setItem("ts_allow_dupes", v ? "1" : "0"); } catch (e) {}
}
function orgRosterList(org) {
  const out = [];
  ((org && org.groups) || []).forEach((g) => (g.rosters || []).forEach((r) => out.push({ id: r.id, name: r.name, division: r.division || null, groupId: g.id, groupName: g.name, color: g.color, players: r.players || 0 })));
  ((org && org.loose) || []).forEach((r) => out.push({ id: r.id, name: r.name, groupId: null, groupName: null, color: "#3f3f46", players: r.players || 0 }));
  return out;
}
function rosterDupeDivergence(store, org) {
  const list = orgRosterList(org);
  const def = !!(store && store.allowDuplicateNumbers);
  const overridden = list.filter((r) => rosterDupeOverridden(r.id) && rosterDupeAllowed(store, r.id) !== def);
  return { total: list.length, overridden: overridden.length, list, names: overridden.map((r) => r.name) };
}

// ── 7b/7c/7d — one number-entry component, two input models. A taken number is a
// CONFLICT when duplicates are off (locked, unselectable, red) and merely IN USE
// when they're on (neutral, informational, still selectable). ──
function jerseyHolders(n, existing, selfId) {
  const s = String(n);
  return (existing || []).filter((p) => p.id !== selfId && String(p.number || "").trim() === s);
}
function jerseyHolderNames(hs) { return hs.map((p) => (p.first || "") + " " + (p.last || "")).join(", ").trim(); }
function JerseyGrid({ value, onChange, existing, selfId, allowDupes, cell = 30 }) {
  const takenCount = {};
  (existing || []).forEach((p) => { if (p.id === selfId) return; const n = String(p.number || "").trim(); if (n) takenCount[n] = (takenCount[n] || 0) + 1; });
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(10, " + cell + "px)", gap: 4 }}>
        {Array.from({ length: 100 }, (_, n) => {
          const s = String(n);
          const used = takenCount[s] || 0;
          const sel = String(value || "") === s;
          const locked = used > 0 && !allowDupes;
          const dupe = used > 0 && allowDupes;
          const hs = used ? jerseyHolders(s, existing, selfId) : [];
          const title = used ? (allowDupes ? s + " · duplicate — also worn by " + jerseyHolderNames(hs) : s + " taken by " + jerseyHolderNames(hs)) : "Assign " + s;
          return (
            <button key={n} type="button" title={title} disabled={locked}
              onClick={() => { if (!locked) onChange(sel ? "" : s); }}
              style={{
                height: cell, width: cell, padding: 0, borderRadius: 5, fontFamily: "inherit",
                fontSize: 11.5, fontWeight: sel ? 800 : 600, position: "relative",
                background: sel ? "#0e0e10" : locked ? "#f4f4f5" : "#fff",
                color: sel ? "#fff" : locked ? "#c4c4cb" : dupe ? "#52525b" : "#3f3f46",
                border: sel ? "1px solid #0e0e10" : dupe ? "1px dashed #b6b6bd" : "1px solid #e4e4e7",
                textDecoration: locked ? "line-through" : "none",
                cursor: locked ? "not-allowed" : "pointer",
              }}>
              {s}
              {dupe && !sel && <span aria-hidden="true" style={{ position: "absolute", top: 2, right: 3, width: 4, height: 4, borderRadius: 999, background: "#a1a1aa" }} />}
            </button>
          );
        })}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 14, marginTop: 10, fontSize: 10.5, color: "#6b6b72" }}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: "#fff", border: "1px solid #e4e4e7" }} />Available</span>
        {allowDupes
          ? <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: "#fff", border: "1px dashed #b6b6bd" }} />In use · duplicate allowed</span>
          : <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: "#f4f4f5", border: "1px solid #e4e4e7" }} />Taken · locked</span>}
        <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}><span style={{ width: 11, height: 11, borderRadius: 3, background: "#0e0e10" }} />Selected</span>
      </div>
    </div>
  );
}
function JerseyNumberField({ value, onChange, existing, selfId, allowDupes, mode, onModeChange, autoFocus }) {
  const [localMode, setLocalMode] = React.useState("grid");
  const m = mode || localMode;
  const setMode = onModeChange || setLocalMode;
  const clean = String(value || "").trim();
  const hs = clean ? jerseyHolders(clean, existing, selfId) : [];
  const conflict = hs.length > 0 && !allowDupes;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <div style={{ display: "inline-flex", background: "#f1f1f3", borderRadius: 7, padding: 3 }}>
          {[{ k: "grid", l: "Number grid" }, { k: "type", l: "Type it" }].map((o) => {
            const on = m === o.k;
            return <button key={o.k} type="button" onClick={() => setMode(o.k)} style={{ padding: "5px 11px", border: 0, borderRadius: 5, cursor: "pointer", fontSize: 11.5, fontWeight: 700, fontFamily: "inherit", background: on ? "#fff" : "transparent", color: on ? "#0e0e10" : "#6b6b72", boxShadow: on ? "0 1px 2px rgba(20,20,30,.12)" : "none" }}>{o.l}</button>;
          })}
        </div>
        <span style={{ marginLeft: "auto", fontSize: 11, fontWeight: 700, color: allowDupes ? "#6b6b72" : "#0e0e10" }}>{allowDupes ? "Duplicates allowed on this team" : "Unique numbers required"}</span>
      </div>
      {m === "grid"
        ? <JerseyGrid value={value} onChange={onChange} existing={existing} selfId={selfId} allowDupes={allowDupes} />
        : <input value={clean} autoFocus={autoFocus} inputMode="numeric" maxLength={2} placeholder="#"
            onChange={(e) => onChange(e.target.value.replace(/\D/g, "").slice(0, 2))}
            style={{ width: 92, boxSizing: "border-box", height: 40, border: "1px solid " + (conflict ? "#e1251b" : "#d4d4d8"), borderRadius: 6, padding: "0 12px", fontSize: 16, fontWeight: 700, fontFamily: "JetBrains Mono, monospace", color: "#0e0e10", outline: "none" }} />}
      {clean && hs.length > 0 &&
        <div style={{ marginTop: 10, display: "flex", alignItems: "flex-start", gap: 7, fontSize: 12, fontWeight: 600, lineHeight: 1.45, color: conflict ? "#b81d14" : "#6b6b72" }}>
          {conflict ? <IconAlert size={13} style={{ strokeWidth: 2.2, flexShrink: 0, marginTop: 1 }} /> : <IconInfo size={13} style={{ strokeWidth: 2, flexShrink: 0, marginTop: 1 }} />}
          <span>{conflict
            ? clean + " is taken by " + jerseyHolderNames(hs) + " \u2014 pick a number that isn\u2019t locked."
            : clean + " \u00b7 duplicate \u2014 also worn by " + jerseyHolderNames(hs) + ". Allowed on this team."}</span>
        </div>}
    </div>
  );
}
// Inline roster row: the grid can't live in a 90px cell, so the cell opens it.
function JerseyCellPicker({ value, onChange, existing, selfId, allowDupes, invalid }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef(null);
  React.useEffect(() => {
    if (!open) return;
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const t = setTimeout(() => document.addEventListener("mousedown", h), 0);
    return () => { clearTimeout(t); document.removeEventListener("mousedown", h); };
  }, [open]);
  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button type="button" onClick={() => setOpen(!open)} style={{
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 6, width: "100%",
        height: 40, boxSizing: "border-box", padding: "0 10px", cursor: "pointer", fontFamily: "inherit",
        background: "#fff", border: "1px solid " + (invalid ? "#e1251b" : open ? "#0e0e10" : "#d4d4d8"), borderRadius: 4,
        fontSize: 14, fontWeight: value ? 700 : 400, color: value ? "#0e0e10" : "#9a9aa1",
      }}>
        {value || "#"} <IconGrid size={13} style={{ color: "#9a9aa1", flexShrink: 0 }} />
      </button>
      {open &&
        <div style={{ position: "absolute", top: 46, left: 0, zIndex: 60, width: 372, background: "#fff", border: "1px solid #e4e4e7", borderRadius: 10, boxShadow: "0 16px 40px rgba(20,20,30,.16)", padding: 14 }}>
          <JerseyNumberField value={value} onChange={onChange} existing={existing} selfId={selfId} allowDupes={allowDupes} />
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 12, paddingTop: 12, borderTop: "1px solid #f1f1f3" }}>
            <button type="button" onClick={() => { onChange(""); }} style={{ background: "none", border: 0, fontSize: 12, fontWeight: 700, color: "#6b6b72", cursor: "pointer", fontFamily: "inherit" }}>Clear</button>
            <button type="button" onClick={() => setOpen(false)} style={{ background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6, padding: "8px 14px", fontSize: 12, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Done</button>
          </div>
        </div>}
    </div>
  );
}

// ── 8 — Move to different team. The crux is the jersey number: it is released on
// the origin roster and re-validated against the destination's own rules before
// the move commits. Players with team-gear orders can't move (same reasoning as
// the publish gate — fulfillment is already in flight). ──
function rosterNumberRegistry() { window.__rosterNumbers = window.__rosterNumbers || {}; return window.__rosterNumbers; }
function rosterTakenNumbers(rosterId, playerCount) {
  const reg = rosterNumberRegistry();
  if (reg[rosterId]) return reg[rosterId];
  // Unopened rosters: deterministic stand-in so collisions are demonstrable.
  let h = 5381; const s = String(rosterId || "");
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  const out = [];
  const n = Math.max(0, Math.min(playerCount || 0, 24));
  for (let i = 0; i < n; i++) { h = (Math.imul(h, 1664525) + 1013904223) >>> 0; const v = h % 100; if (!out.includes(String(v))) out.push(String(v)); }
  return out;
}
function firstFreeNumber(taken) {
  for (let i = 0; i < 100; i++) if (!taken.includes(String(i))) return String(i);
  return "";
}
function MovePlayersModal({ open, players, current, targets, store, onClose, onConfirm }) {
  const [destId, setDestId] = React.useState("");
  const [query, setQuery] = React.useState("");
  const [choices, setChoices] = React.useState({});
  React.useEffect(() => { if (open) { setDestId(""); setQuery(""); setChoices({}); } }, [open, players]);
  if (!open) return null;
  const gear = (p) => playerTeamGear(p, store);
  const blocked = (players || []).filter((p) => gear(p).orderedCount > 0);
  const movable = (players || []).filter((p) => gear(p).orderedCount === 0);
  const q = query.trim().toLowerCase();
  const list = (targets || []).filter((t) => !q || t.name.toLowerCase().includes(q) || (t.groupName || "").toLowerCase().includes(q));
  const dest = (targets || []).find((t) => t.id === destId) || null;
  const destTaken = dest ? rosterTakenNumbers(dest.id, dest.players) : [];
  const destDupes = dest ? rosterDupeAllowed(store, dest.id) : false;
  const rows = movable.map((p) => {
    const num = String(p.number || "").trim();
    const collides = !!num && destTaken.includes(num) && !destDupes;
    const choice = choices[p.id] || (collides ? "new" : "keep");
    const suggested = firstFreeNumber(destTaken.concat(movable.map((x) => String(choices[x.id + ":n"] || "")).filter(Boolean)));
    const assigned = choice === "keep" ? num : choice === "none" ? "" : String(choices[p.id + ":n"] || suggested);
    return { p, num, collides, choice, assigned };
  });
  const commit = () => {
    if (!dest || !rows.length) return;
    onConfirm(dest, rows.map((r) => ({ player: r.p, number: r.assigned })));
  };
  const cardBtn = (on) => ({
    display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left", cursor: "pointer",
    background: on ? "#fafafb" : "#fff", border: "1px solid " + (on ? "#0e0e10" : "#ececf0"), borderRadius: 8,
    padding: "10px 12px", fontFamily: "inherit", marginBottom: 6,
  });
  return (
    <Modal open onClose={onClose} width={600}>
      <div style={{ padding: "28px 28px 0" }}>
        <h2 style={{ margin: 0, fontSize: 19, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>Move {players.length === 1 ? (players[0].first + " " + players[0].last) : players.length + " players"} to a different team</h2>
        <p style={{ margin: "10px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>
          Contact details, associated emails, name on jersey and address move with the player. The jersey number is released on {current?.name || "this roster"} and re-validated against the destination.
        </p>
      </div>
      <div style={{ padding: "20px 28px 0", maxHeight: "56vh", overflowY: "auto" }}>
        {blocked.length > 0 &&
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: "#fdf6e7", border: "1px solid #efdcae", borderRadius: 8, padding: "12px 14px", marginBottom: 16 }}>
            <IconLock size={14} style={{ flexShrink: 0, marginTop: 2, color: "#8a5f10" }} />
            <div style={{ fontSize: 12.5, color: "#6b5314", lineHeight: 1.5 }}>
              <strong style={{ color: "#8a5f10" }}>{blocked.length} {blocked.length === 1 ? "player can\u2019t move" : "players can’t move"} — team-gear orders already placed.</strong>
              <div style={{ marginTop: 3 }}>{blocked.map((p) => p.first + " " + p.last + " (" + gear(p).orderedCount + " ordered)").join(", ")}. Orders can’t be reassigned once they’re in fulfillment — same rule as an ordered product that can no longer be unpublished.</div>
            </div>
          </div>}
        {movable.length === 0
          ? <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.55, padding: "4px 0 18px" }}>
              <strong style={{ color: "#0e0e10" }}>Nothing left to move.</strong> A player follows their orders: cancel the team-gear order in the Orders tab to free them up, or wait until the batch is fulfilled and move them next season. Editing the player’s record still works from the row menu.
            </div>
          : <React.Fragment>
            <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".06em", color: "#0e0e10", marginBottom: 8 }}>DESTINATION TEAM</div>
            {(targets || []).length > 6 &&
              <div style={{ position: "relative", marginBottom: 10 }}>
                <IconSearch size={14} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "#9a9aa1" }} />
                <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search teams"
                  style={{ width: "100%", boxSizing: "border-box", fontFamily: "inherit", fontSize: 13, padding: "9px 10px 9px 32px", border: "1px solid #e4e4e7", borderRadius: 6, outline: "none" }} />
              </div>}
            {list.length === 0 && <div style={{ fontSize: 12.5, color: "#9a9aa1", padding: "10px 0" }}>No other teams in {current?.groupName ? current.groupName : "this store"} match.</div>}
            {list.map((t) => {
              const isCur = t.id === current?.id;
              const on = t.id === destId;
              return (
                <button key={t.id} type="button" disabled={isCur} onClick={() => setDestId(t.id)} style={{ ...cardBtn(on), cursor: isCur ? "default" : "pointer", opacity: isCur ? .55 : 1 }}>
                  <span style={{ width: 28, height: 28, borderRadius: 7, background: t.color, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: t.division ? 10 : 10.5, fontWeight: 800, flexShrink: 0 }}>{t.division || rInitials(t.name)}</span>
                  <span style={{ minWidth: 0, flex: 1 }}>
                    <span style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{t.name}</span>
                    <span style={{ display: "block", fontSize: 11.5, color: "#9a9aa1", marginTop: 1 }}>{t.groupName ? t.groupName + " \u00b7 " : "Standalone roster \u00b7 "}{t.players} players · {rosterDupeAllowed(store, t.id) ? "duplicates allowed" : "unique numbers"}</span>
                  </span>
                  {isCur && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: "#6b6b72", background: "#f1f1f3", borderRadius: 999, padding: "3px 8px" }}>CURRENT TEAM</span>}
                </button>
              );
            })}
            <div style={{ marginTop: 4, fontSize: 11.5, color: "#9a9aa1", lineHeight: 1.5 }}>
              {current?.groupName
                ? "Only teams inside " + current.groupName + " are listed \u2014 roster groups carry their own branding and freight routing, so cross-group moves aren\u2019t allowed."
                : "Only standalone rosters are listed \u2014 moving into a roster group would change branding and freight routing."}
            </div>

            {dest &&
              <div style={{ marginTop: 20, paddingTop: 16, borderTop: "1px solid #ececf0" }}>
                <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".06em", color: "#0e0e10", marginBottom: 8 }}>JERSEY NUMBERS AT {String(dest.name).toUpperCase()}</div>
                {rows.map((r) => (
                  <div key={r.p.id} style={{ border: "1px solid " + (r.collides ? "#f0d4d1" : "#ececf0"), borderRadius: 8, padding: "11px 13px", marginBottom: 8, background: "#fff" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <span style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10", flex: 1, minWidth: 0 }}>{r.p.first} {r.p.last}</span>
                      <span style={{ fontFamily: "JetBrains Mono, monospace", fontSize: 12, fontWeight: 700, color: "#6b6b72" }}>#{r.num || "\u2014"}</span>
                    </div>
                    <div style={{ marginTop: 4, fontSize: 12, color: r.collides ? "#b81d14" : "#1f7a44", fontWeight: 600 }}>
                      {!r.num ? "No number to carry \u2014 moves without one."
                        : r.collides ? "#" + r.num + " is already taken at " + dest.name + " \u2014 resolve before moving."
                        : "#" + r.num + " is free at " + dest.name + " \u2014 the number moves with the player."}
                    </div>
                    {r.collides &&
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 9 }}>
                        {[{ k: "new", l: "Assign #" + r.assigned }, { k: "none", l: "Move without a number" }].map((o) => {
                          const on = r.choice === o.k;
                          return <button key={o.k} type="button" onClick={() => setChoices((c) => ({ ...c, [r.p.id]: o.k }))} style={{ background: on ? "#0e0e10" : "#fff", color: on ? "#fff" : "#0e0e10", border: "1px solid " + (on ? "#0e0e10" : "#d4d4d8"), borderRadius: 6, padding: "7px 11px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{o.l}</button>;
                        })}
                      </div>}
                  </div>
                ))}
                <div style={{ fontSize: 11.5, color: "#9a9aa1", lineHeight: 1.5 }}>Team-gear completion resets at {dest.name} — required items differ per team. Nothing is ordered for these players, so nothing is left behind.</div>
              </div>}
          </React.Fragment>}
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, padding: "20px 28px 24px" }}>
        <Button variant="secondary" onClick={onClose}>Cancel</Button>
        <Button variant="primary" disabled={!dest || rows.length === 0} onClick={commit}>Move {rows.length || ""} {rows.length === 1 ? "player" : "players"}</Button>
      </div>
    </Modal>
  );
}

function RosterPlayerTable({ startEmpty, store, header, injected, onNumbers, rosterName, onDeleteRoster, rosterId, moveTargets, onMovePlayers }) {
  const [players, setPlayers] = React.useState(startEmpty ? [] : [
  { id: 1, first: "Jalen", last: "Hurts", number: "1", nameOnJersey: "Hurtski", email: "name@example.com", phone: "202-111-5555", associatedEmails: ["susanQuinones@gmail.com"], shippingAddress: "2001 Lincoln Ave, Philadelphia, PA 19145" },
  { id: 2, first: "Omar", last: "Calzoni", number: "17", nameOnJersey: "Calzoni", email: "fwright@outlook.com", phone: "679-604-5561", associatedEmails: [] },
  { id: 3, first: "Abram", last: "Passaquindici Arcand", number: "11", nameOnJersey: "A. Passaquindici-Arcand", email: "igeorge@gmail.com", phone: "439-431-7751", associatedEmails: [], shippingAddress: "88 Maple Court, Austin, TX 78701", addressFromCheckout: true },
  { id: 4, first: "Cooper", last: "Curtis", number: "8", nameOnJersey: "Curtis", email: "khall@aol.com", phone: "297-362-8278", associatedEmails: [] },
  { id: 5, first: "Davis", last: "Aminoff", number: "2", nameOnJersey: "Aminoff", email: "abrown@hotmail.com", phone: "559-506-5875", associatedEmails: [] },
  { id: 6, first: "Lincoln", last: "Herwitz", number: "22", nameOnJersey: "Herwitz", email: "egarcia@yahoo.com", phone: "787-648-4307", associatedEmails: [] },
  { id: 7, first: "Ahmad", last: "Passaquindici Arcand", number: "23", nameOnJersey: "Passaquindici-Arcand", email: "emitchell@outlook.com", phone: "822-984-1775", associatedEmails: [] },
  { id: 8, first: "Corey", last: "Stanton", number: "0", nameOnJersey: "Stanton", email: "sjones@icloud.com", phone: "516-761-0087", associatedEmails: [] },
  { id: 9, first: "Jon", last: "Jones", number: "7", nameOnJersey: "Jones", email: "jonjones@icloud.com", phone: "111-761-0087", associatedEmails: [] }]
  );
  const [adding, setAdding] = React.useState(false);
  const [editingPlayer, setEditingPlayer] = React.useState(null);
  const [openMenuId, setOpenMenuId] = React.useState(null);
  const [selected, setSelected] = React.useState(new Set());
  const [sort, setSort] = React.useState("Name (A-Z)");
  const [uploadOpen, setUploadOpen] = React.useState(false);
  const [shareOpen, setShareOpen] = React.useState(false);
  const [templateOpen, setTemplateOpen] = React.useState(false);
  const [confirmDeleteOpen, setConfirmDeleteOpen] = React.useState(false);
  const [confirmClearOpen, setConfirmClearOpen] = React.useState(false);
  const [confirmRosterDeleteOpen, setConfirmRosterDeleteOpen] = React.useState(false);
  const [gearPlayer, setGearPlayer] = React.useState(null);
  const [toast, setToast] = React.useState("");
  // 7a — this roster's own allow-duplicates value (Settings only seeds the default).
  const [dupeTick, setDupeTick] = React.useState(0);
  const allowDupes = rosterDupeAllowed(store, rosterId);
  const dupeOverridden = rosterDupeOverridden(rosterId);
  const [movePlayers, setMovePlayers] = React.useState(null);

  // Bank-zone commits flow into the table as committed roster records.
  React.useEffect(() => {
    if (!injected || !injected.length) return;
    setPlayers((cur) => {
      const add = injected.filter((p) => !cur.some((c) => c.id === p.id));
      return add.length ? [...cur, ...add] : cur;
    });
  }, [injected]);
  // Report claimed jersey numbers so the bank zone can flag conflicts
  // (uncommitted captures count against these, and vice versa).
  React.useEffect(() => {
    onNumbers && onNumbers(players.map((p) => String(p.number)));
    // 8 — publish this roster's claimed numbers so a move can validate against it.
    if (rosterId) rosterNumberRegistry()[rosterId] = players.map((p) => String(p.number || "").trim()).filter(Boolean);
  }, [players, rosterId]);

  const allChecked = players.length > 0 && selected.size === players.length;
  const someChecked = selected.size > 0 && selected.size < players.length;

  // Epic 3 — Direct-to-Home Delivery stores collect a per-player shipping address.
  const homeDelivery = (store?.distributionModel || "coach") === "home";
  const cols = homeDelivery ? ROSTER_COLS_HOME : ROSTER_COLS;

  function toggleAll() {
    if (allChecked) setSelected(new Set());else
    setSelected(new Set(players.map((p) => p.id)));
  }
  function toggleOne(id) {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id);else next.add(id);
    setSelected(next);
  }

  function addPlayer(p) {
    setPlayers((cur) => [...cur, { ...p, id: Date.now() }]);
    setAdding(false);
    window.dispatchEvent(new CustomEvent("tour:roster-added"));
  }
  function updatePlayer(p) {
    setPlayers((cur) => cur.map((x) => x.id === p.id ? p : x));
    setEditingPlayer(null);
  }
  function deletePlayer(id) {
    setPlayers((cur) => cur.filter((x) => x.id !== id));
    setSelected((s) => {const n = new Set(s);n.delete(id);return n;});
  }
  function removeSelected() {
    setPlayers((cur) => cur.filter((x) => !selected.has(x.id)));
    setSelected(new Set());
  }
  function bulkAddPlayers(rows) {
    setPlayers((cur) => [
    ...cur,
    ...rows.map((r, i) => ({ ...r, id: Date.now() + i }))]
    );
    setUploadOpen(false);
    if (rows && rows.length) window.dispatchEvent(new CustomEvent("tour:roster-added"));
  }
  function shareStoreLink(p) {
    const link = `https://prolook.com/store/hoyas?invite=${p.first.toLowerCase()}-${p.id}`;
    try {navigator.clipboard?.writeText(link);} catch (e) {}
    setToast(`Store link for ${p.first} ${p.last} copied to clipboard`);
  }

  // Players currently selected, and the de-duped pool of emails to pre-fill the share modal.
  const selectedPlayers = players.filter((p) => selected.has(p.id));
  // 8 — players with team-gear orders can't move, so say so before the modal opens.
  const movableSelected = selectedPlayers.filter((p) => playerTeamGear(p, store).orderedCount === 0).length;
  const sharePool = React.useMemo(() => {
    const set = new Set();
    selectedPlayers.forEach((p) => {
      if (p.email) set.add(p.email);
      (p.associatedEmails || []).forEach((e) => e && set.add(e));
    });
    return [...set];
  }, [selected, players]);

  function clearSelection() {setSelected(new Set());}

  // Sorted view of the roster (sorting never mutates the underlying list).
  const sortedPlayers = React.useMemo(() => {
    const arr = [...players];
    const name = (p) => `${p.first || ""} ${p.last || ""}`.trim().toLowerCase();
    const num = (p) => {const n = parseInt(p.number, 10);return isNaN(n) ? Infinity : n;};
    if (sort === "Name (A-Z)") arr.sort((a, b) => name(a).localeCompare(name(b)));else
    if (sort === "Name (Z-A)") arr.sort((a, b) => name(b).localeCompare(name(a)));else
    if (sort === "Number (low to high)") arr.sort((a, b) => num(a) - num(b));else
    if (sort === "Number (high to low)") arr.sort((a, b) => num(b) - num(a));
    return arr;
  }, [players, sort]);

  const doMove = (dest, assignments) => {
    const ids = new Set(assignments.map((a) => a.player.id));
    setPlayers((cur) => cur.filter((p) => !ids.has(p.id)));
    setSelected(new Set());
    setMovePlayers(null);
    onMovePlayers && onMovePlayers(dest, assignments);
    setToast(assignments.length + (assignments.length === 1 ? " player moved from " : " players moved from ") + (rosterName || "this roster") + " to " + dest.name);
  };

  return (
    <div style={{ minHeight: "800px" }}>
      {header}
      {/* 7a — roster rules in force for THIS team, editable where the rep is working */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap", background: "#fff", border: "1px solid #ececf0", borderRadius: 8, padding: "12px 16px", marginBottom: 16 }}>
        <span style={{ width: 32, height: 32, borderRadius: 8, flexShrink: 0, background: allowDupes ? "#f4f4f5" : "#f1f1f3", color: "#6b6b72", display: "inline-flex", alignItems: "center", justifyContent: "center" }}><IconUsers size={16} /></span>
        <span style={{ minWidth: 200, flex: 1 }}>
          <span style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>Duplicate numbers on this team</span>
          <span style={{ display: "block", fontSize: 12, color: "#6b6b72", marginTop: 1 }}>
            {allowDupes ? "Two players can share a number. Taken numbers stay selectable." : "Numbers are unique — taken numbers are locked in the picker."}
          </span>
        </span>
        {dupeOverridden
          ? <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: "#8a5f10", background: "#fdf6e7", border: "1px solid #efdcae", borderRadius: 999, padding: "3px 9px" }}>OVERRIDES STORE DEFAULT</span>
          : <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".05em", color: "#6b6b72", background: "#f4f4f5", borderRadius: 999, padding: "3px 9px" }}>FOLLOWING STORE DEFAULT</span>}
        {dupeOverridden &&
          <button type="button" onClick={() => { setRosterDupe(rosterId, null); setDupeTick((n) => n + 1); setToast("Reset to the store default"); }}
            style={{ background: "none", border: 0, fontSize: 12, fontWeight: 700, color: "#6b6b72", cursor: "pointer", fontFamily: "inherit" }}>Reset to default</button>}
        <span style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: allowDupes ? "#1f9d55" : "#6b6b72" }}>{allowDupes ? "Allowed" : "Blocked"}</span>
          <SettingsToggle value={allowDupes} onChange={(v) => { setRosterDupe(rosterId, v); setDupeTick((n) => n + 1); setToast(v ? "Duplicates allowed on " + (rosterName || "this team") : "Duplicates blocked on " + (rosterName || "this team")); }} />
        </span>
      </div>
      {/* Sort toolbar — shares the Stores/Leagues list toolbar component */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16, gap: 16 }}>
        <div style={{ fontSize: 13.5, fontWeight: 600, color: "#6b6b72" }}>
          {players.length} {players.length === 1 ? "Player" : "Players"}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <button onClick={() => setUploadOpen(true)} style={{ display: "inline-flex", alignItems: "center", gap: 8, borderRadius: 6, padding: "11px 18px", fontSize: 13, fontWeight: 700, fontFamily: "inherit", background: "#0e0e10", border: "1px solid #0e0e10", color: "#fff", cursor: "pointer" }}>
            <IconUpload size={14} style={{ strokeWidth: 2.4 }} /> Upload Roster
          </button>
          <button disabled={players.length === 0} onClick={() => setConfirmClearOpen(true)} style={{ display: "inline-flex", alignItems: "center", gap: 8, borderRadius: 6, padding: "11px 18px", fontSize: 13, fontWeight: 700, fontFamily: "inherit", background: "#fff", border: "1px solid #d4d4d8", color: players.length === 0 ? "#a1a1aa" : "#0e0e10", cursor: players.length === 0 ? "default" : "pointer" }}>
            Clear Roster
          </button>
          {onDeleteRoster && <button onClick={() => setConfirmRosterDeleteOpen(true)} style={{ display: "inline-flex", alignItems: "center", gap: 8, borderRadius: 6, padding: "11px 18px", fontSize: 13, fontWeight: 700, fontFamily: "inherit", background: "#fff", border: "1px solid #f0c9c5", color: "#b81d14", cursor: "pointer" }}>
            <IconTrash size={14} style={{ strokeWidth: 2.2 }} /> Delete Roster
          </button>}
          <ListToolbar
            showSearch={false}
            sort={{ value: sort, options: ROSTER_SORT_OPTIONS, onChange: setSort, width: 248 }} />
        </div>
      </div>
      {/* Bulk selection bar — appears once one or more players are checked */}
      {selected.size > 0 &&
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        background: "#f4f4f6", borderRadius: 40,
        padding: "16px 16px 16px 28px", marginBottom: 16, gap: 16
      }}>
          <span style={{ fontSize: 15, fontWeight: 700, color: "#0e0e10" }}>
            {selected.size} Selected
          </span>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button onClick={() => movableSelected > 0 && setMovePlayers(selectedPlayers)} disabled={movableSelected === 0}
            title={movableSelected === 0 ? "Every selected player has team-gear orders — those can't be moved" : ""} style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            background: "#fff", border: "1px solid #e2e2e6", borderRadius: 6,
            padding: "12px 16px", fontSize: 14, fontWeight: 600, color: movableSelected === 0 ? "#b6b6bd" : "#0e0e10",
            cursor: movableSelected === 0 ? "not-allowed" : "pointer", fontFamily: "inherit"
          }}>
              <IconArrowRight size={15} style={{ strokeWidth: 2 }} /> Move to team
              {selected.size > 1 && <span style={{ fontWeight: 700, color: movableSelected === 0 ? "#b6b6bd" : "#6b6b72" }}>{movableSelected} of {selected.size}</span>}
            </button>
            <button onClick={() => setConfirmDeleteOpen(true)} style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            background: "#fff", border: "1px solid #e2e2e6", borderRadius: 6,
            padding: "12px 16px", fontSize: 14, fontWeight: 600, color: "#0e0e10",
            cursor: "pointer", fontFamily: "inherit"
          }}>
              <IconTrash size={15} style={{ strokeWidth: 2 }} /> Delete
            </button>
            <button onClick={() => setShareOpen(true)} style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            background: "#0e0e10", border: "1px solid #0e0e10", borderRadius: 6,
            padding: "12px 16px", fontSize: 14, fontWeight: 600, color: "#fff",
            cursor: "pointer", fontFamily: "inherit"
          }}>
              Share Team Store Link
            </button>
            <button onClick={clearSelection} aria-label="Clear selection" style={{
            width: 40, height: 40, borderRadius: 8, background: "transparent",
            border: 0, cursor: "pointer", color: "#0e0e10",
            display: "inline-flex", alignItems: "center", justifyContent: "center"
          }}>
              <IconX size={20} style={{ strokeWidth: 2 }} />
            </button>
          </div>
        </div>
      }

      <div style={{ background: "#fff", border: "1px solid #ececf0", borderRadius: 8, overflow: "visible" }}>
        {/* Header row */}
        <div style={{
          display: "grid", gridTemplateColumns: cols, gap: 16,
          padding: "16px 24px", borderBottom: "1px solid #ececf0",
          fontSize: 12, color: "#6b6b72", fontWeight: 600,
          letterSpacing: ".02em", alignItems: "center"
        }}>
          <RosterCheckbox checked={allChecked} indeterminate={someChecked} onChange={toggleAll} />
          <div>Player Name</div>
          <div>Jersey Number</div>
          <div>Name on Jersey</div>
          <div>Email</div>
          <div>Phone Number</div>
          {homeDelivery && <div>Player Address</div>}
          <div>Team Gear</div>
          <div></div>
        </div>

        {/* Body */}
        <div style={{ minHeight: 360, height: "700px" }}>
          {players.length === 0 && !adding &&
          <div style={{ padding: "120px 20px", textAlign: "center", color: "#9a9aa1", fontSize: 13 }}>
              No players yet — that's a normal state. Team-gear orders will fill this roster in, or add players below / upload a CSV.
            </div>
          }
          {sortedPlayers.map((p) =>
          <div key={p.id} style={{
            display: "grid", gridTemplateColumns: cols, gap: 16,
            padding: "16px 24px", borderBottom: "1px solid #f3f3f4",
            fontSize: 14, color: "#0e0e10", alignItems: "center"
          }}>
                <RosterCheckbox checked={selected.has(p.id)} onChange={() => toggleOne(p.id)} />
                <div style={{ fontWeight: 600 }}>{p.first} {p.last}</div>
                <div>{p.number || "—"}</div>
                <div>{p.nameOnJersey || "—"}</div>
                <div style={{ color: "#9a9aa1" }}>{p.email || "—"}</div>
                <div>{p.phone || "—"}</div>
                {homeDelivery &&
            <div style={{ minWidth: 0 }}>
                  {p.shippingAddress ?
                <React.Fragment>
                      <div style={{ color: "#0e0e10", lineHeight: 1.35 }}>{p.shippingAddress}</div>
                      {p.addressFromCheckout &&
                  <span style={{
                    display: "inline-flex", alignItems: "center", gap: 4, marginTop: 4,
                    fontSize: 10.5, fontWeight: 700, letterSpacing: ".04em", textTransform: "uppercase",
                    color: "#2563eb", background: "#eef3ff", borderRadius: 999, padding: "2px 8px"
                  }}>
                        <IconCart size={11} style={{ strokeWidth: 2.2 }} /> From checkout
                      </span>
                  }
                    </React.Fragment> :
                <span style={{ color: "#c0c0c6", fontStyle: "italic" }}>Awaiting checkout</span>
                }
                </div>
            }
                <div>
                  {(() => { const g = playerTeamGear(p, store); return (
                    <button onClick={() => setGearPlayer(p)} style={{
                      background: "none", border: 0, padding: 0, cursor: "pointer", fontFamily: "inherit",
                      fontSize: 13, fontWeight: 600, color: "#2563eb", textAlign: "left", whiteSpace: "nowrap",
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.textDecoration = "underline"}
                    onMouseLeave={(e) => e.currentTarget.style.textDecoration = "none"}>
                      {g.orderedCount}/{g.total} team gear items
                    </button>
                  ); })()}
                </div>
                <div style={{ position: "relative", justifySelf: "end" }}>
                  <button onClick={(e) => {e.stopPropagation();setOpenMenuId(openMenuId === p.id ? null : p.id);}}
              style={{
                width: 32, height: 32, borderRadius: 4, background: "transparent",
                border: 0, padding: 0, cursor: "pointer", color: "#6b6b72",
                display: "inline-flex", alignItems: "center", justifyContent: "center"
              }}
              title="Row actions">
                    <svg width={18} height={18} viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="1.7" /><circle cx="12" cy="12" r="1.7" /><circle cx="19" cy="12" r="1.7" /></svg>
                  </button>
                  {openMenuId === p.id &&
              <RowMenu
                onEdit={() => {setEditingPlayer(p);setOpenMenuId(null);}}
                onShare={() => {shareStoreLink(p);setOpenMenuId(null);}}
                moveBlocked={playerTeamGear(p, store).orderedCount > 0}
                onMove={() => {setMovePlayers([p]);setOpenMenuId(null);}}
                onDelete={() => {deletePlayer(p.id);setOpenMenuId(null);}}
                onClose={() => setOpenMenuId(null)} />
              }
                </div>
              </div>
          )}

          {adding && <PlayerEditRow existing={players} cols={cols} homeDelivery={homeDelivery} allowDupes={allowDupes} onCancel={() => setAdding(false)} onSave={addPlayer} />}
        </div>

        {/* Inline Add Player */}
        <button data-tour="roster-add" onClick={() => {setAdding(true);}} disabled={adding} style={{
          background: "transparent", border: 0, padding: "20px 24px",
          display: "flex", alignItems: "center", gap: 12, fontSize: 14, fontWeight: 600,
          color: adding ? "#9a9aa1" : "#0e0e10",
          cursor: adding ? "not-allowed" : "pointer",
          width: "100%", textAlign: "left", borderTop: players.length ? "1px solid #f3f3f4" : "none"
        }}>
          <span style={{
            width: 24, height: 24, borderRadius: "50%", border: "1.5px solid currentColor",
            display: "inline-flex", alignItems: "center", justifyContent: "center"
          }}>
            <IconPlus size={12} style={{ strokeWidth: 2.4 }} />
          </span>
          Add Player
        </button>
      </div>

      <RosterDangerConfirmModal
        open={confirmClearOpen}
        title="Clear this roster?"
        body={"All " + players.length + (players.length === 1 ? " player" : " players") + " will be removed from " + (rosterName || "this roster") + ". The roster itself is kept. This action can't be undone."}
        confirmLabel="Clear Roster"
        onClose={() => setConfirmClearOpen(false)}
        onConfirm={() => { const n = players.length; setPlayers([]); setSelected(new Set()); setConfirmClearOpen(false); setToast("Roster cleared — " + n + (n === 1 ? " player" : " players") + " removed"); }} />
      <RosterDangerConfirmModal
        open={confirmRosterDeleteOpen}
        title="Delete this roster?"
        body={(rosterName || "This roster") + " and its " + players.length + (players.length === 1 ? " player" : " players") + " will be permanently deleted. This action can't be undone."}
        confirmLabel="Delete Roster"
        onClose={() => setConfirmRosterDeleteOpen(false)}
        onConfirm={() => { setConfirmRosterDeleteOpen(false); onDeleteRoster && onDeleteRoster(); }} />
      <UploadRosterModal open={uploadOpen} onClose={() => setUploadOpen(false)} onImport={bulkAddPlayers} store={store} />

      <ShareRosterTemplateModal
        open={templateOpen}
        store={store}
        onClose={() => setTemplateOpen(false)}
        onSend={() => {setTemplateOpen(false);setToast("Roster template sent to team managers");}} />

      <ShareTeamStoreModal
        open={shareOpen}
        count={selected.size}
        emails={sharePool}
        onClose={() => setShareOpen(false)}
        onSend={() => {setShareOpen(false);setToast("Team store link shared");}} />

      <ConfirmDeleteModal
        open={confirmDeleteOpen}
        count={selected.size}
        onClose={() => setConfirmDeleteOpen(false)}
        onConfirm={() => {
          const n = selected.size;
          removeSelected();
          setConfirmDeleteOpen(false);
          setToast(`${n} player${n === 1 ? "" : "s"} removed`);
        }} />


      <MovePlayersModal
        open={!!movePlayers}
        players={movePlayers || []}
        current={{ id: rosterId, name: rosterName, groupName: (moveTargets || []).find((t) => t.id === rosterId)?.groupName || null }}
        targets={moveTargets || []}
        store={store}
        onClose={() => setMovePlayers(null)}
        onConfirm={doMove} />

      <PlayerDrawer
        player={editingPlayer}
        existing={players}
        allowDupes={allowDupes}
        homeDelivery={homeDelivery}
        onClose={() => setEditingPlayer(null)}
        onSave={updatePlayer}
        onShare={(p) => shareStoreLink(p)} />

      {gearPlayer &&
      <TeamGearDrawer
        player={gearPlayer}
        store={store}
        onClose={() => setGearPlayer(null)}
        onSendReminder={(p) => { setGearPlayer(null); setToast(`Reminder sent to ${p.first} ${p.last}`); }} />}

      <Toast message={toast} onDone={() => setToast("")} />
    </div>);
}

// Roster field validation: phone must be a 10-digit US number; email a basic
// valid address. Both are optional, but if entered they must be well-formed.
function formatPhone(raw) {
  const d = String(raw || "").replace(/\D/g, "").slice(0, 10);
  if (d.length <= 3) return d;
  if (d.length <= 6) return `(${d.slice(0, 3)}) ${d.slice(3)}`;
  return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
}
function phoneDigits(v) {return String(v || "").replace(/\D/g, "");}
function isValidPhone(v) {return phoneDigits(v).length === 10;}
function isValidEmail(v) {return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v || "").trim());}
// Jersey number is optional (Roster spec #12) but, when present, must be 0–99 and
// unique on the roster. Returns the colliding player, or null.
function rosterNumberConflict(number, existing, selfId) {
  const n = String(number || "").trim();
  if (!n) return null;
  return (existing || []).find((p) => p.id !== selfId && String(p.number || "").trim() === n) || null;
}

function PlayerEditRow({ initial, existing, cols = ROSTER_COLS, homeDelivery, onCancel, onSave, allowDupes }) {
  const [first, setFirst] = React.useState(initial?.first || "");
  const [last, setLast] = React.useState(initial?.last || "");
  const [number, setNumber] = React.useState(initial?.number || "");
  const [nameOnJersey, setNameOnJersey] = React.useState(initial?.nameOnJersey || "");
  const [email, setEmail] = React.useState(initial?.email || "");
  const [phone, setPhone] = React.useState(initial?.phone || "");
  const [address, setAddress] = React.useState(initial?.shippingAddress || "");
  const [validating, setValidating] = React.useState(false);
  const [addrErr, setAddrErr] = React.useState("");

  const numConflict = rosterNumberConflict(number, existing, initial?.id);
  // 7c — a taken number only blocks when duplicates are off for this team.
  const numBlocked = !!numConflict && !allowDupes;
  // Shipping address is OPTIONAL (mirrors Name on Jersey) — never blocks save.
  const canSave =
  first.trim() && last.trim() &&
  isValidEmail(email) && (
  !phone || isValidPhone(phone)) &&
  !numBlocked;

  async function commit() {
    if (!canSave || validating) return;
    let finalAddr = address.trim();
    // Direct-to-Home stores validate any entered address against a map service.
    if (homeDelivery && finalAddr) {
      setValidating(true);
      setAddrErr("");
      const res = await validateAddressService(finalAddr);
      setValidating(false);
      if (!res.ok) {
        setAddrErr("We couldn’t verify this address. Check it and try again — or leave it blank.");
        return;
      }
      finalAddr = res.normalized;
    }
    onSave({
      ...(initial || {}),
      first: first.trim(), last: last.trim(),
      number: number.trim(), nameOnJersey: nameOnJersey.trim(),
      email: email.trim(), phone: phone.trim(),
      shippingAddress: finalAddr
    });
  }

  function onKey(e) {
    if (e.key === "Enter") commit();
    if (e.key === "Escape") onCancel();
  }

  const showError = numBlocked || addrErr;

  return (
    <React.Fragment>
    <div onKeyDown={onKey} style={{
      display: "grid", gridTemplateColumns: cols, gap: 16,
      padding: "12px 24px", borderBottom: showError || validating ? "none" : "1px solid #f3f3f4",
      alignItems: "center", background: "#fafafb"
    }} data-tour="roster-player-fields">
      <div></div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <RosterInput value={first} onChange={setFirst} placeholder="First Name" autoFocus />
        <RosterInput value={last} onChange={setLast} placeholder="Last Name" />
      </div>
      <JerseyCellPicker value={number} onChange={setNumber} existing={existing} selfId={initial?.id} allowDupes={allowDupes} invalid={numBlocked} />
      <RosterInput value={nameOnJersey} onChange={setNameOnJersey} placeholder="Name on Jersey" />
      <RosterInput value={email} onChange={setEmail} placeholder="Email" type="email" inputMode="email" invalid={!!email && !isValidEmail(email)} />
      <RosterInput value={phone} onChange={(v) => setPhone(formatPhone(v))} placeholder="Phone Number" type="tel" inputMode="tel" maxLength={14} invalid={!!phone && !isValidPhone(phone)} />
      {homeDelivery &&
      <RosterInput value={address} onChange={(v) => { setAddress(v); if (addrErr) setAddrErr(""); }} placeholder="Player Shipping Address (optional)" invalid={!!addrErr} />
      }
      <div></div>
      <div style={{ display: "flex", gap: 8, justifySelf: "end" }}>
        <button onClick={commit} disabled={!canSave || validating} title="Save"
        style={{
          width: 36, height: 36, borderRadius: 4,
          background: canSave && !validating ? "#1f9d55" : "#cfead9",
          color: "#fff", border: 0, display: "inline-flex",
          alignItems: "center", justifyContent: "center",
          cursor: canSave && !validating ? "pointer" : "not-allowed"
        }}>
          <IconCheck size={16} style={{ strokeWidth: 2.6 }} />
        </button>
        <button onClick={onCancel} title="Cancel"
        style={{
          width: 36, height: 36, borderRadius: 4,
          background: "#fff", color: "#0e0e10",
          border: "1px solid #d4d4d8", display: "inline-flex",
          alignItems: "center", justifyContent: "center", cursor: "pointer"
        }}>
          <IconX size={14} style={{ strokeWidth: 2.4 }} />
        </button>
      </div>
    </div>
    {numConflict &&
      <div style={{
        display: "flex", alignItems: "center", gap: 8,
        padding: "8px 24px 12px", background: "#fafafb",
        borderBottom: "1px solid #f3f3f4",
        fontSize: 12.5, fontWeight: 600, color: numBlocked ? "#b81d14" : "#6b6b72"
      }}>
        {numBlocked
          ? <React.Fragment><IconAlert size={14} style={{ strokeWidth: 2.2, flexShrink: 0 }} />Number {number} is taken by {numConflict.first} {numConflict.last} — locked while duplicates are off</React.Fragment>
          : <React.Fragment><IconInfo size={14} style={{ strokeWidth: 2, flexShrink: 0 }} />Number {number} · duplicate — also worn by {numConflict.first} {numConflict.last}</React.Fragment>}
      </div>
    }
    {!numConflict && validating &&
      <div style={{
        display: "flex", alignItems: "center", gap: 8,
        padding: "8px 24px 12px", background: "#fafafb",
        borderBottom: "1px solid #f3f3f4",
        fontSize: 12.5, fontWeight: 600, color: "#6b6b72"
      }}>
        <IconPin size={14} style={{ strokeWidth: 2.2, flexShrink: 0 }} />
        Verifying address with map service…
      </div>
    }
    {!numConflict && !validating && addrErr &&
      <div style={{
        display: "flex", alignItems: "center", gap: 8,
        padding: "8px 24px 12px", background: "#fafafb",
        borderBottom: "1px solid #f3f3f4",
        fontSize: 12.5, fontWeight: 600, color: "#b81d14"
      }}>
        <IconAlert size={14} style={{ strokeWidth: 2.2, flexShrink: 0 }} />
        {addrErr}
      </div>
    }
    </React.Fragment>);
}

function RosterInput({ value, onChange, placeholder, type = "text", autoFocus, invalid, inputMode, maxLength }) {
  const [focus, setFocus] = React.useState(false);
  const borderColor = invalid ? "#e1251b" : focus ? "#0e0e10" : "#d4d4d8";
  return (
    <input
      type={type}
      value={value}
      placeholder={placeholder}
      autoFocus={autoFocus}
      inputMode={inputMode}
      maxLength={maxLength}
      aria-invalid={invalid ? "true" : undefined}
      onChange={(e) => onChange(e.target.value)}
      onFocus={() => setFocus(true)}
      onBlur={() => setFocus(false)}
      style={{
        width: "100%", boxSizing: "border-box",
        padding: "8px 12px", fontSize: 13, fontFamily: "inherit",
        background: invalid ? "#fdf2f1" : "#fff",
        border: `1px solid ${borderColor}`,
        borderRadius: 4, color: "#0e0e10", outline: "none"
      }} />);
}

function RosterCheckbox({ checked, indeterminate, onChange }) {
  return (
    <button onClick={onChange} aria-pressed={!!checked} style={{
      width: 20, height: 20, borderRadius: 3,
      background: checked || indeterminate ? "#0e0e10" : "#fff",
      border: `1.5px solid ${checked || indeterminate ? "#0e0e10" : "#c4c4c8"}`,
      cursor: "pointer", padding: 0,
      display: "inline-flex", alignItems: "center", justifyContent: "center"
    }}>
      {checked && !indeterminate &&
      <svg width={12} height={12} viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12l5 5L20 6" /></svg>
      }
      {indeterminate &&
      <div style={{ width: 12, height: 2, background: "#fff", borderRadius: 1 }} />
      }
    </button>);
}

function RowMenu({ onEdit, onShare, onDelete, onClose, onMove, moveBlocked }) {
  React.useEffect(() => {
    const handler = () => onClose();
    const t = setTimeout(() => document.addEventListener("click", handler), 0);
    return () => {clearTimeout(t);document.removeEventListener("click", handler);};
  }, [onClose]);
  return (
    <div onClick={(e) => e.stopPropagation()} style={{
      position: "absolute", right: 0, top: 36,
      background: "#fff", border: "1px solid #ececf0",
      borderRadius: 6, boxShadow: "0 10px 28px rgba(0,0,0,.10)",
      minWidth: 196, zIndex: 20, overflow: "hidden"
    }}>
      <MenuItem onClick={onEdit} icon={<IconEdit size={14} />}>Edit Player</MenuItem>
      {onMove && <MenuItem onClick={onMove} icon={<IconArrowRight size={14} />}
        disabled={!!moveBlocked} title={moveBlocked ? "Team-gear orders already placed — cancel or fulfil them first" : "Move this player to another team in this group"}>
        {moveBlocked ? "Move to different team — has orders" : "Move to different team"}
      </MenuItem>}
      <MenuItem onClick={onShare} icon={<ShareLinkIcon size={14} />}>Share Store Link</MenuItem>
      <MenuItem onClick={onDelete} icon={<IconTrash size={14} />} danger>Delete Player</MenuItem>
    </div>);
}

const ShareLinkIcon = ({ size = 14 }) =>
<svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 1 0-7-7l-1 1" />
    <path d="M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 1 0 7 7l1-1" />
  </svg>;

// ─────────── Edit Player drawer ───────────
function PlayerDrawer({ player, existing, homeDelivery, onClose, onSave, onShare, allowDupes }) {
  const [first, setFirst] = React.useState("");
  const [last, setLast] = React.useState("");
  const [nameOnJersey, setNameOnJersey] = React.useState("");
  const [number, setNumber] = React.useState("");
  const [phone, setPhone] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [associatedEmails, setAssociatedEmails] = React.useState([]);
  const [address, setAddress] = React.useState("");
  const [validating, setValidating] = React.useState(false);
  const [addrErr, setAddrErr] = React.useState("");

  React.useEffect(() => {
    if (!player) return;
    setFirst(player.first || "");
    setLast(player.last || "");
    setNameOnJersey(player.nameOnJersey || "");
    setNumber(player.number || "");
    setPhone(player.phone || "");
    setEmail(player.email || "");
    setAssociatedEmails(player.associatedEmails || []);
    setAddress(player.shippingAddress || "");
    setAddrErr("");
    setValidating(false);
  }, [player]);

  React.useEffect(() => {
    if (!player) return;
    const h = (e) => {if (e.key === "Escape") onClose();};
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [player, onClose]);

  async function commit() {
    if ((!allowDupes && rosterNumberConflict(number, existing, player?.id)) || validating) return;
    let finalAddr = address.trim();
    // Direct-to-Home stores validate any entered address against a map service.
    if (homeDelivery && finalAddr && finalAddr !== (player?.shippingAddress || "").trim()) {
      setValidating(true);
      setAddrErr("");
      const res = await validateAddressService(finalAddr);
      setValidating(false);
      if (!res.ok) {
        setAddrErr("We couldn’t verify this address. Check it and try again — or leave it blank.");
        return;
      }
      finalAddr = res.normalized;
    }
    onSave({
      ...player,
      first: first.trim(), last: last.trim(),
      nameOnJersey: nameOnJersey.trim(), number: number.trim(),
      phone: phone.trim(), email: email.trim(),
      shippingAddress: finalAddr,
      // A rep-verified edit clears the “from checkout” origin flag.
      addressFromCheckout: finalAddr && finalAddr !== (player?.shippingAddress || "").trim() ? false : player?.addressFromCheckout,
      associatedEmails
    });
  }

  function removeAssociated(em) {
    setAssociatedEmails((cur) => cur.filter((x) => x !== em));
  }

  const open = !!player;

  return (
    <>
      {/* Scrim */}
      <div onClick={onClose} style={{
        position: "fixed", inset: 0, zIndex: 90,
        background: open ? "rgba(20,20,30,.40)" : "transparent",
        opacity: open ? 1 : 0, pointerEvents: open ? "auto" : "none",
        transition: "opacity .2s ease"
      }} />

      {/* Panel */}
      <aside style={{
        position: "fixed", top: 0, right: 0, bottom: 0, width: 480, maxWidth: "96vw",
        background: "#fff", zIndex: 100,
        boxShadow: "-12px 0 40px rgba(20,20,30,.18)",
        transform: open ? "translateX(0)" : "translateX(100%)",
        transition: "transform .26s cubic-bezier(.2,.85,.3,1)",
        display: "flex", flexDirection: "column"
      }}>
        {/* Header */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "24px 28px", borderBottom: "1px solid #ececf0"
        }}>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>Edit Player</h2>
          <button onClick={onClose} aria-label="Close" style={{
            background: "transparent", border: 0, padding: 8, cursor: "pointer",
            color: "#0e0e10", display: "inline-flex", alignItems: "center", justifyContent: "center"
          }}>
            <IconX size={20} style={{ strokeWidth: 2 }} />
          </button>
        </div>

        {/* Body */}
        <div style={{ flex: 1, overflowY: "auto", padding: "24px 28px", display: "flex", flexDirection: "column", gap: 32 }}>
          <TextField label="First Name" value={first} onChange={setFirst} />
          <TextField label="Last Name" value={last} onChange={setLast} />
          <TextField label="Name on Jersey" value={nameOnJersey} onChange={setNameOnJersey} />
          <div>
            <div style={{ fontSize: 11, fontWeight: 500, color: "#6b6b72", marginBottom: 8, paddingLeft: 4 }}>Jersey Number</div>
            <JerseyNumberField value={number} onChange={(v) => setNumber(String(v).replace(/\D/g, "").slice(0, 2))}
              existing={existing} selfId={player?.id} allowDupes={allowDupes} />
          </div>

          <div>
            <div style={{ fontSize: 11, fontWeight: 500, color: "#6b6b72", marginBottom: 8, paddingLeft: 4 }}>Phone Number</div>
            <PhoneField value={phone} onChange={setPhone} />
          </div>

          <TextField label="Email" value={email} onChange={setEmail} type="email" />

          {homeDelivery &&
          <div>
            <div style={{ fontSize: 11, fontWeight: 500, color: "#6b6b72", marginBottom: 8, paddingLeft: 4 }}>
              Player Shipping Address <span style={{ color: "#9a9aa1", fontWeight: 400 }}>(optional)</span>
            </div>
            <TextField value={address} onChange={(v) => { setAddress(v); if (addrErr) setAddrErr(""); }} placeholder="Street, City, State ZIP" />
            {validating &&
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8, paddingLeft: 4, fontSize: 12.5, fontWeight: 600, color: "#6b6b72" }}>
              <IconPin size={13} style={{ strokeWidth: 2.2, flexShrink: 0 }} /> Verifying address with map service…
            </div>
            }
            {!validating && addrErr &&
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8, paddingLeft: 4, fontSize: 12.5, fontWeight: 600, color: "#b81d14" }}>
              <IconAlert size={13} style={{ strokeWidth: 2.2, flexShrink: 0 }} /> {addrErr}
            </div>
            }
            {!validating && !addrErr && player?.addressFromCheckout && address === (player?.shippingAddress || "") &&
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8, paddingLeft: 4, fontSize: 12, fontWeight: 600, color: "#2563eb" }}>
              <IconCart size={13} style={{ strokeWidth: 2.2, flexShrink: 0 }} /> Provided by the player at checkout
            </div>
            }
          </div>
          }

          <div>
            <div style={{ fontSize: 11, fontWeight: 500, color: "#6b6b72", marginBottom: 8, paddingLeft: 4 }}>Associated Emails</div>
            <div style={{
              border: "1px solid #d4d4d8", borderRadius: 4, background: "#fff",
              minHeight: 48, padding: 8, display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center"
            }}>
              {associatedEmails.length === 0 &&
              <span style={{ color: "#9a9aa1", fontSize: 13, padding: "0 8px" }}>No associated emails</span>
              }
              {associatedEmails.map((em) =>
              <span key={em} style={{
                display: "inline-flex", alignItems: "center", gap: 8,
                background: "#f1f1f3", borderRadius: 999,
                padding: "8px 8px 8px 12px", fontSize: 13, color: "#0e0e10"
              }}>
                  {em}
                  <button onClick={() => removeAssociated(em)} aria-label={`Remove ${em}`} style={{
                  width: 16, height: 16, borderRadius: "50%",
                  background: "#9a9aa1", color: "#fff", border: 0,
                  display: "inline-flex", alignItems: "center", justifyContent: "center",
                  cursor: "pointer", padding: 0
                }}>
                    <IconX size={10} style={{ strokeWidth: 3 }} />
                  </button>
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{
          padding: "16px 28px", borderTop: "1px solid #ececf0",
          display: "flex", justifyContent: "space-between", gap: 12, background: "#fff"
        }}>
          <Button variant="secondary" onClick={() => onShare(player)}>Share Link</Button>
          <Button variant="primary" onClick={commit} disabled={(!allowDupes && !!rosterNumberConflict(number, existing, player?.id)) || validating}>{validating ? "Verifying…" : "Save Changes"}</Button>
        </div>
      </aside>
    </>);
}

function MenuItem({ icon, children, onClick, danger, disabled, title }) {
  return (
    <button onClick={disabled ? undefined : onClick} disabled={disabled} title={title} style={{
      display: "flex", alignItems: "center", gap: 12,
      padding: "12px 16px", fontSize: 13,
      color: disabled ? "#b6b6bd" : danger ? "#b81d14" : "#0e0e10",
      background: "transparent", border: 0,
      width: "100%", textAlign: "left", cursor: disabled ? "not-allowed" : "pointer",
      fontFamily: "inherit"
    }}>
      {icon}{children}
    </button>);
}

// ─────────── Confirm delete players modal ───────────
function ConfirmDeleteModal({ open, count, onClose, onConfirm }) {
  const noun = count === 1 ? "this player" : `these ${count} players`;
  return (
    <Modal open={open} onClose={onClose} width={440}>
      <div style={{ padding: "28px 28px 24px" }}>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 16 }}>
          <div style={{
            width: 44, height: 44, borderRadius: "50%", flexShrink: 0,
            background: "#fdecec", color: "#b81d14",
            display: "inline-flex", alignItems: "center", justifyContent: "center"
          }}>
            <IconTrash size={20} style={{ strokeWidth: 2 }} />
          </div>
          <div>
            <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>
              Delete {count === 1 ? "player" : `${count} players`}?
            </h2>
            <p style={{ margin: "8px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>
              Are you sure you want to delete {noun} from the roster? This action can't be undone.
            </p>
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 28 }}>
          <button onClick={onClose} style={{
            background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6,
            padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em",
            color: "#0e0e10", cursor: "pointer", fontFamily: "inherit"
          }}>
            Cancel
          </button>
          <button onClick={onConfirm} style={{
            background: "#b81d14", border: "1px solid #b81d14", borderRadius: 6,
            padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em",
            color: "#fff", cursor: "pointer", fontFamily: "inherit"
          }}>
            Delete
          </button>
        </div>
      </div>
    </Modal>);
}

// ─────────── Confirm clear / delete roster modal ───────────
function RosterDangerConfirmModal({ open, title, body, confirmLabel, onClose, onConfirm }) {
  return (
    <Modal open={open} onClose={onClose} width={440}>
      <div style={{ padding: "28px 28px 24px" }}>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 16 }}>
          <div style={{ width: 44, height: 44, borderRadius: "50%", flexShrink: 0, background: "#fdecec", color: "#b81d14", display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
            <IconTrash size={20} style={{ strokeWidth: 2 }} />
          </div>
          <div>
            <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>{title}</h2>
            <p style={{ margin: "8px 0 0", fontSize: 13, color: "#6b6b72", lineHeight: 1.55 }}>{body}</p>
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 28 }}>
          <button onClick={onClose} style={{ background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6, padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em", color: "#0e0e10", cursor: "pointer", fontFamily: "inherit" }}>Cancel</button>
          <button onClick={onConfirm} style={{ background: "#b81d14", border: "1px solid #b81d14", borderRadius: 6, padding: "12px 24px", fontSize: 13, fontWeight: 700, letterSpacing: ".04em", color: "#fff", cursor: "pointer", fontFamily: "inherit" }}>{confirmLabel}</button>
        </div>
      </div>
    </Modal>);
}

// ─────────── Share Team Store Link modal ───────────
const SHARE_DEFAULT_MESSAGE =
"Hi Team,\n\nIt's that time of year! Our official team store is now open and ready for orders. We've made it easy to get everything you need for the upcoming season in one place. Whether you're picking up required uniforms or grabbing some new fan gear to wear in the stands, just follow the link below to get started.";

function ShareTeamStoreModal({ open, count, emails, onClose, onSend }) {
  const [chips, setChips] = React.useState([]);
  const [draft, setDraft] = React.useState("");
  const [subject, setSubject] = React.useState("");
  const [message, setMessage] = React.useState(SHARE_DEFAULT_MESSAGE);

  React.useEffect(() => {
    if (open) {
      setChips(emails && emails.length ? emails : []);
      setDraft("");
      setSubject("");
      setMessage(SHARE_DEFAULT_MESSAGE);
    }
  }, [open]);

  function addDraft() {
    const v = draft.trim().replace(/,$/, "");
    if (v && !chips.includes(v)) setChips((c) => [...c, v]);
    setDraft("");
  }
  function onDraftKey(e) {
    if (e.key === "Enter" || e.key === ",") {e.preventDefault();addDraft();}
    if (e.key === "Backspace" && !draft && chips.length) setChips((c) => c.slice(0, -1));
  }
  function removeChip(em) {setChips((c) => c.filter((x) => x !== em));}

  const canSend = chips.length > 0;

  return (
    <Modal open={open} onClose={onClose} width={620}>
      <div style={{ padding: "28px 28px 0", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <h2 style={{ margin: 0, fontSize: 20, fontWeight: 800 }}>Share Team Store Link</h2>
        <button onClick={onClose} aria-label="Close" style={{
          background: "transparent", border: 0, padding: 8, cursor: "pointer", color: "#0e0e10",
          display: "inline-flex", alignItems: "center", justifyContent: "center"
        }}>
          <IconX size={22} style={{ strokeWidth: 2 }} />
        </button>
      </div>

      <div style={{ padding: "24px 28px 24px", display: "flex", flexDirection: "column", gap: 20 }}>
        {/* Associated Emails */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>
            Associated Emails <span style={{ color: "#b81d14" }}>*</span>
          </div>
          <div style={{
            border: "1px solid #d4d4d8", borderRadius: 8, background: "#fff",
            minHeight: 52, padding: 8, display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center"
          }}>
            {chips.map((em) =>
            <span key={em} style={{
              display: "inline-flex", alignItems: "center", gap: 8,
              background: "#f1f1f3", borderRadius: 999,
              padding: "8px 8px 8px 16px", fontSize: 13, color: "#0e0e10"
            }}>
                {em}
                <button onClick={() => removeChip(em)} aria-label={`Remove ${em}`} style={{
                width: 16, height: 16, borderRadius: "50%",
                background: "#9a9aa1", color: "#fff", border: 0,
                display: "inline-flex", alignItems: "center", justifyContent: "center",
                cursor: "pointer", padding: 0
              }}>
                  <IconX size={10} style={{ strokeWidth: 3 }} />
                </button>
              </span>
            )}
            <input
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={onDraftKey}
              onBlur={addDraft}
              placeholder={chips.length ? "" : "Add email and press Enter"}
              style={{
                flex: 1, minWidth: 140, border: 0, outline: 0, background: "transparent",
                padding: "8px 4px", fontSize: 13, color: "#0e0e10", fontFamily: "inherit"
              }} />
          </div>
        </div>

        {/* Subject */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>Subject</div>
          <input
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="Ready to gear up for the [Team Name] season? 🏆"
            style={{
              width: "100%", boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 8,
              padding: "12px 16px", fontSize: 14, color: "#0e0e10", outline: "none",
              fontFamily: "inherit", background: "#fff"
            }} />
        </div>

        {/* Message */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>Message</div>
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            rows={6}
            style={{
              width: "100%", boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 8,
              padding: "12px 16px", fontSize: 14, color: "#0e0e10", outline: "none",
              fontFamily: "inherit", background: "#fff", resize: "vertical", lineHeight: 1.55
            }} />
        </div>
      </div>

      <div style={{ padding: "0 28px 28px", display: "flex", justifyContent: "flex-end" }}>
        <button onClick={onSend} disabled={!canSend} style={{
          background: canSend ? "#0e0e10" : "#cfcfd4", color: "#fff", border: 0,
          borderRadius: 999, padding: "12px 40px", fontSize: 15, fontWeight: 700,
          cursor: canSend ? "pointer" : "not-allowed", fontFamily: "inherit"
        }}>
          Send
        </button>
      </div>
    </Modal>);
}

// ─────────── Share Roster Template modal ───────────
// Standalone workflow: emails a blank roster template to team managers so they
// can fill in player details and return it for import. The [Rep Name] signature
// is pulled from the active logged-in platform user shown in the header.
const REP_NAME = "George";
const TEMPLATE_FILE_NAME = "prolook_roster_template.csv";
const TEMPLATE_DEFAULT_SUBJECT = "Action Required: Roster Template for Team Store Setup";
const TEMPLATE_DEFAULT_MESSAGE =
`Hi Team Manager,

Attached is the roster template file for your upcoming team store.

Please open the attached template and fill in your players' details (Names, Jersey Numbers, and Contact Info). Once completed, please reply directly to this email or send the finalized file back to me so I can import your roster and launch your store.

Let me know if you have any questions!

Best regards,
${REP_NAME}`;

function ShareRosterTemplateModal({ open, store, onClose, onSend }) {
  const [chips, setChips] = React.useState([]);
  const [overflow, setOverflow] = React.useState(0);
  const [draft, setDraft] = React.useState("");
  const [subject, setSubject] = React.useState(TEMPLATE_DEFAULT_SUBJECT);
  const [message, setMessage] = React.useState(TEMPLATE_DEFAULT_MESSAGE);

  React.useEffect(() => {
    if (open) {
      // Seed with dummy recipient chips + a "3+" overflow counter for multi-recipient styling.
      setChips(["susanQuinones@gmail.com", "marcusReed@outlook.com"]);
      setOverflow(3);
      setDraft("");
      setSubject(TEMPLATE_DEFAULT_SUBJECT);
      setMessage(TEMPLATE_DEFAULT_MESSAGE);
    }
  }, [open]);

  function addDraft() {
    const v = draft.trim().replace(/,$/, "");
    if (v && !chips.includes(v)) setChips((c) => [...c, v]);
    setDraft("");
  }
  function onDraftKey(e) {
    if (e.key === "Enter" || e.key === ",") {e.preventDefault();addDraft();}
    if (e.key === "Backspace" && !draft && chips.length) setChips((c) => c.slice(0, -1));
  }
  function removeChip(em) {setChips((c) => c.filter((x) => x !== em));}

  const canSend = chips.length > 0 || overflow > 0;

  return (
    <Modal open={open} onClose={onClose} width={620}>
      {/* Header & context */}
      <div style={{ padding: "28px 28px 16px", borderBottom: "1px solid #ececf0" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16 }}>
          <h2 style={{ margin: 0, fontSize: 20, fontWeight: 800 }}>Share Roster Template</h2>
          <button onClick={onClose} aria-label="Close" style={{
            background: "transparent", border: 0, padding: 4, cursor: "pointer", color: "#0e0e10",
            display: "inline-flex", alignItems: "center", justifyContent: "center", marginTop: 2
          }}>
            <IconX size={22} style={{ strokeWidth: 2 }} />
          </button>
        </div>
        <p style={{ margin: "8px 0 0", fontSize: 13, color: "#9a9aa1", lineHeight: 1.55, maxWidth: 520, textWrap: "pretty" }}>
          Send a blank roster template to your team managers. They can fill out their players' information and return it to you for rapid roster import.
        </p>
      </div>

      <div style={{ padding: "24px 28px 24px", display: "flex", flexDirection: "column", gap: 20 }}>
        {/* Associated Emails */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>
            Associated Emails <span style={{ color: "#b81d14" }}>*</span>
          </div>
          <div style={{
            border: "1px solid #d4d4d8", borderRadius: 8, background: "#fff",
            minHeight: 52, padding: 8, display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center"
          }}>
            {chips.map((em) =>
            <span key={em} style={{
              display: "inline-flex", alignItems: "center", gap: 8,
              background: "#f1f1f3", borderRadius: 999,
              padding: "8px 8px 8px 16px", fontSize: 13, color: "#0e0e10"
            }}>
                {em}
                <button onClick={() => removeChip(em)} aria-label={`Remove ${em}`} style={{
                width: 16, height: 16, borderRadius: "50%",
                background: "#9a9aa1", color: "#fff", border: 0,
                display: "inline-flex", alignItems: "center", justifyContent: "center",
                cursor: "pointer", padding: 0
              }}>
                  <IconX size={10} style={{ strokeWidth: 3 }} />
                </button>
              </span>
            )}
            {overflow > 0 &&
            <span style={{
              display: "inline-flex", alignItems: "center",
              background: "#ececf0", borderRadius: 999,
              padding: "8px 16px", fontSize: 13, fontWeight: 600, color: "#6b6b72"
            }}>
                {overflow}+
              </span>
            }
            <input
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={onDraftKey}
              onBlur={addDraft}
              placeholder={chips.length ? "" : "Add email and press Enter"}
              style={{
                flex: 1, minWidth: 140, border: 0, outline: 0, background: "transparent",
                padding: "8px 4px", fontSize: 13, color: "#0e0e10", fontFamily: "inherit"
              }} />
          </div>
        </div>

        {/* Subject */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>Subject</div>
          <input
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            style={{
              width: "100%", boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 8,
              padding: "12px 16px", fontSize: 14, color: "#0e0e10", outline: "none",
              fontFamily: "inherit", background: "#fff"
            }} />
        </div>

        {/* Message */}
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 8 }}>Message</div>
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            rows={9}
            style={{
              width: "100%", boxSizing: "border-box", border: "1px solid #d4d4d8", borderRadius: 8,
              padding: "12px 16px", fontSize: 14, color: "#0e0e10", outline: "none",
              fontFamily: "inherit", background: "#fff", resize: "vertical", lineHeight: 1.55
            }} />
        </div>
      </div>

      {/* Footer action bar: attachment (left) + Send (right) */}
      <div style={{
        padding: "16px 28px 24px", borderTop: "1px solid #ececf0",
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16
      }}>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, color: "#0e0e10", minWidth: 0 }}>
          <IconPaperclip size={16} style={{ strokeWidth: 2, color: "#6b6b72", flexShrink: 0 }} />
          <span style={{ fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {TEMPLATE_FILE_NAME}
          </span>
        </div>
        <button onClick={onSend} disabled={!canSend} style={{
          background: canSend ? "#0e0e10" : "#cfcfd4", color: "#fff", border: 0,
          borderRadius: 6, padding: "12px 36px", fontSize: 15, fontWeight: 700,
          cursor: canSend ? "pointer" : "not-allowed", fontFamily: "inherit", flexShrink: 0
        }}>
          Send
        </button>
      </div>
    </Modal>);
}

// ─────────── Upload Roster modal ───────────
function UploadRosterModal({ open, onClose, onImport, store }) {
  const [phase, setPhase] = React.useState("idle"); // "idle" | "uploading" | "done"
  const [fileName, setFileName] = React.useState("");
  const [progress, setProgress] = React.useState(0);
  const [parsed, setParsed] = React.useState([]);
  const [dragOver, setDragOver] = React.useState(false);
  const inputRef = React.useRef(null);
  const timerRef = React.useRef(null);

  React.useEffect(() => {
    if (!open) {
      clearInterval(timerRef.current);
      setPhase("idle"); setFileName(""); setProgress(0); setParsed([]); setDragOver(false);
    }
  }, [open]);

  const report = React.useMemo(() => validateRosterRows(parsed), [parsed]);

  const TEMPLATE_CSV =
    "First Name,Last Name,Jersey Number,Name on Jersey,Email,Phone Number\n" +
    "Jalen,Hurts,1,Hurtski,jalen@example.com,202-111-5555\n";
  const templateHref = "data:text/csv;charset=utf-8," + encodeURIComponent(TEMPLATE_CSV);

  function handleFile(file) {
    if (!file) return;
    clearInterval(timerRef.current);
    setFileName(file.name);
    setPhase("uploading");
    setProgress(0);
    let prog = 0;
    timerRef.current = setInterval(() => {
      prog += 10 + Math.random() * 20;
      if (prog >= 100) {
        prog = 100;
        clearInterval(timerRef.current);
        const reader = new FileReader();
        reader.onload = () => {
          const rows = parseRosterCSV(String(reader.result || ""));
          setParsed(rows);
          setTimeout(() => setPhase("done"), 220);
        };
        reader.readAsText(file);
      }
      setProgress(Math.min(prog, 100));
    }, 110);
  }

  function clearFile() {
    clearInterval(timerRef.current);
    setPhase("idle"); setFileName(""); setProgress(0); setParsed([]);
  }

  const PREVIEW_COLS = [
    { key: "first", label: "First" },
    { key: "last", label: "Last" },
    { key: "number", label: "#" },
    { key: "nameOnJersey", label: "Name on Jersey" },
    { key: "email", label: "Email" },
  ];

  // Shared file chip used in uploading + done phases
  const FileChip = () => (
    <div style={{ display: "flex", alignItems: "center", gap: 12, background: "#f3f3f4", borderRadius: 8, padding: "12px 16px" }}>
      <div style={{
        width: 36, height: 36, borderRadius: 7, background: "#e8e8eb",
        display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0
      }}>
        <svg width="15" height="15" viewBox="0 0 15 15" fill="none">
          <path d="M2.5 1.5h7l3 3v9h-10v-12z" stroke="#0e0e10" strokeWidth="1.3" fill="none" strokeLinejoin="round"/>
          <path d="M9.5 1.5v3h3" stroke="#0e0e10" strokeWidth="1.3" strokeLinejoin="round"/>
        </svg>
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{fileName}</div>
        {phase === "done" && (
          <div style={{ fontSize: 11.5, color: "#6b6b72", marginTop: 1 }}>
            {parsed.length} row{parsed.length === 1 ? "" : "s"} · {report.valid.length} valid
            {report.errors.length > 0 && ` · ${report.errors.length} skipped`}
          </div>
        )}
      </div>
      <button onClick={clearFile} style={{ background: "transparent", border: 0, padding: 4, cursor: "pointer", color: "#9a9aa1", display: "inline-flex", borderRadius: 4, flexShrink: 0 }}>
        <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><path d="M10.5 3.5L3.5 10.5M3.5 3.5l7 7" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
      </button>
    </div>
  );

  return (
    <Modal open={open} onClose={onClose} width={560}>
      {/* ── Header ── */}
      <div style={{ padding: "24px 28px 16px", borderBottom: "1px solid #ececf0" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>Upload Roster</h2>
          <button onClick={onClose} style={{ background: "transparent", border: 0, padding: 4, cursor: "pointer", color: "#6b6b72", borderRadius: 4, display: "inline-flex" }}>
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M12 4L4 12M4 4l8 8" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>
          </button>
        </div>
      </div>

      {/* ── Body ── */}
      <div style={{ padding: "24px 28px" }}>

        {/* ── idle: drop zone ── */}
        {phase === "idle" && (
          <>
            <div
              onClick={() => inputRef.current?.click()}
              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={(e) => { e.preventDefault(); setDragOver(false); handleFile(e.dataTransfer.files?.[0]); }}
              style={{
                border: `1.5px dashed ${dragOver ? "#0e0e10" : "#d4d4d8"}`,
                borderRadius: 10, padding: "36px 20px",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 12,
                cursor: "pointer", background: dragOver ? "#f7f7f8" : "#fafafb",
                textAlign: "center", transition: "all .12s"
              }}>
              <div style={{
                width: 48, height: 48, borderRadius: "50%",
                background: "#fff", border: "1px solid #ececf0",
                display: "inline-flex", alignItems: "center", justifyContent: "center", color: "#0e0e10"
              }}>
                <IconUpload size={20} style={{ strokeWidth: 2 }} />
              </div>
              <div>
                <div style={{ fontSize: 14, fontWeight: 600, color: "#0e0e10" }}>Drop CSV here or click to browse</div>
                <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 4 }}>CSV files only</div>
              </div>
              <input ref={inputRef} type="file" accept=".csv,text/csv" style={{ display: "none" }}
                onChange={(e) => handleFile(e.target.files?.[0])} />
            </div>
            <div style={{ marginTop: 16 }}>
              <a href={templateHref} download="roster-template.csv"
                style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12.5, color: "#0e0e10", textDecoration: "none", fontWeight: 600 }}
                onMouseEnter={(e) => e.currentTarget.style.color = "#e1251b"}
                onMouseLeave={(e) => e.currentTarget.style.color = "#0e0e10"}>
                <IconDownload size={14} style={{ strokeWidth: 2 }} />
                <span style={{ textDecoration: "underline", textUnderlineOffset: 2 }}>Download CSV template</span>
              </a>
            </div>
          </>
        )}

        {/* ── uploading: progress ── */}
        {phase === "uploading" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <FileChip />
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <span style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Uploading…</span>
                <span style={{ fontSize: 12, color: "#6b6b72" }}>{Math.round(progress)}%</span>
              </div>
              <div style={{ height: 8, background: "#ececf0", borderRadius: 99, overflow: "hidden" }}>
                <div style={{ height: "100%", width: `${progress}%`, background: "#0e0e10", borderRadius: 99, transition: "width .1s linear" }}></div>
              </div>
            </div>
          </div>
        )}

        {/* ── done: preview table + errors ── */}
        {phase === "done" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <FileChip />
            {report.valid.length > 0 && (
              <div style={{ border: "1px solid #ececf0", borderRadius: 8, overflow: "hidden" }}>
                <div style={{ overflowX: "auto", maxHeight: 232 }}>
                  <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                    <thead>
                      <tr style={{ background: "#f7f7f8", borderBottom: "1px solid #ececf0" }}>
                        {PREVIEW_COLS.map(c => (
                          <th key={c.key} style={{ padding: "8px 12px", textAlign: "left", fontWeight: 600, color: "#6b6b72", whiteSpace: "nowrap", fontSize: 11 }}>{c.label}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {report.valid.slice(0, 8).map((row, i) => (
                        <tr key={i} style={{ borderBottom: i < Math.min(report.valid.length, 8) - 1 ? "1px solid #f3f3f4" : "none" }}>
                          {PREVIEW_COLS.map(c => (
                            <td key={c.key} style={{ padding: "8px 12px", color: "#0e0e10", maxWidth: 120, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                              {row[c.key] || <span style={{ color: "#c4c4ca" }}>—</span>}
                            </td>
                          ))}
                        </tr>
                      ))}
                      {report.valid.length > 8 && (
                        <tr><td colSpan={PREVIEW_COLS.length} style={{ padding: "8px 12px", color: "#9a9aa1", fontSize: 11, fontStyle: "italic" }}>+{report.valid.length - 8} more players</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
            {report.errors.length > 0 && (
              <div style={{ border: "1px solid #f3c9c5", borderRadius: 8, background: "#fdf2f1", overflow: "hidden" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 16px", borderBottom: "1px solid #f3c9c5", fontSize: 12.5, fontWeight: 700, color: "#b81d14" }}>
                  <IconAlert size={14} style={{ strokeWidth: 2.2 }} />
                  {report.errors.length} row{report.errors.length === 1 ? "" : "s"} skipped — fix and re-upload
                </div>
                <div style={{ maxHeight: 100, overflowY: "auto", padding: "8px 16px" }}>
                  {report.errors.map((e, i) => (
                    <div key={i} style={{ fontSize: 12, color: "#7a1610", padding: "4px 0", fontFamily: "'JetBrains Mono', monospace" }}>{e.msg}</div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ── Footer ── */}
      <div style={{ padding: "16px 28px", borderTop: "1px solid #ececf0", display: "flex", justifyContent: "flex-end", gap: 12 }}>
        <Button variant="secondary" size="sm" onClick={onClose}>Cancel</Button>
        {phase === "uploading" && (
          <Button variant="primary" size="sm" disabled>Uploading…</Button>
        )}
        {phase === "done" && (
          <Button variant="primary" size="sm" disabled={report.valid.length === 0}
            onClick={() => onImport(report.valid)}>
            Import {report.valid.length > 0 ? `${report.valid.length} player${report.valid.length === 1 ? "" : "s"}` : ""}
          </Button>
        )}
      </div>
    </Modal>
  );
}

function parseRosterCSV(text) {
  const lines = text.split(/\r?\n/);
  const rows = [];
  // Detect a header on the first non-empty line.
  let started = false, headerSkipped = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    if (!started) {
      started = true;
      if (/first|name/i.test(line)) { headerSkipped = true; continue; }
    }
    const cells = line.split(",").map((c) => c.trim());
    if (!cells[0] && !cells[1]) continue;
    rows.push({
      _row: i + 1, // 1-based line number in the uploaded file
      first: cells[0] || "",
      last: cells[1] || "",
      number: cells[2] || "",
      nameOnJersey: cells[3] || "",
      email: cells[4] || "",
      phone: cells[5] || ""
    });
  }
  return rows;
}

// Validate parsed CSV rows. Returns { valid, errors:[{row,msg}] }.
// Required: First + Last name. Optional but, if present, well-formed: email,
// phone (10-digit), jersey number (0–99, unique across the import).
function validateRosterRows(rows) {
  const errors = [];
  const valid = [];
  const seenNum = {};
  rows.forEach((r) => {
    const where = `Row ${r._row}`;
    let ok = true;
    if (!r.first || !r.last) { errors.push({ row: r._row, msg: `${where}: Missing player name` }); ok = false; }
    if (r.email && !isValidEmail(r.email)) { errors.push({ row: r._row, msg: `${where}: Invalid email format` }); ok = false; }
    if (r.phone && !isValidPhone(r.phone)) { errors.push({ row: r._row, msg: `${where}: Invalid phone number` }); ok = false; }
    const num = String(r.number || "").trim();
    if (num) {
      if (!/^\d{1,2}$/.test(num)) { errors.push({ row: r._row, msg: `${where}: Jersey number must be 0–99` }); ok = false; }
      else if (seenNum[num] != null) { errors.push({ row: r._row, msg: `${where}: Duplicate jersey number ${num} (also Row ${seenNum[num]})` }); ok = false; }
      else seenNum[num] = r._row;
    }
    if (ok) valid.push(r);
  });
  return { valid, errors };
}

