// ─────────── Bundle pricing model ───────────
// Mirrors the individual-item model one level up: members’ base cost + dealer
// profit + team profit (+ fundraising when the store allows it) is what the
// shopper pays. Precedence follows the item model, which has exactly one profit
// set per priced thing: the bundle’s own profit REPLACES the summed per-member
// profit on the bundle line. Per-member profit still governs an item sold alone.
// One profit set for the whole bundle — base cost is what varies by size, the
// profit doesn’t, so the item model’s per-size rows collapse to a single set.
function defaultBundleProfit() {
  return { dealerUnit: "$", dealer: "10.00", teamUnit: "$", team: "5.00", fundUnit: "$", fund: "0.00" };
}
function bnum(v) { const n = parseFloat(v); return isNaN(n) ? 0 : n; }
function bmoney(v) { return "$" + v.toFixed(2); }
function brange(s) { return s.lo === s.hi ? bmoney(s.lo) : bmoney(s.lo) + " – " + bmoney(s.hi); }

// One size’s derived numbers. All-Items → a single combined price;
// Choice → one price per option (the shopper buys exactly one member).
function bundleSizeMath(items, pricings, profit, size, bundleType, fundOn) {
  const bases = items.map((it) => bnum(((pricings || {})[it.id] || it.pricing || defaultPricing())[size]?.base));
  if (bases.length === 0) return null;
  const combos = bundleType === "choice" ? bases : [bases.reduce((a, b) => a + b, 0)];
  const p = profit || defaultBundleProfit();
  const amt = (unit, val, base) => unit === "%" ? base * bnum(val) / 100 : bnum(val);
  const rows = combos.map((base) => {
    const dealer = amt(p.dealerUnit, p.dealer, base);
    const team = amt(p.teamUnit, p.team, base);
    const fund = fundOn ? amt(p.fundUnit, p.fund, base) : 0;
    return { base, dealer, team, fund, customer: base + dealer + team + fund };
  });
  const span = (k) => ({ lo: Math.min.apply(null, rows.map((r) => r[k])), hi: Math.max.apply(null, rows.map((r) => r[k])) });
  return { rows, base: span("base"), dealer: span("dealer"), team: span("team"), fund: span("fund"), customer: span("customer") };
}
// Card snapshot — the catalog card’s "from $X" reads the low end of this.
function bundleCardPricing(items, pricings, profit, bundleType, supplied, fundOn) {
  const one = (size) => {
    if (supplied) return "0.00";
    const m = bundleSizeMath(items, pricings, profit, size, bundleType, fundOn);
    if (!m) return "—";
    return m.customer.lo === m.customer.hi ?
    m.customer.lo.toFixed(2) :
    m.customer.lo.toFixed(2) + " - " + m.customer.hi.toFixed(2);
  };
  return { youth: { retail: one("youth") }, adult: { retail: one("adult") } };
}

function BundleLockChip() {
  return (
    <span style={{
      fontSize: 10, fontWeight: 800, letterSpacing: ".06em", background: "#ececf0",
      color: "#52525b", borderRadius: 4, padding: "3px 8px", flexShrink: 0
    }}>LOCKED</span>);

}

// ─────────── BundlePriceSettings ─────────── (per-bundle profit, mirrors items)
function BundlePriceSettings({ items, pricings, profit, onChange, bundleType, supplied, fundOn, locked }) {
  const choice = bundleType === "choice";
  const p = profit || defaultBundleProfit();
  const math = {
    youth: bundleSizeMath(items, pricings, profit, "youth", bundleType, fundOn),
    adult: bundleSizeMath(items, pricings, profit, "adult", bundleType, fundOn)
  };
  const fields = [
  { label: "DEALER PROFIT", unit: p.dealerUnit, value: p.dealer, u: "dealerUnit", v: "dealer" },
  { label: "TEAM PROFIT", unit: p.teamUnit, value: p.team, u: "teamUnit", v: "team" }].
  concat(fundOn ? [{ label: "FUNDRAISING", unit: p.fundUnit || "$", value: p.fund ?? "0.00", u: "fundUnit", v: "fund" }] : []);
  const readoutCols = "70px minmax(130px,240px) minmax(130px,240px)";
  return (
    <div style={{ border: "1px solid #ececf0", borderRadius: 8, padding: 24, marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
        <span style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10" }}>Bundle Price Settings</span>
        {locked && <BundleLockChip />}
      </div>
      <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.5, marginBottom: 16 }}>
        {supplied ?
        "Team Supplied — the team has already covered this bundle, so shoppers pay $0 and these inputs don’t apply." :
        "Members’ base cost + dealer profit + team profit, derived exactly the way it is on an individual item. The bundle’s profit replaces the summed per-member profit on the bundle line; per-member profit still applies when an item is sold on its own."}
      </div>

      {supplied ? null : items.length === 0 ?
      <div style={{ padding: "24px 16px", textAlign: "center", color: "#9a9aa1", fontSize: 12.5, border: "1px dashed #e5e5e9", borderRadius: 8 }}>
          Add products to set bundle pricing.
        </div> :

      <React.Fragment>
          <div style={locked ? { pointerEvents: "none", opacity: 0.5 } : undefined}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 220px))", gap: 16 }}>
              {fields.map((f) =>
            <div key={f.label}>
                  <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".10em", color: "#9a9aa1", marginBottom: 8 }}>{f.label}</div>
                  <ProfitInput
                unit={f.unit}
                value={f.value}
                onUnit={(u) => onChange(f.u, u)}
                onValue={(v) => onChange(f.v, v)} />
                </div>
            )}
            </div>
            <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 10 }}>
              One profit for the bundle — base cost is what varies by size.
            </div>
          </div>

          {choice &&
        <div style={{ fontSize: 12.5, color: "#6b6b72", background: "#fafafb", border: "1px solid #f1f1f3", borderRadius: 6, padding: "10px 12px", marginTop: 16, lineHeight: 1.45 }}>
              Choice Bundle — the shopper buys one option, so the same profit produces a different customer price per option.
            </div>
        }

          <div style={{ marginTop: 20, paddingTop: 16, borderTop: "1px solid #ececf0" }}>
            <div style={{ display: "grid", gridTemplateColumns: readoutCols, gap: 12, fontSize: 11, fontWeight: 700, letterSpacing: ".10em", color: "#9a9aa1", marginBottom: 10 }}>
              <div>SIZE</div>
              <div>MEMBERS’ BASE COST</div>
              <div>BUNDLE RETAIL</div>
            </div>
            {["youth", "adult"].map((size, i) =>
          <div key={size} style={{ display: "grid", gridTemplateColumns: readoutCols, gap: 12, alignItems: "center", padding: "8px 0", borderTop: i > 0 ? "1px solid #f1f1f3" : 0 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#0e0e10" }}>{size.toUpperCase()}</div>
                <div style={{ fontSize: 13, color: "#6b6b72" }}>{brange(math[size].base)}</div>
                <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10" }}>{brange(math[size].customer)}</div>
              </div>
          )}
            <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 8, fontStyle: "italic" }}>
              Bundle retail is what customers see.
            </div>
          </div>
        </React.Fragment>
      }
    </div>);

}

// ─────────── BundleOptions ─────────── (storefront + shipping flags)
// Visibility reuses the one storefront Visible/Hidden control every catalog
// product carries (product.hidden) — surfaced here so a rep never has to leave
// the panel. Display flags stay editable in every lock state; free shipping
// changes order economics, so it locks with the commercial fields.
function BundleOptions({ hidden, onHidden, hideRetail, onHideRetail, freeShipping, onFreeShipping, locked }) {
  const rowStyle = (i) => ({
    display: "flex", alignItems: "center", gap: 20, padding: "14px 0",
    borderTop: i > 0 ? "1px solid #f1f1f3" : 0
  });
  return (
    <div style={{
      border: "1px solid " + (locked ? "#0e0e10" : "#ececf0"), borderRadius: 8,
      padding: 24, marginBottom: 16, position: "relative"
    }}>
      {locked &&
      <span style={{
        position: "absolute", top: -9, left: 16, background: "#0e0e10", color: "#fff",
        fontSize: 10, fontWeight: 800, letterSpacing: ".06em", borderRadius: 4, padding: "2px 8px"
      }}>STILL EDITABLE</span>
      }
      <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10", marginBottom: 4 }}>Bundle Options</div>
      <div style={{ fontSize: 12.5, color: "#6b6b72", marginBottom: 4 }}>
        How this bundle shows up on the storefront, and how it ships.
      </div>

      <div style={rowStyle(0)}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>Storefront visibility</div>
          <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.45, marginTop: 2 }}>
            {hidden ?
            "Hidden — shoppers won’t see this bundle in the catalog." :
            "Visible — shoppers see this bundle in the catalog while the store is live."}
          </div>
        </div>
        <button
          onClick={() => onHidden(!hidden)}
          title={hidden ? "Hidden from the storefront — click to show" : "Visible on the storefront — click to hide"}
          style={{
            display: "inline-flex", alignItems: "center", gap: 9, background: "none",
            border: 0, padding: 0, cursor: "pointer", fontFamily: "inherit", flexShrink: 0
          }}>
          <span style={{
            width: 34, height: 19, borderRadius: 999, position: "relative", flexShrink: 0,
            background: hidden ? "#d4d4d8" : "#1f8a55", transition: "background .14s"
          }}>
            <span style={{
              position: "absolute", top: 2, left: hidden ? 2 : 17, width: 15, height: 15,
              borderRadius: 999, background: "#fff", transition: "left .14s"
            }} />
          </span>
          <span style={{ fontSize: 11.5, fontWeight: 700, width: 44, textAlign: "left", color: hidden ? "#71717a" : "#1f8a55" }}>
            {hidden ? "Hidden" : "Visible"}
          </span>
        </button>
      </div>

      <div style={rowStyle(1)}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>Hide retail price</div>
          <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.45, marginTop: 2 }}>
            The catalog card and product page won’t show a price. Shoppers still pay the configured price at checkout — this hides the number, it doesn’t zero it.
          </div>
        </div>
        <BundleToggle on={hideRetail} onChange={onHideRetail} />
      </div>

      <div style={rowStyle(2)}>
        <div style={{ flex: 1, minWidth: 0, ...(locked ? { opacity: 0.5 } : {}) }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10", display: "flex", alignItems: "center", gap: 8 }}>
            Free shipping for the bundle{locked && <BundleLockChip />}
          </div>
          <div style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.45, marginTop: 2 }}>
            Waives shipping on the whole bundle order line at checkout — not on the rest of the cart.
          </div>
        </div>
        <span style={locked ? { pointerEvents: "none", opacity: 0.5, display: "inline-flex" } : { display: "inline-flex" }}>
          <BundleToggle on={freeShipping} onChange={onFreeShipping} />
        </span>
      </div>
    </div>);

}

// ─────────── BundlePricingInsights ─────────── (read-only, recalculates live)
function BundlePricingInsights({ items, pricings, profit, bundleType, supplied, freeShipping, fundOn }) {
  const my = bundleSizeMath(items, pricings, profit, "youth", bundleType, fundOn);
  const ma = bundleSizeMath(items, pricings, profit, "adult", bundleType, fundOn);
  const shell = (children) => (
    <div style={{ background: "#fafafb", border: "1px solid #ececf0", borderRadius: 8, padding: "18px 20px" }}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 14 }}>
        <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".08em", textTransform: "uppercase", color: "#6b6b72" }}>
          Bundle Pricing Information
        </span>
        <span style={{ fontSize: 11.5, color: "#9a9aa1" }}>Updates as members, profit and options change</span>
      </div>
      {children}
    </div>);

  if (!my || !ma) return shell(
    <div style={{ fontSize: 12.5, color: "#9a9aa1" }}>Add products to see the bundle’s pricing breakdown.</div>);

  const choice = bundleType === "choice";
  const anyFund = fundOn && (my.fund.hi > 0 || ma.fund.hi > 0);
  const rows = [
  { label: "Store price", hint: "Members’ base cost", y: brange(my.base), a: brange(ma.base) },
  { label: "Dealer profit", y: brange(my.dealer), a: brange(ma.dealer) },
  { label: "Team profit", y: brange(my.team), a: brange(ma.team) },
  anyFund && { label: "Fundraising", y: brange(my.fund), a: brange(ma.fund) },
  {
    label: "Customer price",
    hint: supplied ? "Paid by the team" : choice ? "Per option" : "One combined price",
    y: supplied ? "Covered" : brange(my.customer),
    a: supplied ? "Covered" : brange(ma.customer),
    strong: true
  },
  freeShipping && { label: "Est. shipping", y: "Free", a: "Free", free: true }].
  filter(Boolean);
  const grid = { display: "grid", gridTemplateColumns: "minmax(150px,1.4fr) 1fr 1fr", gap: 12, alignItems: "baseline" };
  return shell(
    <React.Fragment>
      <div style={{ ...grid, fontSize: 10, fontWeight: 800, letterSpacing: ".08em", color: "#9a9aa1", paddingBottom: 8, borderBottom: "1px solid #ececf0" }}>
        <div></div><div style={{ textAlign: "right" }}>YOUTH</div><div style={{ textAlign: "right" }}>ADULT</div>
      </div>
      {rows.map((r, i) =>
      <div key={r.label} style={{ ...grid, padding: "9px 0", borderTop: i > 0 ? "1px solid #f1f1f3" : 0 }}>
          <div style={{ minWidth: 0 }}>
            <span style={{ fontSize: 12.5, fontWeight: r.strong ? 700 : 500, color: r.strong ? "#0e0e10" : "#6b6b72" }}>{r.label}</span>
            {r.hint && <span style={{ fontSize: 11.5, color: "#9a9aa1", marginLeft: 8 }}>{r.hint}</span>}
          </div>
          {[r.y, r.a].map((v, k) =>
        <div key={k} style={{
          textAlign: "right", fontSize: r.strong ? 13.5 : 12.5,
          fontWeight: r.strong || r.free ? 700 : 500,
          color: r.free || v === "Covered" ? "#1f8a55" : r.strong ? "#0e0e10" : "#3f3f46"
        }}>{v}</div>
        )}
        </div>
      )}
      {choice && !supplied &&
      <div style={{ marginTop: 12, paddingTop: 12, borderTop: "1px solid #ececf0", fontSize: 11.5, color: "#9a9aa1", lineHeight: 1.45 }}>
          Catalog card reads “from {bmoney(Math.min(my.customer.lo, ma.customer.lo))}” — the lowest-priced option.
        </div>
      }
    </React.Fragment>);

}

// ─────────── CreateBundleSection ─────────── (inline card in Products tab)
function CreateBundleSection({ store, draftProducts, onCancel, onCreate }) {
  const [name, setName] = React.useState("");
  const [btype, setBtype] = React.useState(null); // "all" | "choice" — immutable after creation
  const [setting, setSetting] = React.useState(null); // "team-required" | "team-supplied" | null
  const [cat, setCat] = React.useState("");
  const [selectedIds, setSelectedIds] = React.useState([]);
  const [search, setSearch] = React.useState("");
  const [showModal, setShowModal] = React.useState(false);
  const [bundleProfit, setBundleProfit] = React.useState(defaultBundleProfit());
  const [hiddenFlag, setHiddenFlag] = React.useState(false);
  const [hideRetail, setHideRetail] = React.useState(false);
  const [freeShipping, setFreeShipping] = React.useState(false);
  const updateBundleProfit = (field, value) =>
  setBundleProfit((prev) => ({ ...prev, [field]: value }));
  const fundOn = store?.fundraisingEnabled !== false;
  // C3/C5 — steps (Required/Optional, all/pick-one) and Vault items pulled straight into the bundle.
  const [groups, setGroups] = React.useState([{ id: "g-req", name: "Required items", mode: "all", required: true, productIds: [] }]);
  const [pickForGroup, setPickForGroup] = React.useState(null);
  const [vaultAdds, setVaultAdds] = React.useState([]);
  const allPool = React.useMemo(() => { const ids = new Set(draftProducts.map((p) => p.id)); return [...draftProducts, ...vaultAdds.filter((p) => !ids.has(p.id))]; }, [draftProducts, vaultAdds]);

  const selectedSet = new Set(selectedIds);
  const selectedProducts = selectedIds
    .map((id) => allPool.find((p) => p.id === id))
    .filter(Boolean);


  // Available products = drafts NOT already selected, filtered by search.
  const q = search.trim().toLowerCase();
  const availableAll = draftProducts.filter(
    (p) => !q || (p.title || "").toLowerCase().includes(q)
  );
  // First 8 shown in the inline grid (selected products are shown disabled / faded
  // so users get a sense of "what's in vs. what's available" at a glance).
  const QUICK = 8;
  const visibleQuick = availableAll.slice(0, QUICK);

  const addProduct = (id) => {
    if (!selectedSet.has(id)) setSelectedIds((s) => [...s, id]);
  };
  const removeProduct = (id) => {
    setSelectedIds((s) => s.filter((x) => x !== id));
    setGroups((gs) => gs.map((g) => ({ ...g, productIds: g.productIds.filter((x) => x !== id) })));
  };
  // Legacy bundle type is derived from the steps: any pick-one step makes it a choice bundle.
  React.useEffect(() => { if (groups.length) setBtype(groups.some((g) => g.mode === "one") ? "choice" : "all"); }, [groups]);
  const groupsValid = groups.length > 0 && groups.some((g) => g.required) && groups.every((g) => g.productIds.length >= (g.mode === "one" ? 2 : 1));

  const canCreate = name.trim().length > 0 && selectedIds.length >= 1 && groupsValid && (setting != null || cat !== "");

  const handleCreate = () => {
    if (!canCreate) return;
    onCreate({
      name: name.trim(),
      teamSetting: setting,
      bundleType: btype,
      category: setting ? "Team Gear" : cat,
      productIds: selectedIds,
      groups,
      vaultAdds: vaultAdds.filter((p) => selectedIds.includes(p.id)),
      bundleProfit,
      hidden: hiddenFlag,
      hideRetail,
      freeShipping
    });
  };

  const hasSelection = selectedIds.length > 0;

  return (
    <div style={{ paddingBottom: 100 }}>
      <div style={{
        background: "#fff", border: "1px solid #ececf0", borderRadius: 12,
        boxShadow: "0 1px 2px rgba(20,20,30,.03)",
        padding: 28
      }}>
        {/* Header */}
        <div style={{
          display: "flex", alignItems: "flex-start", justifyContent: "space-between",
          gap: 16, marginBottom: 24
        }}>
          <div style={{ display: "flex", alignItems: "flex-start", gap: 16 }}>
            <div style={{
              width: 44, height: 44, borderRadius: 8, background: "#f4f4f6",
              display: "inline-flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0
            }}>
              <BundleStackIcon size={22} />
            </div>
            <div>
              <h2 style={{ fontSize: 18, fontWeight: 700, margin: 0, color: "#0e0e10" }}>
                Create Bundle
              </h2>
              <div style={{ fontSize: 13, color: "#6b6b72", marginTop: 2 }}>
                Add products to create a team bundle
              </div>
            </div>
          </div>

          <div style={{ display: "inline-flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
            <button onClick={onCancel} style={{
              background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6,
              padding: "12px 24px", fontSize: 13, fontWeight: 600, color: "#0e0e10",
              cursor: "pointer"
            }}>Cancel</button>
            <button
              onClick={handleCreate}
              disabled={!canCreate}
              title={!canCreate ? "Name the bundle, set a distinction or category, and give every step its items (pick-one steps need 2+)" : ""}
              style={{
                background: canCreate ? "#0e0e10" : "#ececf0",
                color: canCreate ? "#fff" : "#9a9aa1",
                border: 0, borderRadius: 6, padding: "12px 24px",
                fontSize: 13, fontWeight: 700,
                cursor: canCreate ? "pointer" : "not-allowed",
                transition: "background .15s, color .15s"
              }}>Create Bundle</button>
          </div>
        </div>

        {/* Steps — Required / Optional, all items or pick one (C3) */}
        <div style={{ marginBottom: 24 }}>
          <BundleGroupsEditor groups={groups} onChange={setGroups} products={selectedProducts} store={store} onPickProducts={(gid) => setPickForGroup(gid)} />
          <div style={{ fontSize: 12, color: "#9a9aa1", marginTop: 8 }}>{btype === "choice" ? "Has a pick-one step — shoppers see it as a choice bundle." : "Every step includes all its items — one combined price."}</div>
        </div>

        {/* Bundle Name + Product Settings + Category — aligned field set */}
        <div style={{ marginBottom: 24, display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: "24px 32px", alignItems: "start" }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Bundle Name</label>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Name this bundle"
              style={{
                height: 40, boxSizing: "border-box",
                border: "1px solid #d4d4d8", borderRadius: 6,
                padding: "0 14px", fontSize: 13.5, color: "#0e0e10", outline: 0,
                background: "#fff", fontFamily: "inherit"
              }} />
            <span style={{ fontSize: 12, color: "#9a9aa1", lineHeight: 1.45 }}>Shown to shoppers wherever the bundle appears.</span>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Product Settings</label>
            <div style={{ display: "inline-flex", alignItems: "center", gap: 3, height: 40, boxSizing: "border-box", padding: 3, background: "#f4f4f6", border: "1px solid #ececf0", borderRadius: 8, width: "fit-content" }}>
              {[
              { id: null, label: "None" },
              { id: "team-required", label: "Team Required" },
              { id: "team-supplied", label: "Team Supplied" }].
              map((opt) => {
                const on = setting === opt.id;
                return (
                  <button key={opt.label} type="button" onClick={() => setSetting(opt.id)} style={{
                    height: 32, padding: "0 12px", borderRadius: 6, border: 0, cursor: "pointer",
                    fontSize: 12.5, fontWeight: 600, fontFamily: "inherit", whiteSpace: "nowrap",
                    background: on ? "#fff" : "transparent",
                    color: on ? "#0e0e10" : "#6b6b72",
                    boxShadow: on ? "0 1px 2px rgba(20,20,30,.12)" : "none",
                    transition: "background .14s cubic-bezier(0.2,0,0,1), color .14s cubic-bezier(0.2,0,0,1)"
                  }}>{opt.label}</button>);
              })}
            </div>
            <span style={{ fontSize: 12, color: "#9a9aa1", lineHeight: 1.45 }}>How the team buys this bundle — separate from its store category.</span>
          </div>

          {setting == null ?
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Category <span style={{ color: "#e1251b" }}>*</span></label>
            <select value={cat} onChange={(e) => setCat(e.target.value)} style={{ height: 40, boxSizing: "border-box", border: "1px solid " + (cat ? "#d4d4d8" : "#e1251b"), borderRadius: 6, padding: "0 10px", fontSize: 13.5, fontFamily: "inherit", outline: "none", background: "#fff", color: "#0e0e10", width: "100%" }}>
              <option value="">Select a category</option>
              {(window.__prodCats || []).map((c) => <option key={c.id} value={c.name}>{c.name}</option>)}
            </select>
            <span style={{ fontSize: 12, color: "#9a9aa1", lineHeight: 1.45 }}>Required when no product setting is applied.</span>
          </div> :
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <label style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Category</label>
            <div style={{ display: "inline-flex", alignItems: "center", gap: 8, height: 40, boxSizing: "border-box", padding: "0 12px", border: "1px dashed #d4d4d8", borderRadius: 6, background: "#fafafb", width: "fit-content" }}>
              <span style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>Team Gear</span>
              <span style={{ fontSize: 11.5, color: "#9a9aa1" }}>set by product settings</span>
            </div>
            <span style={{ fontSize: 12, color: "#9a9aa1", lineHeight: 1.45 }}>Turn off the product setting to choose your own category.</span>
          </div>}
        </div>

        {/* MOQ warning — choice bundles splitting made-to-order demand */}
        {btype === "choice" && selectedProducts.length > 0 && selectedProducts.some((p) => pteRestricted(p)) && (
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: "#fff8ef", border: "1px solid #f2e2c9", borderRadius: 8, padding: "12px 16px", marginBottom: 24 }}>
            <span style={{ color: "#b06f1e", display: "inline-flex", marginTop: 1 }}><IconAlert size={15} /></span>
            <span style={{ fontSize: 12.5, color: "#6b6b72", lineHeight: 1.5 }}>Splitting a required purchase across options may prevent individual options from reaching minimum order quantity.</span>
          </div>
        )}

        {/* Selected products row (only when items selected) */}
        {hasSelection &&
        <div style={{ marginBottom: 24 }}>
            <div style={{
            display: "flex", alignItems: "baseline", gap: 12, marginBottom: 12
          }}>
              <span style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10" }}>
                Selected Products
              </span>
              <span style={{ fontSize: 13, color: "#6b6b72" }}>
                ({selectedIds.length})
              </span>
            </div>
            <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
            gap: 12
          }}>
              {selectedProducts.map((p) =>
            <SelectedChip
              key={p.id}
              product={p}
              store={store}
              onRemove={() => removeProduct(p.id)} />
            )}
            </div>
          </div>
        }

        {/* Add Products */}
        <div style={{ fontSize: 13, fontWeight: 600, color: "#0e0e10", marginBottom: 12 }}>
          Add Products
        </div>
        <div style={{ position: "relative", marginBottom: 16 }}>
          <span style={{
            position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)",
            color: "#9a9aa1", display: "inline-flex"
          }}>
            <IconSearch size={16} />
          </span>
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Find products"
            style={{
              width: "100%", border: "1px solid #d4d4d8", borderRadius: 6,
              padding: "12px 16px 12px 40px", fontSize: 13, color: "#0e0e10", outline: 0
            }} />
        </div>

        {visibleQuick.length === 0 ?
        <div style={{
          padding: "32px 16px", textAlign: "center", color: "#6b6b72", fontSize: 13,
          border: "1px dashed #e5e5e9", borderRadius: 8
        }}>
            {draftProducts.length === 0 ?
          "Add draft products to your store before bundling." :
          "No products match your search."}
          </div> :

        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
          gap: 12
        }}>
            {visibleQuick.map((p) =>
          <PickerCard
            key={p.id}
            product={p}
            store={store}
            selected={selectedSet.has(p.id)}
            disabled={selectedSet.has(p.id)}
            onAdd={() => addProduct(p.id)} />
          )}
          </div>
        }

        <button onClick={() => setPickForGroup(groups[0] ? groups[0].id : "__none")} style={{ background: "#fff", border: "1px solid #d4d4d8", borderRadius: 6, padding: "10px 14px", fontSize: 12.5, fontWeight: 700, color: "#0e0e10", cursor: "pointer", fontFamily: "inherit", marginTop: 16, marginRight: 14 }}>Browse the Product Vault</button>
        {availableAll.length > 0 &&
        <button
          onClick={() => setShowModal(true)}
          style={{
            background: "transparent", border: 0, color: "#2563eb",
            fontSize: 13, fontWeight: 600, cursor: "pointer", padding: 0,
            marginTop: 16, display: "inline-flex", alignItems: "center", gap: 4
          }}>
            See All Products <IconChevronRight size={14} />
          </button>
        }

        <div style={{ marginTop: 28, paddingTop: 24, borderTop: "1px solid #ececf0" }}>
          <BundlePriceSettings
            items={selectedProducts}
            pricings={null}
            profit={bundleProfit}
            onChange={updateBundleProfit}
            bundleType={btype || "all"}
            supplied={setting === "team-supplied"}
            fundOn={fundOn}
            locked={false} />
          <BundleOptions
            hidden={hiddenFlag}
            onHidden={setHiddenFlag}
            hideRetail={hideRetail}
            onHideRetail={setHideRetail}
            freeShipping={freeShipping}
            onFreeShipping={setFreeShipping}
            locked={false} />
          <BundlePricingInsights
            items={selectedProducts}
            pricings={null}
            profit={bundleProfit}
            bundleType={btype || "all"}
            supplied={setting === "team-supplied"}
            freeShipping={freeShipping}
            fundOn={fundOn} />
          {selectedProducts.length > 0 && setting !== "team-supplied" && <BundleCommissionSplit items={selectedProducts} store={store} bundlePrice={parseFloat((bundleProfit || {}).bundlePrice) || null} />}
        </div>
      </div>

      <SelectProductsModal
        open={showModal}
        store={store}
        products={allPool}
        initialSelectedIds={selectedIds}
        onClose={() => setShowModal(false)}
        onConfirm={(ids) => {setSelectedIds(ids);setShowModal(false);}} />
      <BundleVaultPickerModal
        open={!!pickForGroup}
        store={store}
        storeProducts={allPool}
        initialIds={(groups.find((g) => g.id === pickForGroup) || {}).productIds || []}
        onClose={() => setPickForGroup(null)}
        onConfirm={(ids, rows) => {
          const fresh = rows.filter((r) => r.fromVault && !allPool.some((p) => p.id === r.id));
          if (fresh.length) setVaultAdds((v) => [...v, ...fresh]);
          setSelectedIds((s) => Array.from(new Set([...s, ...ids])));
          if (pickForGroup && pickForGroup !== "__none") setGroups((gs) => gs.map((g) => g.id === pickForGroup ? { ...g, productIds: ids } : g));
          setPickForGroup(null);
        }} />
      
    </div>);

}

// ─────────── SelectProductsModal ─────────── (full product picker)
function SelectProductsModal({ open, store, products, initialSelectedIds, onClose, onConfirm }) {
  const [localIds, setLocalIds] = React.useState(initialSelectedIds || []);
  const [filter, setFilter] = React.useState("all");
  const [search, setSearch] = React.useState("");

  // Sync incoming selection whenever the modal is (re)opened.
  React.useEffect(() => {
    if (open) {
      setLocalIds(initialSelectedIds || []);
      setSearch("");
      setFilter("all");
    }
  }, [open]);

  const toggle = (id) => {
    setLocalIds((s) => s.includes(id) ? s.filter((x) => x !== id) : [...s, id]);
  };

  const q = search.trim().toLowerCase();
  const filtered = products.filter((p) => {
    if (q && !(p.title || "").toLowerCase().includes(q)) return false;
    if (filter === "team-required" && p.teamSetting !== "team-required") return false;
    if (filter === "team-supplied" && p.teamSetting !== "team-supplied") return false;
    return true;
  });

  const filterChips = [
  { id: "all", label: "All" },
  { id: "team-required", label: "Team Required" },
  { id: "team-supplied", label: "Team Supplied" }];


  return (
    <Modal open={open} onClose={onClose} width={780}>
      <div style={{ padding: "24px 24px 0" }}>
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          marginBottom: 16
        }}>
          <h3 style={{ fontSize: 18, fontWeight: 700, margin: 0 }}>Select Products</h3>
          <button onClick={onClose} style={{
            background: "transparent", border: 0, cursor: "pointer", padding: 4, color: "#6b6b72"
          }}>
            <IconX size={20} />
          </button>
        </div>

        {/* Search */}
        <div style={{ position: "relative", marginBottom: 16 }}>
          <span style={{
            position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)",
            color: "#9a9aa1", display: "inline-flex"
          }}>
            <IconSearch size={16} />
          </span>
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Find products"
            style={{
              width: "100%", border: "1px solid #d4d4d8", borderRadius: 6,
              padding: "12px 16px 12px 40px", fontSize: 13, color: "#0e0e10", outline: 0
            }} />
        </div>

        {/* Filter chips */}
        <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
          {filterChips.map((c) => {
            const active = filter === c.id;
            return (
              <button key={c.id} onClick={() => setFilter(c.id)} style={{
                background: active ? "#0e0e10" : "#fff",
                color: active ? "#fff" : "#0e0e10",
                border: `1px solid ${active ? "#0e0e10" : "#d4d4d8"}`,
                padding: "8px 16px", borderRadius: 999,
                fontSize: 12, fontWeight: 600, cursor: "pointer", transition: "all .12s"
              }}>
                {c.label}
              </button>);

          })}
        </div>
      </div>

      {/* List */}
      <div style={{
        maxHeight: "55vh", overflowY: "auto", padding: "0 24px",
        display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12
      }}>
        {filtered.length === 0 ?
        <div style={{
          gridColumn: "1 / -1",
          padding: "48px 12px", textAlign: "center", color: "#6b6b72", fontSize: 13
        }}>
            No products match.
          </div> :

        filtered.map((p) => {
          const checked = localIds.includes(p.id);
          return (
            <div
              key={p.id}
              onClick={() => toggle(p.id)}
              style={{
                display: "flex", alignItems: "center", gap: 12,
                padding: "12px 12px",
                border: "1px solid #ececf0", borderRadius: 8,
                background: checked ? "#f6fbf8" : "#fff",
                borderColor: checked ? "#bfe5d0" : "#ececf0",
                cursor: "pointer", transition: "border-color .12s, background .12s"
              }}>
                <ProductMiniThumb product={p} store={store} size={44} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{
                  fontSize: 12, fontWeight: 700, color: "#0e0e10",
                  letterSpacing: ".04em", textTransform: "uppercase",
                  whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis"
                }}>{p.title || "Untitled"}</div>
                  <div style={{ marginTop: 2 }}>
                    <SettingPill teamSetting={p.teamSetting} small />
                  </div>
                </div>
                <span style={{
                width: 24, height: 24, borderRadius: "50%",
                border: `1.5px solid ${checked ? "#1f9d55" : "#d4d4d8"}`,
                background: checked ? "#1f9d55" : "#fff",
                display: "inline-flex", alignItems: "center", justifyContent: "center",
                flexShrink: 0, transition: "all .12s"
              }}>
                  {checked && <IconCheck size={14} style={{ color: "#fff", strokeWidth: 3 }} />}
                </span>
              </div>);

        })
        }
      </div>

      {/* Footer */}
      <div style={{
        borderTop: "1px solid #ececf0", marginTop: 16,
        padding: "16px 24px",
        display: "flex", alignItems: "center", justifyContent: "space-between"
      }}>
        <div style={{ fontSize: 13, color: "#6b6b72" }}>
          {localIds.length} {localIds.length === 1 ? "product" : "products"} selected
        </div>
        <button
          onClick={() => onConfirm(localIds)}
          style={{
            background: "#0e0e10", color: "#fff", border: 0, borderRadius: 6,
            padding: "12px 24px", fontSize: 13, fontWeight: 700, cursor: "pointer"
          }}>
          Add to Bundle
        </button>
      </div>
    </Modal>);

}

// ─────────── BundleThumbCollage ─────────── (2x2 mini grid shown on bundle cards)
function BundleThumbCollage({ items, store, slotSize = 90 }) {
  const slots = items.slice(0, 4);
  while (slots.length < 4) slots.push(null);
  return (
    <div style={{
      display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12,
      width: "100%", maxWidth: slotSize * 2 + 10
    }}>
      {slots.map((it, i) =>
      <div key={i} style={{
        width: "100%", aspectRatio: "1 / 1",
        background: it ? "#fff" : "transparent",
        border: it ? "1px solid #ececf0" : "1px dashed #e5e5e9",
        borderRadius: 6,
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: 8
      }}>
          {it ?
        <div style={{ width: "82%", height: "82%" }}>
              {it.thumbnail || <DefaultProductThumb store={store} product={it} />}
            </div> :

        null}
        </div>
      )}
    </div>);

}

// Helper used by ProductCard to compute price range.
function bundlePriceRange(items, size) {
  const vals = items.
  map((p) => parseFloat(p?.pricing?.[size]?.retail)).
  filter((v) => !isNaN(v));
  if (vals.length === 0) return "—";
  const min = Math.min(...vals);
  const max = Math.max(...vals);
  if (min === max) return `$${min.toFixed(2)}`;
  return `$${min.toFixed(2)} - $${max.toFixed(2)}`;
}

// ─────────── BundleToggle ─────────── (iOS-style switch)
function BundleToggle({ on, onChange }) {
  return (
    <span
      onClick={() => onChange(!on)}
      role="switch"
      aria-checked={on}
      style={{
        width: 44, height: 24, borderRadius: 999,
        background: on ? "#0e0e10" : "#d4d4d8",
        position: "relative", cursor: "pointer",
        transition: "background .15s", flexShrink: 0,
        display: "inline-block"
      }}>
      <span style={{
        position: "absolute", top: 2, left: on ? 22 : 2,
        width: 20, height: 20, borderRadius: "50%", background: "#fff",
        transition: "left .15s",
        boxShadow: "0 1px 3px rgba(0,0,0,.18)"
      }} />
    </span>);

}

