function BigJersey({ colors, label, variant }) {
  const c1 = colors?.[0] || "#1d3a8a";
  const c2 = colors?.[1] || "#0e0e10";
  const c3 = colors?.[2] || "#f5b400";
  return (
    <svg width="220" height="240" viewBox="0 0 220 240">
      <path d="M40 30 L72 14 L148 14 L180 30 L210 60 L188 84 L180 60 L180 220 L40 220 L40 60 L32 84 L10 60 Z"
      fill={c1.toLowerCase() === "#ffffff" ? "#f1f1f3" : c1}
      stroke={c2} strokeWidth="2" strokeLinejoin="round" />
      {/* neckline */}
      <path d="M72 14 Q110 36 148 14 L148 26 Q110 46 72 26 Z" fill={c2} />
      {/* shoulder stripes */}
      <rect x="50" y="36" width="50" height="6" fill={c3} opacity=".95" transform="rotate(-12 75 39)" />
      <rect x="50" y="46" width="50" height="6" fill="#fff" opacity=".85" transform="rotate(-12 75 49)" />
      <rect x="50" y="56" width="50" height="6" fill={c3} opacity=".95" transform="rotate(-12 75 59)" />
      <rect x="120" y="36" width="50" height="6" fill={c3} opacity=".95" transform="rotate(12 145 39)" />
      <rect x="120" y="46" width="50" height="6" fill="#fff" opacity=".85" transform="rotate(12 145 49)" />
      <rect x="120" y="56" width="50" height="6" fill={c3} opacity=".95" transform="rotate(12 145 59)" />
      {/* label */}
      <text x="110" y="140" textAnchor="middle" fontFamily="JetBrains Mono, monospace" fontWeight="800"
      fontSize={label && label.length <= 2 ? 70 : label && label.length < 6 ? 40 : 28}
      fill={c3}
      style={{ filter: "drop-shadow(2px 2px 0 rgba(0,0,0,.4))" }}>{label || ""}</text>
    </svg>);

}

function MetaRow({ label, value }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 16, fontSize: 14 }}>
      <span style={{ color: "#0e0e10", fontWeight: 600 }}>{label}</span>
      <span style={{ color: "#0e0e10", fontVariantNumeric: "tabular-nums" }}>{value || "—"}</span>
    </div>);

}

function ProgressStepper({ order }) {
  const steps = [
  { id: "submit", label: "Submit Date", sub: order.submitDate },
  { id: "confirm", label: "Order Confirmed", sub: order.confirmedDate },
  { id: "artwork", label: "Artwork Production", sub: order.artworkDate },
  { id: "factory", label: "Factory Production", sub: order.factoryDate },
  { id: "ship", label: "Ship Date", sub: order.shipDate || `Temporary: ${order.tempShipDate || ""}` },
  { id: "delivery", label: "Delivery", sub: order.deliveryDate }];

  const stageIndex = {
    "submitted": 0,
    "order-confirmed": 1,
    "artwork-production": 2,
    "factory-production": 3,
    "shipped": 4,
    "delivered": 5,
    "on-hold": 2
  }[order.status] ?? 0;

  return (
    <div style={{ position: "relative", display: "grid", gridTemplateColumns: `repeat(${steps.length}, 1fr)`, gap: 0 }}>
      {/* connecting line */}
      <div style={{
        position: "absolute", left: `${100 / steps.length / 2}%`, right: `${100 / steps.length / 2}%`,
        top: 16, height: 2, background: "#ececf0"
      }} />
      <div style={{
        position: "absolute", left: `${100 / steps.length / 2}%`,
        width: `calc((100% - ${100 / steps.length}%) * ${stageIndex / (steps.length - 1)})`,
        top: 16, height: 2, background: "#0e0e10", transition: "width .3s"
      }} />
      {steps.map((s, i) => {
        const active = i === stageIndex;
        const past = i < stageIndex;
        return (
          <div key={s.id} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, position: "relative" }}>
            <div style={{
              width: 32, height: 32, borderRadius: "50%",
              background: active ? "#0e0e10" : past ? "#0e0e10" : "#ececf0",
              color: active || past ? "#fff" : "#6b6b72",
              display: "inline-flex", alignItems: "center", justifyContent: "center",
              fontSize: 13, fontWeight: 700
            }}>{past ? <IconCheck size={14} style={{ strokeWidth: 3 }} /> : i + 1}</div>
            <div style={{ fontSize: 12, fontWeight: active ? 700 : 500, color: active ? "#0e0e10" : "#6b6b72", textAlign: "center" }}>{s.label}</div>
            {s.sub && <div style={{ fontSize: 11, color: "#9a9aa1", textAlign: "center" }}>{s.sub}</div>}
          </div>);

      })}
    </div>);

}

function DeliveryBlock({ delivery }) {
  if (!delivery) return <div />;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
        <span style={{ fontSize: 14, fontWeight: 700 }}>Delivery Information</span>
        <button title="Edit" style={{ background: "transparent", border: 0, color: "#6b6b72", cursor: "pointer", padding: 2 }}>
          <IconEdit size={14} />
        </button>
      </div>
      <div style={{ fontSize: 13, color: "#0e0e10", lineHeight: 1.7 }}>
        <div style={{ fontWeight: 600 }}>{delivery.name}</div>
        <div>{delivery.street}</div>
        <div>{delivery.cityLine}</div>
        <div style={{ marginTop: 12 }}>
          <a href="#" onClick={(e) => e.preventDefault()} style={{ color: "#2563eb", textDecoration: "none" }}>{delivery.email}</a>
        </div>
        <div>{delivery.phone}</div>
      </div>
    </div>);

}

function RepBlock({ rep }) {
  if (!rep) return <div />;
  return (
    <div>
      <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 12 }}>Rep/Dealership</div>
      <div style={{ fontSize: 13, color: "#0e0e10", lineHeight: 1.7 }}>
        <div style={{ fontWeight: 600 }}>{rep.name}</div>
        <div><a href="#" onClick={(e) => e.preventDefault()} style={{ color: "#2563eb", textDecoration: "none" }}>{rep.email}</a></div>
        <div style={{ marginTop: 12 }}>{rep.dealership}</div>
        <div>{rep.phone}</div>
      </div>
    </div>);

}

function PricingBlock({ pricing }) {
  if (!pricing) return <div />;
  return (
    <div>
      <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 12 }}>Item Pricing</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {pricing.lines.map((l, i) =>
        <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "#0e0e10" }}>
            <span>{l.label} <span style={{ color: "#6b6b72" }}>({l.detail})</span></span>
            <span style={{ fontVariantNumeric: "tabular-nums", fontWeight: 600 }}>${l.amount.toFixed(2)}</span>
          </div>
        )}
        {pricing.charges?.length > 0 &&
        <>
            <div style={{ fontSize: 11, color: "#6b6b72", textAlign: "center", margin: "8px 0", letterSpacing: ".02em" }}>Production Charges</div>
            {pricing.charges.map((l, i) =>
          <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "#0e0e10" }}>
                <span>{l.label} <span style={{ color: "#6b6b72" }}>{l.detail ? `(${l.detail})` : ""}</span></span>
                <span style={{ fontVariantNumeric: "tabular-nums" }}>${l.amount.toFixed(2)}</span>
              </div>
          )}
          </>
        }
        <div style={{ borderTop: "1px solid #ececf0", marginTop: 8, paddingTop: 12, display: "flex", justifyContent: "space-between", fontSize: 14, fontWeight: 700 }}>
          <span>Item Subtotal</span>
          <span style={{ fontVariantNumeric: "tabular-nums" }}>${pricing.subtotal.toFixed(2)}</span>
        </div>
      </div>
    </div>);

}

function DrawerActions({ order }) {
  const base = ["Contact Support"];
  const actions = base;
  return (
    <div style={{
      position: "sticky", bottom: 0, background: "#fff",
      padding: "16px 36px", borderTop: "1px solid #ececf0",
      display: "grid", gridTemplateColumns: `repeat(${actions.length}, 1fr)`, gap: 16
    }}>
      {actions.map((label) =>
      <button key={label} style={{
        background: "#fff", border: "1px solid #d4d4d8", borderRadius: 999,
        padding: "12px 16px", fontSize: 13, fontWeight: 600, color: "#0e0e10",
        cursor: "pointer", whiteSpace: "nowrap",
        transition: "all .12s"
      }}
      onMouseEnter={(e) => {e.currentTarget.style.background = "#0e0e10";e.currentTarget.style.color = "#fff";e.currentTarget.style.borderColor = "#0e0e10";}}
      onMouseLeave={(e) => {e.currentTarget.style.background = "#fff";e.currentTarget.style.color = "#0e0e10";e.currentTarget.style.borderColor = "#d4d4d8";}}>
          {label}
        </button>
      )}
    </div>);

}

// ─────────── Empty state (no orders / not seeded) ───────────
function OrdersEmpty({ sub, search }) {
  const map = {
    all: { title: "No Orders Yet", body: "Rep-placed and fan orders will appear here once purchases are made through your team store." },
    pending: { title: "No Pending Orders", body: "When customers place orders through your team store, they'll appear here for review." },
    fan: { title: "No Fan Orders", body: "Fan and supporter orders will show up here as your store generates sales." }
  };
  const m = map[sub] || map.all;
  const searching = !!search;
  return (
    <div style={{
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      padding: "120px 20px", textAlign: "center"
    }}>
      <div style={{
        width: 56, height: 56, borderRadius: "50%", background: "#dff5ea", color: "#1f9d55",
        display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 16
      }}>
        <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <rect x="3" y="3" width="18" height="18" rx="2" />
          <line x1="8" y1="16" x2="8" y2="12" /><line x1="12" y1="16" x2="12" y2="8" /><line x1="16" y1="16" x2="16" y2="10" />
        </svg>
      </div>
      <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 8 }}>{searching ? "No matching orders" : m.title}</div>
      <div style={{ fontSize: 13, color: "#6b6b72", maxWidth: 440, lineHeight: 1.55 }}>
        {searching ? "Try a different name, email, or order number." : m.body}
      </div>
    </div>);

}

// ─────────── Top-level Orders tab ───────────
function OrdersTabV2({ store, org, setOrg, pendingJump, allOrdersJump, pendingTabJump, onSubView }) {
  const [sub, setSub] = React.useState("all");
  // Freight gate: submitting pending orders from a group whose fulfillment
  // routing is unresolved opens the assign-managers modal instead.
  const [assignGate, setAssignGate] = React.useState(null); // { gate, grps }
  const requestSubmit = (grps, orgOverride) => {
    const o = orgOverride || org;
    for (const g of grps) {
      const gate = freightGateFor(o, store, g.shippingGroup);
      if (gate) { setAssignGate({ gate, grps }); return; }
    }
    setSubmitGroups(grps);
  };
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState("none");
  const [filter, setFilter] = React.useState("none");
  const [openOrder, setOpenOrder] = React.useState(null);
  const [toast, setToast] = React.useState(null);
  const [submitGroups, setSubmitGroups] = React.useState(null);

  // Report each viewed sub-tab up so the Orders badge can clear once all
  // have been seen. Fires on mount with the default sub and on changes.
  React.useEffect(() => {onSubView && onSubView(sub);}, [sub]);

  const data = store?.seeded ?
  makeOrdersDataset(store) :
  { myOrders: [], fanOrders: [], pending: [] };

  // When the Products tab asks us to jump to a pending order (e.g. after the
  // user clicks "Go to Pending Orders" in the active-orders warning), switch to
  // the Pending sub-tab and open the first pending order's drawer.
  React.useEffect(() => {
    if (!pendingJump) return;
    setSub("pending");
    const firstGroup = data.pending?.[0];
    const firstRow = firstGroup?.rows?.[0];
    if (firstRow) {
      setOpenOrder({ ...firstRow, shippingGroup: firstGroup.shippingGroup, kind: "pending" });
    }
  }, [pendingJump]);

  // Jump to the All Orders sub-tab when requested (e.g. from the Reports KPI).
  React.useEffect(() => {
    if (!allOrdersJump) return;
    setSub("all");
  }, [allOrdersJump]);

  // Jump to the Pending Orders sub-tab when requested (e.g. from the Reports KPI).
  React.useEffect(() => {
    if (!pendingTabJump) return;
    setSub("pending");
  }, [pendingTabJump]);

  const filterFn = (o) => {
    if (!search) return true;
    const s = search.toLowerCase();
    return [o.organization, o.customer, o.playerName, o.rep, o.webOrderNum, o.factoryOrderNum, o.cartName, o.product?.title].
    filter(Boolean).some((v) => String(v).toLowerCase().includes(s));
  };

  // All Orders = rep-placed (My) + fan-placed (Fan), tagged so the table can
  // badge each row's origin.
  const allOrders = [
  ...(data.myOrders || []).map((o) => ({ ...o, orderType: "my" })),
  ...(data.fanOrders || []).map((o) => ({ ...o, orderType: "fan" }))];

  const allOrdersCols = makeAllOrdersColumns();

  // Pending groups: search-filter rows, then sort within each group.
  const pendingGroups = (data.pending || [])
    .map((g) => {
      let rows = (g.rows || []).filter(filterFn);
      if (sort !== "none") rows = [...rows].sort((a, b) => {
        const va = orderSortValue(a, sort), vb = orderSortValue(b, sort);
        if (typeof va === "number" && typeof vb === "number") return va - vb;
        return String(va).localeCompare(String(vb));
      });
      return { ...g, rows };
    })
    .filter((g) => g.rows.length > 0);

  // Pending count for the sub-tab badge (all rows across shipping groups, unfiltered).
  const pendingCount = (data.pending || []).reduce((n, g) => n + ((g.rows || []).length), 0);

  const orderNav = [
  { id: "all", label: "All Orders", desc: "Every rep and fan order" },
  { id: "pending", label: "Pending Orders", desc: "Awaiting MOQ & submission", count: pendingCount }];

  return (
    <div style={{ paddingBottom: 60 }}>
      <div style={{ display: "flex", gap: 36, alignItems: "flex-start" }}>
      <SectionSideNav items={orderNav} value={sub} onChange={setSub} />
      <div style={{ flex: 1, minWidth: 0 }}>
      {sub !== "all" &&
      <div style={{ display: "flex", alignItems: "center", gap: 24, marginBottom: 16, flexWrap: "wrap" }}>
        <AllOrdersToolbar
          sort={sort} onSort={setSort}
          filter={filter} onFilter={setFilter}
          search={search} onSearch={setSearch}
          showFilter={false} showDate={false} showExport={false} />
      </div>}

      {sub === "all" && (
      <AllOrdersExperience
        orders={allOrders}
        columns={allOrdersCols}
        store={store}
        onOpen={(o) => setOpenOrder({ ...o, kind: o.orderType })} />)
      }
      {sub === "pending" && (
      pendingGroups.length === 0 ?
      <OrdersEmpty sub="pending" search={search} /> :
      <PendingOrdersList
        groups={pendingGroups}
        store={store}
        org={org}
        onOpen={(o) => setOpenOrder({ ...o, kind: "pending" })}
        onSubmit={(grps) => {if (grps && grps.length) requestSubmit(grps);}} />)

      }
      </div>
      </div>

      {openOrder && <OrderDetailDrawer order={openOrder} store={store} onClose={() => setOpenOrder(null)} />}
      {assignGate &&
      <AssignManagersModal
        gate={assignGate.gate}
        org={org}
        store={store}
        onClose={() => setAssignGate(null)}
        onComplete={(entries) => {
          const merged = { ...org, managers: { ...((org && org.managers) || {}), ...entries } };
          setOrg && setOrg((o) => ({ ...o, managers: { ...(o.managers || {}), ...entries } }));
          const grps = assignGate.grps;
          setAssignGate(null);
          requestSubmit(grps, merged); // auto-continue — next gate or the review modal
        }} />}
      <SubmitOrderModal
        open={!!submitGroups}
        groups={submitGroups || []}
        store={store}
        onClose={() => setSubmitGroups(null)}
        onConfirm={({ itemCount }) => {
          setSubmitGroups(null);
          setToast(itemCount === 1 ? "Order submitted" : `${itemCount} orders submitted`);
        }} />
      
      <Toast message={toast} onDone={() => setToast(null)} />
    </div>);

}

