// Sports that only exist in the women's catalog — used to pick a sensible
// default tab when the store's sport implies a gender.
const WOMEN_ONLY = ["Softball", "Field Hockey"];

function GenderTabs({ gender, onChange }) {
  const Tab = ({ value, children }) => {
    const active = gender === value;
    return (
      <button
        type="button"
        onClick={() => onChange(value)}
        style={{
          flex: 1, padding: "12px 16px", border: 0, cursor: "pointer",
          background: active ? "#ececef" : "#fff",
          color: active ? "#0e0e10" : "#6b6b72",
          fontSize: 14, fontWeight: active ? 700 : 500, letterSpacing: ".005em",
          transition: "background .15s, color .15s",
        }}
      >
        {children}
      </button>
    );
  };
  return (
    <div style={{
      display: "flex", border: "1px solid #e5e5e9", borderRadius: 8,
      overflow: "hidden", background: "#fff", boxShadow: "0 1px 2px rgba(20,20,30,.04)",
    }}>
      <Tab value="men">Men</Tab>
      <div style={{ width: 1, background: "#e5e5e9" }}></div>
      <Tab value="women">Women</Tab>
    </div>
  );
}

function SportCard({ item, onPick }) {
  return (
    <button
      type="button"
      onClick={() => onPick(item)}
      style={{
        background: "transparent", border: 0, padding: 0, cursor: "pointer",
        display: "block", width: "100%", borderRadius: 10,
        transition: "transform .14s ease, filter .14s ease",
      }}
      onMouseEnter={(e) => { e.currentTarget.style.transform = "translateY(-3px)"; e.currentTarget.style.filter = "drop-shadow(0 6px 14px rgba(20,20,30,.12))"; }}
      onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.filter = "none"; }}
      onFocus={(e) => { e.currentTarget.style.transform = "translateY(-3px)"; }}
      onBlur={(e) => { e.currentTarget.style.transform = "translateY(0)"; }}
      aria-label={item.label}
    >
      <img
        src={CARD_DIR + item.img}
        alt={item.label}
        draggable="false"
        style={{ display: "block", width: "100%", height: "auto" }}
      />
    </button>
  );
}

