// onboarding-checklist.jsx
// "Kickoff Checklist" — a persistent, non-blocking onboarding panel that replaces
// the old guided-tooltip tour. It docks in a corner, never covers the working
// area, and lets a first-time Rep complete setup at their own pace.
//
// The four steps are the SAME milestones the old tour walked through, tracked by
// the exact same app CustomEvents (so no app wiring had to change):
//   tour:product-ready      → "Add & verify a product"  becomes complete
//   tour:product-published  → "Publish your product"     becomes complete
//   tour:roster-added       → "Build your roster"        becomes complete
//   tour:store-live         → "Launch your store"        becomes complete
//
// Completion is ALSO derived from the live store object (products / live flag)
// and persisted per-store to localStorage, so a refresh restores real progress.
//
// Clicking an incomplete step routes the Rep to the feature that completes it
// (via the onStepAction callback the app supplies).
//
// Exposes <OnboardingChecklist run store screen accent position onStepAction
//          onDismiss onComplete />.

// ─────────── Steps (verbatim from the old tooltip flow) ───────────
const CHECKLIST_STEPS = [
{
  id: "product-added",
  title: "Add & verify your first product",
  desc: "Customize a new design, pull from a saved cart, or drop in a saved design — then confirm the logo application sizes. Your draft becomes Ready.",
  cta: "Add a product"
},
{
  id: "product-published",
  title: "Publish your product",
  desc: "Your product is Ready. Publish it so it appears on your storefront — a store needs at least one published product before it can go live.",
  cta: "Publish a product"
},
{
  id: "roster",
  title: "Add your teams (optional)",
  desc: "Rosters are optional — front-load players by CSV, manual entry, or a share link, or launch now and let rosters back-fill from team-gear orders.",
  cta: "Open My Teams"
},
{
  id: "launch",
  title: "Launch your store",
  desc: "Take your store live. Share the link and team codes — team-gear orders can build your roster from there.",
  cta: "Launch your store"
}];


// ─────────── Accent presets (PROLOOK palette) ───────────
const CHECKLIST_ACCENTS = {
  red: { base: "#e1251b", deep: "#b81d14", soft: "#fbe7e5" },
  navy: { base: "#1d3a8a", deep: "#152c6b", soft: "#e4e9f6" },
  green: { base: "#1f9d55", deep: "#177a41", soft: "#e7f5ed" }
};
function resolveAccent(name) {
  return CHECKLIST_ACCENTS[name] || CHECKLIST_ACCENTS.red;
}

// ─────────── Derive completion from the live store object ───────────
function deriveDone(store) {
  const done = {};
  const products = store && store.products || [];
  if (products.length > 0) done["product-added"] = true;
  if (products.some((p) => p.status === "published")) {
    done["product-added"] = true;
    done["product-published"] = true;
  }
  if (store && store.live) {
    done["product-added"] = true;
    done["product-published"] = true;
    done["launch"] = true;
  }
  return done;
}

const ckKey = (id) => id ? "prolook_checklist_" + id : null;
function loadPersisted(id) {
  const k = ckKey(id);
  if (!k) return {};
  try {return JSON.parse(localStorage.getItem(k) || "{}");} catch (e) {return {};}
}
function savePersisted(id, done) {
  const k = ckKey(id);
  if (!k) return;
  try {localStorage.setItem(k, JSON.stringify(done));} catch (e) {}
}
const dismissKey = (id) => id ? "prolook_checklist_dismissed_" + id : null;

// ─────────── Circular completion indicator ───────────
function StepCircle({ done, accent, hovered }) {
  return (
    <span style={{
      width: 28, height: 28, borderRadius: "50%", flexShrink: 0,
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      background: done ? accent.base : "#fff",
      border: done ? `1px solid ${accent.base}` : `2px solid ${hovered ? accent.base : "#cdcdd4"}`,
      color: "#fff", marginTop: 1,
      transition: "background .25s ease, border-color .2s ease, transform .25s ease",
      transform: done ? "scale(1)" : "scale(1)",
      boxShadow: done ? `0 2px 6px ${accent.base}40` : "none"
    }}>
      {done && <IconCheck size={14} style={{ strokeWidth: 3 }} />}
    </span>);

}

// ─────────── A single step row ───────────
function StepRow({ step, done, accent, last, onClick }) {
  const [hover, setHover] = React.useState(false);
  const clickable = !done;
  return (
    <div
      role={clickable ? "button" : undefined}
      tabIndex={clickable ? 0 : undefined}
      onClick={clickable ? onClick : undefined}
      onKeyDown={clickable ? (e) => {if (e.key === "Enter" || e.key === " ") {e.preventDefault();onClick();}} : undefined}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: "flex", alignItems: "flex-start", gap: 12,
        padding: "12px 16px",
        borderBottom: last ? "none" : "1px solid #f1f1f3",
        cursor: clickable ? "pointer" : "default",
        background: clickable && hover ? "#faf9f9" : "transparent",
        transition: "background .15s ease",
        position: "relative"
      }}>
      
      <StepCircle done={done} accent={accent} hovered={clickable && hover} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          display: "flex", alignItems: "center", gap: 8,
          fontSize: 14, fontWeight: 700, lineHeight: 1.3,
          color: done ? "#9a9aa1" : "#0e0e10",
          textDecoration: done ? "line-through" : "none",
          textDecorationColor: done ? "#c2c2c8" : "transparent"
        }}>
          {step.title}
        </div>
        <div style={{
          fontSize: 12.5, lineHeight: 1.5, marginTop: 4,
          color: done ? "#b6b6bd" : "#6b6b72", textWrap: "pretty"
        }}>
          {step.desc}
        </div>
        {clickable &&
        <span style={{
          display: "inline-flex", alignItems: "center", gap: 4,
          marginTop: 8, fontSize: 12, fontWeight: 700,
          color: accent.base,
          opacity: hover ? 1 : 0.82, transition: "opacity .15s, gap .15s",
          gap: hover ? 6 : 4
        }}>
            {step.cta}
            <IconChevronRight size={13} style={{ strokeWidth: 2.6 }} />
          </span>
        }
      </div>
    </div>);

}

// ─────────── Collapsed launcher (a compact progress pill) ───────────
function ChecklistLauncher({ pct, total, completed, accent, position, onExpand, allDone, bottom = 24 }) {
  const [hover, setHover] = React.useState(false);
  const size = 38,stroke = 4,r = (size - stroke) / 2,c = 2 * Math.PI * r;
  const corner = position === "left" ? { left: 24 } : { right: 24 };
  return (
    <button
      onClick={onExpand}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        position: "fixed", bottom, ...corner, zIndex: 90,
        display: "flex", alignItems: "center", gap: 12,
        background: "#fff", border: "1px solid #e5e5e9", borderRadius: 999,
        padding: "8px 16px 8px 8px",
        boxShadow: hover ? "0 12px 32px rgba(20,20,30,.16)" : "0 6px 20px rgba(20,20,30,.10)",
        transform: hover ? "translateY(-1px)" : "translateY(0)",
        transition: "box-shadow .2s, transform .2s",
        fontFamily: '"Inter", system-ui, sans-serif'
      }}>
      
      <span style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
        <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#ececf0" strokeWidth={stroke} />
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={accent.base} strokeWidth={stroke}
          strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c * (1 - pct / 100)}
          style={{ transition: "stroke-dashoffset .5s cubic-bezier(.4,.9,.3,1)" }} />
        </svg>
        <span style={{
          position: "absolute", inset: 0, display: "inline-flex", alignItems: "center", justifyContent: "center"
        }}>
          {allDone ?
          <IconCheck size={16} style={{ strokeWidth: 3, color: accent.base }} /> :
          <span style={{ fontSize: 10.5, fontWeight: 800, color: "#0e0e10" }}>{pct}%</span>}
        </span>
      </span>
      <span style={{ textAlign: "left" }}>
        <span style={{ display: "block", fontSize: 13, fontWeight: 800, color: "#0e0e10", letterSpacing: ".01em" }}>
          {allDone ? "Setup complete" : "Setup checklist"}
        </span>
        <span style={{ display: "block", fontSize: 11.5, fontWeight: 600, color: "#9a9aa1", marginTop: 1 }}>
          {completed} of {total} steps done
        </span>
      </span>
      <span style={{ display: "inline-flex", color: "#9a9aa1", marginLeft: 2, transform: "rotate(180deg)" }}>
        <IconChevron size={16} style={{ strokeWidth: 2.4 }} />
      </span>
    </button>);

}

// ─────────── The expanded checklist card ───────────
function ChecklistCard({ store, done, accent, position, onStep, onCollapse, onDismiss, bottom = 24 }) {
  const total = CHECKLIST_STEPS.length;
  const completed = CHECKLIST_STEPS.filter((s) => done[s.id]).length;
  const pct = Math.round(completed / total * 100);
  const allDone = completed === total;
  const teamName = store && (store.teamName || store.storeTitle) || "your team";
  const corner = position === "left" ? { left: 24 } : { right: 24 };

  return (
    <div style={{
      position: "fixed", bottom, ...corner, zIndex: 90,
      width: 380, maxWidth: "calc(100vw - 48px)", maxHeight: `calc(100vh - ${bottom + 24}px)`,
      display: "flex", flexDirection: "column",
      background: "#fff", borderRadius: 14, overflow: "hidden",
      boxShadow: "0 18px 50px rgba(20,20,30,.20), 0 0 0 1px rgba(20,20,30,.06)",
      fontFamily: '"Inter", system-ui, sans-serif',
      animation: "ckPop .28s cubic-bezier(.2,.9,.3,1.1)"
    }}>
      {/* Header */}
      <div style={{ ...{
          background: `linear-gradient(180deg, ${accent.base} 0%, ${accent.deep} 130%)`,
          color: "#fff", padding: "16px 20px 32px", position: "relative", flexShrink: 0
        }, background: "linear-gradient(rgb(225, 37, 27) 0%, rgb(184, 29, 20) 130%) center center" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12 }}>
          <div style={{ minWidth: 0 }}>
            <div style={{
              fontSize: 10.5, fontWeight: 800, letterSpacing: ".14em", textTransform: "uppercase",
              opacity: 0.82, marginBottom: 8
            }}>
              Draft store · Setup
            </div>
            <h3 style={{ margin: 0, fontSize: 17, fontWeight: 800, letterSpacing: "-.01em", lineHeight: 1.25 }}>
              Let's get {teamName} ready for kickoff!
            </h3>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 4, flexShrink: 0 }}>
            <span style={{ fontSize: 19, fontWeight: 800, lineHeight: 1, letterSpacing: "-.02em" }}>{pct}%</span>
            <button onClick={onCollapse} aria-label="Collapse checklist" style={{
              background: "rgba(255,255,255,.16)", border: 0, cursor: "pointer",
              color: "#fff", borderRadius: 7, padding: 8, display: "inline-flex", marginLeft: 8
            }}
            onMouseEnter={(e) => e.currentTarget.style.background = "rgba(255,255,255,.28)"}
            onMouseLeave={(e) => e.currentTarget.style.background = "rgba(255,255,255,.16)"}>
              <IconChevron size={16} style={{ strokeWidth: 2.6 }} />
            </button>
          </div>
        </div>
      </div>

      {/* Progress bar — a white pill straddling the header/body seam */}
      <div style={{ position: "relative", height: 0, flexShrink: 0 }}>
        <div style={{
          position: "absolute", left: 20, right: 20, top: -12,
          height: 12, borderRadius: 999, background: "#fff",
          padding: 4, boxShadow: "0 2px 8px rgba(20,20,30,.12)"
        }}>
          <div style={{
            height: "100%", borderRadius: 999,
            width: `${pct}%`, minWidth: pct > 0 ? 6 : 0,
            background: `linear-gradient(90deg, ${accent.base}, ${accent.deep})`,
            transition: "width .55s cubic-bezier(.4,.9,.3,1)"
          }} />
        </div>
      </div>

      {/* Steps */}
      <div style={{ paddingTop: 16, flex: 1, minHeight: 0, overflowY: "auto" }}>
        {CHECKLIST_STEPS.map((s, i) =>
        <StepRow
          key={s.id}
          step={s}
          done={!!done[s.id]}
          accent={accent}
          last={i === CHECKLIST_STEPS.length - 1}
          onClick={() => onStep(s.id)} />

        )}
      </div>

      {/* Done banner */}
      {allDone &&
      <div style={{
        display: "flex", alignItems: "center", gap: 12, margin: "0 16px 4px",
        padding: "12px 16px", borderRadius: 10, background: accent.soft
      }}>
          <span style={{
          width: 32, height: 32, borderRadius: 9, flexShrink: 0, background: accent.base, color: "#fff",
          display: "inline-flex", alignItems: "center", justifyContent: "center"
        }}>
            <IconTrophy size={17} style={{ strokeWidth: 1.9 }} />
          </span>
          <div style={{ fontSize: 12.5, lineHeight: 1.45, color: accent.deep, fontWeight: 600 }}>
            {teamName} is live and ready for kickoff. Nicely done — you cleared every setup step.
          </div>
        </div>
      }

      {/* Footer */}
      <div style={{ padding: "12px 16px 16px", textAlign: "center", borderTop: "1px solid #f1f1f3", marginTop: 8, flexShrink: 0 }}>
        <button onClick={onDismiss} style={{
          background: "transparent", border: 0, cursor: "pointer",
          fontSize: 12.5, fontWeight: 600, color: "#9a9aa1", fontFamily: "inherit", padding: "4px 8px"
        }}
        onMouseEnter={(e) => e.currentTarget.style.color = "#6b6b72"}
        onMouseLeave={(e) => e.currentTarget.style.color = "#9a9aa1"}>
          {allDone ? "Dismiss checklist" : "Dismiss checklist"}
        </button>
      </div>
    </div>);

}

// ─────────── Controller ───────────
function OnboardingChecklist({ run, store, screen, accent: accentName = "red", position = "right", onStepAction, onDismiss, onComplete }) {
  const accent = React.useMemo(() => resolveAccent(accentName), [accentName]);
  const storeId = store && store.id;

  const [open, setOpen] = React.useState(false); // controller active?
  const [collapsed, setCollapsed] = React.useState(false); // expanded vs launcher pill
  const [done, setDone] = React.useState({});
  const completedRef = React.useRef(0);

  // Start / reset when the run flag (a fresh first store) flips.
  React.useEffect(() => {
    if (run) {
      const dismissed = (() => {try {return localStorage.getItem(dismissKey(storeId)) === "true";} catch (e) {return false;}})();
      if (dismissed) {setOpen(false);return;}
      const t = setTimeout(() => {
        setDone({ ...deriveDone(store), ...loadPersisted(storeId) });
        setCollapsed(false);
        setOpen(true);
      }, 450);
      return () => clearTimeout(t);
    }
    setOpen(false);
    // eslint-disable-next-line
  }, [run, storeId]);

  // Re-merge whenever the live store object changes (products added, went live).
  React.useEffect(() => {
    if (!open) return;
    setDone((cur) => {
      const merged = { ...cur, ...deriveDone(store), ...loadPersisted(storeId) };
      // keep anything already true
      Object.keys(cur).forEach((k) => {if (cur[k]) merged[k] = true;});
      return merged;
    });
    // eslint-disable-next-line
  }, [store, open]);

  // Mark a step done + persist.
  const mark = React.useCallback((ids) => {
    setDone((cur) => {
      const next = { ...cur };
      (Array.isArray(ids) ? ids : [ids]).forEach((id) => {next[id] = true;});
      savePersisted(storeId, next);
      return next;
    });
  }, [storeId]);

  // Listen to the SAME completion events the old tour used.
  React.useEffect(() => {
    if (!open) return;
    const onReady = () => mark("product-added");
    const onPublished = () => mark(["product-added", "product-published"]);
    const onRoster = () => mark("roster");
    const onLive = () => mark(["product-added", "product-published", "launch"]);
    window.addEventListener("tour:product-ready", onReady);
    window.addEventListener("tour:product-published", onPublished);
    window.addEventListener("tour:roster-added", onRoster);
    window.addEventListener("tour:store-live", onLive);
    return () => {
      window.removeEventListener("tour:product-ready", onReady);
      window.removeEventListener("tour:product-published", onPublished);
      window.removeEventListener("tour:roster-added", onRoster);
      window.removeEventListener("tour:store-live", onLive);
    };
  }, [open, mark]);

  // Fire onComplete once all four are done.
  const completed = CHECKLIST_STEPS.filter((s) => done[s.id]).length;
  React.useEffect(() => {
    if (open && completed === CHECKLIST_STEPS.length && completedRef.current < CHECKLIST_STEPS.length) {
      onComplete && onComplete();
    }
    completedRef.current = completed;
  }, [completed, open, onComplete]);

  const handleStep = React.useCallback((id) => {
    onStepAction && onStepAction(id);
  }, [onStepAction]);

  const dismiss = React.useCallback(() => {
    try {localStorage.setItem(dismissKey(storeId), "true");} catch (e) {}
    setOpen(false);
    onDismiss && onDismiss();
  }, [storeId, onDismiss]);

  if (!open) return <ChecklistStyles />;

  const total = CHECKLIST_STEPS.length;
  const pct = Math.round(completed / total * 100);
  const allDone = completed === total;
  // The dashboard has a fixed action/launch bar pinned to the bottom (~70px).
  // Lift the checklist above it so the corner button is never covered.
  const bottom = screen === "dashboard" ? 96 : 24;

  return (
    <>
      <ChecklistStyles />
      {collapsed ?
      <ChecklistLauncher
        pct={pct} total={total} completed={completed} accent={accent}
        position={position} allDone={allDone} bottom={bottom}
        onExpand={() => setCollapsed(false)} /> :


      <ChecklistCard
        store={store} done={done} accent={accent} position={position} bottom={bottom}
        onStep={handleStep}
        onCollapse={() => setCollapsed(true)}
        onDismiss={dismiss} />

      }
    </>);

}

function ChecklistStyles() {
  return (
    <style>{`
      @keyframes ckPop { from { transform: translateY(12px) scale(.985) } to { transform: none } }
    `}</style>);

}

Object.assign(window, { OnboardingChecklist, CHECKLIST_STEPS });

