function AccountProfile({ profile: profileProp = ACCOUNT_PROFILE, brands = ACCOUNT_BRANDS, authMode = "native", brandStates = {}, onBrandState, primaryId = null, onPrimary, onEditProfile, onToast, archivedStores = [], onManageStore, onUnarchive, onCreateTemplate }) {
  const isNative = authMode === "native" || authMode === "native-new";
  const isLinked = authMode === "linked";
  const hasNativeAccount = isNative || isLinked;
  const [profile, setProfile] = React.useState(profileProp);
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(profileProp);
  const [hoverStar, setHoverStar] = React.useState(null);
  // brand connect modal: { brand, mode: "signin" | "different-email" }
  const [loginBrand, setLoginBrand] = React.useState(null);
  const [creds, setCreds] = React.useState({ email: "", password: "" });
  const [signingIn, setSigningIn] = React.useState(false);
  // native password change
  const [pw, setPw] = React.useState({ current: "", next: "", show: false });
  const [pwSaving, setPwSaving] = React.useState(false);
  // account linking (explicit confirmation)
  const [linkOpen, setLinkOpen] = React.useState(false);
  const [linkStep, setLinkStep] = React.useState(0); // 0 choose brand/email, 1 password, 2 confirm
  const [link, setLink] = React.useState({ email: "", password: "" });
  const [linkedIdentity, setLinkedIdentity] = React.useState(isLinked ? { brand: "Marucci", email: "max.lee@marucci-dealer.com" } : null);

  const stateOf = (b) => brandStates[b.id] || b.state || "signin";
  const primaryBrand = primaryId ? (brands.find((b) => b.id === primaryId) || CUSTOMIZER_BRANDS[primaryId]) : null;
  const connectedCount = brands.filter((b) => stateOf(b) === "connected").length;

  const openLogin = (b, mode) => { setCreds({ email: mode === "different-email" ? "" : profile.email, password: "" }); setLoginBrand({ brand: b, mode }); };
  const closeLogin = () => { if (!signingIn) setLoginBrand(null); };
  const submitLogin = (e) => {
    e && e.preventDefault();
    if (!loginBrand || !creds.email || !creds.password) return;
    setSigningIn(true);
    setTimeout(() => {
      const b = loginBrand.brand;
      onBrandState && onBrandState(b.id, "connected");
      if (!primaryId && onPrimary) onPrimary(b.id);
      setSigningIn(false);
      setLoginBrand(null);
      onToast && onToast(`${b.name} connected — you can now add products from this brand`);
    }, 850);
  };
  const requestAccess = (b) => { onBrandState && onBrandState(b.id, "pending"); onToast && onToast(`Access request for ${b.name} sent to Prolook`); };

  // Password criteria (Landing Page, Epic D)
  const rules = (() => {
    const p = pw.next || ""; const low = p.toLowerCase(); const email = profile.email.toLowerCase(); const local = email.split("@")[0];
    const common = ["password", "123456", "qwerty", "letmein", "teamstores", "welcome1"];
    return [
      { ok: p.length >= 12 && p.length <= 128, label: "At least 12 characters (any characters, spaces included)" },
      { ok: p.length > 0 && !common.some((c) => low.includes(c)), label: "Not a common or previously breached password" },
      { ok: p.length > 0 && !low.includes(email) && !(local.length > 2 && low.includes(local)), label: "Doesn't contain your email address" },
      { ok: p.length > 0 && p !== pw.current, label: "Different from your current password" },
    ];
  })();
  const pwOk = pw.current && rules.every((r) => r.ok);
  const savePassword = (e) => {
    e && e.preventDefault(); if (!pwOk) return;
    setPwSaving(true);
    setTimeout(() => { setPwSaving(false); setPw({ current: "", next: "", show: false }); onToast && onToast("Password changed — other sessions signed out, confirmation email sent"); }, 900);
  };

  const saveProfile = () => { setProfile(draft); setEditing(false); onToast && onToast("Profile updated"); };
  const field = (label, key, opts = {}) => (
    <ProfileReadField label={label} value={profile[key]} required dropdown={opts.dropdown && !editing} mono={opts.mono}>
      {editing && (
        <input value={draft[key]} onChange={(e) => setDraft((d) => ({ ...d, [key]: e.target.value }))} style={{
          background: "#fff", border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, color: "#0e0e10", minHeight: 48, outline: "none", width: "100%",
          fontFamily: opts.mono ? "JetBrains Mono, monospace" : "inherit",
        }} onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
      )}
    </ProfileReadField>
  );
  const pill = (txt, icon) => (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12, fontWeight: 700, letterSpacing: ".03em", color: "#6b6b72", background: "#f1f1f3", border: "1px solid #e5e5e9", borderRadius: 999, padding: "4px 12px" }}>{icon} {txt}</span>
  );
  const pwInput = (label, key, placeholder) => (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      <label style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "#3f3f46" }}>{label}</label>
      <div style={{ position: "relative" }}>
        <input type={pw.show ? "text" : "password"} value={pw[key]} onChange={(e) => setPw((p) => ({ ...p, [key]: e.target.value }))} placeholder={placeholder} disabled={pwSaving}
          style={{ border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 44px 12px 16px", fontSize: 15, outline: "none", width: "100%" }}
          onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
        <button type="button" onClick={() => setPw((p) => ({ ...p, show: !p.show }))} aria-label="Toggle password visibility" style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", border: 0, background: "transparent", cursor: "pointer", color: "#71717a", width: 28, height: 28, borderRadius: 6, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
          <IconEye size={16} />
        </button>
      </div>
    </div>
  );

  return (
    <div style={{ flex: 1, padding: "32px 40px 120px", background: "#fafafb" }}>
      <div style={{ maxWidth: 1120, margin: "0 auto" }}>
        {/* Page header */}
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 20, flexWrap: "wrap" }}>
          <div>
            <h1 style={{ fontSize: 32, fontWeight: 800, margin: 0, color: "#0e0e10", letterSpacing: "-.01em" }}>My Account</h1>
            <p style={{ fontSize: 15, color: "#6b6b72", margin: "8px 0 0", maxWidth: 620, lineHeight: 1.5 }}>
              {hasNativeAccount
                ? "Your profile, brand access and Team Stores security — in one place."
                : "Your profile is synced from the Customizer account you signed in with. Review your details below."}
            </p>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
            <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12.5, fontWeight: 700, color: "#52525b", background: "#fff", border: "1px solid #e5e5e9", borderRadius: 999, padding: "8px 14px" }}>
              <IconLock size={13} /> {isLinked ? "Signed in · Linked account" : isNative ? "Signed in with Team Stores" : `Signed in with ${primaryBrand ? primaryBrand.name : "Marucci"} Customizer`}
            </span>
            {!hasNativeAccount && (
              <button onClick={onEditProfile} style={{ border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 9, padding: "10px 18px", cursor: "pointer", fontSize: 14, fontWeight: 700, display: "inline-flex", alignItems: "center", gap: 8 }}
                onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#0e0e10"; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#d4d4d8"; }}>
                <IconEdit size={16} /> Edit in Customizer <IconExternal size={15} style={{ color: "#9a9aa1" }} />
              </button>
            )}
          </div>
        </div>

        {/* Identity strip */}
        <div style={{ display: "flex", alignItems: "center", gap: 16, margin: "28px 0 28px" }}>
          <div style={{ width: 64, height: 64, borderRadius: "50%", background: "#0e0e10", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 22, fontWeight: 800, fontFamily: "Archivo, sans-serif", flexShrink: 0 }}>{(profile.firstName[0] || "") + (profile.lastName[0] || "")}</div>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 19, fontWeight: 800, color: "#0e0e10" }}>{profile.firstName} {profile.lastName}</div>
            <div style={{ fontSize: 14, color: "#6b6b72", marginTop: 2, display: "inline-flex", alignItems: "center", gap: 8 }}><IconMail size={15} /> {profile.email}</div>
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
          {/* ─── Card A — Personal Info ─── */}
          <SettingsCard style={{ padding: "32px 36px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 4, gap: 12 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Personal Info</h2>
              {hasNativeAccount ? (
                editing ? (
                  <div style={{ display: "flex", gap: 8 }}>
                    <button onClick={() => { setDraft(profile); setEditing(false); }} style={{ border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 8, padding: "8px 14px", cursor: "pointer", fontSize: 13.5, fontWeight: 700 }}>Cancel</button>
                    <button onClick={saveProfile} style={{ border: 0, background: "#0e0e10", color: "#fff", borderRadius: 8, padding: "8px 16px", cursor: "pointer", fontSize: 13.5, fontWeight: 700 }}>Save changes</button>
                  </div>
                ) : (
                  <button onClick={() => { setDraft(profile); setEditing(true); }} style={{ border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 8, padding: "8px 14px", cursor: "pointer", fontSize: 13.5, fontWeight: 700, display: "inline-flex", alignItems: "center", gap: 8 }}
                    onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#0e0e10"; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#d4d4d8"; }}>
                    <IconEdit size={15} /> Edit
                  </button>
                )
              ) : pill("Read-only", <IconLock size={13} />)}
            </div>
            <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 28px" }}>
              {hasNativeAccount
                ? "Stored on your Team Stores account" + (profile.dealership ? `; your dealership (${profile.dealership}) comes from qx7.` : ".")
                : <React.Fragment>Pulled directly from your primary brand, <strong style={{ color: "#09090b", fontWeight: 700 }}>{primaryBrand ? primaryBrand.name : "Marucci"}</strong>. To edit these details, update them in that Customizer account.</React.Fragment>}
            </p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "24px 36px" }}>
              {field("First Name", "firstName")}
              {field("Last Name", "lastName")}
              <ProfileReadField label="Email Address" value={profile.email} required />
              <ProfileReadField label="Phone Number" required>
                {editing ? (
                  <input value={draft.phone} onChange={(e) => setDraft((d) => ({ ...d, phone: e.target.value }))} style={{ background: "#fff", border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, color: "#0e0e10", minHeight: 48, outline: "none", width: "100%" }} />
                ) : (
                  <div style={{ display: "flex", background: "#f5f5f7", border: "1px solid #ececf0", borderRadius: 8, overflow: "hidden", minHeight: 48, cursor: "not-allowed" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "0 16px", borderRight: "1px solid #e5e5e9" }}>
                      <span style={{ fontSize: 15, color: "#52525b" }}>{profile.countryCode}</span>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", padding: "0 16px", fontSize: 15, color: "#52525b" }}>{profile.phone}</div>
                  </div>
                )}
              </ProfileReadField>
              {field("Country", "country", { dropdown: true })}
              {field("State", "state", { dropdown: true })}
              {field("City", "city", { dropdown: true })}
              {field("Zip Code", "zip", { mono: true })}
            </div>
          </SettingsCard>

          {/* ─── Card B — Brand Access & Authentication (editable) ─── */}
          <SettingsCard style={{ padding: "32px 36px" }}>
            <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Brand Access &amp; Authentication</h2>
            <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 24px", maxWidth: 720, lineHeight: 1.5 }}>Every brand Customizer your dealership is entitled to. Connecting a brand reuses your existing Customizer account and permissions, and unlocks its products in Add Products.</p>

            {/* Dealership callout */}
            <div style={{ display: "flex", alignItems: "center", gap: 16, background: "#0e0e10", borderRadius: 12, padding: "16px 24px" }}>
              <span style={{ width: 44, height: 44, borderRadius: 10, background: "rgba(255,255,255,.12)", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><IconShield size={22} /></span>
              <div style={{ minWidth: 0, flex: 1 }}>
                <div style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: ".1em", textTransform: "uppercase", color: "#a1a1aa" }}>Dealership</div>
                <div style={{ fontSize: 17, fontWeight: 800, color: "#fff", marginTop: 4 }}>{profile.dealership}</div>
              </div>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12.5, fontWeight: 700, color: "#4ade80", background: "rgba(74,222,128,.12)", borderRadius: 999, padding: "8px 12px", flexShrink: 0 }}><IconCircleCheck size={15} /> Verified in qx7</span>
            </div>

            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", margin: "28px 0 12px" }}>
              <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "#6b6b72" }}>Entitled Brands</div>
              <div style={{ fontSize: 12.5, color: "#9a9aa1" }}>{connectedCount} of {brands.length} connected{!primaryId ? " · no primary brand set" : ""}</div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {brands.map((b) => {
                const st = stateOf(b);
                const isPrimary = primaryId === b.id;
                const canPrimary = st === "connected";
                const hovered = hoverStar === b.id;
                return (
                <div key={b.id} style={{ border: `1px solid ${isPrimary ? "#f0c64a" : "#ececf0"}`, borderRadius: 12, padding: "16px 20px", background: isPrimary ? "#fffdf5" : st === "request" || st === "pending" ? "#fafafa" : "#fff" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                    <div style={{ position: "relative", flexShrink: 0, display: "flex" }} onMouseEnter={() => setHoverStar(b.id)} onMouseLeave={() => setHoverStar(null)}>
                      <button onClick={() => canPrimary && onPrimary && onPrimary(b.id)} aria-label={isPrimary ? "Primary brand" : "Set as primary brand"} style={{ border: 0, background: "transparent", padding: 4, lineHeight: 0, cursor: canPrimary ? "pointer" : "not-allowed", opacity: canPrimary ? 1 : 0.4 }}>
                        <svg width="22" height="22" viewBox="0 0 24 24" fill={isPrimary ? "#f5b301" : "none"} stroke={isPrimary ? "#f5b301" : "#a1a1aa"} strokeWidth="1.8" strokeLinejoin="round"><path d="M12 2.5l2.9 6.1 6.6.6-5 4.4 1.5 6.5L12 17.2 5.5 20.6l1.5-6.5-5-4.4 6.6-.6L12 2.5z" /></svg>
                      </button>
                      {hovered && (
                        <div style={{ position: "absolute", left: "50%", bottom: "calc(100% + 8px)", transform: "translateX(-50%)", width: 220, background: "#0e0e10", color: "#fff", borderRadius: 8, padding: "8px 12px", fontSize: 12.5, lineHeight: 1.45, fontWeight: 500, textAlign: "center", zIndex: 20, boxShadow: "0 8px 22px rgba(20,20,30,.28)", pointerEvents: "none" }}>
                          {!canPrimary ? "Connect this brand to set it as your primary." : isPrimary ? "Your primary brand — the Customizer item in the account menu opens it." : "Make this your primary brand for the workspace session."}
                          <span style={{ position: "absolute", left: "50%", top: "100%", transform: "translateX(-50%)", width: 0, height: 0, borderLeft: "6px solid transparent", borderRight: "6px solid transparent", borderTop: "6px solid #0e0e10" }} />
                        </div>
                      )}
                    </div>
                    <span style={{ width: 48, height: 48, borderRadius: 10, background: "#f1f1f3", border: "1px solid #e5e5e9", color: "#0e0e10", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 17, fontWeight: 800, fontFamily: "Archivo, sans-serif", flexShrink: 0 }}>{b.name[0]}</span>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ fontSize: 15.5, fontWeight: 800, color: "#0e0e10", display: "inline-flex", alignItems: "center", gap: 8 }}>
                        {b.name}
                        {isPrimary && <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".05em", textTransform: "uppercase", color: "#a67c00", background: "#fdf1cf", border: "1px solid #f0d98a", borderRadius: 999, padding: "2px 8px" }}>Primary</span>}
                      </div>
                      <div style={{ fontSize: 13, color: "#6b6b72", marginTop: 2, lineHeight: 1.45 }}>
                        {st === "connected" ? `${b.desc} · Connected with ${profile.email}`
                          : st === "signin" ? "Customizer account found for your email. Sign in once to connect it."
                          : st === "request" ? "You don't have an account for this Customizer yet. Accounts are added by Prolook."
                          : "Access request sent to Prolook. We'll let you know when your account is ready."}
                      </div>
                    </div>
                    {st === "connected" && (
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13.5, fontWeight: 700, color: "#1f9d55", background: "#e7f5ed", border: "1px solid #c7ead4", borderRadius: 999, padding: "8px 16px", flexShrink: 0 }}><IconCheck size={16} /> Connected</span>
                    )}
                    {st === "signin" && (
                      <button onClick={() => openLogin(b, "signin")} style={{ border: "1px solid #0e0e10", background: "#fff", color: "#0e0e10", borderRadius: 9, padding: "8px 16px", cursor: "pointer", fontSize: 13.5, fontWeight: 700, flexShrink: 0, display: "inline-flex", alignItems: "center", gap: 8 }}
                        onMouseEnter={(e) => { e.currentTarget.style.background = "#0e0e10"; e.currentTarget.style.color = "#fff"; }} onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.color = "#0e0e10"; }}>
                        <IconLock size={15} /> Sign in to connect
                      </button>
                    )}
                    {st === "pending" && (
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, fontWeight: 700, color: "#92670b", background: "#fdf1cf", border: "1px solid #f0d98a", borderRadius: 999, padding: "8px 14px", flexShrink: 0 }}><IconClock size={15} /> Access pending</span>
                    )}
                  </div>
                  {st === "request" && (
                    <div style={{ display: "flex", gap: 8, marginTop: 14, marginLeft: 94, flexWrap: "wrap" }}>
                      <button onClick={() => requestAccess(b)} style={{ background: "#09090b", color: "#fff", border: 0, borderRadius: 8, padding: "9px 14px", fontFamily: "inherit", fontSize: 13, fontWeight: 700, cursor: "pointer" }}
                        onMouseEnter={(e) => e.currentTarget.style.background = "#dc2626"} onMouseLeave={(e) => e.currentTarget.style.background = "#09090b"}>Request access to this brand</button>
                      <button onClick={() => openLogin(b, "different-email")} style={{ background: "#fff", color: "#09090b", border: "1px solid #d4d4d8", borderRadius: 8, padding: "9px 14px", fontFamily: "inherit", fontSize: 13, fontWeight: 600, cursor: "pointer" }}
                        onMouseEnter={(e) => e.currentTarget.style.borderColor = "#09090b"} onMouseLeave={(e) => e.currentTarget.style.borderColor = "#d4d4d8"}>Sign in with a different email</button>
                    </div>
                  )}
                  {st === "signin" && (
                    <div style={{ marginTop: 10, marginLeft: 94, fontSize: 12.5, color: "#9a9aa1" }}>Used a different email for {b.name}? <button onClick={() => openLogin(b, "different-email")} style={{ border: 0, background: "transparent", padding: 0, color: "#0e0e10", fontWeight: 700, cursor: "pointer", textDecoration: "underline", textUnderlineOffset: 2, fontSize: 12.5, fontFamily: "inherit" }}>Sign in with that email</button></div>
                  )}
                </div>
                );
              })}
            </div>
          </SettingsCard>

          {/* ─── Card C — Sign-in & Security ─── */}
          <SettingsCard style={{ padding: "32px 36px" }}>
            <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Sign-in &amp; Security</h2>
            <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 24px", maxWidth: 720, lineHeight: 1.5 }}>
              {hasNativeAccount
                ? "Your Team Stores password applies only to signing in with Team Stores credentials. It never changes a Customizer password."
                : "You sign in through your Customizer, so your password lives there."}
            </p>

            <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) minmax(0,1fr)", gap: 24 }}>
              {/* Password */}
              <div style={{ border: "1px solid #ececf0", borderRadius: 12, padding: "20px 22px" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 6 }}>
                  <div style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10" }}>{hasNativeAccount ? "Team Stores password" : "Password"}</div>
                  {hasNativeAccount && pill("Native account", <IconLock size={12} />)}
                </div>
                {hasNativeAccount ? (
                  <form onSubmit={savePassword} style={{ display: "flex", flexDirection: "column", gap: 14, marginTop: 14 }}>
                    {pwInput("Current password", "current", "Enter your current password")}
                    {pwInput("New password", "next", "At least 12 characters")}
                    <ul style={{ listStyle: "none", margin: 0, padding: "12px 14px", background: "#fafafa", border: "1px solid #ececee", borderRadius: 10, display: "flex", flexDirection: "column", gap: 8 }}>
                      {rules.map((r) => (
                        <li key={r.label} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 13, color: r.ok ? "#09090b" : "#71717a" }}>
                          <span style={{ width: 18, height: 18, borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, background: r.ok ? "#16a34a" : "#fff", border: r.ok ? "none" : "1.5px solid #d4d4d8", color: "#fff" }}>{r.ok && <IconCheck size={11} />}</span>
                          {r.label}
                        </li>
                      ))}
                    </ul>
                    <button type="submit" disabled={!pwOk || pwSaving} style={{ border: 0, borderRadius: 9, padding: "13px", background: pwOk && !pwSaving ? "#0e0e10" : "#e5e5e9", color: pwOk && !pwSaving ? "#fff" : "#9a9aa1", fontSize: 14.5, fontWeight: 700, cursor: pwOk && !pwSaving ? "pointer" : "default" }}>
                      {pwSaving ? "Updating…" : "Update password"}
                    </button>
                    <div style={{ fontSize: 12.5, color: "#9a9aa1", lineHeight: 1.5 }}>Changing it signs out your other Team Stores sessions and emails a confirmation to {profile.email}.</div>
                  </form>
                ) : (
                  <div style={{ marginTop: 10 }}>
                    <p style={{ margin: "0 0 14px", fontSize: 13.5, color: "#52525b", lineHeight: 1.55 }}>Passwords can't be changed in Team Stores for Customizer-only accounts. Update it in your {primaryBrand ? primaryBrand.name : "Marucci"} Customizer account.</p>
                    <button onClick={onEditProfile} style={{ border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 9, padding: "10px 16px", cursor: "pointer", fontSize: 13.5, fontWeight: 700, display: "inline-flex", alignItems: "center", gap: 8 }}
                      onMouseEnter={(e) => { e.currentTarget.style.borderColor = "#0e0e10"; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = "#d4d4d8"; }}>
                      Open Customizer account <IconExternal size={15} style={{ color: "#9a9aa1" }} />
                    </button>
                  </div>
                )}
              </div>

              {/* Linked accounts */}
              <div style={{ border: "1px solid #ececf0", borderRadius: 12, padding: "20px 22px" }}>
                <div style={{ fontSize: 15, fontWeight: 800, color: "#0e0e10", marginBottom: 6 }}>Linked sign-in methods</div>
                <p style={{ margin: "0 0 16px", fontSize: 13.5, color: "#52525b", lineHeight: 1.55 }}>One Team Stores account, however you sign in. Stores, orders, access status and brand connections are shared across linked methods.</p>
                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", border: "1px solid #ececf0", borderRadius: 10, background: hasNativeAccount ? "#fff" : "#fafafa" }}>
                    <span style={{ width: 36, height: 36, borderRadius: 9, background: "#0e0e10", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 12, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>TS</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10" }}>Team Stores account</div>
                      <div style={{ fontSize: 12.5, color: "#6b6b72", marginTop: 1 }}>{hasNativeAccount ? profile.email : "Not set up"}</div>
                    </div>
                    {hasNativeAccount ? <span style={{ fontSize: 12.5, fontWeight: 700, color: "#1f9d55" }}>Active</span> : <span style={{ fontSize: 12.5, color: "#9a9aa1" }}>—</span>}
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", border: "1px solid #ececf0", borderRadius: 10, background: (linkedIdentity || !isNative) ? "#fff" : "#fafafa" }}>
                    <span style={{ width: 36, height: 36, borderRadius: 9, background: "#f1f1f3", border: "1px solid #e5e5e9", color: "#0e0e10", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 14, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>M</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10" }}>Customizer identity</div>
                      <div style={{ fontSize: 12.5, color: "#6b6b72", marginTop: 1 }}>{linkedIdentity ? `${linkedIdentity.brand} · ${linkedIdentity.email}` : !isNative ? `Marucci · ${profile.email}` : "Not linked"}</div>
                    </div>
                    {(linkedIdentity || !isNative) ? <span style={{ fontSize: 12.5, fontWeight: 700, color: "#1f9d55" }}>Linked</span> : (
                      <button onClick={() => { setLink({ email: "", password: "" }); setLinkStep(0); setLinkOpen(true); }} style={{ border: "1px solid #0e0e10", background: "#fff", color: "#0e0e10", borderRadius: 8, padding: "7px 12px", cursor: "pointer", fontSize: 13, fontWeight: 700, fontFamily: "inherit" }}
                        onMouseEnter={(e) => { e.currentTarget.style.background = "#0e0e10"; e.currentTarget.style.color = "#fff"; }} onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.color = "#0e0e10"; }}>Link account</button>
                    )}
                  </div>
                </div>
                <div style={{ fontSize: 12.5, color: "#9a9aa1", lineHeight: 1.5, marginTop: 14 }}>Linking requires signing in with both. Use it when your Customizer email differs from your Team Stores email.</div>
              </div>
            </div>
          </SettingsCard>

          {/* ─── Card C — Archived Stores (restore) ─── */}
          <SettingsCard style={{ padding: "32px 36px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, flexWrap: "wrap" }}>
              <div style={{ minWidth: 0 }}>
                <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0, color: "#0e0e10" }}>Archived Stores</h2>
                <p style={{ fontSize: 14, color: "#6b6b72", margin: "8px 0 0", maxWidth: 620, lineHeight: 1.5 }}>
                  Permanently shut-down stores, kept as read-only records. Order history and reports are retained. Restore a store to move it back into your active stores list.
                </p>
              </div>
              {archivedStores.length > 0 && (
                <span style={{
                  display: "inline-flex", alignItems: "center", gap: 8, fontSize: 12.5, fontWeight: 700,
                  color: "#52525b", background: "#f1f1f3", border: "1px solid #e5e5e9", borderRadius: 999,
                  padding: "6px 14px", flexShrink: 0,
                }}>
                  {archivedStores.length} archived
                </span>
              )}
            </div>

            <div style={{ display: "flex", alignItems: "flex-start", gap: 12, margin: "20px 0 4px", background: "#f7f7f8", border: "1px solid #ececf0", borderRadius: 10, padding: "14px 16px" }}>
              <span style={{ width: 30, height: 30, borderRadius: 8, background: "#fdf1cf", color: "#92670b", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                <IconLock size={15} />
              </span>
              <div style={{ fontSize: 13, color: "#52525b", lineHeight: 1.55, paddingTop: 2 }}>
                Archiving can&rsquo;t be self-reversed. Restoring an archived store is a <strong style={{ color: "#09090b", fontWeight: 700 }}>managing rep</strong> action.
              </div>
            </div>

            {archivedStores.length === 0 ? (
              <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: "40px 20px 28px", color: "#9a9aa1" }}>
                <div style={{ width: 64, height: 64, borderRadius: "50%", background: "#f5f5f7", border: "1px solid #ececf0", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}>
                  <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#a1a1aa" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                    <rect x="3" y="4" width="18" height="4" rx="1" /><path d="M5 8v11a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8" /><path d="M10 12h4" />
                  </svg>
                </div>
                <div style={{ fontSize: 14.5, fontWeight: 700, color: "#52525b" }}>No archived stores</div>
                <div style={{ fontSize: 13, color: "#9a9aa1", marginTop: 4 }}>Stores you archive from the Stores tab will appear here.</div>
              </div>
            ) : (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(248px, 1fr))", gap: 16, marginTop: 20 }}>
                {archivedStores.map((s) => (
                  <StoreCard
                    key={s.id}
                    store={s}
                    archived
                    onManage={() => onManageStore && onManageStore(s.id)}
                    onView={() => onManageStore && onManageStore(s.id)}
                    onUnarchive={() => onUnarchive && onUnarchive(s.id)}
                    onCreateTemplate={onCreateTemplate}
                  />
                ))}
              </div>
            )}
          </SettingsCard>
        </div>
      </div>

      {/* Brand connect modal */}
      <Modal open={!!loginBrand} onClose={closeLogin} width={440}>
        {loginBrand && (
          <form onSubmit={submitLogin} style={{ padding: "32px 36px 32px", position: "relative" }}>
            <button type="button" onClick={closeLogin} style={{ position: "absolute", top: 16, right: 16, border: 0, background: "transparent", cursor: "pointer", color: "#9a9aa1", width: 32, height: 32, borderRadius: 7, display: "inline-flex", alignItems: "center", justifyContent: "center" }} title="Close"><IconX size={18} /></button>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap: 16, marginBottom: 24 }}>
              <span style={{ width: 60, height: 60, borderRadius: 14, background: "#0e0e10", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 26, fontWeight: 800, fontFamily: "Archivo, sans-serif" }}>{loginBrand.brand.name[0]}</span>
              <div>
                <div style={{ fontSize: 20, fontWeight: 800, color: "#0e0e10" }}>Connect {loginBrand.brand.name}</div>
                <div style={{ fontSize: 13.5, color: "#6b6b72", marginTop: 4, lineHeight: 1.5, maxWidth: 320 }}>
                  {loginBrand.mode === "different-email" ? `Sign in with the email you use for the ${loginBrand.brand.name} Customizer.` : `Enter your ${loginBrand.brand.name} Customizer password. Team Stores reuses that account and its permissions.`}
                </div>
              </div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <label style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "#3f3f46" }}>Customizer email</label>
                <input type="email" autoFocus={loginBrand.mode === "different-email"} value={creds.email} disabled={signingIn || loginBrand.mode !== "different-email"} onChange={(e) => setCreds((c) => ({ ...c, email: e.target.value }))} placeholder="you@yourdealership.com"
                  style={{ border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, outline: "none", width: "100%", background: loginBrand.mode !== "different-email" ? "#f5f5f7" : "#fff", color: "#0e0e10" }}
                  onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <label style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "#3f3f46" }}>Customizer password</label>
                <input type="password" autoFocus={loginBrand.mode !== "different-email"} value={creds.password} disabled={signingIn} onChange={(e) => setCreds((c) => ({ ...c, password: e.target.value }))} placeholder="••••••••••••"
                  style={{ border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, outline: "none", width: "100%" }}
                  onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
              </div>
            </div>
            <button type="submit" disabled={!creds.email || !creds.password || signingIn} style={{ marginTop: 24, width: "100%", border: 0, borderRadius: 9, padding: "16px", background: (!creds.email || !creds.password || signingIn) ? "#e5e5e9" : "#0e0e10", color: (!creds.email || !creds.password || signingIn) ? "#9a9aa1" : "#fff", fontSize: 15, fontWeight: 700, cursor: (!creds.email || !creds.password || signingIn) ? "default" : "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
              {signingIn ? "Connecting…" : <React.Fragment><IconLock size={16} /> Connect brand</React.Fragment>}
            </button>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 16, fontSize: 12.5, color: "#9a9aa1" }}><IconLock size={12} /> Verified against your dealership in qx7</div>
          </form>
        )}
      </Modal>

      {/* Link accounts modal — explicit confirmation */}
      <Modal open={linkOpen} onClose={() => setLinkOpen(false)} width={460}>
        <div style={{ padding: "32px 36px", position: "relative" }}>
          <button type="button" onClick={() => setLinkOpen(false)} style={{ position: "absolute", top: 16, right: 16, border: 0, background: "transparent", cursor: "pointer", color: "#9a9aa1", width: 32, height: 32, borderRadius: 7, display: "inline-flex", alignItems: "center", justifyContent: "center" }} title="Close"><IconX size={18} /></button>
          <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", color: "#a1a1aa", textAlign: "center", marginBottom: 12 }}>Step {Math.min(linkStep + 1, 3)} of 3</div>
          <h3 style={{ margin: "0 0 8px", fontSize: 21, fontWeight: 800, color: "#0e0e10", textAlign: "center" }}>{linkStep === 2 ? "Confirm the link" : "Link your Customizer identity"}</h3>
          <p style={{ margin: "0 auto 24px", maxWidth: 360, fontSize: 14, color: "#52525b", lineHeight: 1.55, textAlign: "center" }}>
            {linkStep === 0 ? "Enter the email you use for your Marucci Customizer. We'll verify it's you by signing in."
              : linkStep === 1 ? `Enter the Customizer password for ${link.email}.`
              : "Both sign-in methods will open the same Team Stores account. Nothing is merged until you confirm."}
          </p>
          {linkStep < 2 ? (
            <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
              {linkStep === 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  <label style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "#3f3f46" }}>Customizer email</label>
                  <input type="email" autoFocus value={link.email} onChange={(e) => setLink((l) => ({ ...l, email: e.target.value }))} placeholder="you@yourdealership.com" style={{ border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, outline: "none", width: "100%" }} onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
                </div>
              )}
              {linkStep === 1 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  <label style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".05em", textTransform: "uppercase", color: "#3f3f46" }}>Customizer password</label>
                  <input type="password" autoFocus value={link.password} onChange={(e) => setLink((l) => ({ ...l, password: e.target.value }))} placeholder="••••••••••••" style={{ border: "1px solid #d4d4d8", borderRadius: 8, padding: "12px 16px", fontSize: 15, outline: "none", width: "100%" }} onFocus={(e) => e.target.style.borderColor = "#0e0e10"} onBlur={(e) => e.target.style.borderColor = "#d4d4d8"} />
                </div>
              )}
              <button onClick={() => setLinkStep(linkStep + 1)} disabled={linkStep === 0 ? !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(link.email) : !link.password} style={{ width: "100%", border: 0, borderRadius: 9, padding: 15, background: (linkStep === 0 ? /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(link.email) : !!link.password) ? "#0e0e10" : "#e5e5e9", color: (linkStep === 0 ? /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(link.email) : !!link.password) ? "#fff" : "#9a9aa1", fontSize: 15, fontWeight: 700, cursor: "pointer" }}>Continue</button>
            </div>
          ) : (
            <div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 20 }}>
                {[{ k: "Team Stores account", v: profile.email }, { k: "Marucci Customizer", v: link.email }].map((r) => (
                  <div key={r.k} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "12px 14px", border: "1px solid #ececf0", borderRadius: 10 }}>
                    <span style={{ fontSize: 13.5, fontWeight: 700, color: "#0e0e10" }}>{r.k}</span>
                    <span style={{ fontSize: 13.5, color: "#52525b" }}>{r.v}</span>
                  </div>
                ))}
              </div>
              <div style={{ display: "flex", gap: 10 }}>
                <button onClick={() => setLinkOpen(false)} style={{ flex: 1, border: "1px solid #d4d4d8", background: "#fff", color: "#0e0e10", borderRadius: 9, padding: 14, fontSize: 14.5, fontWeight: 700, cursor: "pointer" }}>Cancel</button>
                <button onClick={() => { setLinkedIdentity({ brand: "Marucci", email: link.email }); onBrandState && onBrandState("prolook", "connected"); if (!primaryId && onPrimary) onPrimary("prolook"); setLinkOpen(false); onToast && onToast("Accounts linked — sign in either way to reach this workspace"); }} style={{ flex: 1, border: 0, background: "#0e0e10", color: "#fff", borderRadius: 9, padding: 14, fontSize: 14.5, fontWeight: 700, cursor: "pointer" }}>Link accounts</button>
              </div>
            </div>
          )}
        </div>
      </Modal>
    </div>
  );
}

/* ===== Auto-sign-in · Welcome & Primary Brand modal ===== */
// Interrupts the first landing on the Team Stores overview per session. Explains
// the silent SSO hand-off from the originating brand customizer and lets multi-
// brand accounts pick their primary brand before entering the workspace.
function WelcomeSSOModal({ open, originId = "prolook", accessibleIds = ACCESSIBLE_CUSTOMIZERS, multiBrand = true, onConfirm, nativePath = false, email, brandStates = {}, onConnectBrand }) {
  const origin = CUSTOMIZER_BRANDS[originId] || CUSTOMIZER_BRANDS.prolook;
  const brands = (multiBrand ? accessibleIds : [originId]).map((id) => ({ id, ...CUSTOMIZER_BRANDS[id] })).filter((b) => b.name);
  const [primary, setPrimary] = React.useState(originId);
  React.useEffect(() => { if (open) setPrimary(originId); }, [open, originId]);
  const isMulti = !nativePath && multiBrand && brands.length > 1;
  // Native path: brands found in qx7 for the rep's email, with their connection state.
  const foundBrands = accessibleIds.map((id) => ({ id, ...CUSTOMIZER_BRANDS[id], state: brandStates[id] || "signin" })).filter((b) => b.name);
  const anyConnected = foundBrands.some((b) => b.state === "connected");

  const brandGlyph = (b, size) => (
    b.logoBlack || b.logoInk
      ? <img src={b.logoBlack || b.logoInk} alt={b.name} style={{ height: size, width: "auto", objectFit: "contain" }} />
      : <span style={{ fontSize: Math.round(size * 0.62), fontWeight: 800, letterSpacing: "-.3px", color: "#0e0e10", lineHeight: 1, textAlign: "center" }}>{b.wordmark || b.name}</span>
  );

  return (
    <Modal open={open} onClose={() => {}} width={isMulti ? 640 : 520}>
      <div style={{ padding: "40px 40px 32px", position: "relative" }}>
        {nativePath ? (
          <React.Fragment>
            <h2 style={{ margin: "0 0 12px", fontSize: 28, fontWeight: 800, letterSpacing: "-.4px", color: "#09090b", textAlign: "center", fontFamily: "Archivo, sans-serif" }}>Welcome to Team Stores</h2>
            <p style={{ margin: "0 auto", maxWidth: 440, fontSize: 15, lineHeight: 1.6, color: "#52525b", textAlign: "center" }}>
              Your account is ready. Connect the brand Customizers you're entitled to so you can add their products to your stores.
            </p>
            <div style={{ marginTop: 28 }}>
              <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", color: "#71717a", marginBottom: 12 }}>Brands found for {email}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {foundBrands.map((b) => (
                  <div key={b.id} style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 16px", background: "#fff", border: "1px solid #e4e4e7", borderRadius: 12 }}>
                    <span style={{ width: 44, height: 44, borderRadius: 10, background: "#f4f4f5", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{brandGlyph(b, 18)}</span>
                    <span style={{ flex: 1, minWidth: 0 }}>
                      <span style={{ display: "block", fontSize: 15, fontWeight: 800, color: "#09090b" }}>{b.name}</span>
                      <span style={{ display: "block", fontSize: 12.5, color: "#71717a", marginTop: 2 }}>
                        {b.state === "connected" ? `Connected · reuses your ${b.name} Customizer account` : b.state === "request" ? "No Customizer account for your email yet" : b.state === "pending" ? "Access request sent to Prolook" : "Customizer account found for your email"}
                      </span>
                    </span>
                    {b.state === "connected" ? (
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12.5, fontWeight: 700, color: "#1f9d55", background: "#e7f5ed", border: "1px solid #c7ead4", borderRadius: 999, padding: "7px 12px" }}><IconCheck size={14} /> Connected</span>
                    ) : b.state === "pending" ? (
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12.5, fontWeight: 700, color: "#92670b", background: "#fdf1cf", border: "1px solid #f0d98a", borderRadius: 999, padding: "7px 12px" }}><IconClock size={14} /> Access pending</span>
                    ) : (
                      <button onClick={() => onConnectBrand && onConnectBrand(b.id)} style={{ background: "#fff", color: "#09090b", border: "1px solid #09090b", borderRadius: 8, padding: "8px 14px", fontFamily: "inherit", fontSize: 13, fontWeight: 700, cursor: "pointer" }}
                        onMouseEnter={(e) => { e.currentTarget.style.background = "#09090b"; e.currentTarget.style.color = "#fff"; }} onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.color = "#09090b"; }}>
                        {b.state === "request" ? "Request access" : "Connect"}
                      </button>
                    )}
                  </div>
                ))}
              </div>
              <p style={{ margin: "16px 0 0", fontSize: 12.5, lineHeight: 1.5, color: "#a1a1aa", textAlign: "center" }}>
                {anyConnected ? "Set your primary brand anytime from My Account." : "No primary brand is set until you connect one. You can connect brands later from My Account."}
              </p>
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 32 }}>
              <button onClick={() => onConfirm(anyConnected ? (foundBrands.find((b) => b.state === "connected") || {}).id : null)} style={{ border: 0, borderRadius: 9, padding: "16px 32px", background: "#09090b", color: "#fff", fontSize: 15, fontWeight: 700, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8 }}
                onMouseEnter={(e) => e.currentTarget.style.background = "#dc2626"} onMouseLeave={(e) => e.currentTarget.style.background = "#09090b"}>
                Continue to Workspace <IconArrowRight size={17} />
              </button>
            </div>
          </React.Fragment>
        ) : (
        <React.Fragment>
        {/* SSO badge */}
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
          <span style={{
            display: "inline-flex", alignItems: "center", gap: 8, background: "#e7f5ed", border: "1px solid #c7ead4",
            color: "#1f9d55", borderRadius: 999, padding: "8px 16px", fontSize: 12.5, fontWeight: 700, letterSpacing: ".03em",
          }}>
            <IconCircleCheck size={15} /> Signed in automatically
          </span>
        </div>

        <h2 style={{ margin: "0 0 12px", fontSize: 28, fontWeight: 800, letterSpacing: "-.4px", color: "#09090b", textAlign: "center", fontFamily: "Archivo, sans-serif" }}>
          Welcome to Team Stores
        </h2>
        <p style={{ margin: "0 auto", maxWidth: 440, fontSize: 15, lineHeight: 1.6, color: "#52525b", textAlign: "center" }}>
          We've automatically signed you in using your <strong style={{ color: "#09090b", fontWeight: 700 }}>{origin.name}</strong> Customizer account and set it as your primary brand for this workspace session.
        </p>

        {isMulti ? (
          <div style={{ marginTop: 32 }}>
            <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", color: "#71717a", marginBottom: 16 }}>Primary Brand Selection</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
              {brands.map((b) => {
                const on = primary === b.id;
                return (
                  <button key={b.id} onClick={() => setPrimary(b.id)} title={b.name} style={{
                    position: "relative", aspectRatio: "1 / 1", display: "flex", flexDirection: "column",
                    alignItems: "center", justifyContent: "center", gap: 8, padding: 12,
                    background: on ? "#fff" : "#f4f4f5", border: `2px solid ${on ? "#09090b" : "#f4f4f5"}`,
                    borderRadius: 14, cursor: "pointer", transition: "border-color .12s, background .12s",
                  }}
                    onMouseEnter={(e) => { if (!on) { e.currentTarget.style.borderColor = "#d4d4d8"; e.currentTarget.style.background = "#fff"; } }}
                    onMouseLeave={(e) => { if (!on) { e.currentTarget.style.borderColor = "#f4f4f5"; e.currentTarget.style.background = "#f4f4f5"; } }}>
                    {on && <span style={{ position: "absolute", top: 8, right: 8, width: 20, height: 20, borderRadius: "50%", background: "#09090b", color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center" }}><IconCheck size={13} /></span>}
                    <span style={{ height: 32, display: "flex", alignItems: "center" }}>{brandGlyph(b, 22)}</span>
                    <span style={{ fontSize: 11.5, fontWeight: 600, color: "#52525b", textAlign: "center", lineHeight: 1.2 }}>{b.name}</span>
                  </button>
                );
              })}
            </div>
            <p style={{ margin: "16px 0 0", fontSize: 12.5, color: "#a1a1aa", textAlign: "center" }}>You can change your primary brand anytime from My Account.</p>
          </div>
        ) : (
          <div style={{ marginTop: 28 }}>
            <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", color: "#71717a", marginBottom: 12, textAlign: "center" }}>Your Primary Brand</div>
            <div style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: 16,
              background: "#f7f7f8", border: "1px solid #ececf0", borderRadius: 14, padding: "16px 24px", maxWidth: 340, margin: "0 auto",
            }}>
              <span style={{ height: 32, display: "flex", alignItems: "center" }}>{brandGlyph(origin, 24)}</span>
              <span style={{ width: 1, height: 28, background: "#e4e4e7" }} />
              <span style={{ fontSize: 15.5, fontWeight: 800, color: "#0e0e10" }}>{origin.name}</span>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 4, color: "#1f9d55", fontSize: 12.5, fontWeight: 700 }}><IconCircleCheck size={15} /> Primary</span>
            </div>
          </div>
        )}

        {/* CTA */}
        <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 32 }}>
          <button onClick={() => onConfirm(primary)} style={{
            border: 0, borderRadius: 9, padding: "16px 32px", background: "#09090b", color: "#fff",
            fontSize: 15, fontWeight: 700, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 8,
          }}
            onMouseEnter={(e) => e.currentTarget.style.background = "#dc2626"}
            onMouseLeave={(e) => e.currentTarget.style.background = "#09090b"}>
            {isMulti ? "Confirm & Enter" : "Continue to Workspace"} <IconArrowRight size={17} />
          </button>
        </div>
        </React.Fragment>
        )}
      </div>
    </Modal>
  );
}

function App() {
  const [tweaks, setTweak] = useTweaks(TWEAK_DEFAULTS);
  const frameRoute = React.useMemo(getFrameRoute, []);
  const isFrameRoute = !!frameRoute;

  // expose a global so deep components can route here without prop-drilling
  React.useEffect(() => {
    window.__openMyCarts = () => setScreen("my-carts");
    window.__openSavedDesigns = () => setScreen("saved-designs");
    return () => { delete window.__openMyCarts; delete window.__openSavedDesigns; };
  });

  // Global hook to kick off the onboarding demo (also used by the Tweak button).
  React.useEffect(() => {
    window.__startOnboardingDemo = () => startOnboardingDemo();
    return () => { delete window.__startOnboardingDemo; };
  });

  // State machine: overview | gate | list | leagues | empty | form | loading | dashboard | customizer
  // The Team Stores landing page is the entry point; reps arrive already on Overview.
  // A signed-in rep whose dealership has no access is handed off from the landing
  // page with ?access=none and lands straight on the business-details form.
  const [screen, setScreen] = React.useState(() => {
    try { if (new URLSearchParams(window.location.search).get("access") === "none") return "access-form"; } catch (e) {}
    return "overview";
  });
  const [navTab, setNavTab] = React.useState("overview");
  // Auto-sign-in welcome: originating brand comes from the ?brand= hand-off param
  // (falls back to the tweak). Interrupts the first overview landing per session.
  const ssoOriginId = React.useMemo(() => {
    try { const b = new URLSearchParams(window.location.search).get("brand"); if (b && CUSTOMIZER_BRANDS[b]) return b; } catch (e) {}
    return tweaks.ssoOriginBrand || "prolook";
  }, [tweaks.ssoOriginBrand]);
  // Sign-in method (Landing Page Epics A/D/E). Native reps have no primary brand
  // until they connect one; Customizer-path reps arrive with their origin brand connected.
  const authMode = React.useMemo(getAuthMode, []);
  const isNative = authMode === "native" || authMode === "native-new";
  const isLinked = authMode === "linked";
  React.useEffect(() => { try { sessionStorage.setItem("ts_auth_mode", authMode); } catch (e) {} }, [authMode]);
  // Brand connection state per entitled brand: connected | signin | request | pending
  const [brandStates, setBrandStates] = React.useState(() => {
    const init = {};
    ACCOUNT_BRANDS.forEach((b) => { init[b.id] = b.state; });
    if (!isNative) init[ssoOriginId] = "connected";
    return init;
  });
  const setBrandState = (id, state) => setBrandStates((s) => ({ ...s, [id]: state }));
  // First visit after native sign-up: show the native welcome (connect brands).
  const [showWelcome, setShowWelcome] = React.useState(() => {
    try { return authMode === "native-new" && !sessionStorage.getItem("ts_sso_welcomed") && new URLSearchParams(window.location.search).get("access") !== "none"; } catch (e) { return false; }
  });
  const [primaryBrand, setPrimaryBrand] = React.useState(() => isNative ? null : ssoOriginId);
  const confirmWelcome = (chosen) => {
    setPrimaryBrand(isNative ? (chosen || null) : (chosen || ssoOriginId));
    setShowWelcome(false);
    try { sessionStorage.setItem("ts_sso_welcomed", "1"); } catch (e) {}
  };
  const primaryBrandMeta = primaryBrand ? CUSTOMIZER_BRANDS[primaryBrand] : null;
  const openPrimaryCustomizer = () => {
    if (!primaryBrand) { setNavTab("overview"); setScreen("account"); setToast("Connect a brand and set it as primary to open its Customizer"); return; }
    if (brandStates[primaryBrand] !== "connected") { setNavTab("overview"); setScreen("account"); setToast(`${primaryBrandMeta.name} isn't connected yet — connect it from My Account`); return; }
    window.open(`https://customizer.${primaryBrand}.com`, "_blank", "noopener");
    setToast(`Opening ${primaryBrandMeta.name} Customizer in a new tab…`);
  };
  const signOut = () => { try { sessionStorage.removeItem("ts_sso_welcomed"); sessionStorage.removeItem("ts_auth_mode"); } catch (e) {} window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); };
  // Session grant: a no-access user who passes the splash unlocks Team Stores
  // for the rest of the session.
  const [gatePassed, setGatePassed] = React.useState(false);
  const [showTaxModal, setShowTaxModal] = React.useState(false);
  const [showCancelModal, setShowCancelModal] = React.useState(false);
  const [pendingNav, setPendingNav] = React.useState(null);
  const [pendingData, setPendingData] = React.useState(null);
  const [stores, setStores] = React.useState(() => makeSeededStores());
  const [activeStoreId, setActiveStoreId] = React.useState(null);
  const [toast, setToast] = React.useState(null);
  const [presetData, setPresetData] = React.useState(null);
  const [portalView, setPortalView] = React.useState(null); // TM portal preview (2.1)
  React.useEffect(() => { window.__openTmPortal = (inv, st) => setPortalView({ invite: inv, store: st }); return () => { delete window.__openTmPortal; }; }, []);
  const [showTemplateModal, setShowTemplateModal] = React.useState(false);
  const [templateMode, setTemplateMode] = React.useState(false);
  const [dashboardTab, setDashboardTab] = React.useState("general");
  const [leagues, setLeagues] = React.useState(() => makeSampleLeagues());
  const [activeLeagueId, setActiveLeagueId] = React.useState(null);
  const [activeGroupId, setActiveGroupId] = React.useState(null);
  const [showLeagueModal, setShowLeagueModal] = React.useState(false);
  const [showGroupModal, setShowGroupModal] = React.useState(false);
  const [userTemplates, setUserTemplates] = React.useState(() => loadUserTemplates());
  const [createTplStore, setCreateTplStore] = React.useState(null);

  // ─── Onboarding "Launchpad" tour ───
  // is_first_store: global flag. The guided tour runs only while it's true; it
  // flips permanently to false once the tour is dismissed or completed.
  const [isFirstStore, setIsFirstStore] = React.useState(() => {
    try { return localStorage.getItem("prolook_is_first_store") !== "false"; } catch (e) { return true; }
  });
  const [tourRun, setTourRun] = React.useState(false);
  const persistFirstStore = (v) => {
    setIsFirstStore(v);
    try { localStorage.setItem("prolook_is_first_store", v ? "true" : "false"); } catch (e) {}
  };
  const endTour = () => { setTourRun(false); persistFirstStore(false); };

  // Route a checklist step to the feature that completes it.
  const handleChecklistStep = (stepId) => {
    setScreen("dashboard");
    if (stepId === "product-added" || stepId === "product-published") {
      setDashboardTab("products");
      setTimeout(() => window.__goToDashTab && window.__goToDashTab("products"), 30);
    } else if (stepId === "roster") {
      setDashboardTab("roster");
      setTimeout(() => window.__goToDashTab && window.__goToDashTab("roster"), 30);
    } else if (stepId === "launch") {
      setDashboardTab("general");
      setTimeout(() => { window.__goToDashTab && window.__goToDashTab("general"); window.__openLaunchModal && window.__openLaunchModal(); }, 60);
    }
  };

  // ─── Frame routing: hydrate state for the requested deep-link ───
  React.useEffect(() => {
    if (!frameRoute) return;
    const seeded = makeSeedStores();
    const firstId = seeded[0]?.id;

    switch (frameRoute) {
      case "empty":
        setStores([]);
        setScreen("empty");
        break;
      case "form":
        setStores([]);
        setPresetData(makePrefill());
        setScreen("form");
        break;
      case "form-tax":
        setStores([]);
        setPresetData(makePrefill());
        setScreen("form");
        setPendingData(makePrefill());
        setShowTaxModal(true);
        break;
      case "loading":
        setStores([]);
        setScreen("loading");
        break;
      case "portal":
        setStores(seeded);
        setScreen("portal");
        break;
      case "list":
        setStores(seeded);
        setScreen("list");
        break;
      case "dashboard-general":
        setStores(seeded);
        setActiveStoreId(firstId);
        setDashboardTab("general");
        setScreen("dashboard");
        break;
      case "dashboard-products-empty": {
        setStores(seeded);
        setActiveStoreId(firstId);
        setDashboardTab("products");
        setScreen("dashboard");
        break;
      }
      case "dashboard-products-configure": {
        const withPending = seeded.map((s, i) =>
          i === 0
            ? {
                ...s,
                pendingProducts: [
                  { __pendingId: "p-1", title: "Custom Football Jersey — Home", subtitle: "Sublimated Set-In, Full Button Jersey", source: "cart" },
                  { __pendingId: "p-2", title: "Custom Football Jersey — Away", subtitle: "Sublimated Set-In, 2-Button Jersey", source: "cart" },
                ],
              }
            : s
        );
        setStores(withPending);
        setActiveStoreId(firstId);
        setDashboardTab("products");
        setScreen("dashboard");
        break;
      }
      case "dashboard-products-drafts": {
        const withDrafts = seeded.map((s, i) =>
          i === 0
            ? {
                ...s,
                products: [
                  { id: "pr-1", title: "Custom Football Jersey — Home", subtitle: "Sublimated Set-In, Full Button Jersey", status: "published", teamSetting: "team-required" },
                  { id: "pr-2", title: "Custom Football Jersey — Away", subtitle: "Sublimated Set-In, 2-Button Jersey", status: "draft" },
                  { id: "pr-3", title: "Performance Hoodie",          subtitle: "Sublimated Traditional, Full-Length, Elastic Cuff Pant", status: "draft" },
                ],
              }
            : s
        );
        setStores(withDrafts);
        setActiveStoreId(firstId);
        setDashboardTab("products");
        setScreen("dashboard");
        break;
      }
      case "customizer":
        setStores(seeded);
        setActiveStoreId(firstId);
        setScreen("customizer");
        break;
      case "my-carts":
        setStores(seeded);
        setActiveStoreId(firstId);
        setScreen("my-carts");
        break;
      case "saved-designs":
        setStores(seeded);
        setActiveStoreId(firstId);
        setScreen("saved-designs");
        break;
      default:
        break;
    }
    // eslint-disable-next-line
  }, [frameRoute]);

  const updateStore = (id, patch) => {
    setStores((arr) => arr.map((s) => s.id === id ? { ...s, ...patch } : s));
  };

  // Archive confirmation triggered from a store card's actions menu.
  const [archiveTargetId, setArchiveTargetId] = React.useState(null);
  const archiveTargetStore = stores.find((s) => s.id === archiveTargetId);
  const [copyTargetId, setCopyTargetId] = React.useState(null);
  const copyTargetStore = stores.find((s) => s.id === copyTargetId);
  // Restore confirmation triggered from the My Account archived-stores list.
  const [restoreTargetId, setRestoreTargetId] = React.useState(null);
  const restoreTargetStore = stores.find((s) => s.id === restoreTargetId);
  const activeStores = stores.filter((s) => !s.archived);
  const archivedStores = stores.filter((s) => s.archived);

  const handleLaunch = (id) => {
    updateStore(id, { live: true, status: "active" });
    setToast("Your store is now live");
    // Milestone 3 signal for the onboarding tour.
    window.dispatchEvent(new CustomEvent("tour:store-live"));
  };
  const handleSetStatus = (id, status) => {
    updateStore(id, { status });
    setToast(status === "hold" ? "Store put on hold" : "Store is active again");
  };
  const handleViewStore = (s) => {
    setToast(`Opening ${s.teamName || s.storeTitle} storefront…`);
  };

  const addPendingToStore = (storeId, pendingItems) => {
    setStores((arr) => arr.map((s) => {
      if (s.id !== storeId) return s;
      const withIds = pendingItems.map((p, i) => ({
        ...p,
        __pendingId: p.__pendingId || `pending-${Date.now()}-${i}-${Math.floor(Math.random() * 1e6)}`,
      }));
      return { ...s, pendingProducts: [...(s.pendingProducts || []), ...withIds] };
    }));
  };

  const goCreate = () => {
    setPresetData(makePrefill());
    setTemplateMode(false);
    setShowTemplateModal(true);
  };

  const handleCreateLeague = (league) => {
    // Normalize step-2 group names into group objects so they share a shape
    // with groups created later from inside the league via "Add Group".
    const groups = (league.groups || []).map((g, i) =>
      typeof g === "string"
        ? { id: "group-" + Date.now() + "-" + i, name: g, storeIds: [] }
        : g
    );
    setLeagues((arr) => [...arr, {
      ...league,
      groups,
      location: league.location || "Perrisville, CA",
      avatarColor: "#1d3a8a",
      members: league.members || [
        { id: "m-owner", name: "Matt Passmore", email: "matt@prolook.com", role: "Owner", color: "#1f9d55" },
        { id: "m-admin", name: "Stevie Nicks", email: "stevie@prolook.com", role: "Admin", color: "#9a6a1e" },
        { id: "m-mgr", name: "George Lin", email: "george@prolook.com", role: "Manager", color: "#1d3a8a" },
      ],
    }]);
    setShowLeagueModal(false);
    setActiveLeagueId(league.id);
    setActiveGroupId(null);
    setScreen("list");
    setToast(`League "${league.name}" created`);
  };

  const handleCreateGroup = (leagueId, group) => {
    setLeagues((arr) => arr.map((l) =>
      l.id === leagueId ? { ...l, groups: [...(l.groups || []), group] } : l
    ));
    setShowGroupModal(false);
    setToast(`Group "${group.name}" created`);
  };

  const handleUpdateLeague = (leagueId, patch, silent) => {
    setLeagues((arr) => arr.map((l) => l.id === leagueId ? { ...l, ...patch } : l));
  };

  const handleDeleteLeague = (leagueId) => {
    setLeagues((arr) => arr.filter((l) => l.id !== leagueId));
    setActiveLeagueId(null);
    setActiveGroupId(null);
    setScreen("list");
    setToast("League deleted");
  };

  const seedDummyData = () => {
    setStores(makeSeededStores());
    setActiveStoreId(null);
    setLeagues(makeSampleLeagues());
    setActiveLeagueId(null);
    setActiveGroupId(null);
    setScreen("overview");
    setNavTab("overview");
  };

  const clearAll = () => {
    setStores([]);
    setLeagues([]);
    setActiveLeagueId(null);
    setActiveGroupId(null);
    setActiveStoreId(null);
    setScreen("empty");
  };

  const toggleSeed = (v) => {
    setTweak("seedData", v);
    if (v) seedDummyData(); else clearAll();
  };

  // Wipe everything — stores, leagues, active selection, and any running tour —
  // and return to the empty state.
  const clearAllData = () => {
    setTweak("seedData", false);
    setTourRun(false);
    setLeagues([]);
    setActiveLeagueId(null);
    setActiveGroupId(null);
    clearAll();
    setToast("Cleared all dummy data");
  };

  // The 6-step wizard collects compliance + tax in-flow (Step 4) and audits it
  // (Step 6), so deploying goes straight to the loading → finalize path. The
  // standalone SalesTaxModal is retained for the "form-tax" deep-link frame.
  const handleFormSubmit = (data) => {
    setPendingData(data);
    setScreen("loading");
    setTimeout(() => finalizeStore(data), 1800);
  };

  const handleTaxConfirm = () => {
    setShowTaxModal(false);
    setScreen("loading");
    setTimeout(() => finalizeStore(pendingData), 1800);
  };

  const finalizeStore = (data) => {
    const id = "store-" + Date.now();
    const newStore = {
      id, ...data,
      __fresh: true,
      ownership: "mine", // created by the active session user
      revenue: Math.round((Math.random() * 1200 + 200) * 100) / 100,
    };
    setStores((s) => [...s, newStore]);
    setActiveStoreId(id);
    setDashboardTab("general");
    setScreen("dashboard");
    setToast("Store created successfully");
    // First-ever store → launch the contextual onboarding tour.
    if (isFirstStore) setTourRun(true);
  };

  // Tweak helper: spin up a blank fresh store and start the tour immediately,
  // so the onboarding can be demoed without walking the whole create form.
  const startOnboardingDemo = () => {
    const id = "store-" + Date.now();
    const newStore = { ...makePrefill(), id, __fresh: true, products: [], pendingProducts: [], revenue: 0 };
    setStores((s) => [...s, newStore]);
    setActiveStoreId(id);
    setDashboardTab("general");
    setScreen("dashboard");
    persistFirstStore(true);
    setTourRun(true);
  };

  const handleCancel = () => setShowCancelModal(true);

  const handleSaveTemplate = (tpl) => {
    setUserTemplates((list) => { const next = [tpl, ...list]; saveUserTemplates(next); return next; });
    setCreateTplStore(null);
    setToast(`"${tpl.name}" saved to your templates`);
  };
  const confirmCancel = () => {
    setShowCancelModal(false);
    setTemplateMode(false);
    if (pendingNav) { const fn = pendingNav; setPendingNav(null); fn(); return; }
    setScreen(stores.length > 0 ? "list" : "empty");
  };

  const activeStore = stores.find((s) => s.id === activeStoreId);
  const sidebarTeams = stores.map((s) => ({
    id: s.id,
    name: s.teamName || s.storeTitle,
    color: s.teamColors?.[0] || "#e1251b",
    initial: (s.teamName || s.storeTitle || "T")[0],
  }));

  // ─── prolook.com header navigation ───
  const canAccessStores = tweaks.hasStoreAccess || gatePassed || tweaks.bypassGate;
  const TEAM_STORES_SCREENS = ["gate", "access-form", "access-pending", "stripe-verify", "portal", "overview", "orders", "list", "leagues", "league-settings", "empty", "form", "template", "loading", "account"];

  const goTeamStores = () => {
    // Reps land straight on the Team Stores Overview (the standalone landing page replaced the portal).
    setNavTab("overview"); setActiveLeagueId(null); setActiveGroupId(null); setScreen("overview");
  };
  // Header items: Discover + the (unbuilt) Build menus return to the Overview.
  const onNavigate = (id) => {
    if (id === "team-stores") goTeamStores();
    else setScreen("overview");
  };

  // ─── Team Stores section sub-tabs (Overview / Stores / Leagues) ───
  const onTabChange = (id) => {
    if (id === "overview") { setNavTab("overview"); setScreen("overview"); }
    else if (id === "stores") { setNavTab("stores"); setActiveLeagueId(null); setActiveGroupId(null); setScreen((tweaks.zeroState || stores.length) ? "list" : "empty"); }
    else if (id === "leagues") { setNavTab("leagues"); setActiveLeagueId(null); setActiveGroupId(null); setScreen("leagues"); }
    else if (id === "vault") { setNavTab("vault"); setScreen("vault"); }
    else if (id === "wsettings") { setNavTab("wsettings"); setActiveLeagueId(null); setActiveGroupId(null); setScreen("wsettings"); }
  };
  React.useEffect(() => { window.__goWorkspaceSettings = (sec) => { window.__wsSettingsInitial = sec; onNavigate("wsettings"); }; });
  const goStores = () => onTabChange("stores");
  const goLeagues = () => onTabChange("leagues");

  // Toggling the access tweak should be immediately demonstrable: revoking it
  // drops a user sitting in Team Stores back to the splash; granting it lets
  // them in from the splash.
  const setStoreAccess = (v) => {
    setTweak("hasStoreAccess", v);
    setGatePassed(false);
    if (!v && TEAM_STORES_SCREENS.includes(screen)) { setNavTab("overview"); setScreen("gate"); }
    if (v && (screen === "gate" || screen === "access-form" || screen === "access-pending")) { setNavTab("overview"); setScreen("overview"); }
  };
  const unlockFromGate = (msg) => { setGatePassed(true); setNavTab("overview"); setActiveLeagueId(null); setActiveGroupId(null); setScreen("overview"); setToast(msg); };

  // Store-editor screens drop the storefront chrome entirely.
  const inEditor = screen === "dashboard" || screen === "customizer";
  const headerActive = inEditor ? "none" : (screen === "home" ? "none" : "team-stores");
  const showSubTabs = !inEditor && (screen === "wsettings" || screen === "vault" || screen === "overview" || screen === "orders" || screen === "leagues" || screen === "empty" || screen === "account" || screen === "form" || screen === "template" || screen === "template-repo" || (screen === "list" && !activeLeagueId));
  const activeSubTab = screen === "wsettings" ? "wsettings" : screen === "vault" ? "vault" : (screen === "form" || screen === "template" || screen === "template-repo") ? "stores" : (screen === "account" ? "account" : ((screen === "overview" || screen === "orders") ? "overview" : (screen === "leagues" ? "leagues" : "stores")));
  const topLevelStoreCount = stores.filter((s) => s.kind !== "fan").length;
  const inCreateFlow = screen === "form" || screen === "template" || screen === "template-repo";
  const guardNav = (fn) => { if (inCreateFlow) { setPendingNav(() => fn); setShowCancelModal(true); } else { fn(); } };

  // ─── Overview mode short-circuit (top-level app only, never inside an iframe) ───
  if (tweaks.overviewMode && !isFrameRoute) {
    return (
      <React.Fragment>
        <OverviewGrid onExit={() => setTweak("overviewMode", false)} />
        <TweaksPanel title="Tweaks">
          <TweakSection label="View">
            <TweakToggle label="Frame overview" value={tweaks.overviewMode} onChange={(v) => setTweak("overviewMode", v)} />
            <TweakToggle label="Has Team Stores access" value={tweaks.hasStoreAccess} onChange={setStoreAccess} />
            <TweakToggle label="Bypass compliance gate" value={tweaks.bypassGate} onChange={(v) => setTweak("bypassGate", v)} />
            <TweakToggle label="Seed dummy data" value={tweaks.seedData} onChange={toggleSeed} />
            <TweakButton label="Clear all dummy data" secondary onClick={clearAllData} />
          </TweakSection>
        </TweaksPanel>
      </React.Fragment>
    );
  }

  // ─── No-access flow short-circuit ───
  // The gate, the application form, and the manual-review pending state are
  // full-viewport standalone pages (no prolook.com shell) — they sit BETWEEN
  // the brand site and the tools.
  if ((screen === "gate" || screen === "access-form" || screen === "access-pending" || screen === "stripe-verify") && !isFrameRoute) {
    return (
      <React.Fragment>
        {screen === "gate" && (
          <div style={{ minHeight: "100vh", background: "#fbfbfc", minWidth: 1280, display: "flex", flexDirection: "column" }}>
            <TeamStoresHeader
              active=""
              onChange={() => {}}
              accountName={`${ACCOUNT_PROFILE.firstName} ${ACCOUNT_PROFILE.lastName}`}
              onAccount={() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); }}
              onGoLanding={() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); }}
            />
            <div style={{ display: "flex", minHeight: "calc(100vh - 92px)" }}>
              <FeatureGate
                embedded
                onApply={() => setScreen("access-form")}
                onBypass={() => unlockFromGate("Verified — welcome to Team Stores")}
                onBack={() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); }}
              />
            </div>
          </div>
        )}
        {screen === "access-form" && (
          <AccessApplyForm
            email={ACCOUNT_PROFILE.email}
            onSubmit={() => setScreen("access-pending")}
            onCancel={() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); }}
          />
        )}
        {screen === "stripe-verify" && (
          <StripeVerifying
            onDone={() => unlockFromGate("Verified with Stripe \u2014 welcome to Team Stores")}
          />
        )}
        {screen === "access-pending" && (
          <AccessPending
            email={ACCOUNT_PROFILE.email}
            onApprove={() => unlockFromGate("Access approved — welcome to Team Stores")}
            onBack={() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); }}
          />
        )}
        <Toast message={toast} onDone={() => setToast(null)} />
        <TweaksPanel title="Tweaks">
          <TweakSection label="Access">
            <TweakToggle label="Has Team Stores access" value={tweaks.hasStoreAccess} onChange={setStoreAccess} />
            <TweakToggle label="Bypass compliance gate" value={tweaks.bypassGate} onChange={(v) => setTweak("bypassGate", v)} />
          </TweakSection>
          <TweakSection label="No-access flow">
            <TweakButton label="▶  Gate landing" onClick={() => setScreen("gate")} />
            <TweakButton label="▶  Stripe business registration" onClick={() => setScreen("access-form")} />
            <TweakButton label="▶  Pending Prolook review" onClick={() => setScreen("access-pending")} />
          </TweakSection>
        </TweaksPanel>
      </React.Fragment>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "#fbfbfc", minWidth: 1280 }}>
      {portalView && <TeamManagerPortal invite={portalView.invite} store={portalView.store} onExit={() => setPortalView(null)} />}
      {!inEditor && !showSubTabs && <UtilityBar />}
      <PlatformVaultOverlay />
      {!inEditor && !showSubTabs && <GlobalHeader active={headerActive} onNavigate={(id) => guardNav(() => onNavigate(id))} hideAccountCart={showSubTabs} />}
      {showSubTabs && (
        <TeamStoresHeader
          active={activeSubTab}
          onChange={(id) => guardNav(() => onTabChange(id))}
          accountName={`${ACCOUNT_PROFILE.firstName} ${ACCOUNT_PROFILE.lastName}`}
          primaryBrandName={primaryBrandMeta ? primaryBrandMeta.name : null}
          primaryConnected={!!primaryBrand && brandStates[primaryBrand] === "connected"}
          onOpenCustomizer={() => guardNav(openPrimaryCustomizer)}
          onWorkspaceSettings={() => guardNav(() => onTabChange("wsettings"))}
          onSignOut={signOut}
          onAccount={() => guardNav(() => { setNavTab("overview"); setActiveLeagueId(null); setActiveGroupId(null); setScreen("account"); })}
          onGoLanding={() => guardNav(() => { window.location.href = encodeURI("Marucci Team Stores Landing.dc.html"); })}
        />
      )}
      <div key={screen} style={{ display: "flex", minHeight: inEditor ? "100vh" : "calc(100vh - 114px)", animation: "pageIn .22s ease-out both" }}>
        {screen === "home" && <ProlookHome onShopTeamStores={goTeamStores} />}
        {screen === "portal" && (
          <TeamStoresPortal
            onEnter={() => { if (canAccessStores) { setNavTab("overview"); setScreen("overview"); } else { setScreen("gate"); } }}
            headlineKey={tweaks.portalHeadline}
            heroVariant={tweaks.portalHero}
            ctaLabel={tweaks.portalCta === "dashboard" ? "Go to Dashboard" : "Enter Store Manager"}
            ctaColor={tweaks.portalCtaColor}
          />
        )}
        {screen === "vault" && <PlatformVaultPage
          stores={activeStores}
          onOpenStore={(id) => { recordStoreVisit(id); setActiveStoreId(id); setDashboardTab("products"); setScreen("dashboard"); }}
          onDeployToStore={(dest, items) => {
            // 9c — Vault items land in an existing store as drafts flagged for confirmation.
            const target = stores.find((s) => s.id === dest.id);
            const added = items.map((v, i) => ({
              id: "dep-" + v.id + "-" + (Date.now() + i), title: v.title, brand: v.brand, source: v.source,
              category: v.category || "Fleece", stock: "in", deco: "approved", decoratable: true, photo: v.photo,
              status: "draft", srcKind: "vault", teamSetting: "fan-gear",
              subtitle: "From Vault · confirm pricing, setting & sizes",
            }));
            updateStore(dest.id, { products: [...((target && target.products) || []), ...added] });
            recordStoreVisit(dest.id);
            setActiveStoreId(dest.id);
            setDashboardTab("products");
            setScreen("dashboard");
            setToast(added.length + (added.length === 1 ? " Vault item" : " Vault items") + " deployed to " + (dest.storeTitle || dest.teamName) + " — confirm pricing, team setting & sizes");
          }}
          onStartStore={(items) => {
          // 1.1 — Vault multi-select → store creation at Step 1 with Step 2 pre-complete.
          setPresetData({
            ...makePrefill(),
            _fromVault: true,
            curatedProducts: items.map((v) => ({ id: "wv-" + v.id, srcId: v.id, title: v.title, subtitle: "From Vault · confirm pricing, setting & sizes", status: "draft", teamSetting: "fan-gear", rosters: [], photo: v.photo, letter: v.letter, brand: v.brand, source: v.source, sku: v.sku })),
          });
          setTemplateMode(false);
          setNavTab("stores");
          setScreen("form");
        }} />}
        {screen === "overview" && (
          <OverviewDashboard
            isEmpty={tweaks.overviewEmpty || tweaks.zeroState}
            stores={activeStores}
            leagues={leagues}
            onManageStore={(id, tab) => { recordStoreVisit(id); setActiveStoreId(id); setDashboardTab(tab || "roster"); setScreen("dashboard"); }}
            onGoStores={goStores}
            onViewOrders={() => { setNavTab("overview"); setScreen("orders"); }}
            onAdd={goCreate}
          />
        )}
        {screen === "orders" && (
          <OrdersOverview
            stores={stores}
            onBack={() => { setNavTab("overview"); setScreen("overview"); }}
          />
        )}
        {screen === "leagues" && (
          <LeaguesGrid
            leagues={leagues}
            stores={stores}
            onOpenLeague={(id) => { setNavTab("leagues"); setActiveLeagueId(id); setActiveGroupId(null); setScreen("list"); }}
            onAddLeague={() => setShowLeagueModal(true)}
          />
        )}
        {screen === "empty" && <EmptyState onCreate={goCreate} />}
        {screen === "wsettings" && <WorkspaceSettings stores={stores} />}
        {screen === "account" && (
          <AccountProfile
            authMode={authMode}
            brandStates={brandStates}
            onBrandState={setBrandState}
            primaryId={primaryBrand}
            onPrimary={setPrimaryBrand}
            onEditProfile={() => { window.open("https://customizer.prolook.com/account", "_blank", "noopener"); setToast("Opening Product Customizer account settings in a new tab…"); }}
            onToast={setToast}
            archivedStores={archivedStores}
            onManageStore={(id) => { setActiveStoreId(id); setDashboardTab("roster"); setScreen("dashboard"); }}
            onUnarchive={(id) => setRestoreTargetId(id)}
            onCreateTemplate={(s) => setCreateTplStore(s)}
          />
        )}        {screen === "list" && (
          <StoreList
            stores={activeStores}
            zeroState={tweaks.zeroState}
            onAdd={goCreate}
            onAddLeague={() => setShowLeagueModal(true)}
            onAddGroup={() => setShowGroupModal(true)}
            onManage={(id) => { recordStoreVisit(id); setActiveStoreId(id); setDashboardTab("roster"); setScreen("dashboard"); }}
            onArchive={(id) => setArchiveTargetId(id)}
            onCopy={(s) => setCopyTargetId(s.id)}
            onCreateTemplate={(s) => setCreateTplStore(s)}
            leagues={leagues}
            activeLeagueId={activeLeagueId}
            onSelectLeague={(id) => { setActiveLeagueId(id); setActiveGroupId(null); }}
            activeGroupId={activeGroupId}
            onOpenGroup={(gid) => setActiveGroupId(gid)}
            onCloseGroup={() => setActiveGroupId(null)}
            onOpenSettings={() => setScreen("league-settings")}
            onBackToLeagues={goLeagues}
          />
        )}
        {screen === "league-settings" && (
          <LeagueSettings
            league={leagues.find((l) => l.id === activeLeagueId)}
            onBack={() => setScreen("list")}
            onSave={handleUpdateLeague}
            onDelete={handleDeleteLeague}
            onToast={setToast}
          />
        )}
        {screen === "form" && (
          <CreateForm
            onCancel={handleCancel}
            onSubmit={handleFormSubmit}
            presetData={presetData}
            accent={tweaks.wizardAccent === "navy" ? "#1d3a8a" : "#e1251b"}
            athletes={tweaks.wizardAthletes || 30}
            templateMode={templateMode}
          />
        )}
        {screen === "template" && (
          <TemplateWorkspace
            presetData={presetData}
            layout={tweaks.templateLayout || "sidebar"}
            accent={tweaks.wizardAccent === "navy" ? "#1d3a8a" : "#e1251b"}
            onCancel={handleCancel}
            onContinue={(preset) => { setPresetData(preset); setTemplateMode(true); setScreen("form"); }}
          />
        )}
        {screen === "template-repo" && (
          <TemplateRepository
            userTemplates={userTemplates}
            accent={tweaks.wizardAccent === "navy" ? "#1d3a8a" : "#e1251b"}
            onCancel={handleCancel}
            onPickCurated={() => { setPresetData({}); setScreen("template"); }}
            onPickUser={(tpl) => {
              setPresetData({
                storeType: tpl.storeType,
                distributionModel: tpl.distributionModel,
                distributionFormat: "popup",
                curatedProducts: blocksToCuratedProducts(tpl.blocks),
                _fromUserTemplate: true,
                _templateName: tpl.name,
                _templateBlocks: tpl.blocks,
              });
              setTemplateMode(true);
              setScreen("form");
            }}
          />
        )}
        {screen === "loading" && (
          <div style={{ flex: 1, background: "#fff" }} />
        )}
        {screen === "dashboard" && activeStore && (
          <ManageStoreWorkspace
            store={activeStore}
            readOnly={!!activeStore.archived}
            onBack={goStores}
            onCustomize={() => setScreen("customizer")}
            initialTab={dashboardTab}
            liveStores={stores.filter((s) => s.live)}
            onLaunch={handleLaunch}
            onSetStatus={handleSetStatus}
            onViewStore={handleViewStore}
            onSwitchStore={(id) => { setActiveStoreId(id); setScreen("dashboard"); }}
            onProductsChange={(changes) => updateStore(activeStore.id, changes)}
            onUpdateStore={(patch) => updateStore(activeStore.id, patch)}
            onCreateTemplate={(s) => setCreateTplStore(s)}
          />
        )}
        {screen === "customizer" && activeStore && (
          <Customizer
            storeSport={activeStore.sport}
            onClose={() => setScreen("dashboard")}
            onPick={(item) => { setScreen("dashboard"); setToast(`Selected ${item.label} — opening Customizer 3.0…`); }}
          />
        )}
        {screen === "my-carts" && (
          <MyCarts
            stores={stores}
            activeStoreId={activeStoreId}
            onClose={() => setScreen("dashboard")}
            onLoadCart={(cart) => { setScreen("dashboard"); setToast(`Loaded "${cart.name}" into the store`); }}
            onAddToStore={({ cart, store }) => {
              // Build pending products from the cart (1-3 items for demo)
              const itemCount = Math.min(Math.max(cart.qty || 1, 1), 3);
              const items = Array.from({ length: itemCount }).map((_, i) => ({
                title: cart.name + (itemCount > 1 ? ` — Item ${i + 1}` : ""),
                subtitle: (store.teamName || store.storeTitle || "").toUpperCase(),
                source: "cart",
              }));
              addPendingToStore(store.id, items);
              setActiveStoreId(store.id);
              setDashboardTab("products");
              setScreen("dashboard");
              setToast(`Added "${cart.name}" — configure ${itemCount} item${itemCount > 1 ? "s" : ""} below`);
            }}
          />
        )}
        {screen === "saved-designs" && (
          <SavedDesigns
            stores={stores}
            activeStoreId={activeStoreId}
            onClose={() => setScreen("dashboard")}
            storeTeamName={activeStore?.teamName}
            onAddToStore={({ design, store }) => {
              addPendingToStore(store.id, [{
                title: design.title,
                subtitle: (store.teamName || store.storeTitle || "").toUpperCase(),
                source: "design",
                designPalette: design.palette,
              }]);
              setActiveStoreId(store.id);
              setDashboardTab("products");
              setScreen("dashboard");
              setToast(`Added "${design.title}" — configure pricing below`);
            }}
          />
        )}
      </div>

      <SalesTaxModal open={showTaxModal} onClose={() => setShowTaxModal(false)} onConfirm={handleTaxConfirm} />
      <CancelConfirmModal open={showCancelModal} onClose={() => { setShowCancelModal(false); setPendingNav(null); }} onConfirm={confirmCancel} />
      <CreateTemplateModal
        open={!!createTplStore}
        store={createTplStore}
        accent={tweaks.wizardAccent === "navy" ? "#1d3a8a" : "#e1251b"}
        onClose={() => setCreateTplStore(null)}
        onSave={handleSaveTemplate}
      />
      <StoreTemplateInterstitial
        open={showTemplateModal}
        accent={tweaks.wizardAccent === "navy" ? "#1d3a8a" : "#e1251b"}
        onClose={() => setShowTemplateModal(false)}
        onScratch={() => { setShowTemplateModal(false); setTemplateMode(false); setPresetData({}); setScreen("form"); }}
        onTemplate={() => { setShowTemplateModal(false); setPresetData({}); setScreen("template-repo"); }}
      />
      <CreateLeagueModal
        open={showLeagueModal}
        stores={stores}
        onClose={() => setShowLeagueModal(false)}
        onCreate={handleCreateLeague}
      />
      <CreateGroupModal
        open={showGroupModal}
        league={leagues.find((l) => l.id === activeLeagueId)}
        stores={stores}
        onClose={() => setShowGroupModal(false)}
        onCreate={handleCreateGroup}
      />
      <LoadingOverlay visible={screen === "loading"} />
      <ArchiveStoreModal
        open={!!archiveTargetStore}
        store={archiveTargetStore}
        onClose={() => setArchiveTargetId(null)}
        onConfirm={() => { updateStore(archiveTargetId, { status: "archived", live: false, archived: true }); setArchiveTargetId(null); setToast("Store archived"); }}
      />
      <CopyStoreModal
        open={!!copyTargetStore}
        store={copyTargetStore}
        onClose={() => setCopyTargetId(null)}
        onConfirm={(opts) => { const copy = copyStoreRecord(copyTargetStore, opts); setStores((arr) => [copy, ...arr]); setCopyTargetId(null); setToast("Copied to \"" + opts.name + "\" — opening the draft"); recordStoreVisit(copy.id); setActiveStoreId(copy.id); setDashboardTab("home"); setScreen("dashboard"); }}
      />
      <RestoreStoreModal
        open={!!restoreTargetStore}
        store={restoreTargetStore}
        onClose={() => setRestoreTargetId(null)}
        onConfirm={() => { updateStore(restoreTargetId, { status: "active", live: false, archived: false }); setRestoreTargetId(null); setToast("Store restored — now a draft in your active stores"); }}
      />
      <Toast message={toast} onDone={() => setToast(null)} />

      <OnboardingChecklist
        run={tourRun && !isFrameRoute && !tweaks.overviewMode}
        store={activeStore}
        screen={screen}
        accent={tweaks.checklistAccent}
        position={tweaks.checklistPosition}
        onStepAction={handleChecklistStep}
        onDismiss={endTour}
        onComplete={() => persistFirstStore(false)}
      />

      <WelcomeSSOModal
        open={showWelcome && !isFrameRoute && !tweaks.overviewMode}
        originId={ssoOriginId}
        multiBrand={tweaks.ssoMultiBrand}
        nativePath={isNative || tweaks.welcomeNativePath}
        email={ACCOUNT_PROFILE.email}
        accessibleIds={ACCOUNT_BRANDS.map((b) => b.id)}
        brandStates={brandStates}
        onConnectBrand={(id) => { if (brandStates[id] === "request") setBrandState(id, "pending"); else setBrandState(id, "connected"); }}
        onConfirm={confirmWelcome}
      />

      <TweaksPanel title="Tweaks">
        <TweakSection label="Access">
          <TweakToggle label="Has Team Stores access" value={tweaks.hasStoreAccess} onChange={setStoreAccess} />
          <TweakToggle label="Bypass compliance gate" value={tweaks.bypassGate} onChange={(v) => setTweak("bypassGate", v)} />
        </TweakSection>
        <TweakSection label="Auto sign-in welcome">
          <TweakButton label="▶  Preview welcome modal" onClick={() => setShowWelcome(true)} />
          <TweakToggle label="Native sign-in path" value={isNative || !!tweaks.welcomeNativePath} onChange={(v) => setTweak("welcomeNativePath", v)} />
          <TweakToggle label="Multi-brand account" value={tweaks.ssoMultiBrand} onChange={(v) => setTweak("ssoMultiBrand", v)} />
          <TweakSelect label="Origin brand" value={tweaks.ssoOriginBrand}
            options={ACCESSIBLE_CUSTOMIZERS.map((id) => ({ value: id, label: CUSTOMIZER_BRANDS[id].name }))}
            onChange={(v) => setTweak("ssoOriginBrand", v)} />
        </TweakSection>
        <TweakSection label="View">
          <TweakToggle label="Frame overview" value={tweaks.overviewMode} onChange={(v) => setTweak("overviewMode", v)} />
          <TweakToggle label="Overview empty state" value={tweaks.overviewEmpty} onChange={(v) => setTweak("overviewEmpty", v)} />
          <TweakToggle label="Zero state usability test" value={tweaks.zeroState} onChange={(v) => setTweak("zeroState", v)} />
          <TweakToggle label="Seed dummy data" value={tweaks.seedData} onChange={toggleSeed} />
          <TweakButton label="Clear all dummy data" secondary onClick={clearAllData} />
        </TweakSection>
        <TweakSection label="Store Close Report">
          <TweakButton label="▶  Replay first-after-close" onClick={() => window.dispatchEvent(new CustomEvent("closereport:replay"))} />
        </TweakSection>
        <TweakSection label="Team Stores portal">
          <TweakButton label="▶  Preview portal landing" onClick={() => { setNavTab("overview"); setScreen("portal"); }} />
          <TweakRadio label="Hero treatment" value={tweaks.portalHero}
            options={[{ value: "cinematic", label: "Cinematic" }, { value: "split", label: "Split panel" }]}
            onChange={(v) => setTweak("portalHero", v)} />
          <TweakRadio label="Headline" value={tweaks.portalHeadline}
            options={[{ value: "fulfillment", label: "Total fulfillment" }, { value: "teamstores", label: "Team stores" }, { value: "geared", label: "Geared up" }]}
            onChange={(v) => setTweak("portalHeadline", v)} />
          <TweakRadio label="Gateway CTA" value={tweaks.portalCta}
            options={[{ value: "manager", label: "Store Manager" }, { value: "dashboard", label: "Dashboard" }]}
            onChange={(v) => setTweak("portalCta", v)} />
          <TweakRadio label="CTA color" value={tweaks.portalCtaColor}
            options={[{ value: "black", label: "Black" }, { value: "red", label: "Red" }]}
            onChange={(v) => setTweak("portalCtaColor", v)} />
        </TweakSection>
        <TweakSection label="Create-store wizard">
          <TweakButton label="▶  Open create wizard" onClick={() => { setPresetData(makePrefill()); setTemplateMode(false); setScreen("form"); }} />
          <TweakButton label="▶  Add Store (interstitial)" onClick={() => { setPresetData(makePrefill()); setTemplateMode(false); setShowTemplateModal(true); }} />
          <TweakButton label="▶  Open template workspace" onClick={() => { setPresetData(makePrefill()); setScreen("template"); }} />
          <TweakButton label="▶  Template repository (tabs)" onClick={() => { setPresetData({}); setScreen("template-repo"); }} />
          <TweakButton label="▶  Create Template modal" onClick={() => setCreateTplStore(makeSeededStores()[0])} />
          <TweakRadio label="Template layout" value={tweaks.templateLayout}
            options={[{ value: "sidebar", label: "Sidebar" }, { value: "stacked", label: "Stacked" }]}
            onChange={(v) => setTweak("templateLayout", v)} />
          <TweakRadio label="Accent" value={tweaks.wizardAccent}
            options={[{ value: "red", label: "PROLOOK Red" }, { value: "navy", label: "Navy" }]}
            onChange={(v) => setTweak("wizardAccent", v)} />
          <TweakSlider label="Projected athletes" min={10} max={60} step={1}
            value={tweaks.wizardAthletes} onChange={(v) => setTweak("wizardAthletes", v)} />
        </TweakSection>
        <TweakSection label="Onboarding checklist">
          <TweakButton label="▶  Start onboarding demo" onClick={startOnboardingDemo} />
          <TweakRadio label="Accent" value={tweaks.checklistAccent}
            options={[{ value: "red", label: "Red" }, { value: "navy", label: "Navy" }, { value: "green", label: "Green" }]}
            onChange={(v) => setTweak("checklistAccent", v)} />
          <TweakRadio label="Position" value={tweaks.checklistPosition}
            options={[{ value: "right", label: "Bottom right" }, { value: "left", label: "Bottom left" }]}
            onChange={(v) => setTweak("checklistPosition", v)} />
          <TweakToggle label="Run on next new store" value={isFirstStore} onChange={persistFirstStore} />
          {activeStore && !tourRun && (
            <TweakButton label="Replay checklist on this store" secondary onClick={() => { try { localStorage.removeItem("prolook_checklist_dismissed_" + activeStore.id); } catch (e) {} persistFirstStore(true); setTourRun(true); }} />
          )}
        </TweakSection>
      </TweaksPanel>
    </div>
  );
}

// Demo prefill values to make the flow tangible
const USER_TPL_KEY = "prolook_user_templates";
function loadUserTemplates() {
  try { const raw = localStorage.getItem(USER_TPL_KEY); return raw ? JSON.parse(raw) : []; } catch (e) { return []; }
}
function saveUserTemplates(list) {
  try { localStorage.setItem(USER_TPL_KEY, JSON.stringify(list)); } catch (e) {}
}

