    const fund = parseFloat(row.fund) || 0;
    row.dealerUnit = "$"; row.dealer = mine.commission.toFixed(2);
    row.teamUnit = "$"; row.team = "0.00";
    row.fundUnit = "$"; row.fund = fund.toFixed(2);
